typedef struct {
    int UE_ID;
    double RX_Power;
    char SRS_Configuration[20];
    pthread_t thread_id;
} LTE_UE;

void *update_RX_Power(void *arg) {
    LTE_UE *ue = arg;
    // Simulate radio channel conditions and update RX Power
    ue->RX_Power += rand() % 10 + 50;
    return NULL;
}

void init_LTE_UE(LTE_UES **ues, int num_ues) {
    *ues = malloc(num_ues * sizeof(LTE_UES));
    if (*ues == NULL) {
        perror("Memory allocation failed");
        return;
    }

    for (int i = 0; i < num_ues; ++i) {
        (*ues)[i].UE_ID = i + 1;
        // Initialize RX Power, SRS Configuration, and thread with detached state
        (*ues)[i].RX_Power = 50;
        strcpy((*ues)[i].SRS_Configuration, "Default");
        if (pthread_create(&(*ues)[i].thread_id, NULL, update_RX_Power, &(*ues)[i]) != 0) {
            perror("Thread creation failed");
        } else {
            pthread_detach((*ues)[i].thread_id);
        }
    }
}

void destroy_LTE_UE(LTE_UES *ues, int num_ues) {
    for (int i = 0; i < num_ues; ++i) {
        // Join the thread if it's still running
        pthread_join((ues[i].thread_id), NULL);
    }
    free(ues);
}
