#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <getopt.h>
#include <stdbool.h>
#include <unistd.h>
#include <sys/types.h>
#include <fcntl.h>

typedef struct {
    char *input_file;
    char *output_file;
    bool count_only, summary;
} opts;

void print_usage(char *program_name) {
    printf("Usage: %s [options]\n", program_name);
    printf("-i, --input-file <FILE>       Specifies the input file to be processed.\n");
    printf("-c, --count-only               Prints only the total number of lines.\n");
    printf("-s, --summary                  Prints a summary of lines per unique word.\n");
    printf("-o, --output-file <FILE>       Specifies an output file where results should be written.\n");
    printf("-h, --help                     Displays this help message.\n");
    printf("-m, --manpage                  Displays a detailed usage information.\n");
}

void print_manpage(char *program_name) {
    printf("Detailed Usage Information for %s:\n", program_name);
    // Add detailed usage information here.
}

opts parse_options(int argc, char *argv[]) {
    opts opt;
    memset(&opt, 0, sizeof(opts));
    int option_index = 0;
    static struct option long_options[] = {
        {"input-file", required_argument, NULL, 'i'},
        {"count-only", no_argument, NULL, 'c'},
        {"summary", no_argument, NULL, 's'},
        {"output-file", required_argument, NULL, 'o'},
        {"help", no_argument, NULL, 'h'},
        {"manpage", no_argument, NULL, 'm'},
        {0, 0, 0, 0}
    };

    while (1) {
        int c = getopt_long(argc, argv, "i:cso:hfm", long_options, &option_index);
        if (c == -1) break;

        switch (c) {
            case 'i':
                opt.input_file = optarg;
                break;
            case 'c':
                opt.count_only = true;
                break;
            case 's':
                opt.summary = true;
                break;
            case 'o':
                opt.output_file = optarg;
                break;
            case 'h':
                print_usage(argv[0]);
                exit(EXIT_SUCCESS);
            case 'm':
                print_manpage(argv[0]);
                exit(EXIT_SUCCESS);
            default:
                print_usage(argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    if (optind < argc) {
        if (strcmp(argv[optind], "--input-file") == 0 && opt.input_file == NULL) {
            opt.input_file = argv[++optind];
        } else {
            print_usage(argv[0]);
            exit(EXIT_FAILURE);
        }
    }

    return opt;
}

void process_lines(FILE *file, bool count_only, bool summary, size_t *line_count, void (*word_counter)(char *, size_t *, void *), void *userdata) {
    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        size_t line_len = strlen(line);
        if (count_only) {
            ++(*line_count);
            continue;
        }

        char *word = strtok(line, " \n");
        while (word != NULL) {
            if (summary) {
                word_counter(word, line_count, userdata);
            }
            word = strtok(NULL, " \n");
        }
    }
}

void count_lines(size_t *line_count) {
    (*line_count)++;
}

int main(int argc, char *argv[]) {
    opts options = parse_options(argc, argv);

    if (options.input_file == NULL && !options.count_only) {
        print_usage(argv[0]);
        return EXIT_FAILURE;
    }

    FILE *input_file = NULL;
    size_t line_count = 0;
    if (options.input_file != NULL) {
        int fd = open(options.input_file, O_RDONLY);
        if (fd == -1) {
            perror("Error opening input file");
            return EXIT_FAILURE;
        }
        input_file = fdopen(fd, "r");
    }

    void *word_counter_userdata = malloc(sizeof(size_t));
    memset(word_counter_userdata, 0, sizeof(size_t));

    process_lines(input_file, options.count_only, options.summary, &line_count, count_lines, word_counter_userdata);

    if (options.output_file != NULL) {
        int fd = open(options.output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd == -1) {
            perror("Error opening output file");
            return EXIT_FAILURE;
        }
        FILE *output_file = fdopen(fd, "w");
        fprintf(output_file, "%zu\n", line_count);
        fclose(output_file);
    } else {
        printf("%zu\n", line_count);
    }

    free(word_counter_userdata);
    if (input_file != NULL) fclose(input_file);
    return EXIT_SUCCESS;
}
```
