int main(int argc, char **argv) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s input_log output_summary config transformation_format\n", argv[0]);
        return 1;
    }

    const char *input_file = argv[1];
    const char *output_file = argv[2];
    const char *config_file = argv[3];
    bool html_format = strcmp(argv[4], "--html") == 0 || strcmp(argv[4], "-html");

    char **config;
    read_config(config_file, &config);

    FILE *input = fopen(input_file, "r");
    if (!input) {
        perror("Error opening input file");
        return 1;
    }

    char line[4096];
    char summary[65536];
    size_t summary_len = 0;
    bool first_line = true;

    while (fgets(line, sizeof(line), input)) {
        if (!process_line(line, config, html_format)) {
            return 1;
        }

        if (first_line) {
            first_line = false;
            continue;
        }

        summary_len += snprintf(summary + summary_len, sizeof(summary) - summary_len, "%s\n", line);
    }

    fclose(input);

    write_summary(output_file, summary, html_format);
    free(config);
    return 0;
}

void read_config(const char *filename, char ***config) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("Error opening config file");
        exit(1);
    }

    size_t capacity = 0;
    size_t count = 0;
    char **array = NULL;

    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        if (capacity <= count) {
            capacity *= 2;
            array = realloc(array, capacity * sizeof(*array));
        }
        array[count] = strdup(line);
        ++count;
    }

    fclose(file);

    *config = malloc((count + 1) * sizeof(**config));
    memcpy(*config, array, count * sizeof(*array));
    (*config)[count] = NULL;
}

bool process_line(char *line, const char *config_file[], bool html) {
    // Implement your transformation logic here.
    // Use the config_file[] array to access the configuration as needed.
    return true;
}

void write_summary(const char *output_file, const char *summary, bool html) {
    FILE *output = fopen(output_file, "w");
    if (!output) {
        perror("Error opening output file");
        return;
