#include <stdio.h>
#include <stdlib.h>

int max_integer(int* arr, int size) {
    if (size == 0) return INT_MIN;
    int max = arr[0];
    for (int i = 1; i < size; ++i)
        if (arr[i] > max) max = arr[i];
    return max;
}

void read_integers(int** arr, int* size) {
    *size = 0;
    int temp;
    while (1) {
        scanf("%d", &temp);
        if (feof(stdin)) break;
        if (*size == 0) {
            *arr = malloc(*size * sizeof(int));
        } else {
            int* new_arr = realloc(*arr, (*size + 1) * sizeof(int));
            if (!new_arr) {
                fprintf(stderr, "Memory allocation failed.\n");
                free(*arr);
                return;
            }
            *arr = new_arr;
        }
        if (temp < INT_MIN || temp > INT_MAX) {
            fprintf(stderr, "Invalid input: out of range.\n");
            free(*arr);
            return;
        }
        (*arr)[*size] = temp;
        ++(*size);
    }
}

int main() {
    int* arr;
    int size;
    read_integers(&arr, &size);
    if (size == 0) {
        printf("No integers provided.\n");
    } else {
        printf("The largest integer is %d\n", max_integer(arr, size));
    }
    free(arr);
    return 0;
}
