// Throttling settings
#define LOG_THROTTLE_PERIOD 100000 // Number of logging requests allowed per microsecond
sem_t log_throttle;

void init_log(void) {
    sem_init(&log_throttle, 0, LOG_THROTTLE_PERIOD);
}

void log_message(const char* level, const char* format, ...) {
    va_list args;
    int count = 0; // To track the number of logged messages per microsecond

    // Acquire throttling semaphore to avoid overwhelming the log storage system
    sem_wait(&log_throttle);

    // Save current time for throttling purposes
    long current_time = get_microseconds();

    va_start(args, format);
    vprintf(format, args);
    va_end(args);

    // Increment the number of logged messages and release the semaphore if it's time to do so
    count++;
    if ((current_time - last_logged_time) >= 1000000 / LOG_THROTTLE_PERIOD || count == LOG_THROTTLE_PERIOD) {
        sem_post(&log_throttle);
        last_logged_time = current_time;
        count = 0;
    }
}

// Assuming a static variable `last_logged_time` has been initialized with the current time before using log_message for the first time.

// You can use your existing logging framework's API to integrate this function into your system.
