import hashlib
import os
import tempfile
import logging

def md5_hash(file_path):
    logging.basicConfig(format='%(asctime)s - %(message)s', level=logging.INFO)
    chunk_size = 1 * (2 ** 20)  # 1 MB
    hasher = hashlib.md5()
    temp_file = None

    try:
        with open(file_path, 'rb') as f:
            while True:
                data = f.read(chunk_size)
                if not data:
                    break
                hasher.update(data)
                processed = len(data)
                log_message = f"Processed {processed} bytes from {file_path}"
                logging.info(log_message)
            file_size = os.path.getsize(file_path)
            log_message = f"Finished processing {file_size} bytes from {file_path}"
            logging.info(log_message)
        status_report = {"status": "success", "hexdigest": hasher.hexdigest()}
    except FileNotFoundError:
        status_report = {"status": "error", "message": f"File '{file_path}' not found."}
    except PermissionError:
        status_report = {"status": "error", "message": f"Permission denied for file '{file_path}'."}
    except Exception as e:
        status_report = {"status": "error", "message": f"An unexpected error occurred: {str(e)}"}
    else:
        if os.path.getsize(file_path) > (2 ** 31) - 1:  # Checking for 32-bit system limits
            with tempfile.TemporaryDirectory() as tempdir:
                temp_file = os.path.join(tempdir, file_path)
                shutil.copyfileobj(f, open(temp_file, 'ab'))
                status_report = md5_hash(temp_file)

    if temp_file:
        try:
            os.remove(temp_file)
        except Exception as e:
            logging.error(f"Failed to remove temporary file '{temp_file}': {str(e)}")

    return status_report
