#include <openssl/evp.h>
#include <openssl/err.h>
#include <json-c/json.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher;
} crypt_context;

bool validate_token(char *json) {
    json_object *obj = json_tokener_parse(json, 0);
    if (!obj) return false;

    bool token_type_valid = json_object_get_string(obj, "token_type") && strcmp(json_object_get_string(obj, "token_type"), "Bearer") == 0;
    bool expires_in_valid = json_object_get_int(obj, "expires_in") > 0;
    bool has_access_token = json_object_object_get_ex(obj, "access_token");
    bool has_refresh_token = json_object_object_get_ex(obj, "refresh_token");

    json_object_put(obj);

    if (!has_access_token) return false;
    if (!expires_in_valid || !token_type_valid) return false;

    return true;
}

crypt_context create_cipher(const char *mode) {
    const EVP_CIPHER *cipher;
    crypt_context ctx = {0};

    if (strcmp(mode, "ECB") == 0)
        cipher = EVP_des_ecb();
    else if (strcmp(mode, "EDE") == 0)
        cipher = EVP_des_ede();
    else if (strcmp(mode, "EDE3") == 0)
        cipher = EVP_des_ede3_cbc();
    else if (strcmp(mode, "CFB") == 0)
        cipher = EVP_des_cfb1();
    else if (strcmp(mode, "null") == 0) // Null encryption for testing purposes
        return (crypt_context){.cipher = NULL};
    else
        return ctx;

    if (!EVP_CIPHER_CTX_init(&ctx.ctx)) {
        ERR_print_errors_fp(stderr);
        exit(EXIT_FAILURE);
    }

    EVP_CIPHER_CTX_set_cipher(&ctx.ctx, cipher);

    return ctx;
}
