#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdlib.h>
#include <stdio.h>

typedef struct ResourcePool {
    sem_t resources; // Semaphore for number of available resources
    sem_t max_resources; // Semaphore for maximum capacity
    int num_resources; // Current number of resources in the pool
    int max_capacity; // Maximum capacity of the resource pool
    pthread_mutex_t lock; // Mutex to protect shared variables
} ResourcePool;

ResourcePool* createResourcePool(int num_resources, int max_capacity) {
    ResourcePool *pool = malloc(sizeof(ResourcePool));
    if (!pool) {
        perror("Error allocating memory for resource pool");
        exit(EXIT_FAILURE);
    }

    pool->num_resources = 0;
    pool->max_capacity = max_capacity > num_resources ? max_capacity : num_resources;
    sem_init(&pool->resources, 0, num_resources);
    sem_init(&pool->max_resources, 0, pool->max_capacity - num_resources);
    pthread_mutex_init(&pool->lock, NULL);

    return pool;
}

void destroyResourcePool(ResourcePool *pool) {
    if (pool) {
        sem_destroy(&pool->resources);
        sem_destroy(&pool->max_resources);
        pthread_mutex_destroy(&pool->lock);
        free(pool);
    }
}

bool tryAcquireResource(ResourcePool *pool) {
    bool success = true;

    pthread_mutex_lock(&pool->lock);
    if (sem_wait(&pool->resources) < 0 || sem_trywait(&pool->max_resources) >= 0) {
        pool->num_resources++;
    } else {
        success = false;
    }
    pthread_mutex_unlock(&pool->lock);

    return success;
}

void releaseResource(ResourcePool *pool) {
    pthread_mutex_lock(&pool->lock);
    if (sem_post(&pool->resources) < 0 || pool->num_resources > 0) {
        pool->num_resources--;
    }
    pthread_mutex_unlock(&pool->lock);
}
