use rusty_parser::{CParser,CppParser,RustParser, Grammar};
use rayon::prelude::*;
use log::{error, info, LevelFilter, SetLoggerLevelFilter};

type Result<T> = std::result::Result<T, Box<dyn std::error::Error>>;

const SUPPORTED_GRAMMARS: &[&str] = &[".c", ".cc", ".cpp", ".h", ".hh", ".hpp", ".rs"];
const LOGGING_ENABLED: bool = false;
const OPTIMIZATION_LEVEL: llvm::OptLevel = llvm::OptLevel::O3;
const OUTPUT_DIR: &str = ".";

fn generate_llvm_ir(file_path: &str) -> (bool, String, Option<String>) {
    let file_ext = Path::new(file_path).extension().and_then(AsRef::as_ref).map(|s| s.to_str());

    if file_ext.is_none() || !SUPPORTED_GRAMMARS.iter().any(|ext| ext == file_ext.as_ref()) {
        return (false, format!("Unsupported file extension: {}", file_path), None);
    }

    let mut log = Vec::new();
    let parser = match file_ext.as_ref() {
        ".rs" => RustParser::new(),
        _     => CParser::new(),
    };

    let file = BufReader::new(File::open(file_path).unwrap());
    if let Err(e) = parser.parse(file, &mut log) {
        return (false, format!("Error parsing input: {}", e), None);
    }

    // LLVM IR generation here...

    (true, log.into(), Some(generate_output_path(OUTPUT_DIR, file_path)))
}

fn generate_output_path<'a>(dir: &'a str, input_path: &'a str) -> String {
    let output_file = Path::new(input_path).file_name().unwrap().to_str().unwrap();
    let mut ext = output_file.split(".");
    ext.pop();
    let ext = ext.next().map(|s| s.as_str()).unwrap_or("ll");
    Path::new(dir).join(format!("{}.{}", output_file, ext))
        .to_string_lossy()
        .into_owned()
}

fn main() {
    SetLoggerLevelFilter!(if LOGGING_ENABLED { LevelFilter::Info } else { LevelFilter::Error });

    let matches = clap_app!(my_app =>
        (version: crate_version!())
        (author: crate_authors!())
        (about: crate_description!())
    )
    .arg(clap_arg!(-o --output_dir <DIR> "Output directory for generated LLVM IR"))
    .get_matches();

    let output_dir = matches.value_of("output_dir").unwrap_or(OUTPUT_DIR);
    let (success, log_messages, output_path) = generate_llvm_ir("example.rs");

    if success {
        if let Some(output_path) = output_path {
            let mut file = File::create(output_path).unwrap();
            file.write_all(&log_messages.as_bytes()).unwrap();
        }
    } else {
        error!("{}", log_messages);
    }
}
```

