```javascript
const express = require('express');
const app = express();
const bodyParser = require('body-parser');

let resources = []; // In-memory storage for simplicity. Replace with a database connection in real-world scenarios.

app.use(bodyParser.json());

// PUT operation - updates a resource by its id
app.put('/resources/:id', (req, res) => {
  const id = req.params.id;
  const updatedResourceIndex = resources.findIndex(resource => resource.id === id);

  if (updatedResourceIndex !== -1) {
    // Update the resource with the new data from the request body
    resources[updatedResourceIndex] = { ...resources[updatedResourceIndex], ...req.body };
    res.sendStatus(200);
  } else {
    res.sendStatus(404);
  }
});

// DELETE operation - deletes a resource by its id, ensuring idempotency
app.delete('/resources/:id', (req, res) => {
  const id = req.params.id;
  const resourceIndex = resources.findIndex(resource => resource.id === id);

  if (resourceIndex !== -1) {
    // Remove the resource from the collection
    resources.splice(resourceIndex, 1);
    res.sendStatus(200);
  } else {
    res.sendStatus(404);
  }
});
