public class PageUpdaterController : Controller
{
    private readonly IPageService _pageService;

    public PageUpdaterController(IPageService pageService)
    {
        _pageService = pageService;
    }

    [HttpPost]
    public async Task<IActionResult> UpdatePage(int pageId, List<int> elementIds, Dictionary<int, string> updates)
    {
        var cachedPage = await _pageService.GetCachedPage(pageId);
        if (cachedPage != null)
        {
            foreach (var element in elementIds)
            {
                cachedPage[element] = updates[element];
            }
            await _pageService.SaveUpdatedCache(cachedPage, pageId);
            return Content("Refreshed from cache");
        }

        var updatedPage = await _pageService.ApplyUpdatesAndGetPage(pageId, elementIds, updates);
        await _pageService.SaveUpdatedCache(updatedPage, pageId);
        return Content("Refreshed");
    }
}
```

