['```java
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.serialization.LinkedTransferData;
import java.util.logging.Logger;
import java.util.concurrent.ConcurrentHashMap;

public class MoSTStateLoader {
    private static final Logger LOGGER = Logger.getLogger(MoSTStateLoader.class.getName());
    private static final ConcurrentHashMap<Path, MoSTState> LOADED_STATES = new ConcurrentHashMap<>();

    public static MoSTState loadFromFile(Path filePath) {
        try (ObjectInputStream objectInput = new ObjectInputStream(Files.newInputStream(filePath))) {
            Object readObject = objectInput.readObject();
            if (readObject instanceof MoSTState mostState) {
                LOADED_STATES.putIfAbsent(filePath, mostState);
                return mostState;
            }
        } catch (IOException | ClassNotFoundException e) {
            LOGGER.severe("Error loading state from file: " + filePath + ", message: " + e.getMessage());
        } finally {
            // Always close the input stream to avoid resource leaks
            if (null != objectInput) {
                try {
                    objectInput.close();
                } catch (IOException ex) {
                    LOGGER.warning("Error closing ObjectInputStream: " + ex.getMessage());
                }
            }
        }
        return null;
    }
}
```

