const runTests = (label, modules, timeout = 5000) => {
  const blueslip = require('blueslip');
  const _modules = new WeakMap();

  // Reset mocking library at the beginning of each test session.
  blueslip.reset();

  const logTestResult = (result, testName) => {
    if (result) console.log(`✅ Test case "${testName}" passed`);
    else console.log(`🚫 Test case "${testName}" failed`);
  };

  const runModuleTests = (modulePath) => {
    const module = _modules.get(modulePath) || require(modulePath);
    _modules.set(modulePath, module);

    console.log(`📦 Loaded test module: ${modulePath}`);

    module.tests.forEach((testFn, i) => {
      try {
        const testName = `${modulePath} - Test Case ${i + 1}`;
        blueslip.mockReset();
        console.log(`🔄 Running test case: ${testName}`);
        const startTime = Date.now();
        testFn();
        const endTime = Date.now();
        const duration = endTime - startTime;
        logTestResult(true, testName);
        console.log(`🕒 Test case "${testName}" completed in ${duration}ms`);
      } catch (error) {
        const testName = `${modulePath} - Test Case ${i + 1}`;
        logTestResult(false, testName);
        console.log(`❗️ Test case "${testName}" failed:`, error.stack);
      }
    });
  };

  modules.forEach(({ path, tests }) => runModuleTests(path));

  const numSuccessful = modules.reduce((sum, { tests }) => sum + tests.filter(Boolean.bind(null)).length, 0);
  const numFailed = modules.reduce((sum, { tests }) => sum + tests.filter(Boolean.bind(null, false)).length, 0);
  const numSkipped = modules.reduce((sum, { tests }) => sum + tests.filter(testFn => testFn instanceof Function && 'skip' in testFn).length, 0);

  console.log(`🔁 ${modules.length} test modules loaded`);
  console.log(`✅ ${numSuccessful} successful tests, 🚫 ${numFailed} failed tests, ❗️ ${numSkipped} skipped tests`);
};
