const axios = require('axios');
const _ = require('lodash');
const bluebird = require('bluebird');

// Constants (Book names from Old Testament)
const OLD_TESTAMENT = ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy', //...add more books here
                      'Joshua', 'Judges', 'Ruth', '1 Samuel', '2 Samuel', '1 Kings',
                      '2 Kings', '1 Chronicles', '2 Chronicles', 'Ezra', 'Nehemiah',
                      'Esther'];

// API URL to fetch Old Testament book names
const apiUrl = 'https://api.example.com/bible/oldtestament';

// Regular Expression for matching book names
const regex = /(\b\w+ \w+\b)/g;

// Function to extract books from text using the defined regular expression
function extractBooks(text) {
  const matches = text.match(regex);
  if (!matches) return {};

  let bookCount = _.countBy(matches);
  bookCount = Object.keys(bookCount).filter(key => OLD_TESTAMENT.includes(key));
  return bookCount;
}

// Function to make API call and process text concurrently using Bluebird
function processText(text) {
  // Fetch Old Testament books names from the external API (asynchronous call)
  const apiPromise = axios.get(apiUrl).then(({ data }) => data);

  // Extract the promise to handle concurrent execution
  const extractPromises = text.split('\n').map(extractBooks);

  // Concatenate all promises to a single array and execute them in parallel
  return bluebird.map(bluebird.all([apiPromise, ...extractPromises]), (result) => {
    const books = _.mergeWith({}, result[0], result[1], (value, newValue) => value + newValue);
    return books;
  });
}
