        this.threadPool = Executors.newFixedThreadPool(corePoolSize, r -> new Thread(r, "High-Throughput-Data-Transfer-" + r.hashCode()));
    }

    public void addTask(Runnable task) {
        tasks.add(task);
    }

    public void start() {
