['```rust
use reqwest::{Client, Response};
use serde_json::Value;
use chrono::Utc;
use log::{info, error};
use std::collections::HashMap;
use std::option::Option;
use std::sync::Mutex;
use reqwest_middleware::LoggerMiddleware;

static LOGGER: Mutex<log::Logger> = Mutex::new(log::Logger::root(log4rs::append::console::ConsoleAppender::new(), log4rs::filter::LevelFilter::Info));

async fn handle_request(url: &str, method: reqwest::Method, headers: HashMap<String, String>, body: Option<Value>, no_ssl_verification: bool) -> Result<Response, Box<dyn std::error::Error>> {
    let client = Client::builder()
        .add_middlewares(LoggerMiddleware::new(|req, res| {
            if let Some(body) = res.text().await {
                info!(target: "http", "{} {} {}", Utc::now(), url, method.as_ref().unwrap(), "status_code" => res.status().as_u16());
                info!(target: "http", "{} {}", body, "");
            }
        }))
        .build()?;

    let resp = match no_ssl_verification {
        true => client.execute(url, method, headers, body).await?,
        false => client.request(url, method, headers)
                       .header("User-Agent", "MyApp/1.0")
                       .body(body)
                       .verify_trusted_certificate(true)
                       .send()
                       .await?
    };

    Ok(resp)
}

fn get(url: &str, headers: HashMap<String, String>, no_ssl_verification: bool) -> Result<Response, Box<dyn std::error::Error>> {
    handle_request(url, reqwest::Method::GET, headers, None, no_ssl_verification)
}

fn post(url: &str, headers: HashMap<String, String>, body: Value, no_ssl_verification: bool) -> Result<Response, Box<dyn std::error::Error>> {
    handle_request(url, reqwest::Method::POST, headers, Some(body), no_ssl_verification)
}

fn put(url: &str, headers: HashMap<String, String>, body: Value, no_ssl_verification: bool) -> Result<Response, Box<dyn std::error::Error>> {
    handle_request(url, reqwest::Method::PUT, headers, Some(body), no_ssl_verification)
}

fn delete(url: &str, headers: HashMap<String, String>, no_ssl_verification: bool) -> Result<Response, Box<dyn std::error::Error>> {
    handle_request(url, reqwest::Method::DELETE, headers, None, no_ssl_verification)
}
```

