class Utilities {
    private $charSets = [];
    private $hashes = [];
    private $cache = [];

    public function __construct($charSets = [], $hashes = ['sha256', 'argon2i']) {
        $this->charSets = $charSets;
        $this->hashes = $hashes;
    }

    public function addCharSet(string $name, string $chars) {
        $this->charSets[$name] = $chars;
    }

    public function addHash(string $algorithm) {
        $this->hashes[] = $algorithm;
    }

    public function getRandomString($length, $charSet = 'default', $cacheTime = 60) {
        $key = md5($charSet . $length);
        if (!isset($this->cache[$key]) || time() - $this->cache[$key]['time'] > $cacheTime) {
            shuffle($this->charSets[$charSet]);
            $randomString = '';
            for ($i = 0; $i < $length; $i++) {
                $randomString .= $this->charSets[$charSet][$i];
            }
            $this->cache[$key] = ['string' => $randomString, 'time' => time()];
        }
        return $this->cache[$key]['string'];
    }

    public function hashPassword($password, $algorithm = 'sha256') {
        if (!in_array($algorithm, $this->hashes)) {
            throw new Exception("Invalid hashing algorithm: {$algorithm}. Supported algorithms are: " . implode(', ', $this->hashes));
        }
        return password_hash($password, PASSWORD_DEFAULT); // Using PHP's built-in password_hash function for improved security
    }

    public function verifyPassword($hashedPassword, $clearTextPassword, $algorithm = 'sha256') {
        if (!in_array($algorithm, $this->hashes)) {
            throw new Exception("Invalid hashing algorithm: {$algorithm}. Supported algorithms are: " . implode(', ', $this->hashes));
        }
        return password_verify($clearTextPassword, $hashedPassword); // Using PHP's built-in password_verify function for improved security
    }
}
