class SessionManager {
    private $authBackend;
    private $tokenExpiryMinutes = 60; // Default token expiration time in minutes

    public function __construct($authBackend) {
        $this->authBackend = $authBackend;
    }

    public function startSession() {
        if (!isset($_SESSION)) {
            session_start();
        }
        if (!isset($_SESSION['access_token']) || $_SESSION['access_token_expiry'] < time()) {
            $accessToken = $this->authBackend->authenticate();
            $_SESSION['access_token'] = $accessToken;
            $_SESSION['access_token_expiry'] = time() + ($this->tokenExpiryMinutes * 60);
        }
        return $_SESSION['access_token'];
    }

    public function refreshToken() {
        if (!isset($_SESSION) || !isset($_SESSION['access_token'])) {
            throw new Exception('No active session found.');
        }
        if ($_SESSION['access_token_expiry'] > time()) {
            $this->startSession();
        } else {
            $_SESSION = array(); // Destroy session data to force a refresh
        }
    }
}
