class UserPasswordDAO {
    private $db;
    private $idmService;
    private $passwordValidator;

    public function __construct(PDO $db, IdmService $idmService, PasswordValidator $passwordValidator) {
        $this->db = $db;
        $this->idmService = $idmService;
        $this->passwordValidator = $passwordValidator;
    }

    public function updatePassword(int $userId, string $newPassword): bool {
        try {
            // Validate password strength before updating the database
            if (!$this->passwordValidator->validate($newPassword)) {
                throw new Exception("Invalid password.");
            }

            // Verify user's current status with external IdM service
            $userStatus = $this->idmService->getUserStatus($userId);

            // Handle potential network failures and latency
            if (!$userStatus && $this->idmService->isTemporarilyUnavailable()) {
                sleep(5); // Retry after a short delay
                return $this->updatePassword($userId, $newPassword);
            } elseif (!$userStatus) {
                throw new Exception("Failed to verify user's current status.");
            }

            if ($userStatus['is_active'] !== true) {
                throw new Exception("User is inactive or suspended.");
            }

            // Update the password in the database
            $stmt = $this->db->prepare("UPDATE users SET password = ? WHERE id = ?");
            $stmt->execute([$newPassword, $userId]);

            return true;
        } catch (Exception $e) {
            error_log($e->getMessage());
            return false;
        }
    }
}
