typedef struct State {
    int id;
    struct State* next;
    struct Transition* transitions;
} State;

typedef struct Transition {
    int to_state;
    struct Transition* next;
} Transition;

State* createStateList(int* states, int num_states, const Transition* fsa, int last_state, bool debug, bool track_transitions) {
    if (!states || !fsa || num_states <= 0) return NULL;

    State* head = malloc(sizeof(State));
    if (!head) return NULL;
    head->id = states[0];
    head->next = NULL;
    head->transitions = NULL;

    State* current = head;
    for (int i = 1; i < num_states; ++i) {
        State* new_state = malloc(sizeof(State));
        if (!new_state) {
            freeMem(head);
            return NULL;
        }
        new_state->id = states[i];
        new_state->next = NULL;
        new_state->transitions = NULL;

        Transition* transition = fsa;
        while (transition && transition->to_state != current->id) {
            transition = transition->next;
        }
        if (!transition) {
            freeMem(head);
            return NULL;
        }
        new_state->transitions = transition->next;
        transition->next = new_state;

        if (debug) printf("Creating state %d from state %d\n", states[i], current->id);
        if (track_transitions) logTransition(states[i], current->id);

        current->next = new_state;
        current = new_state;
    }

    // Update the 'next' pointer of the last state in the list to point to the newly created state list.
    current->next = head;

    if (last_state != -1) {
        State* state_to_link = findStateById(head, last_state);
        if (!state_to_link || !state_to_link->next) {
            freeMem(head);
            return NULL;
        }
        state_to_link->next = current;
    }

    return head;
}

void logTransition(int from, int to) {
    // Implement this function based on the requirements.
}

void freeMem(State* node) {
    if (!node) return;

    State* temp = node;
    Transition* transition = node->transitions;
    while (temp) {
        Transition* next_transition = transition ? transition->next : NULL;
        free(transition);
        transition = next_transition;

        State* next_state = temp->next;
        free(temp);
        temp = next_state;
    }
}
