#include <vector>
#include <memory>
#include <unordered_map>
#include <cassert>
#include <new>
#include <functional>

// Define the OctreeNode struct with necessary data members: index, position, data, child pointers and flag for being a leaf node
struct OctreeNode {
    unsigned int index; // Index in the primary storage or the external data source
    std::array<double, 3> position; // Position within the 3D space
    std::vector<double> data; // Array to store the data associated with this node
    std::unique_ptr<OctreeNode[]> children; // Dynamic allocation for child nodes
    bool isLeaf = false; // Flag to indicate whether this node is a leaf or not
};

// Define the Octree struct with necessary member variables and functions
struct Octree {
private:
    const double featureSize; // Size of each octree cell
    unsigned int initialLeafNodes; // Number of initial leaf nodes in the tree
    unsigned int maxDataCapacity; // Maximum number of data points that can be stored in a node before splitting
    std::vector<OctreeNode> primaryStorage; // Primary storage for frequently accessed data
    std::unordered_map<unsigned int, OctreeNode*> secondaryStorage; // Secondary storage for less frequently accessed data
    std::function<void(const OctreeNode&)> updateCallback; // Callback function to integrate with external data source

public:
    // Constructor taking in the feature size, initial leaf nodes and maximum data capacity
    Octree(double featureSize_, unsigned int initialLeafNodes_, unsigned int maxDataCapacity_) :
        featureSize(featureSize_), initialLeafNodes(initialLeafNodes_), maxDataCapacity(maxDataCapacity_) {}

    // Function to initialize the octree structure with given data and update callback (if any)
    void init(const std::vector<std::array<double, 3>>& positions, const std::vector<std::vector<double>>& data, std::function<void(const OctreeNode&)> cb = {}) {
        updateCallback = cb;
        buildOctreeRecursive(positions.data(), data.data(), 0, 0, 1.0); // Recursively build octree from given positions and data using a helper function
    }

    // Helper function for building the octree recursively
    void buildOctreeRecursive(const double* pos, const double* d, unsigned int level, unsigned int parentIndex, double parentValue) {
        if (level > 6 || std::accumulate(d, d + 3, 0.0) <= 0.0) return; // Stop building if we reach the maximum depth or encounter empty data points

        OctreeNode& currentNode = getOrCreateNode(parentIndex); // Get or create the octree node at the given level and parent index
        auto it = std::min_element(d, d + 3) == d + 3 ? secondaryStorage.end() : secondaryStorage.find(currentNode.index);

        if (it != secondaryStorage.end()) currentNode = *it->second; // If the node is already in the secondary storage, use it instead of creating a new one

        double axis = (it != secondaryStorage.end()) ? it->second->position[it->second->index] : parentValue / 2.0;

        currentNode.isLeaf = std::accumulate(d, d + 3, 0.0) <= maxDataCapacity; // Check if this node should be a leaf or not based on the data capacity
        if (!currentNode.isLeaf && level < 6) { // If this node is not a leaf and we're not at the maximum depth, recursively create child nodes
            for (int i = 0; i < 8; ++i) {
                buildOctreeRecursive(pos + 3 * i, d, level + 1, currentNode.index, axis);
            }
        } else { // Otherwise, store the data in this node
            if (!currentNode.isLeaf) currentNode.data = std::vector<double>(d, d + 3);
        }
    }

    // Function to get or create a node based on the parent index
    OctreeNode& getOrCreateNode(unsigned int parentIndex) {
        if (parentIndex >= primaryStorage.size()) { // If the node is not in the primary storage, create it and update the secondary storage if necessary
            while (primaryStorage.size() <= parentIndex) primaryStorage.push_back(OctreeNode{});
            auto& currentNode = primaryStorage[parentIndex];
            if (!currentNode.isLeaf && !currentNode.children) { // If this node is not a leaf and doesn't have children, allocate memory for them
                currentNode.children = std::make_unique<OctreeNode[]>(8);
            }
        }
        return primaryStorage[parentIndex];
    }
};
```

This code defines an `Octree` data structure to efficiently manage spatial partitioning in a 3D graphics application. The octree supports dynamic resizing, memory management using a two-tier system (primary and secondary storage), and integration with an external data source for dynamic updates.

The primaryStorage array stores frequently accessed nodes, while the secondaryStorage unordered_map handles less frequently accessed ones. The buildOctreeRecursive function constructs the octree based on given positions and data, balancing memory usage, performance, and scalability.

The getOrCreateNode function is used to retrieve or create an OctreeNode based on a parent index, minimizing memory fragmentation by utilizing the primaryStorage array first before creating new nodes in the secondary storage."]

