// Performance metrics logging system (placeholder)
void logPerformanceMetric(const std::string& move);

class MoveSelector {
public:
    void selectMove(std::function<void()> move1, std::function<void()> move2) {
        auto now = std::chrono::high_resolution_clock::now();
        auto duration = now - lastSelected;
        if (duration > std::chrono::seconds(9)) {
            lastSelected = now;
            selectedMove(move1, move2);
            logPerformanceMetric(getCurrentMove());
        }
    }

private:
    void selectedMove(std::function<void()> move1, std::function<void()> move2) {
        if (isRandom()) {
            (*move1)(); // execute chosen move
        } else {
            (*move2)(); // execute chosen move
        }
    }

    bool isRandom() const {
        static thread_local std::mt19937 generator(std::random_device{}());
        static thread_local std::uniform_int_distribution<> distribution(0, 1);
        return distribution(generator) == 0;
    }

    std::chrono::time_point<std::chrono::high_resolution_clock> lastSelected;
    mutable std::queue<std::function<void()>> movesQueue;

    void enqueueMove(std::function<void()> move) {
        std::unique_lock<std::mutex> lock(movesMutex);
        movesQueue.push(move);
    }

    std::string getCurrentMove() const {
        std::unique_lock<std::mutex> lock(movesMutex);
        if (!movesQueue.empty()) {
            auto move = movesQueue.front();
            movesQueue.pop();
            return (move == move1 ? "Move 1" : "Move 2");
        }
        return "No Move Selected";
    }

    std::mutex movesMutex;
    std::function<void()> move1, move2;
};
