['```csharp
using System;
using System.Collections.Generic;
using Newtonsoft.Json;
using System.IO;

public class RandomValueGenerator
{
    private Dictionary<string, Range> _ranges;

    public RandomValueGenerator()
    {
        _ranges = new Dictionary<string, Range>();
        LoadRangesFromFile();
    }

    [JsonIgnore]
    public IEnumerable<Range> Ranges => _ranges.Values;

    private void LoadRangesFromFile()
    {
        if (File.Exists("ranges.json"))
        {
            string json = File.ReadAllText("ranges.json");
            _ranges = JsonConvert.DeserializeObject<Dictionary<string, Range>>(json);
        }
    }

    private void SaveRangesToFile()
    {
        if (_ranges.Count > 0)
        {
            string json = JsonConvert.SerializeObject(_ranges, Formatting.Indented);
            File.WriteAllText("ranges.json", json);
        }
    }

    public void AddRange(string name, double min, double max, bool inclusiveUpperBound = true)
    {
        if (min >= max) throw new ArgumentOutOfRangeException(nameof(min), "Minimum value must be less than or equal to maximum value.");
        _ranges[name] = new Range(min, max, inclusiveUpperBound);
        SaveRangesToFile();
    }

    public double GenerateRandomValue(string name)
    {
        if (!_ranges.TryGetValue(name, out var range)) throw new KeyNotFoundException($"Range '{name}' not found.");
        return range.GenerateRandomValue();
    }

    private class Range
    {
        public Range(double min, double max, bool inclusiveUpperBound)
        {
            Min = min;
            Max = max;
            InclusiveUpperBound = inclusiveUpperBound;
        }

        public double Min { get; }
        public double Max { get; }
        public bool InclusiveUpperBound { get; }

        public double GenerateRandomValue()
        {
            if (InclusiveUpperBound)
            {
                return Random.Shared.NextDouble() * (Max - Min) + Min;
            }
            else
            {
                return Min + Random.Shared.NextDouble() * (Max - Min - (Min != Max));
            }
        }

        public override string ToString() => $"{nameof(Min)}: {Min}, {nameof(Max)}: {Max}, {nameof(InclusiveUpperBound)}: {InclusiveUpperBound}";
    }

    public override string ToString() => string.Join("\n", _ranges.Values);
}
```

