// Custom error codes
enum ErrorCodes {
    NO_ERROR = 0,
    FILE_NOT_FOUND = 1,
    INVALID_FILE_EXTENSION = 2,
    FILE_OPEN_FAILURE = 3,
    HEADER_VALIDATION_FAILURE = 4,
    MEMORY_ALLOCATION_FAILURE = 5
};

typedef struct {
    void* data;
    size_t size;
    char* type; // e.g., "json", "xml", "csv"
} ResourceItem;

typedef struct {
    ResourceItem** items;
    size_t count;
    size_t capacity;
} ResourceBundle;

// Load a resource bundle from a file. Returns the number of items in the bundle or an error code on failure.
int loadResourceBundle(const char* path, ResourceBundle* bundle) {
    FILE* file = fopen(path, "r");
    if (!file) return FILE_NOT_FOUND;

    // Determine file extension and select appropriate parser function
    const char* ext = strchr(path, '.');
    if (!ext) goto cleanup;
    ext++;

    if (strcmp(ext, "json") == 0) {
        // Implement JSON parsing logic here...
    } else if (strcmp(ext, "xml") == 0) {
        // Implement XML parsing logic here...
    } else if (strcmp(ext, "csv") == 0) {
        // Implement CSV parsing logic here...
    } else goto cleanup;

    char buffer[256];
    size_t header_length = 0;
    size_t content_length = 0;

    if (fgets(buffer, sizeof(buffer), file) == NULL) goto cleanup;

    // Validate the header and determine the content length
    for (size_t i = 0; buffer[i] != '\n'; ++i) {
        if (!isspace((unsigned char)buffer[i])) ++header_length;
        if (i + content_length > sizeof(buffer)) break;
        content_length++;
    }

    if (header_validation_failure()) goto cleanup;

    // Allocate memory for the bundle and items
    ResourceItem** items = malloc((bundle->capacity = 1) * sizeof(ResourceItem*));
    if (!items) goto cleanup;
    ResourceItem* item = items[0] = malloc(sizeof(ResourceItem));
    if (!item) goto cleanup;

    // Read the content into the item's data and set the type, size, etc.
    char* content = malloc(content_length);
    if (!content) goto cleanup;
    fseek(file, header_length, SEEK_SET);
    fread(content, content_length, 1, file);
    item->data = content;
    item->size = content_length;
    item->type = strdup("unknown"); // Set the type based on parsing logic...

    bundle->count = 1;

cleanup:
    if (file) fclose(file);
    if (bundle->items) free(bundle->items);
    if (item) {
        free(item->data);
        free(item);
    }
    return errno == EOF ? FILE_NOT_FOUND : errno;
}
