char* truncate_string(const char *input, size_t limit, bool truncate) {
    if (limit == 0 || limit < 1) {
        return NULL;
    }

    size_t input_len = strlen(input);

    if (truncate && input_len > limit - 1) {
        // Calculate the number of characters to be truncated
        size_t chars_to_remove = input_len - limit + 1;

        // Allocate memory for the new string and copy the first 'limit' characters
        char *new_str = malloc(limit);
        if (!new_str) {
            return NULL;
        }
        memcpy(new_str, input, chars_to_remove);

        // Null-terminate the new string
        new_str[chars_to_remove] = '\0';
    } else {
        size_t new_len = (truncate && input_len <= limit) ? input_len + 1 : input_len;
        char *new_str = malloc(new_len);
        if (!new_str) {
            return NULL;
        }

        // Copy the original string and append a slash if necessary
        memcpy(new_str, input, input_len);
        if (truncate && input_len > limit) {
            new_str[limit - 1] = '\0';
            new_str[input_len] = '/';
        } else if (!truncate && input_len == limit) {
            new_str[input_len] = '\0';
        }
    }

    return new_str;
}
```
