#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <libtiff/tiff.h>
#include <openssl/aes.h>
#include <openssl/evp.h>

typedef struct {
    int bits_per_sample;
    int sample_per_pixel;
    int extra_samples;
} ImageInfo;

ImageInfo processTIFFAndEncrypt(const char *file_path, const char *encryption_option) {
    TIFF *tif = TIFFOpen(file_path, "r");

    if (!tif) {
        fprintf(stderr, "Error: Could not open file %s\n", file_path);
        return (ImageInfo){0};
    }

    int sample_format = TIFFGetField(tif, TIFFSamplingFormat);
    switch (sample_format) {
        case 1: // unsigned byte
        case 3: // OSA-2, unsigned short
            break;
        case 2: // signed byte
        case 4: // unsigned short (big-endian)
        case 5: // signed short (big-endian)
        case 6: // unsigned long (big-endian)
        case 7: // signed long (big-endian)
            if (TIFFGetField(tif, TIFFBitsPerSample) != 8 &&
                TIFFGetField(tif, TIFFBitsPerSample) != 16) {
                fprintf(stderr, "Error: Unsupported number of bits per sample\n");
                TIFClose(tif);
                return (ImageInfo){0};
            }
            break;
        default:
            fprintf(stderr, "Error: Unsupported sampling format\n");
            TIFClose(tif);
            return (ImageInfo){0};
    }

    int bits_per_sample = TIFFGetField(tif, TIFFBitsPerSample)[0];
    int sample_per_pixel = TIFFGetFieldDefaulted(tif, TIFFSamplingFactor)[0];
    int extra_samples = 1; // Assuming only one pixel per sample for now

    if (TIFFGetField(tif, TIFFPhotometricInterpretation))
        extra_samples += TIFFGetField(tif, TIFFExtraSamples) / 2;

    unsigned char *image = NULL;
    size_t image_size = TIFFScanlineSize(tif);
    int rows = TIFFNumberOfDirectoryEntries(tif)-TIFFDefaultStripNumber;

    image = malloc(image_size * rows);
    if (!image) {
        fprintf(stderr, "Error: Failed to allocate memory for image\n");
        TIFClose(tif);
        return (ImageInfo){0};
    }

    if (TIFFReadEncodedTile(tif, 0, 0, rows, 1, &image[0]) != rows) {
        fprintf(stderr, "Error: Failed to read image data\n");
        free(image);
        TIFClose(tif);
        return (ImageInfo){0};
    }

    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *cipher = NULL;

    if (encryption_option && strlen(encryption_option) > 0) {
        cipher = EVP_get_cipherbyname(encryption_option);
        if (!cipher) {
            fprintf(stderr, "Error: Unsupported encryption operation\n");
            free(image);
            TIFClose(tif);
            return (ImageInfo){0};
        }

        ctx = EVP_CIPHER_CTX_new();
        int err = EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL);
        if (err) {
            fprintf(stderr, "Error: Failed to initialize encryption context\n");
            EVP_CIPHER_CTX_free(ctx);
            free(image);
            TIFClose(tif);
            return (ImageInfo){0};
        }
    }

    for (int i = 0; i < rows; ++i) {
        if (encryption_option && ctx) {
            size_t encrypted_size = image_size;
            unsigned char *encrypted = malloc(encrypted_size);
            if (!encrypted) {
                fprintf(stderr, "Error: Failed to allocate memory for encryption\n");
                EVP_CIPHER_CTX_free(ctx);
                free(image);
                TIFClose(tif);
                return (ImageInfo){0};
            }

            err = EVP_EncryptUpdate(ctx, encrypted, &encrypted_size, image + i * image_size, image_size);
            if (err) {
                fprintf(stderr, "Error: Failed to encrypt image data\n");
                free(encrypted);
                continue;
            }

            memcpy(image + i * image_size, encrypted, encrypted_size);
            free(encrypted);
        }
    }

    ImageInfo result = {bits_per_sample, sample_per_pixel, extra_samples};
    TIFClose(tif);
    free(image);
    return result;
}
