#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

char* generate_filename(const char* original) {
    size_t path_len = strrchr(original, '/') ? strlen(strchr(original, '/')) : 0;
    size_t base_name_len = strlen(original + path_len);
    size_t ext_len = strlen(strchr(original + base_name_len, '.')) + 1;

    char* base_name = malloc(base_name_len + ext_len);
    strncpy(base_name, original + path_len, base_name_len);
    base_name[base_name_len] = '\0';

    char* extension = strchr(original + base_name_len, '.') ? (char*)calloc(ext_len, sizeof(char)) : (char*)calloc(1, sizeof(char));
    strncpy(extension, original + base_name_len + (ext_len > 1), ext_len);

    int sequence = atoi(base_name);
    char* new_sequence = malloc(4);
    sprintf(new_sequence, "%04d", sequence++);

    size_t new_filename_len = path_len + strlen(new_sequence) + strlen(extension);
    char* new_filename = malloc(new_filename_len + 1);
    strncpy(new_filename, original, path_len);
    strcat(new_filename, new_sequence);
    strcat(new_filename, extension);

    free(base_name);
    free(extension);

    // Add file type if provided
    char* file_type = ".txt";
    size_t file_type_len = strlen(file_type);
    new_filename_len += file_type_len;
    new_filename = realloc(new_filename, new_filename_len + 1);
    strcat(new_filename, file_type);

    return new_filename;
}
