    randomize_IV(iv, sizeof(iv));

    PKCS5_PBKDF2_HMAC(EVP_aes_256_cbc(), password, password_len, salt, iterations, derived_key, sizeof(derived_key));
    AES_set_encrypt_key(derived_key, 256, &key);

    EVP_CIPHER_CTX_init(ctx);
    EVP_CIPHER_CTX_set_cipher(ctx, EVP_aes_256_cbc());
    EVP_CIPHER_CTX_set_padding(ctx, 1);
    EVP_CIPHER_CTX_set_key(ctx, &key);
    EVP_CIPHER_CTX_set_iv(ctx, iv);

    *out = malloc(sizeof(AESS256_ctx));
    (*out)->cipher = key;
    (*out)->iv = iv;

    ret = 1;

cleanup:
    if (ret == 0) clean_up(*out);
    EVP_CIPHER_CTX_free(ctx);

    return ret;
}

int aes256_cbc_encrypt(const AESS256_ctx *ctx, unsigned char *data, size_t data_len, unsigned char **out) {
    EVP_CIPHER_CTX *ctx_ = ctx->cipher;
    int ret = 0;

    *out = malloc(data_len + AES_BLOCK_SIZE);
    memset(*out, 0, data_len + AES_BLOCK_SIZE);

    size_t total = 0;
    while (total < data_len) {
        int len = data_len - total > AES_BLOCK_SIZE ? AES_BLOCK_SIZE : data_len - total;
        int encrypted_len = EVP_CipherUpdate(*ctx_, *out + total, &len, data + total, len);
        if (encrypted_len < 0) {
            ret = 0;
            break;
        }
        total += encrypted_len;
    }

    if (ret > 0) {
        memcpy(ctx_->iv, (*out), AES_BLOCK_SIZE);
        ret = 1;
    }

cleanup:
    return ret;
}

int aes256_cbc_decrypt(AESS256_ctx *ctx, const unsigned char *data, size_t data_len, unsigned char **out) {
    EVP_CIPHER_CTX *ctx_ = ctx->cipher;
    int ret = 0;

    if (memcmp(ctx_->iv, data, AES_BLOCK_SIZE)) {
        free(ctx_->iv);
        memcpy(ctx_->iv, data, AES_BLOCK_SIZE);
    }

    *out = malloc(data_len);
    memset(*out, 0, data_len);

    size_t total = 0;
    while (total < data_len) {
        int len = data_len - total > AES_BLOCK_SIZE ? AES_BLOCK_SIZE : data_len - total;
        int decrypted_len = EVP_CipherUpdate(*ctx_, *out + total, &len, data + total + AES_BLOCK_SIZE, len);
        if (decrypted_len < 0) {
            ret = 0;
            break;
        }
        total += decrypted_len;
    }

    if (ret > 0) ret = 1;

cleanup:
    return ret;
}
```

This code provides an AES-256-CBC cipher initialization function, `aes256_cbc_init`, that takes a password, a number of iterations for PBKDF2 key derivation, and a salt. It generates a random IV and ensures it is securely stored alongside the ciphertext for decryption. The code also includes functions to encrypt and decrypt data in blocks using `aes256_cbc_encrypt` and `aes256_cbc_decrypt`, respectively. Finally, there is a cleanup function to release resources when the cipher is no longer needed.']

