        return 1;
    }

    if (avcodec_open2(pCodecCtx, pCodec, NULL) < 0) {
        fprintf(stderr, "Failed to open codec.\n");
        return 1;
    }

    pFrame = av_frame_alloc();

    y_size = pCodecCtx->width * pCodecCtx->height;
    cb_size = y_size / 2;

    out_buffer = (uint8_t *)av_malloc(y_size + cb_size + AV_INPUT_BUFFER_PADDING_SIZE);

    while (av_read_frame(pFormatCtx, &packet) >= 0) {
        if (packet.stream_index == 0) {
            ret = avcodec_decode_video2(pCodecCtx, pFrame, &frame_finished, &packet);
            if (ret < 0) {
                fprintf(stderr, "Error decoding video frame.\n");
                break;
            }
            if (frame_finished) {
                SwsContext *sws_ctx = sws_getContext(pCodecCtx->width, pCodecCtx->height,
                                                     pCodecCtx->pix_fmt, pCodecCtx->width,
                                                     pCodecCtx->height, AV_PIX_FMT_RGB24, SWS_FAST_BILINEAR, NULL, NULL, NULL);
                uint8_t *rgb_frame = malloc(pFrame->size);
                sws_scale(sws_ctx, (const uint8_t * const *)pFrame->data, pFrame->linesize, 0, pCodecCtx->height, rgb_frame, pFrame->width);
                jpeg_compress_struct_init(&cjc);
                jpeg_error_init(&jerr);
                jpeg_compress_stderr(&cjc, &jerr);
                jpeg_set_quality(&cjc, 80, true);
                struct jpeg_marker_segment markers[1] = {{0xFFD8, 0xFFEOI}};
                cjc.image_width = pCodecCtx->width;
                cjc.image_height = pCodecCtx->height;
                cjc.in_color_space = JCS_RGB;
                jpeg_mem_dest(&cjc, (void *)out_buffer, y_size + cb_size);
                jpeg_write_scanlines(&cjc, &rgb_frame, 1);
                fwrite(out_buffer, 1, cjc.next_scanline - 1, thumbnail_fileptr);
                free(rgb_frame);
                sws_freeContext(sws_ctx);
            }
        }
    }

    av_free_packet(&packet);
    avcodec_close(pCodecCtx);
    fclose(thumbnail_fileptr);
    avformat_free_context(pFormatCtx);
    av_frame_free(&pFrame);
    free(out_buffer);

    return 0;
}
