#include <fcntl.h>
#include <stdlib.h>
#include <string.h>

#define MAX_PROCESSES 10
pid_t current_processes = 0;

void log(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    int fd = open("logfile.txt", O_WRONLY | O_APPEND | O_CREAT, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
    char time_string[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(time_string, sizeof(time_string), "%Y-%m-%d %H:%M:%S ", timeinfo);

    write(fd, time_string, strlen(time_string));
    write(fd, message, strlen(message));
    close(fd);
}

pid_t run_command_background(const char *command) {
    pid_t pid = fork();

    if (pid < 0) {
        log("Error: Fork failed");
        return -1;
    } else if (pid == 0) {
        setsid(); // detach from terminal
        dup2(open("/dev/null", O_RDONLY), STDIN_FILENO);
        dup2(open("/dev/null", O_WRONLY), STDOUT_FILENO);
        dup2(open("/dev/null", O_WRONLY), STDERR_FILENO);
        execlp(command, command, NULL);
        log("Error: Execution failed");
        exit(-1);
    } else {
        current_processes++;
        if (current_processes > MAX_PROCESSES) {
            waitpid(pid, NULL, 0); // block and wait for the child process to finish
            current_processes--;
        }
        return pid;
    }
}

int main() {
    signal(SIGINT, handle_sigint);

    // replace command_list with your array of commands
    char *command_list[] = {"command1", "command2", "command3"};

    for (size_t i = 0; i < sizeof(command_list) / sizeof(char*); ++i) {
        pid_t pid = run_command_background(command_list[i]);
        if (pid == -1) return -1;
    }

    while (current_processes > 0) {
        pid_t wstatus;
        pid_t pid = waitpid(-1, &wstatus, WNOHANG);
        if (pid > 0) {
            current_processes--;
            log(ctime(&wstatus)); // print command completion time in the log file
        }
    }

    return 0;
}

void handle_sigint() {
    while (current_processes > 0) {
        kill(getpid(), SIGKILL);
        pause(); // wait for child processes to terminate
    }
    exit(0);
}
