import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ExecutionException;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.logging.Handler;
import org.apache.commons.io.FileUtils;
import org.apache.commons.lang3.StringUtils;
import org.slf4j.LoggerFactory;
import com.google.common.base.Joiner;
import com.google.common.util.concurrent.ListenableFuture;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

public class CommandRunner {
    private static final Logger LOGGER = LoggerFactory.getLogger(CommandRunner.class);
    private static final int MAX_COMMAND_LENGTH = 1024 * 8; // 8KB
    private static final long TIMEOUT_MS = TimeUnit.MINUTES.toMillis(5);
    private static final long MEMORY_THRESHOLD = 1024L * 1024L * 30L; // 30MB
    private static final Joiner JOINER = Joiner.on("\n");
    private static final OkHttpClient httpClient = new OkhttpClientBuilder().build();

    public void run(String fileToDelete, String command) throws IOException, InterruptedException, ExecutionException {
        if (Files.exists(Paths.get(fileToDelete))) {
            Files.deleteIfExists(Paths.get(fileToDelete));
        }

        ProcessBuilder pb = new ProcessBuilder(command.split("\\s+"));
        pb.redirectErrorStream(true);

        ExecutorService exec = Executors.newSingleThreadExecutor();
        List<Future<Process>> processes = exec.invokeAll(pb::start);

        try {
            for (Future<Process> future : processes) {
                Process process = future.get(TIMEOUT_MS, TimeUnit.MILLISECONDS);

                BufferedReader inputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
                BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

                logOutputToFile(inputReader, process, "output");
                logOutputToFile(errorReader, process, "error");

                long currentMemory = Runtime.getRuntime().totalMemory() - Runtime.getRuntime().freeMemory();
                if (currentMemory > MEMORY_THRESHOLD) {
                    LOGGER.warning("Memory usage exceeded threshold: " + currentMemory + " bytes");
                }

                int exitCode = process.waitFor();
                if (exitCode != 0) {
                    String message = "Command execution failed with exit code: " + exitCode;
                    LOGGER.log(Level.SEVERE, message);
                    throw new RuntimeException(message);
                }
            }
        } catch (TimeoutException e) {
            String message = "Command timed out after " + TIMEOUT_MS / 1000 + " seconds";
            LOGGER.log(Level.SEVERE, message);
            throw new RuntimeException(message);
        } finally {
            exec.shutdownNow();
        }
    }

    private void logOutputToFile(BufferedReader reader, Process process, String logType) throws IOException {
        if (reader != null) {
            String line;
            StringBuilder output = new StringBuilder();
            while ((line = reader.readLine()) != null) {
                output.append(line).append("\n");
            }

            Path logFilePath = Paths.get("command_" + logType + "_log.txt");
            if (Files.exists(logFilePath)) {
                FileUtils.appendLines(logFilePath, output.toString().split("\n"));
            } else {
                Files.createFile(logFilePath);
                FileUtils.writeStringToFile(logFilePath, output.toString(), "UTF-8");
            }
        }
    }

    // External logging service integration (assuming it uses the OkHttpClient for requests)
    private class OkhttpClientBuilder {
        OkHttpClient build() {
            return new OkHttpClient.Builder()
                    .addInterceptor(new LoggingInterceptor())
                    .build();
        }
    }

    // Implement LoggingInterceptor here based on the requirements of your logging service
}
