#include <stdbool.h>
#include <pthread.h>
#include <string.h>
#include <funcptr/function_ptr.h> // For thread-safe function pointers

typedef struct {
    char *token;
    struct connection *conn;
    void (*callback)(struct session*);
    pthread_mutex_t lock;
} Session;

int validate_and_initialize(Session *session) {
    if (!session || !session->token || !session->conn || !session->callback) {
        return -1;
    }

    if (!session->conn->title) {
        return -2;
    }

    // Thread-safe function pointer validation using funcptr library
    if (!funcptr_is_valid(session->callback)) {
        return -3;
    }

    // Optimized for performance and concurrent access with a mutex lock
    pthread_mutex_lock(&session->lock);
    bool session_changed = false;

    if (!session->token) {
        session->token = calloc(1, MAX_TOKEN_LENGTH + 1);
        if (!session->token) {
            session_changed = true;
            pthread_mutex_unlock(&session->lock);
            return -4;
        }
    }

    if (strlen(session->token) == 0) {
        session_changed = true;
    }

    // Handle race conditions by ensuring that the callback function is only updated if no other thread changed the session state
    if (session_changed && funcptr_is_equal(session->callback, session->_callback)) {
        session->_callback = NULL;
        session->_callback = session->callback;
    }

    pthread_mutex_unlock(&session->lock);
    return 0;
}
