#include <ctype.h>

bool validate_oauth2_token(const char *json_str) {
    cJSON *root;
    root = cJSON_Parse(json_str);

    if (!root) {
        // JSON parsing failed, return false
        return false;
    }

    cJSON *access_token = cJSON_GetObjectItemCase(root, "access_token");
    cJSON *expires_in = cJSON_GetObjectItemCase(root, "expires_in");
    cJSON *token_type = cJSON_GetObjectItemCase(root, "token_type");
    cJSON *refresh_token = cJSON_GetObjectItemCase(root, "refresh_token");

    if (!access_token || !expires_in || !token_type) {
        // Missing required fields, return false
        cJSON_Delete(root);
        return false;
    }

    if (strcmp(token_type->valuestring, "Bearer") != 0) {
        // Incorrect token type, return false
        cJSON_Delete(root);
        return false;
    }

    if (expires_in->type != cJSON_Number) {
        // Invalid expires_in type, return false
        cJSON_Delete(root);
        return false;
    }

    if ((expires_in->valuedouble <= 0)) {
        // Expiration time is not positive, return false
        cJSON_Delete(root);
        return false;
    }

    const char *access_token_str = access_token->valuestring;
    if (strlen(access_token_str) >= 64 || strchr(access_token_str, '.')) {
        // C reserved keyword or invalid token character, return false
        cJSON_Delete(root);
        return false;
    }

    const char *refresh_token_str = refresh_token ? refresh_token->valuestring : "";
    if (strlen(refresh_token_str) > 1024) {
        // Refresh token exceeds the limit, return false
        cJSON_Delete(root);
        return false;
    }

    bool nested_valid = true;
    cJSON_ArrayIt it = cJSON_GetArrayIterator(root);
    while (!cJSON_ArrayEnd(it)) {
        if (it.val->type & cJSON_Object) {
            nested_valid &= validate_oauth2_token(it.val->valuestring);
        }
        cJSON_NextItem(&it);
    }

    cJSON_Delete(root);

    return nested_valid;
}
