        {
            while (!reader.EndOfStream)
            {
                lines = reader.BufferedReadLines(8192);

                foreach (var line in lines)
                {
                    enqueueLine(line);
                }
            }
        }
        catch (IOException ex)
        {
            Console.WriteLine($"Error reading file: {ex.Message}");
        }

        tasks = lines.AsParallel().WithDegreeOfParallelism(options.MaxDegreeOfParallelism).Select(processLineTaskFactory).ToList();
        Task.WaitAll(tasks.ToArray());
    }

