    public class CacheItemPolicy : CacheItemPolicyBase
    {
        public CacheItemPolicy(double absoluteExpiration, TimeSpan slidingExpiration)
            : base()
        {
            AbsoluteExpiration = DateTimeOffset.Now.AddSeconds(absoluteExpiration);
            SlidingExpiration = slidingExpiration;
        }

        public CacheItemPolicy(TimeSpan slidingExpiration)
            : base()
