using System.IO.Compression;
using System.Runtime.Serialization.Formatters.Binary;
using System.Security.Cryptography;

public class MyDataStructure
{
    public int SomeProperty { get; set; }
    // Add other properties as needed...
}

public static T LoadDeserializedData<T>(string filePath) where T : new()
{
    using (FileStream stream = File.OpenRead(filePath))
    using (var archive = new GZipStream(stream, CompressionMode.Decompress))
    {
        BinaryFormatter formatter = new BinaryFormatter();
        formatter.AssemblyFormat = System.Runtime.Serialization.Formatters.FormatterAssemblyStyle.Simple;

        var header = formatter.Deserialize(archive);
        if (!(header is FileHeader fileHeader))
            throw new InvalidDataException("Invalid file header.");

        using (HashAlgorithm sha256 = SHA256.Create())
        {
            if (!CryptoHash(fileHeader, sha256).SequenceEqual(fileHeader.Checksum))
                throw new Exception("Deserialized data checksum mismatch.");
        }

        return formatter.Deserialize<T>(archive);
    }
}

public class FileHeader
{
    public byte[] Checksum { get; set; }
    // Add other properties as needed...
}

private static byte[] CryptoHash(object obj, HashAlgorithm algorithm)
{
    using (var ms = new MemoryStream())
    {
        var formatter = new BinaryFormatter();
        formatter.Serialize(ms, obj);
        return algorithm.ComputeHash(ms.ToArray());
    }
}
```
