const axios = require('axios');
const FormData = require('form-data');
const fs = require('fs');
const path = require('path');
const crypt = require('crypto');
const mysql = require('mysql');
const dotenv = require('dotenv');

// Load environment variables from .env file
dotenv.config();

// Database connection configuration
const dbConnection = mysql.createConnection({
  host: process.env.DB_HOST,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  database: process.env.DB_NAME,
});

function validateURL(url) {
  const urlPattern = /^(?:http|https):\/\/[^\s]+$/;
  return urlPattern.test(url);
}

async function uploadFileToCloudStorage(filePath, cloudStorageUrl) {
  try {
    const response = await axios.post(cloudStorageUrl, filePath, {
      headers: {
        'Content-Type': fs.statSync(filePath).mime,
      },
    });

    if (!response.data.key) {
      throw new Error('Failed to upload the file.');
    }

    const metadata = {
      key: response.data.key,
      size: fs.statSync(filePath).size,
      mimeType: fs.statSync(filePath).mime,
      created_at: new Date(),
    };

    await saveMetadataToDatabase(metadata);

    const uniqueFilename = crypt.createHash('sha256').update(JSON.stringify(metadata)).digest('hex');
    const publicUrl = `${process.env.CLOUD_STORAGE_PUBLIC_URL}/${uniqueFilename}`;

    return { publicUrl, metadata };
  } catch (error) {
    console.error(`Error uploading file: ${error.message}`);
    throw error;
  }
}

function saveMetadataToDatabase(metadata) {
  return new Promise((resolve, reject) => {
    dbConnection.connect((err) => {
      if (err) {
        console.error(`Error connecting to the database: ${err.message}`);
        reject(err);
      } else {
        dbConnection.query(
          'INSERT INTO files SET ?',
          metadata,
          (insertErr, result) => {
            if (insertErr) {
              console.error(`Error saving metadata to database: ${insertErr.message}`);
              reject(insertErr);
            } else {
              resolve();
            }
          }
        );
      }
    });
  });
}

async function uploadAndHandleUrl(url) {
  if (!validateURL(url)) {
    throw new Error('Invalid URL.');
  }

  const filePath = await downloadFileFromUrl(url);

  try {
    return await uploadFileToCloudStorage(filePath, process.env.CLOUD_STORAGE_UPLOAD_URL);
  } catch (error) {
    console.error(`Error processing URL: ${error.message}`);
    fs.unlinkSync(filePath); // Remove the downloaded file on error
    throw error;
  }
}

function downloadFileFromUrl(url, dest) {
  return new Promise((resolve, reject) => {
    const file = fs.createWriteStream(dest || path.join(__dirname, 'downloads', path.basename(url)));

    axios.get(url, { responseType: 'stream' })
      .then(response => {
        response.data.pipe(file);
        file.on('finish', () => resolve(file.path));
      })
      .catch(err => reject(err));
  });
}
```

Please note that this code requires the following packages to be installed:
