- dotenv

Make sure you have the necessary environment variables set for your specific database, cloud storage service and public URLs."]

["```javascript
const { exec, spawn } = require('child_process');
const fs = require('fs');
const axios = require('axios'); // For sending notifications

function shellExec(command, filePath, onProgress, onServiceStatusChange) {
  if (!command || !filePath) throw new Error('Invalid arguments: command and filePath are required.');

  let buffer = Buffer.from([]);
  let bytesRead = 0;
  let totalBytes = 0;
  let serviceRunning = false;

  function processStream(childProcess) {
    childProcess.stdout.on('data', (data) => {
      buffer = Buffer.concat([buffer, data]);
      const chunkIndex = bytesRead < buffer.length ? bytesRead : totalBytes + 1;
      if (chunkIndex % 1048576 === 0 && onProgress) onProgress(chunkIndex / 1048576);
      bytesRead += data.length;
      totalBytes += data.length;
    });

    childProcess.stderr.on('data', (data) => {
      console.error(`Error: ${data.toString()}`);
    });

    childProcess.on('close', (code) => {
      if (code !== 0) throw new Error(`Shell command returned non-zero exit code: ${code}`);
      // Return result and status report to the caller
      return { result: buffer.toString(), error: null, statusReport: `Processed ${totalBytes} bytes in total` };
    });
  }

  function startStopService(command, delay) {
    const serviceCmd = `${command} start`.trim();
    setTimeout(() => {
      exec(serviceCmd, (error, stdout, stderr) => {
        if (error) throw error;
        if (!stderr) serviceRunning = true;
      });
      if (onServiceStatusChange) onServiceStatusChange({ status: serviceRunning ? 'running' : 'stopped', command });
    }, delay);
  }

  // Check if file exists and is readable before executing the command
  fs.access(filePath, fs.constants.F_OK | fs.constants.R_OK, (error) => {
    if (error) throw new Error(`File ${filePath} does not exist or is not readable.`);

    const options = {
      encoding: 'buffer',
      shell: true,
    };

    const commandParts = command.split(' ');
    let args = [commandParts[0]];
    if (commandParts.length > 1) args.push(...commandParts.slice(1));
    if (args.includes('<')) args.splice(args.indexOf('<'), 1, filePath);

    const commandWithArgs = args.join(' ');

    const childProcess = spawn(commandParts[0], args);
    processStream(childProcess);

    // If the command includes >, it means we should read from the command output instead of a file
    if (args.includes('>')) {
      childProcess.stdin.end();
    } else {
      const stream = fs.createReadStream(filePath);
      stream.pipe(childProcess.stdin, { end: false });
      stream.on('end', () => childProcess.stdin.end());
    }

    if (serviceRunning) startStopService(command, Math.floor(Math.random() * 5000));
  });
}

// For sending notifications when the service is stopped
function sendNotificationOnServiceStop(message) {
  axios.post('https://your-messaging-system-url', message);
}
```

Usage:

