class GraphManipulator {
  constructor(numVertices, numEdges) {
    this.numVertices = numVertices;
    this.numEdges = numEdges;
  }

  // Generate a graph with specified number of vertices and edges
  async generateGraph() {
    const { GraphDatabase } = require('nexus');
    let db = new GraphDatabase();

    try {
      await db.open();

      for (let i = 0; i < this.numVertices; i++) {
        const properties = { id: i, label: 'Vertex' };
        const vertex = await db.createNode(properties);
      }

      for (let i = 0; i < this.numEdges; i++) {
        const from = Math.floor(Math.random() * this.numVertices);
        const to = Math.floor(Math.random() * this.numVertices);
        const properties = { weight: Math.random() };
        await db.createEdge({ from, to }, properties);
      }

    } catch (error) {
      console.error('Error generating graph:', error);
    } finally {
      try {
        await db.close();
      } catch (error) {
        console.error('Error closing database:', error);
      }
    }
  }

  // Execute a shell command through child_process and display the output on the web interface
  async executeCommand(command) {
    try {
      const { exec } = require('child_process');

      return new Promise((resolve, reject) => {
        exec(command, (error, stdout, stderr) => {
          if (error) {
            console.error(`Error executing command: ${error}`);
            reject(error);
          } else {
            resolve({ stdout, stderr });
          }
        });
      });
    } catch (error) {
      console.error('Error executing command:', error);
    }
  }
}
