use std::env;
use std::fs::File;
use std::io::{self, Write};
use std::path::PathBuf;
use std::sync::Mutex;

struct DataStore {
    data_store_path: PathBuf,
    sub_directories: Vec<(PathBuf, String)>,
}

impl DataStore {
    fn new() -> Self {
        let mut data_store = Self {
            data_store_path: Default::default(),
            sub_directories: Default::default(),
        };
        if let Ok(data_store_path) = env::var("DATASTORE_PATH") {
            match Path::new(&data_store_path).exists() {
                true => {
                    if data_store_path.is_dir() {
                        data_store.data_store_path = data_store_path;
                    } else {
                        eprintln!("Warning: DATASTORE_PATH is not a directory, attempting to create one.");
                        if let Err(e) = std::fs::create_dir_all(&data_store_path) {
                            eprintln!("Error creating directory: {}", e);
                        }
                    }
                }
                false => {
                    let cwd = std::env::current_dir().unwrap();
                    data_store.data_store_path = cwd.join("datastore");
                    if let Err(e) = std::fs::create_dir_all(&data_store.data_store_path) {
                        eprintln!("Error creating directory: {}", e);
                    } else {
                        set_env("DATASTORE_PATH", &data_store.data_store_path.to_str().unwrap());
                    }
                }
            }
        } else {
            let cwd = std::env::current_dir().unwrap();
            data_store.data_store_path = cwd.join("datastore");
            if let Err(e) = std::fs::create_dir_all(&data_store.data_store_path) {
                eprintln!("Error creating directory: {}", e);
            } else {
                set_env("DATASTORE_PATH", &data_store.data_store_path.to_str().unwrap());
            }
        }

        data_store
    }

    fn create_sub_directory(&mut self, index: usize) {
        let sub_dir_name = format!("datastore_sub_{}", index);
        let sub_dir_path = self.data_store_path.join(sub_dir_name);
        if !sub_dir_path.exists() {
            if let Err(e) = std::fs::create_dir_all(&sub_dir_path) {
                eprintln!("Error creating sub-directory: {}", e);
            } else {
                let env_var_name = format!("DATASTORE_PATH_SUB_{}", index);
                set_env(env_var_name.as_str(), &sub_dir_path.to_str().unwrap());
                self.sub_directories.push((sub_dir_path, env_var_name));
            }
        }
    }
}

fn set_env(key: &str, value: &str) {
    let key_value = format!("{}={}", key, value);
    if let Ok(_) = env::set_var(key, value) {
        let mut file = File::create(".env").unwrap();
        write!(file, "{}", key_value).unwrap();
    }
}

impl Drop for DataStore {
    fn drop(&mut self) {
        for (path, _) in &self.sub_directories {
            if path.exists() {
                if let Err(e) = remove_dir_all(path) {
                    eprintln!("Error deleting sub-directory: {}", e);
                }
            }
        }

        if self.data_store_path.exists() {
            if let Err(e) = remove_dir_all(&self.data_store_path) {
                eprintln!("Error deleting data store directory: {}", e);
            }
        }
    }
}

fn remove_dir_all(path: &Path) -> io::Result<()> {
    std::fs::remove_dir_all(path)
}

fn main() {
    let mut data_store = DataStore::new();

    // Add sub-directories if command line arguments are provided.
    if let Some(args) = std::env::args().skip(1) {
        for (index, arg) in args.iter().enumerate() {
            match arg.parse::<usize>() {
                Ok(index) => data_store.create_sub_directory(index),
                Err(_) => eprintln!("Invalid index for creating sub-directory: {}", arg),
            }
        }
    }
}
```

This Rust code creates a `DataStore` struct that manages the main data store directory and its subdirectories. The `new()` function initializes the data store by checking for the existence of the `DATASTORE_PATH` environment variable, ensuring it points to an existing directory if set, or creating one in the current working directory otherwise.

Subdirectories can be created using the `create_sub_directory()` method, which is called with the index of the subdirectory starting from 0 when command-line arguments are provided. The function also supports handling concurrent access safely and ensures all operations are idempotent.

When the DataStore instance goes out of scope (e.g., when the program exits), it cleans up by removing the data store directory and its subdirectories using the `Drop` trait implementation.']

