import json
import importlib
from abc import ABC, abstractmethod
from typing import Any, Dict, Type

class JSONProcessor(ABC):
    @abstractmethod
    def serialize(self, data: Any) -> str:
        pass

    @abstractmethod
    def deserialize(self, json_data: str) -> Any:
        pass

class CoreJSONProcessor(JSONProcessor):
    def __init__(self, parser=json.JSONDecoder, serializer=json.dumps):
        self._parser = parser
        self._serializer = serializer

    def serialize(self, data: Any) -> str:
        return self._serializer(data)

    def deserialize(self, json_data: str) -> Any:
        return self._parser.raw_decode(json_data)

class JSONProcessorFactory:
    _factories = {}

    @staticmethod
    def register(processor_id: str, FactoryFunction: Type[JSONProcessor]):
        JSONProcessorFactory._factories[processor_id] = FactoryFunction

    @staticmethod
    def create(processor_id: str, **kwargs) -> JSONProcessor:
        FactoryFunction = JSONProcessorFactory._factories.get(processor_id)
        if not FactoryFunction:
            raise ValueError(f"Unknown processor id: {processor_id}")

        return FactoryFunction(**kwargs)

def load_json_processor_module(module_name):
    module = importlib.import_module(module_name)
    for name, obj in vars(module).items():
            if issubclass(obj, JSONProcessor):
                JSONProcessorFactory.register(name, obj)

if __name__ == "__main__":
    # Load external json processors
    load_json_processor_module("path.to.external.json.processors")

    # Usage example
    custom_processor = JSONProcessorFactory.create("custom_processor", parser=CustomJSONParser())
    data = {"key": "value"}
    json_data = custom_processor.serialize(data)
    recovered_data = custom_processor.deserialize(json_data)
```

