#include <string.h>

typedef struct {
    AES_KEY aes;
    char *filename;
} Context;

Context* init_context(const char *password) {
    unsigned char key[AES_BLOCK_SIZE];
    SHA1_CTX ctx;
    SHA1_Init(&ctx);
    SHA1_Update(&ctx, password, strlen(password));
    SHA1_Final(key, &ctx);

    AES_KEY aes_key;
    AES_set_encrypt_key(key, 256, &aes_key);
    AES_KEY *cipher = malloc(sizeof(AES_KEY));
    memcpy(cipher, &aes_key, sizeof(AES_KEY));

    const char *filename = get_modified_filename("original_file.txt"); // Assuming this is a separate function
    Context *context = malloc(sizeof(Context));
    context->aes = *cipher;
    context->filename = filename;
    return context;
}

char* get_modified_filename(const char *original) {
    size_t len = strlen(original);
    if (len <= 3) return original; // If the filename has less than 4 characters, it is assumed to be an error and no extension is added.

    size_t dot_index = len - 4; // Assuming the extension starts from the last four characters
    const char *extension = &original[dot_index];

    int num_digits = 0;
    for (size_t i = 0; i < 3 && dot_index + i < len; ++i) {
        if (isdigit(extension[i]))
            num_digits++;
    }

    char new_ext[5] = ".enc"; // Assuming the encrypted file will always have .enc extension
    snprintf(new_ext + num_digits, 4 - num_digits, "%d", atoi(&original[len-4])); // Adding digits to the extension if any
    new_ext[num_digits + 4] = '\0'; // Null terminating the extension string

    char *modified = malloc(strlen(original) + strlen(new_ext) - num_digits);
    strncpy(modified, original, len - num_digits);
    strcat(modified, new_ext);
    return modified;
}

void free_context(Context *ctx) {
    if (ctx == NULL) return;
    free(ctx->filename);
    free(ctx);
}
