#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/evp.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <sys/mman.h>
#include <time.h>
#include <unistd.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    AES_KEY key;
    char *iv, *ciphertext, *plaintext;
    size_t len;
} EncryptContext;

void generate_salt(unsigned char *out, size_t len) {
    if (RAND_bytes(out, len)) {
        memcpy(out, time(NULL), sizeof(time_t));
        RAND_fill(out + sizeof(time_t), len - sizeof(time_t));
    }
}

void pkcs7_padding(unsigned char *buf, size_t *blen) {
    size_t block_size = AES_BLOCK_SIZE;
    size_t padding = block_size - (*blen % block_size);
    memset(&buf[*blen], padding, padding);
    *blen += padding;
}

void pkcs7_unpadding(unsigned char *buf, size_t *blen) {
    size_t block_size = AES_BLOCK_SIZE;
    size_t padding = buf[*blen - 1];
    if (padding > block_size || *blen < padding + 1) return;
    (*blen) -= padding;
}

EncryptContext *encrypt_init(const EVP_CIPHER *cipher, unsigned char *passphrase, size_t passphrase_len, size_t iterations, unsigned char *salt, size_t salt_len) {
    EncryptContext *ctx = malloc(sizeof(EncryptContext));
    if (!ctx || !EVP_CIPHER_CTX_init(&(ctx->ctx))) {
        free(ctx);
        return NULL;
    }
    if (1 != EVP_EncryptInit_ex(ctx->ctx, cipher, NULL, passphrase, salt, iterations)) {
        EVP_CIPHER_CTX_cleanup(&(ctx->ctx));
        free(ctx);
        return NULL;
    }
    AES_set_encrypt_key((const unsigned char *)passphrase, key_len(cipher), &(ctx->key));
    ctx->iv = malloc(AES_BLOCK_SIZE);
    if (!RAND_bytes(ctx->iv, AES_BLOCK_SIZE)) {
        EVP_CIPHER_CTX_cleanup(&(ctx->ctx));
        free(ctx->iv);
        free(ctx);
        return NULL;
    }
    return ctx;
}

void encrypt_file(const char *filename, const EncryptContext *ctx, const void *data, size_t data_len) {
    FILE *fp = fopen(filename, "ab");
    if (!fp) return;

    size_t iv_len = AES_BLOCK_SIZE;
    unsigned char iv[iv_len];
    memcpy(iv, ctx->iv, iv_len);
    fwrite(iv, 1, iv_len, fp);

    void *map = mmap(NULL, data_len + iv_len, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!map) {
        fclose(fp);
        return;
    }

    memcpy((char *)map + iv_len, data, data_len);

    size_t plaintext_len = data_len + iv_len;
    ctx->plaintext = malloc(plaintext_len);
    if (!ctx->plaintext) {
        munmap(map, data_len + iv_len);
        fclose(fp);
        return;
    }

    memcpy(ctx->plaintext, (char *)map, plaintext_len);
    pkcs7_padding((unsigned char *)ctx->plaintext + AES_BLOCK_SIZE, &ctx->len);

    void *ciphertext = malloc(plaintext_len);
    if (!ciphertext) {
        free(ctx->plaintext);
        munmap(map, data_len + iv_len);
        fclose(fp);
        return;
    }

    if (1 != EVP_EncryptUpdate(&(ctx->ctx), (unsigned char *)ciphertext, &ctx->len, ctx->plaintext, plaintext_len)) {
        free(ctx->plaintext);
        free(ciphertext);
        munmap(map, data_len + iv_len);
        fclose(fp);
        return;
    }

    fwrite(ciphertext, 1, ctx->len, fp);
    free(ciphertext);

    if (1 != EVP_EncryptFinal_ex(&(ctx->ctx), ciphertext, &ctx->len)) {
        free(ctx->plaintext);
        munmap(map, data_len + iv_len);
        fclose(fp);
        return;
    }

    fwrite(ciphertext, 1, ctx->len, fp);
    free(ciphertext);
    munmap(map, data_len + iv_len);
    fclose(fp);
}

void decrypt_file(const char *filename, const EncryptContext *ctx, void **data) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) return;

    size_t iv_len = AES_BLOCK_SIZE;
    unsigned char iv[iv_len];
    fread(iv, 1, iv_len, fp);
    memcpy(ctx->iv, iv, iv_len);

    void *map = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!map) {
        fclose(fp);
        return;
    }

    size_t ciphertext_len = ftell(fp) - iv_len;
    void *ciphertext = malloc(ciphertext_len);
    if (!ciphertext) {
        munmap(map, ciphertext_len);
        fclose(fp);
        return;
    }

    fread(ciphertext, 1, ciphertext_len, fp);

    size_t plaintext_len = ciphertext_len - AES_BLOCK_SIZE;
    ctx->plaintext = malloc(plaintext_len);
    if (!ctx->plaintext) {
        free(ciphertext);
        munmap(map, ciphertext_len);
        fclose(fp);
        return;
    }

    memcpy(ctx->plaintext, (char *)map, plaintext_len);
    pkcs7_unpadding((unsigned char *)ctx->plaintext + AES_BLOCK_SIZE, &ctx->len);

    if (1 != EVP_DecryptUpdate(&(ctx->ctx), (unsigned char *)ciphertext, &ctx->len, ctx->plaintext, ctx->len)) {
        free(ctx->plaintext);
        free(ciphertext);
        munmap(map, ciphertext_len);
        fclose(fp);
        return;
    }

    memcpy((char *)map + AES_BLOCK_SIZE, ciphertext, ctx->len);
    if (1 != EVP_DecryptFinal_ex(&(ctx->ctx), (unsigned char *)ciphertext + ctx->len, &ctx->len)) {
        free(ctx->plaintext);
        free(ciphertext);
        munmap(map, ciphertext_len);
        fclose(fp);
        return;
    }

    memcpy((char *)map + AES_BLOCK_SIZE, ciphertext + ctx->len, ctx->len);
    *data = realloc(*data, plaintext_len);
    memcpy(*data, (char *)map, plaintext_len);
    munmap(map, ciphertext_len);
    fclose(fp);
}
