void *lte_ue_update(void *arg) {
    struct lte_ues_manager *mgr = arg;
    time_t last_update;

    while (1) {
        pthread_mutex_lock(&mgr->mutex);
        if (time(NULL) - last_update >= UPDATE_INTERVAL) {
            last_update = time(NULL);

            // Simulate radio channel conditions and update RX Power here
            mgr->ues[0].RX_Power += rand() % 5 - 2;
            mgr->ues[1].RX_Power += rand() % 5 - 2;
            // ...
        }
        pthread_mutex_unlock(&mgr->mutex);
