    }
}

struct lte_ues_manager *lte_ues_manager_create() {
    struct lte_ues_manager *mgr = malloc(sizeof(struct lte_ues_manager));
    if (!mgr) return NULL;

    mgr->num_ues = 0;
    pthread_mutex_init(&mgr->mutex, NULL);

    // Dynamically allocate memory for LTE_UE structures using posix_memalign
    size_t alignment = sizeof(LTE_UE);
    size_t size = MAX_UES * sizeof(LTE_UE);
    void *memory = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!memory) goto error;

    if (posix_memalign(memory, alignment, size)) goto error;

    mgr->ues = memory;

    return mgr;
error:
    free(mgr);
    return NULL;
}

void lte_ue_manager_destroy(struct lte_ues_manager *mgr) {
    if (mgr->ues) munmap(mgr->ues, mgr->num_ues * sizeof(LTE_UE));
    free(mgr);
}

void lte_ue_manager_add_ue(struct lte_ues_manager *mgr, int id, const char *srs_config) {
    if (mgr->num_ues >= MAX_UES) return;

    mgr->ues[mgr->num_ues].UE_ID = id;
    strncpy(mgr->ues[mgr->num_ues].SRS_Config, srs_config, sizeof(mgr->ues[0].SRS_Config));

    pthread_t update_thread;
    if (pthread_create(&update_thread, NULL, lte_ue_update, mgr)) {
        perror("pthread_create");
        return;
    }

    mgr->num_ues++;
}
