#include <limits.h>

typedef struct {
    int value;
    long offset;
    int key;
} record;

typedef struct {
    record *records;
    size_t capacity, size;
    long totalSum;
} recordSet;

recordSet* createRecordSet(size_t size) {
    if (size == 0) return NULL;
    recordSet *rs = malloc(sizeof(recordSet));
    rs->capacity = size;
    rs->size = 0;
    rs->records = calloc(size, sizeof(record));
    if (!rs->records) {
        free(rs);
        return NULL;
    }
    return rs;
}

void shuffle(recordSet *rs, long limit) {
    for (size_t i = 0; i < rs->capacity; ++i)
        rs->records[i].offset = rand(); // Use any appropriate method to generate offsets

    qsort(rs->records, rs->size, sizeof(record), compareOffset);

    long totalSum = 0;
    for (size_t i = 0; i < rs->size && totalSum <= limit; ++i) {
        totalSum += rs->records[i].value;
        rs->records[i].offset += totalSum;
    }
}

int compareOffset(const void *a, const void *b) {
    return (*(long*)a - *(long*)b);
}

void filter(recordSet *rs, int threshold) {
    size_t i = 0;
    for (size_t j = 0; j < rs->size; ++j) {
        if (rs->records[j].key >= threshold) continue;
        swap(&rs->records[i], &rs->records[j]);
        ++i;
    }
}

void destroyRecordSet(recordSet *rs) {
    free(rs->records);
    free(rs);
}

