    // Check input arguments
    if (argc < 4 || strcmp(argv[1], "-p") != 0 || strcmp(argv[3], "-a") != 0) {
        fprintf(stderr, "Usage: %s -p password -f filename -a sha_algorithm\n", argv[0]);
        return 1;
    }

    task_t *tasks = malloc((argc - 4) * sizeof(task_t));
    for (int i = 4; i < argc; ++i) {
        tasks[i - 4].filename = argv[i];
        tasks[i - 4].password = strdup(argv[2]);
        if (strcmp(argv[argc - 1], "sha-1") == 0) {
            tasks[i - 4].sha_algorithm = 0;
        } else if (strcmp(argv[argc - 1], "sha-256") == 0) {
            tasks[i - 4].sha_algorithm = 1;
        } else {
            fprintf(stderr, "Invalid hashing algorithm '%s'. Supported options: sha-1, sha-256.\n", argv[argc - 1]);
            return 1;
        }
    }

    pthread_t threads[tasks->num];
    for (int i = 0; i < tasks->num; ++i) {
        int rc = pthread_create(&threads[i], NULL, process_filenames, &tasks[i]);
        if (rc) {
            perror("Error creating thread");
            return rc;
        }
    }

    for (int i = 0; i < tasks->num; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(tasks);

    // Cleanup AES resources and log audit information if needed
    ...

    return 0;
}
