int* reallocateIntList(IntList* list, size_t newSize) {
    int *newData = malloc(newSize * sizeof(int));
    if (newData == NULL) return NULL;

    if (list->length > 0) {
        memcpy(newData, list->data, list->length * sizeof(int));
        free(list->data);
    }

    list->data = newData;
    list->capacity = newSize;
    return newData;
}

void addIntegerToList(IntList* list, int value) {
    if (list->length >= list->capacity) {
        list->data = reallocateIntList(list, list->capacity * 2);
        if (list->data == NULL) return;
    }

    list->data[list->length++] = value;
}

void printLargestIntegerInList(const IntList* list) {
    int max_int = INT_MIN;

    for (size_t i = 0; i < list->length; ++i) {
        if (list->data[i] > max_int)
            max_int = list->data[i];
    }

    printf(max_int == INT_MIN ? "No integers provided" : "%d\n", max_int);
}

IntList* readAndProcessIntegersFromSource(FILE *src, IntList* list) {
    int value;
    size_t line_count = 0;

    while (!feof(src)) {
        if (fscanf(src, "%d", &value) == 1) {
            addIntegerToList(list, value);
            ++line_count;
        } else if (ferror(src)) {
            perror("Error reading from source");
            break;
        }
    }

    return list;
}

void processIntegersFromSource(FILE *src) {
    IntList* list = createIntList();
    readAndProcessIntegersFromSource(src, list);
    printLargestIntegerInList(list);
    freeIntList(list);
}
