import java.io.*;
import java.math.BigInteger;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class FileMd5Hasher {
    private static final Logger LOGGER = Logger.getLogger(FileMd5Hasher.class.getName());
    private static final int MAX_FILE_SIZE = 1048576; // 1 MB
    private static final ExecutorService EXECUTOR = Executors.newCachedThreadPool();
    private static final AtomicLong processedFilesCounter = new AtomicLong(0);
    private static final AtomicLong processingTimeCounter = new AtomicLong(0);

    public Map<String, String> computeMd5Hashes(List<String> filePaths) {
        Map<String, String> md5Hashes = new HashMap<>();

        Callable<Map.Entry<String, String>> callableTask = filePath -> {
            try {
                File file = new File(filePath);
                if (!file.exists() || !file.isFile() || file.length() > MAX_FILE_SIZE) {
                    LOGGER.warning("Skipping invalid file: " + filePath);
                    return new SimpleImmutableEntry<>(filePath, null);
                }

                try (InputStream is = Files.newInputStream(file.toPath())) {
                    MessageDigest md = MessageDigest.getInstance("MD5");

                    byte[] buffer = new byte[1024];
                    int bytesRead;
                    while ((bytesRead = is.read(buffer)) != -1) {
                        md.update(buffer, 0, bytesRead);
                    }

                    BigInteger bigInt = new BigInteger(1, md.digest());
                    String md5Hash = String.format("%032x", bigInt);
                    LOGGER.info("Processing file: " + filePath + ", MD5 hash: " + md5Hash);
                    return new SimpleImmutableEntry<>(filePath, md5Hash);
                } catch (NoSuchAlgorithmException | IOException e) {
                    LOGGER.severe("Error while processing file: " + filePath + ", Error: " + e.getMessage());
                    throw new RuntimeException(e);
                }
            } catch (NullPointerException e) {
                LOGGER.severe("Invalid input: null value for file path");
                throw new IllegalArgumentException("Invalid input: null value for file path", e);
            }
        };

        try {
            List<Future<Map.Entry<String, String>>> results = EXECUTOR.invokeAll(filePaths.stream()
                    .map(callableTask)
                    .collect(Collectors.toList()));

            for (Future<Map.Entry<String, String>> result : results) {
                Map.Entry<String, String> entry = result.get();
                if (entry != null) {
                    md5Hashes.put(entry.getKey(), entry.getValue());
                    processedFilesCounter.incrementAndGet();
                    processingTimeCounter.addAndGet(System.currentTimeMillis() - result.get().get executionStartTime());
                }
            }
        } catch (InterruptedException | ExecutionException e) {
            LOGGER.severe("Error while processing files in bulk: " + e.getMessage());
        } finally {
            EXECUTOR.shutdownNow();
        }

        double averageProcessingTime = processingTimeCounter.get() / processedFilesCounter.get();
        LOGGER.info("Average processing time per file: " + averageProcessingTime + " ms");
        LOGGER.info("Number of files processed: " + processedFilesCounter);
        return md5Hashes;
    }
}
```

