import java.io.*;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.google.common.io.Files;

public class FileHashService {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileHashService.class);
    private static final long MAX_FILE_SIZE = 1024 * 1024; // 1 MB
    private ExecutorService executor;
    private Map<String, String> hashMap;
    private AtomicBoolean running = new AtomicBoolean(false);
    private AtomicBoolean stopped = new AtomicBoolean(false);

    public FileHashService() {
        this.executor = Executors.newFixedThreadPool(5);
        this.hashMap = new HashMap<>();
    }

    public void startService() throws InterruptedException {
        if (running.get()) {
            LOGGER.warn("Service is already running.");
            return;
        }
        running.compareAndSet(false, true);
        Runnable serviceTask = () -> {
            while (!stopped.get() && !Thread.currentThread().isInterrupted()) {
                try {
                    Thread.sleep((long) (Math.random() * 5000)); // Random delay between starts, up to 5 seconds
                    processFiles();
                } catch (Exception e) {
                    LOGGER.error("Error during service execution:", e);
                }
            }
        };
        executor.submit(serviceTask);
    }

    public void stopService() throws InterruptedException {
        if (!running.get()) {
            LOGGER.warn("Service is not running.");
            return;
        }
        stopped.compareAndSet(false, true);
        executor.shutdownNow();
        executor.awaitTermination(60, TimeUnit.SECONDS); // Wait for up to 1 minute for the service to stop
        sendShutdownMessage();
    }

    private void processFiles() {
        String[] filePaths = new String[]{"file1.txt", "file2.txt"}; // List of file paths to be processed
        for (String path : filePaths) {
            if (!isValidFilePath(path)) continue;
            File file = new File(path);
            if (file.length() > MAX_FILE_SIZE) continue;
            try {
                String md5Hash = computeMD5(Files.toString(file));
                hashMap.put(path, md5Hash);
            } catch (IOException | NoSuchAlgorithmException e) {
                LOGGER.error("Error while computing MD5 for file '{}':", path, e);
            }
        }
    }

    private boolean isValidFilePath(String path) {
        return path != null && new File(path).exists() && new File(path).isFile();
    }

    private String computeMD5(String input) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        byte[] digest = md.digest(input.getBytes());
        BigInteger bigInt = new BigInteger(1, digest);
        return bigInt.toString(16);
    }

    private void sendShutdownMessage() {
        // Implement messaging system functionality here
    }
}
