typedef struct node {
    int value;
    struct node* next;
    char* buffer;
} Node;

void mergeSort(Node** arr, int left, int right) {
    if (left < right) {
        int mid = (left + right) / 2;
        mergeSort(arr, left, mid);
        mergeSort(arr, mid + 1, right);
        mergeNodes(arr, left, mid, right);
    }
}

void mergeNodes(Node** arr, int left, int mid, int right) {
    Node* temp = NULL;
    Node* sortArr = NULL;
    int i = left, j = mid + 1, k = 0;

    while (i <= mid && j <= right) {
        if (!strcmp(arr[i]->buffer, arr[j]->buffer)) {
            temp = malloc(sizeof(Node));
            temp->value = arr[i]->value;
            temp->next = arr[i]->next;
            temp->buffer = arr[i]->buffer;
            arr[i] = temp;
            i++;
        } else if (strcmp(arr[i]->buffer, arr[j]->buffer) > 0) {
            temp = malloc(sizeof(Node));
            temp->value = arr[j]->value;
            temp->next = arr[j]->next;
            temp->buffer = arr[j]->buffer;
            arr[j] = temp;
            j++;
        } else {
            j++;
        }
    }

    while (i <= mid) {
        temp = malloc(sizeof(Node));
        temp->value = arr[i]->value;
        temp->next = arr[i]->next;
        temp->buffer = arr[i]->buffer;
        arr[i] = temp;
        i++;
    }

    while (j <= right) {
        temp = malloc(sizeof(Node));
        temp->value = arr[j]->value;
        temp->next = arr[j]->next;
        temp->buffer = arr[j]->buffer;
        arr[j] = temp;
        j++;
    }
}

int isSorted(Node** arr, int size) {
    for (int i = 0; i < size - 1; ++i) {
        if (!strcmp(arr[i]->buffer, arr[i + 1]->buffer) && arr[i]->value > arr[i + 1]->value) {
            return 0;
        }
    }
    return 1;
}

int adjustValues(Node** arr, int size) {
    if (size <= 1) return 0;

    double avg = 0.0;
    for (int i = 0; i < size; ++i) {
        avg += arr[i]->value;
    }
    avg /= size;

    int adjustment = (limit - avg) / size;
    for (int i = 0; i < size; ++i) {
        arr[i]->value += adjustment;
    }

    return adjustment;
}

void freeMemory(Node** arr, int size) {
    Node* temp;
    for (int i = 0; i < size; ++i) {
        temp = arr[i];
        free(arr[i]);
        arr[i] = temp;
    }
}

void allocateMemory(Node*** arr, int* sizes, int count) {
    for (int i = 0; i < count; ++i) {
        (*arr)[i] = malloc(sizes[i] * sizeof(Node));
    }
}

int main() {
