    double* inputDoubles = NULL;
    char* inputChars = NULL;
    Node** inputNodes = NULL;
    int* nodeSizes = NULL;
    scanf("%d%d%d", &numDoubles, &numChars, &numNodes);

    allocateMemory(&inputDoubles, NULL, 1);
    allocateMemory(&inputChars, NULL, 1);
    allocateMemory(&inputNodes, &nodeSizes, numNodes);

    for (int i = 0; i < numDoubles; ++i) {
        scanf("%lf", inputDoubles + i);
    }

