        inputChars[i] = malloc(strlen(temp) * sizeof(char));
        strcpy(inputChars[i], temp);
    }

    for (int i = 0; i < numNodes; ++i) {
        Node* currNode = inputNodes[i];
        scanf("%d%s", &currNode->value, currNode->buffer);
        if (i != numNodes - 1) {
            currNode->next = inputNodes[i + 1];
        }
    }

    mergeSort(inputNodes, 0, numNodes - 1);

    int sum = 0;
    for (int i = 0; i < numNodes; ++i) {
        sum += inputNodes[i]->value;
    }

    if (sum > limit) {
        int adjustment = adjustValues(inputNodes, numNodes);
        if (adjustment * numNodes > limit - sum) {
            printf("Unable to meet the constraint.\n");
            freeMemory(inputDoubles, numDoubles);
            freeMemory(inputChars, numChars);
            freeMemory(inputNodes, numNodes);
            return 0;
        }
    }

    for (int i = 0; i < numNodes; ++i) {
        printf("%lf %s %d\n", inputNodes[i]->value, inputNodes[i]->buffer, inputNodes[i]->next ? inputNodes[i]->next->value : 0);
    }

    freeMemory(inputDoubles, numDoubles);
    freeMemory(inputChars, numChars);
    freeMemory(inputNodes, numNodes);

    return 0;
}
