LinkMetric* initialize_interface(const char* interface, int log_level, const char* logging_file) {
    static LinkMetric interfaces[MAX_INTERFACES];
    int interface_index = -1;

    for (int i = 0; i < MAX_INTERFACES; ++i) {
        if (!interfaces[i].timestamp) {
            interface_index = i;
            break;
        }
    }

    if (interface_index == -1) {
        fprintf(stderr, "Error: Maximum number of interfaces reached.\n");
        return NULL;
    }

    interfaces[interface_index].timestamp = time(NULL);

    if (interface == NULL || strlen(interface) > 32) {
        fprintf(stderr, "Error: Invalid interface name provided.\n");
        return NULL;
    }

    strcpy(interfaces[interface_index].interface, interface);

    if (log_level < LOG_NONE || log_level > LOG_ERROR) {
        fprintf(stderr, "Error: Invalid log level provided.\n");
