#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <openssl/pkey.h>
#include <openssl/rand.h>
#include <openssl/evp.h>
#include <time.h>

typedef struct {
    FILE* file;
    EVP_CIPHER_CTX* ctx;
    const char* passphrase;
    int iterations;
    unsigned char salt[EVP_MAX_MD_SIZE];
    u_char iv[EVP_MAX_IV_LENGTH];
    u_char header[sizeof(uint32_t) + sizeof(u_char*) + EVP_MAX_IV_LENGTH]; // Header contains file size, IV position, and IV data
} StorageContext;

static int dns_resolver(const char* hostname, u_char* ip_addr, int addr_len);

StorageContext* storage_context_create(const char* passphrase, int iterations) {
    StorageContext* ctx = malloc(sizeof(StorageContext));
    memset(ctx, 0, sizeof(StorageContext));
    ctx->passphrase = passphrase;
    ctx->iterations = iterations;
    RAND_bytes(ctx->salt, sizeof(ctx->salt));
    return ctx;
}

void storage_context_destroy(StorageContext* ctx) {
    if (ctx->file) fclose(ctx->file);
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
}

int storage_open(StorageContext* ctx, const char* filename, const char* mode) {
    // Implement DNS resolution for hostname and obtain IP address
    u_char ip_addr[INET6_ADDRSTRLEN];
    int len = dns_resolver(filename, ip_addr, sizeof(ip_addr));
    if (len <= 0) return -1;

    // Open file with specified mode
    ctx->file = fopen(filename, mode);
    if (!ctx->file) return -1;

    // Initialize encryption context
    EVP_CIPHER_CTX_init(&ctx->ctx);
    EVP_EncryptInit_ex(&ctx->ctx, EVP_aes_256_gcm(), NULL, ctx->passphrase, ctx->salt, ctx->iterations);
    uint32_t iv_position = ftell(ctx->file);
    RAND_bytes(ctx->iv, sizeof(ctx->iv));
    EVP_EncryptUpdate(&ctx->ctx, ctx->header, sizeof(ctx->header), NULL, ctx->iv);
    fseek(ctx->file, -sizeof(ctx->header), SEEK_END);
    fwrite(ctx->header, 1, sizeof(ctx->header), ctx->file);
    return 0;
}

int storage_write(StorageContext* ctx, const char* data, size_t length) {
    // Encrypt and write data to file
    uint32_t plaintext_length = htonl(length);
    fseek(ctx->file, -sizeof(plaintext_length), SEEK_END);
    fwrite(&plaintext_length, 1, sizeof(plaintext_length), ctx->file);
    EVP_EncryptUpdate(&ctx->ctx, NULL, 0, data, length);
    fseek(ctx->file, ftell(ctx->file) + iv_position, SEEK_SET);
    EVP_EncryptFinal_ex(&ctx->ctx, NULL, NULL);
    fwrite(data, 1, length, ctx->file);
    return 0;
}

int storage_close(StorageContext* ctx) {
    // Finalize encryption context and write IV to file header
    EVP_EncryptFinal_ex(&ctx->ctx, ctx->header + sizeof(uint32_t), NULL);
    fseek(ctx->file, -sizeof(ctx->header), SEEK_END);
    fwrite(ctx->header, 1, sizeof(ctx->header), ctx->file);
    fclose(ctx->file);
    return 0;
}

static int dns_resolver(const char* hostname, u_char* ip_addr, int addr_len) {
    struct hostent* he = gethostbyname(hostname);
    if (he) {
        memcpy(ip_addr, he->h_addr, MIN(he->h_length, addr_len));
        return he->h_length;
    }

    int error = 0;
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC;
    hints.ai_socktype = SOCK_STREAM;

    int status = getaddrinfo(hostname, NULL, &hints, &res);
    if (status != 0) {
        error = status;
    } else {
        memcpy(ip_addr, res->ai_addr, MIN(res->ai_addrlen, addr_len));
        freeaddrinfo(res);
    }

    return error;
}
```

This code creates a basic structure for managing secure file storage using the OpenSSL library. It includes a function to create and destroy storage contexts, open files with specified modes, write encrypted data to them, close files, and perform DNS resolution. Error handling is included in the DNS resolution function. However, it does not include features for periodically updating encryption keys and IVs, as well as mechanisms to limit process capabilities or handle potential issues during file operations. You may need to further refine this code according to your specific requirements.']

