#include <gpslib.h>

typedef struct {
    int width, height;
    char color_space[10];
    gps_data_t *gps;
} ImageInfo;

ImageInfo processJPEGAndOptimize(const char *file_path, int optimization_level) {
    FILE *fp = fopen(file_path, "rb");
    if (!fp) return (ImageInfo){0};

    struct jpeg_decompress_struct cinfo;
    struct jpeg_error_mgr jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_decompress(&cinfo);
    jpeg_stdio_src(&cinfo, fp);
    (void)jpeg_read_header(&cinfo, TRUE);
    (void)jpeg_start_decompress(&cinfo);

    ImageInfo info = {
        .width = cinfo.image_width,
        .height = cinfo.image_height,
        .color_space[0] = cinfo.output_color_space == JCS_RGB ? 'R' : (cinfo.output_color_space == JCS_GRAYSCALE ? 'G' : 'C'),
        .gps = NULL
    };

    if (jpeg_read_scanlines(&cinfo, NULL, cinfo.image_height) < 0) {
        jpeg_destroy_decompress(&cinfo);
        return info;
    }

    JSAMPLE *buffer;
    size_t buffer_size = cinfo.output_width * cinfo.output_components;
    buffer = malloc(buffer_size);

    while (jpeg_read_scanlines(&cinfo, buffer, 1) > 0) {}
    jpeg_destroy_decompress(&cinfo);

    ExifData edata;
    if (!extractExifData(file_path, &edata)) {
        free(buffer);
        return info;
    }

    GPSData gpsdata;
    if (parseGPSDataFromExif(&edata.exif, &gpsdata) && hasValidGPSData(&gpsdata)) {
        info.gps = &gpsdata;
    }

    JSAMPARRAY optimized_buffer;
    size_t optimized_buffer_size;
    optimizeJPEG(file_path, buffer, buffer_size, optimization_level, &optimized_buffer, &optimized_buffer_size);

    printf("Optimization progress: %.2f%%\n", (float)optimized_buffer_size / buffer_size * 100.0);

    free(buffer);

    return info;
}
