    private static void processInputAndEncrypt(String filePath) throws IOException, NoSuchAlgorithmException {
        FileInputStream fis = null;
        MessageDigest md = MessageDigest.getInstance("MD5");
        List<Integer> numbers = new ArrayList<>();
        int maxSize = 10; // Maximum size of the integer list

        try {
            fis = new FileInputStream(filePath);

            int chunkSize = 1024 * 1024; // Read data in chunks of 1 MB
            byte[] buffer = new byte[chunkSize];
            long processedBytes = 0;

            while (true) {
                int readBytes = fis.read(buffer);

                if (readBytes <= 0) break; // End-of-file or error

                md.update(buffer, 0, readBytes);
                processedBytes += readBytes;

                if (processedBytes % (1024 * 1024) == 0) {
                    LOGGER.log(Level.INFO, "Processed 1 MB of data.");
                }
            }

            BigInteger hash = new BigInteger(1, md.digest());
            System.out.println("Hexdigest: " + hash.toString(16));

            fis = new FileInputStream(System.in);

            int number;
            while ((number = fis.read()) != -1) {
                if (numbers.size() >= maxSize) break;
                numbers.add((int) number);
            }

            if (numbers.isEmpty()) {
                System.out.println("No integers provided.");
                return;
            }

            int largestNumber = Collections.max(numbers);
            System.out.println("Largest integer: " + largestNumber);
