                    return new UpdateResponse
                    {
                        NeedsRefresh = false,
                        Metrics = new UpdateMetrics
                        {
                            DatabaseHits = databaseHits,
                            CacheMisses = cacheMisses
                        }
                    };
                }
                else
                {
                    // If the versions don't match, it means that someone else has made changes to the page in the meantime. Fetch fresh data from the database
                    databaseHits++;
                    pageData = await FetchPageDataAsync(pageId);
