        await ProcessUpdatesAsync(pageData, elementIds, updates);
        _memoryCache.Set(pageId, pageData);
        return new UpdateResponse
        {
            NeedsRefresh = true,
            Metrics = new UpdateMetrics
            {
                DatabaseHits = databaseHits,
                CacheMisses = cacheMisses
