typedef struct {
    const EVP_CIPHER *cipher;
    void (*key_retrieval)(const char *, unsigned char *, size_t);
} cipher_suite;

struct encryption_engine {
    void *data; // loaded file data
    size_t len; // length of the data
    cipher_suite cs;
};

void load_file(const char *path, size_t *length) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return;
    }

    struct stat st;
    fstat(fd, &st);
    void *map = mmap(NULL, st.st_size, PROT_READ, MAP_PRIVATE, fd, 0);
    close(fd);

    if (map == MAP_FAILED) {
        perror("Error mapping file");
        return;
    }

    *length = st.st_size;
}

struct encryption_engine *init_encryption_engine(const char *path, const char *cipher_name, const char *kms_url) {
    cipher_suite cs = {NULL};
    EVP_CIPHER_CTX *ctx = NULL;
    unsigned char key[EVP_MAX_KEY_LENGTH];
    size_t key_len = 0;

    if (kms_url != NULL) { // Retrieve key from KMS
        if (!load_key(kms_url, key, sizeof(key), &key_len)) {
            fprintf(stderr, "Error retrieving key\n");
            goto cleanup;
        }
    } else {
        // Use a default key or prompt for user input
    }

    cs.cipher = EVP_get_cipherbyname(cipher_name);
    if (cs.cipher == NULL) {
        fprintf(stderr, "Invalid cipher: %s\n", cipher_name);
        goto cleanup;
    }

    size_t length;
    void *data = malloc(length = 1024); // initial allocation for file loading
    load_file(path, &length);

    if (length > 1024) { // Reallocate memory based on actual file size
        data = realloc(data, length);
        if (!data) {
            perror("Error allocating memory");
            goto cleanup;
        }
    }

    load_file(path, &length);

    ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        perror("Error initializing encryption context");
        goto cleanup;
    }

    EVP_EncryptInit_ex(ctx, cs.cipher, key, NULL);
    EVP_EncryptUpdate(ctx, data, &length, (unsigned char *)path, strlen(path));
    EVP_EncryptFinal_ex(ctx, data + length, &length);

cleanup:
    if (ctx) {
        EVP_CIPHER_CTX_free(ctx);
    }
    if (key_retrieval) { // Free memory allocated for the key if needed
        free(key);
    }

    struct encryption_engine *ee = malloc(sizeof(struct encryption_engine));
    ee->data = data;
    ee->len = length;
    ee->cs = cs;

    return ee;
}

/* Add your implementation for load_key() function here */
