#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <unistd.h>
#include <pthread.h>
#define MAX_SIZE 10000

typedef struct {
    int data;
    struct ListNode *next;
} ListNode;

ListNode* create_node(int data) {
    ListNode *new_node = (ListNode*)malloc(sizeof(ListNode));
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(ListNode **head, ListNode *new_node) {
    if (*head == NULL) {
        *head = new_node;
    } else {
        ListNode *temp = *head;
        while (temp->next != NULL) {
            temp = temp->next;
        }
        temp->next = new_node;
    }
}

void free_list(ListNode **head) {
    ListNode *temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}

int get_integer(FILE *stream) {
    char buffer[10];
    int result;
    fgets(buffer, sizeof(buffer), stream);
    if (sscanf(buffer, "%d", &result) != 1) {
        return -1;
    }
    return result;
}

void* process_stream(void *arg) {
    FILE *stream = (FILE*) arg;
    int data;
    ListNode *list_head = NULL;

    while ((data = get_integer(stream)) != EOF && list_head->next != NULL) {
        if (list_head->next == MAX_SIZE) {
            printf("List is full. Dropping data from %s\n", arg);
            break;
        }
        add_to_list(&list_head, create_node(data));
    }

    free_list(&list_head);
    fclose(stream);
}

int manage_data_streams(char *socket_addr) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    inet_pton(AF_INET, socket_addr, &server_addr.sin_addr);
    server_addr.sin_port = htons(8080);

    if (connect(sockfd, (struct sockaddr*)&server_addr, sizeof(server_addr)) < 0) {
        perror("Error connecting to the data stream.");
        return -1;
    }

    pthread_t thread_id;
    FILE *stream = fdopen(sockfd, "r");

    if (pthread_create(&thread_id, NULL, &process_stream, stream) < 0) {
        perror("Error creating processing thread.");
        return -1;
    }

    pthread_join(thread_id, NULL);

    close(sockfd);
    return 0;
}
```

