void enforce_sum_constraint(Node** arr, size_t size, int limit) {
    int total = 0;
    for (size_t i = 0; i < size; ++i) {
        total += (*arr[i]).value;
    }

    if (total > limit) {
        double avg = (double)limit / size;
        for (size_t i = 0; i < size; ++i) {
            (*arr[i]).value -= ((*arr[i]).value - avg);
        }
    }
}
