#define MAX_POLYGONS 10000

typedef struct {
    double x, y;
} Point;

typedef struct {
    size_t point_count;
    Point* points;
} Polygon;

double area(Polygon polygon) {
    double area = 0.0;
    size_t i, j, count = polygon.point_count;

    for (i = 0; i < count; ++i) {
        j = (i == count - 1) ? 0 : i + 1;
        area += polygon.points[i].x * polygon.points[j].y - polygon.points[j].x * polygon.points[i].y;
    }

    return fabs(area) / 2.0;
}

bool optimize_order(Polygon* polygon) {
    size_t i, j, k;
    double dx, dy, d;
    Polygon tmp;

    if (polygon->point_count < 3) return false;

    for (i = 0; i < polygon->point_count - 1; ++i) {
        j = (i == polygon->point_count - 2) ? 0 : i + 1;

        tmp.points = malloc(polygon->point_count * sizeof(Point));
        if (!tmp.points) {
            perror("Memory allocation failure");
            return false;
        }

        for (k = 0; k < polygon->point_count; ++k) tmp.points[k] = polygon->points[k];

        dx = polygon->points[j].x - polygon->points[i].x;
        dy = polygon->points[j].y - polygon->points[i].y;

        for (k = 0; k < polygon->point_count - 1; ++k) {
            d = sqrt((dx - (polygon->points[(i + k + 1) % polygon->point_count].x - polygon->points[i].x)) *
                    (dy - (polygon->points[(i + k + 1) % polygon->point_count].y - polygon->points[i].y)));
            if (d < area(tmp)) {
                tmp.points[(i + k + 1) % polygon->point_count] = polygon->points[j];
                j = (j == polygon->point_count - 1) ? 0 : j + 1;
            } else break;
        }

        free(polygon->points);
        polygon->points = tmp.points;
    }

    return true;
}

void filter(Polygon* polygons, double area_threshold) {
    size_t i;

    for (i = 0; i < MAX_POLYGONS; ++i) {
        if (!polygons[i].points || polygons[i].point_count == 0 ||
            polygons[i].points[0].x > INT_MAX || polygons[i].points[0].y > INT_MAX ||
            polygons[i].points[0].x < INT_MIN || polygons[i].points[0].y < INT_MIN) {
            free(polygons[i].points);
            continue;
        }

        if (area(polygons[i]) > area_threshold) {
            for (size_t j = i + 1; j < MAX_POLYGONS; ++j) {
                polygons[j - 1] = polygons[j];
            }
            --MAX_POLYGONS;
        }
    }
}

Polygon* create_polygons(size_t double_count, size_t point_count, size_t polygon_count) {
    Polygon* polygons = malloc(polygon_count * sizeof(Polygon));
    if (!polygons) {
        perror("Memory allocation failure");
        return NULL;
    }

    Point** points = calloc(point_count * polygon_count, sizeof(Point*));
    if (!points) {
        free(polygons);
        perror("Memory allocation failure");
        return NULL;
    }

    double* doubles = malloc(double_count * sizeof(double));
    if (!doubles) {
        free(polygons);
        free(points);
        perror("Memory allocation failure");
        return NULL;
    }

    size_t i, j, k;

    for (i = 0; i < polygon_count; ++i) {
        polygons[i].point_count = point_count;
        polygons[i].points = points[i] = malloc(point_count * sizeof(Point));
        if (!polygons[i].points) {
            for (j = 0; j <= i; ++j) free(polygons[j].points);
            free(points);
            free(doubles);
            perror("Memory allocation failure");
            return NULL;
        }

        for (j = k = 0; j < double_count; ++j, ++k) {
            doubles[k] = ((double*)calloc(1, sizeof(double)))[0];
            if (!doubles[k]) {
                for (size_t l = i; l > 0; --l) {
                    free(polygons[l - 1].points);
                    polygons[l - 1].point_count = 0;
                }
                for (j = 0; j <= i; ++j) free(polygons[j].points);
                free(points);
                free(doubles);
                perror("Memory allocation failure");
                return NULL;
            }
            doubles[k] = ((double*)calloc(1, sizeof(double)))[0];
        }
    }

    return polygons;
}

void destroy_polygons(Polygon* polygons, size_t polygon_count) {
    size_t i;

    for (i = 0; i < polygon_count; ++i) {
        if (polygons[i].points) free(polygons[i].points);
    }

    free(polygons);
}

void log_memory(size_t allocated, size_t used) {
    printf("Memory: Allocated %zu bytes, Used %zu bytes\n", allocated, used);
}

#define TIME_LOGGER static char _time_logger[64][256]; size_t _time_logger_index = 0;
#define TIME_LOG(message) strcpy(_time_logger[_time_logger_index], message); ++_time_logger_index

void time_log(const char* message, clock_t start, clock_t end) {
    double duration = (double)(end - start) / CLOCKS_PER_SEC;
    printf("%s Elapsed Time: %.6f seconds\n", message, duration);
    TIME_LOG(message);
}

void task() {
    size_t double_count = 10000;
    size_t point_count = 3;
    size_t polygon_count = double_count / point_count;

    Polygon* polygons = create_polygons(double_count, point_count, polygon_count);
    if (!polygons) return;

    clock_t start = clock();

    for (size_t i = 0; i < polygon_count; ++i) {
        optimize_order(&polygons[i]);
    }

    time_log("Polygon ordering optimization", start, clock());

    for (size_t i = 0; i < polygon_count; ++i) {
