#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct user_profile {
    char username[50];
    char status;
    float score;
    int id;
} user_profile;

double* timestamps;
char* statuses;
float* scores;
int* ids;
user_profile* profiles;
size_t num_profiles = 0;
size_t capacity = 0;

void allocate_memory(size_t size) {
    if (capacity >= size) return;

    timestamps = realloc(timestamps, size * sizeof(double));
    statuses = realloc(statuses, size * sizeof(char));
    scores = realloc(scores, size * sizeof(float));
    ids = realloc(ids, size * sizeof(int));
    profiles = realloc(profiles, size * sizeof(user_profile));

    capacity = size;
}

void update_profiles(double threshold) {
    double total_score = 0.0;
    for (size_t i = 0; i < num_profiles; ++i) {
        total_score += profiles[i].score;
    }

    double average_score = total_score / num_profiles;
    if (average_score < threshold) {
        double adjustment = (threshold - average_score) / num_profiles;
        for (size_t i = 0; i < num_profiles; ++i) {
            profiles[i].score += adjustment;
        }
    }
}

void add_profile(const char* username, char status, float score, int id) {
    allocate_memory(num_profiles + 1);

    strcpy(profiles[num_profiles].username, username);
    profiles[num_profiles].status = status;
    profiles[num_profiles].score = score;
    profiles[num_profiles].id = id;

    ++num_profiles;
}

void delete_profile(int id) {
    for (size_t i = 0; i < num_profiles; ++i) {
        if (profiles[i].id == id) {
            memmove(&profiles[i], &profiles[i + 1], (num_profiles - i - 1) * sizeof(user_profile));
            --num_profiles;
            break;
        }
    }
}

