    }
}

void update_link_metrics(struct NetworkInterface* ni, const LinkMetric* new_metric) {
    pthread_mutex_lock(&(ni->lock));
    if (!ni->metrics || ni->num_metrics >= MAX_METRICS) {
        // Reallocate memory for metrics or handle overflow...
        LinkMetric* temp = realloc(ni->metrics, sizeof(LinkMetric) * (ni->num_metrics + 1));
        if (!temp) {
            perror("Error reallocating memory");
            pthread_mutex_unlock(&(ni->lock));
            return;
        }
        ni->metrics = temp;
    }

    memcpy(&(ni->metrics[ni->num_metrics]), new_metric, sizeof(LinkMetric));
    ni->num_metrics++;
    pthread_mutex_unlock(&(ni->lock));
}

