    for (size_t i = strlen(base_name); i > path_len && isdot(base_name[i - 1]); --i) {}
    extension = (i > path_len) ? base_name + i : NULL;
    if (!extension) {
        base_name_len = strlen(base_name);
    } else {
        base_name_len = i - path_len;
    }

    // Generate new filename with custom hash function
    unsigned char hash[SHA256_DIGEST_LENGTH];
    SHA256((unsigned char*)base_name, base_name_len, hash);

    char* numeric_sequence = malloc(5 * SHA256_DIGEST_LENGTH + 1);
    for (size_t i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        snprintf(&numeric_sequence[i * 5], 6, "%04x", hash[i]);
    }
    numeric_sequence[SHA256_DIGEST_LENGTH * 5] = '\0';

    // Ensure the sequence does not exceed 10 digits and append new extension
    char* new_filename = malloc(path_len + base_name_len + strlen(numeric_sequence) + strlen(new_extension) + 2);
    strncpy(new_filename, dir_path, path_len);
    strncat(new_filename, base_name, base_name_len);
    strncat(new_filename, numeric_sequence, strlen(numeric_sequence));
    strncat(new_filename + path_len + base_name_len, new_extension, strlen(new_extension) + 1);

    free(numeric_sequence);
    return new_filename;
}
