    private final ExecutorService executor;
    private final int concurrencyLimit;
    private final long maxFileSize;
    private finallong retryLimit;
    private final FileSystem fileSystem; // Custom protocol for file retrieval

    public FileProcessor(ExecutorService executor, int concurrencyLimit, long maxFileSize, long retryLimit, FileSystem fileSystem) {
        this.executor = executor;
        this.concurrencyLimit = concurrencyLimit;
        this.maxFileSize = maxFileSize;
        this.retryLimit = retryLimit;
        this.fileSystem = fileSystem;
    }

    public Map<String, String> computeMD5Hashes(List<String> filePaths) {
        Map<String, String> results = new ConcurrentHashMap<>();
        Semaphore semaphore = new Semaphore(concurrencyLimit);

        for (String filePath : filePaths) {
            if (filePath == null || !new File(filePath).exists() || !new File(filePath).isFile()) {
                continue;
            }

            FileTask task = new FileTask(filePath, semaphore, results);
            executor.submit(task);
        }

        try {
            executor.shutdown();
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            System.out.println("Interrupted during task execution");
        }

        // Log execution statistics
        long filesProcessed = results.size();
        double averageProcessingTime = results.entrySet().stream()
                .mapToLong(e -> Long.parseLong(e.getValue()))
                .average()
                .orElse(0);
        System.out.printf("Processed %d files with an average processing time of %.2f ms\n", filesProcessed, averageProcessingTime * 1000);

        return results;
    }

    private static class FileTask implements Runnable {
        private final String filePath;
        private final Semaphore semaphore;
        private final Map<String, String> results;

        public FileTask(String filePath, Semaphore semaphore, Map<String, String> results) {
            this.filePath = filePath;
            this.semaphore = semaphore;
            this.results = results;
        }

        @Override
        public void run() {
            try (FileInputStream fis = new FileInputStream(filePath)) {
                long fileSize = fis.available();
                if (fileSize > maxFileSize) {
                    System.out.printf("Skipping %s - file size exceeded the maximum allowed limit of %.1f MB\n", filePath, maxFileSize / (1024 * 1024));
                    return;
                }

                semaphore.acquire(); // Acquire a permit to process this file concurrently

                byte[] buffer = new byte[65536];
                MessageDigest md = MessageDigest.getInstance("MD5");
                long startTime = System.nanoTime();

                int read;
                while ((read = fis.read(buffer)) != -1) {
                    md.update(buffer, 0, read);
                }

                results.put(filePath, Long.toString(new BigInteger(1, md.digest()).toString(16)));

                System.out.printf("Processed %s in %.2f ms\n", filePath, (System.nanoTime() - startTime) * 0.001);
            } catch (IOException | InterruptedException e) {
                // Handle exceptions and log appropriate error messages
            } finally {
                semaphore.release();
            }
        }
    }
}
