class FileManager(object):
    def __init__(self, logger):
        self.logger = logger

    @lru_cache(maxsize=None)
    def read_file(self, filepath):
        try:
            with open(filepath, 'r') as f:
                content = f.readlines()
                return sorted(content, key=len)
        except IOError as e:
            self.logger.error("Failed to read file %s: %s", filepath, str(e))
            return []

    @staticmethod
    def extract_sequence_number(lines):
        sequence_pattern = re.compile(r'^\s*(\d+)$')
        if lines:
            last_line = lines[-1]
            match = sequence_pattern.search(last_line)
            if match:
                return int(match.group(1))
        return None

    def process_files(self, filepaths):
        processed_files = {}
        for filepath in filepaths:
            if not os.path.isfile(filepath):
                continue

            lines = self.read_file(filepath)
            if lines:
                sequence_number = self.extract_sequence_number(lines)
                if sequence_number is not None:
                    processed_files[filepath] = sequence_number
        return processed_files
