void encrypt_and_compress(const char *filename, const uint8_t* key, size_t key_len, uint8_t compression_level, gzFile &gzfp) {
    FILE* fp = fopen(filename, "rb");
    if (!fp) {
        // Handle exceptions here
        return;
    }

    // Read the entire file into memory and encrypt it using AES-256-CBC
    uint8_t *data = new uint8_t[MAX_FILE_SIZE];
    size_t len = fread(data, 1, MAX_FILE_SIZE, fp);
    if (!len) {
        // Handle exceptions here
        delete[] data;
        fclose(fp);
        return;
    }

    // Encrypt the data using AES-256-CBC
