    AES_set_encrypt_key((const unsigned char *) key, key_len * 8, &aes_key);
    for (size_t i = 0; i < len; ++i) {
        data[i] ^= aes_key.encrypt[AES_ENCRYPT]; // Encrypt the data
    }

    // Compress the encrypted data using gzip with a specified compression level
    gzfp = gzopen(filename, "wb" | (compression_level << 8));
    if (!gzfp) {
        // Handle exceptions here
        delete[] data;
        fclose(fp);
        return;
    }

    gzwrite(gzfp, data, len);
    gzclose(gzfp);

    delete[] data;
    fclose(fp);
}
