using System;
using System.Data;
using System.Data.SqlClient;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;

public class DatabaseHelper {
    private readonly string _connectionString;
    private static readonly object _lockObject = new object();
    private readonly List<SqlConnection> _connections = new List<SqlConnection>();

    public DatabaseHelper(string connectionString) {
        _connectionString = connectionString;
    }

    public async Task<IDataReader> ExecuteComplexQueryAsync(string query, params object[] parameters) {
        lock (_lockObject) {
            if (_connections.Count == 0 || _connections[_connections.Count - 1].State != ConnectionState.Open) {
                SqlConnection newConnection = new SqlConnection(_connectionString);
                await newConnection.OpenAsync();
                _connections.Add(newConnection);
            }
            var connection = _connections[_connections.Count - 1];

            using (SqlCommand command = new SqlCommand(query, connection)) {
                command.Parameters.AddRange(parameters);
                return await command.ExecuteReaderAsync();
            }
        }
    }

    public void DisposeUnusedConnections() {
        lock (_lockObject) {
            for (int i = _connections.Count - 1; i >= 0; i--) {
                if (_connections[i].State == ConnectionState.Open) {
                    _connections[i].Close();
                    _connections.RemoveAt(i);
                }
            }
        }
    }
}
