void compute_polygon_area(Polygon *poly) {
    double area = 0.0;
    int i, j;

    // Skipping the first point to calculate the total perimeter optimization
    for (i = 1; i < poly->num_points; ++i) {
        area += (poly->points[i].x - poly->points[i-1].x) * (poly->points[i].y + poly->points[i-1].y);
    }
    // Closing the polygon loop for the last point and first point calculation
    area -= (poly->points[0].x - poly->points[poly->num_points - 1].x) * (poly->points[0].y + poly->points[poly->num_points - 1].y);
    area /= 2.0;

    // Optimizing order of points to minimize total perimeter
    for (i = 1; i < poly->num_points - 1; ++i) {
        for (j = i + 1; j < poly->num_points; ++j) {
            if ((poly->points[i].y > poly->points[j].y && poly->points[(i+1)%poly->num_points].y <= poly->points[(j+1)%poly->num_points].y) ||
                (poly->points[i].y < poly->points[j].y && poly->points[(i+1)%poly->num_points].y >= poly->points[(j+1)%poly->num_points].y)) {

                Point temp = poly->points[i];
                poly->points[i] = poly->points[j];
                poly->points[j] = temp;
            }
        }
    }
}

double polygon_area_filter(Polygon **polygons, int size, double area_threshold) {
    double total_area = 0.0;
    int i;

    for (i = 0; i < size; ++i) {
        if (polygons[i] && polygons[i]->num_points > 2) {
            compute_polygon_area(polygons[i]);
            if (polygons[i]->points[0].x == polygons[i]->points[1].x) {
                if (polygons[i]->points[0].y <= polygons[i]->points[1].y) {
                    if (polygons[i]->points[0].y + area_threshold >= polygons[i]->area) {
                        total_area += polygons[i]->area;
                    }
                } else {
                    if (polygons[i]->points[0].y - area_threshold <= polygons[i]->area) {
                        total_area += polygons[i]->area;
                    }
                }
            } else {
                if (fabs(polygons[i]->points[0].x - polygons[i]->points[1].x) <= area_threshold &&
                    fabs(polygons[i]->points[poly->num_points - 1].x - polygons[i]->points[0].x) <= area_threshold) {
                    total_area += polygons[i]->area;
                }
            }
        }
    }

    return total_area;
}

void free_memory(Polygon **polygons, int size) {
