```java
import java.io.*;
import java.math.BigInteger;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;
import javax.script.*;

public class FileProcessor {
    private static final Logger LOGGER = Logger.getLogger(FileProcessor.class.getName());
    private static final int MAX_FILE_SIZE = 1048576; // 1 MB
    private static final int CONCURRENCY_LIMIT = 10;
    private static final int RETRY_THRESHOLD = 3;
    private static final ExecutorService executor = Executors.newFixedThreadPool(CONCURRENCY_LIMIT);
    private static final ScriptEngine engine = new ScriptEngineManager().getEngineByName("nashorn");

    public Map<String, String> computeMD5Hashes(List<String> filePaths) {
        Map<String, String> result = new HashMap<>();
        Semaphore semaphore = new Semaphore(CONCURRENCY_LIMIT);
        AtomicInteger processedFiles = new AtomicInteger();
        AtomicLong totalProcessingTime = new AtomicLong();
        AtomicInteger failedFiles = new AtomicInteger();

        for (String filePath : filePaths) {
            if (filePath == null || !Files.exists(Paths.get(filePath)) || !Files.isReadable(Paths.get(filePath)) || Files.size(Paths.get(filePath)) > MAX_FILE_SIZE) {
                LOGGER.warning("Skipping invalid file path: " + filePath);
                continue;
            }

            Callable task = () -> processFileAndComputeMD5(semaphore, filePath, result, totalProcessingTime);
            Future<String> future = executor.submit(task);
            processedFiles.incrementAndGet();
            future.addListener(() -> {
                if (future.isDone()) {
                    totalProcessingTime.addAndGet(System.nanoTime() - future.getCompletedExecution().getSubmitTime());
                } else {
                    failedFiles.incrementAndGet();
                }
            }, executor);
        }

        try {
            executor.shutdown();
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }

        LOGGER.info("Processed files: " + processedFiles.get());
        LOGGER.info("Average processing time: " + (double) totalProcessingTime.get() / processedFiles.get());
        LOGGER.info("Failed files: " + failedFiles.get());
        return result;
    }

    private String processFileAndComputeMD5(Semaphore semaphore, String filePath, Map<String, String> results, AtomicLong totalProcessingTime) throws IOException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        try (BufferedInputStream bis = new BufferedInputStream(new RetryableFileReader(filePath))) {
            int read;
            byte[] buffer = new byte[4096];
            long startTime = System.nanoTime();
            while ((read = bis.read(buffer)) != -1) {
                md.update(buffer, 0, read);
            }
            long elapsedTime = System.nanoTime() - startTime;
            totalProcessingTime.addAndGet(elapsedTime);

            semaphore.release();

            return new BigInteger(1, md.digest()).toString(16);
        } catch (NoSuchAlgorithmException | ScriptException e) {
            throw new RuntimeException("Error computing MD5 hash", e);
        }
    }

    public class RetryableFileReader extends InputStream {
        private final String filePath;
        private int retryCount = 0;

        public RetryableFileReader(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public int read() throws IOException {
            if (retryCount > RETRY_THRESHOLD) {
                throw new FileRetrievalException("Failed to retrieve file after " + RETRY_THRESHOLD + " retries: " + filePath);
            }

            try {
                return super.read();
            } catch (IOException e) {
                LOGGER.warning("Retrying file retrieval for " + filePath + ": " + e.getMessage());
                retryCount++;
                Thread.sleep(500); // adjust this value based on network conditions and expected latency
                return read();
            }
        }
    }

    public class FileRetrievalException extends Exception {
        private static final long serialVersionUID = -697283149285016780L;

        public FileRetrievalException(String message) {
            super(message);
        }
    }

    // Python function to extract sequence number from the last line of a file
