import os
import sys
import time
from functools import wraps
import hashlib
import concurrent.futures
import logging

logger = logging.getLogger(__name__)
MAX_FILE_SIZE = 1048576
CONCURRENCY_LIMIT = 10
RETRY_THRESHOLD = 3
TIMEOUT_SECS = 5

def retry(max_attempts=RETRY_THRESHOLD):
    def deco(func):
        @wraps(func)
        def wrapper(*args, **kwargs):
            attempts = max_attempts
            while True:
                try:
                    return func(*args, **kwargs)
                except Exception as e:
                    if attempts <= 0:
                        raise e
                    logger.error(f'Failed to execute {func.__name__}: {e}')
                    attempts -= 1
                    time.sleep(2)
        return wrapper
    return deco

def read_file(filename):
    with open(filename, 'r') as f:
        lines = [line for line in sorted(f)]
        if len(lines) > 0:
            return lines[-1]
        else:
            raise Exception(f'File {filename} does not contain any data.')

class FileApi:
    def __init__(self):
        self._executor = concurrent.futures.ThreadPoolExecutor(max_workers=CONCURRENCY_LIMIT)

    def compute_md5_hashes(self, filepaths):
        results = {}
        tasks = []
        for filepath in filepaths:
            if not os.path.exists(filepath) or not os.access(filepath, os.R_OK):
                continue
            if os.path.getsize(filepath) > MAX_FILE_SIZE:
                logger.warn(f'Skipping file {filepath} due to its size exceeding the limit.')
                continue

            task = self._executor.submit(self._process_file, filepath)
            tasks.append(task)

        for task in concurrent.futures.as_completed(tasks):
            result = task.result()
            if result is not None:
                results[result[0]] = result[1]

        self._executor.shutdown()
        return results

    @retry()
    def _process_file(self, filepath):
        md5 = hashlib.md5()
        with open(filepath, 'rb') as f:
            while True:
                data = f.read(8192)
                if not data:
                    break
                md5.update(data)
        return (filepath, md5.hexdigest())
