import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class MD5Hasher {
    private final ExecutorService executor = Executors.newFixedThreadPool(5); // Adjust concurrency limit based on system resources
    private static final int MAX_FILE_SIZE = 1048576; // Max file size in bytes (1 MB)
    private static final int RETTRY_ATTEMPTS = 3;
    private static final long TIMEOUT_MILLIS = TimeUnit.SECONDS.toMillis(30); // Adjust timeout based on network conditions and system requirements

    public ConcurrentMap<String, String> computeMD5Hashes(List<String> filePaths) {
        ConcurrentMap<String, String> md5Hashes = new HashMap<>();

        for (String filePath : filePaths) {
            if (filePath == null || !Files.exists(Paths.get(filePath)) || Files.notReadable(Paths.get(filePath))) {
                continue;
            }

            Runnable task = () -> md5Hashes.putIfAbsent(filePath, computeMD5(filePath));
            executor.submit(task);
        }

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        return md5Hashes;
    }

    private String computeMD5(String filePath) {
        MessageDigest digest = null;
        try (FileInputStream inputStream = new FileInputStream(filePath)) {
            digest = MessageDigest.getInstance("MD5");

            byte[] buffer = new byte[4096]; // Adjust buffer size based on system memory and file sizes
            int bytesRead;
            while ((bytesRead = inputStream.read(buffer)) != -1) {
                digest.update(buffer, 0, bytesRead);
            }
        } catch (IOException | NoSuchAlgorithmException e) {
            // Log error message and handle exception gracefully
        }

        return new BigInteger(1, digest.digest()).toString(16);
    }

    // Implement logging methods for execution statistics and exceptions here
