class FileLine:
    def __init__(self, line):
        self.line = line

    @staticmethod
    def extract_sequence_number(file_path):
        try:
            with open(file_path, 'r') as f:
                lines = sorted([line for line in f])
                last_line = lines[-1]
                sequence_number_pattern = re.compile(r'sequence\s+(\d+)')
                match = sequence_number_pattern.match(last_line)
                if match:
                    return int(match.group(1))
        except IOError as e:
            # Handle exceptions gracefully and log error messages
            print(f"Error reading file '{file_path}': {e}")
            return None
        return None

    def read_and_extract(self, file_path):
        try:
            with open(file_path, 'r') as f:
                lines = sorted([line for line in f])
                last_line = lines[-1]
                self.line = last_line
                return FileLine.extract_sequence_number(file_path)
        except IOError as e:
            # Handle exceptions gracefully and log error messages
            print(f"Error reading file '{file_path}': {e}")
            return None
