    public ConcurrentMap<String, String> computeMD5Hashes(List<String> filePaths) {
        ConcurrentMap<String, String> result = new ConcurrentHashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool(CONCURRENCY_LIMIT);

        for (String filePath : filePaths) {
            if (!isValidFilePath(filePath)) continue;
            FileTask task = new FileTask(filePath, result);
            executor.execute(task);
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            LOGGER.error("Thread interrupted during file processing", e);
        }

        logExecutionStatistics(result);
        return result;
    }

    private boolean isValidFilePath(String filePath) {
        if (filePath == null || filePath.isEmpty()) return false;
        File file = new File(filePath);
        return file.exists() && !file.isDirectory();
