    class FileTask implements Runnable {
        private final String filePath;
        private final ConcurrentMap<String, String> results;

        public FileTask(String filePath, ConcurrentMap<String, String> results) {
            this.filePath = filePath;
            this.results = results;
        }

        @Override
        public void run() {
            try (InputStream in = getFileInputStream()) {
                MessageDigest md = MessageDigest.getInstance("MD5");

                byte[] buffer = new byte[4096]; // 4 KB chunk size for memory optimization
                int bytesRead;
                while ((bytesRead = in.read(buffer)) != -1) {
                    md.update(buffer, 0, bytesRead);
                }
                BigInteger hash = new BigInteger(1, md.digest());
                String hexHash = hash.toString(16);

                results.putIfAbsent(filePath, hexHash);
            } catch (Exception e) {
                LOGGER.error("Error processing file {}", filePath, e);
            }
