typedef struct {
    EVP_MD_CTX *mdctx;
    unsigned char digest[EVP_MAX_MD_SIZE];
    int length;
    void *buffer;
    size_t size;
    size_t pos;
    FILE *file;
} ProcessFileData;

ProcessFileData *processFileAndEncrypt(const char *path) {
    ProcessFileData *data = malloc(sizeof(ProcessFileData));
    if (!data) {
        perror("malloc");
        return NULL;
    }

    EVP_MD_CTX_init(&data->mdctx);
    data->buffer = mmap(NULL, 1048576, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (data->buffer == MAP_FAILED) {
        perror("mmap");
        free(data);
        return NULL;
    }
    data->size = 1048576;
    data->pos = 0;

    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        perror("open");
        munmap(data->buffer, data->size);
        free(data);
        return NULL;
    }
    data->file = fdopen(fd, "r");
    if (!data->file) {
        perror("fdopen");
        close(fd);
        munmap(data->buffer, data->size);
        free(data);
        return NULL;
    }

    log("Reading file...");
    size_t read = 0;
    while ((read = fread(&data->buffer[data->pos], 1, data->size - data->pos, data->file)) > 0) {
        if (data->pos + read >= data->size) {
            void *new_buf = realloc(data->buffer, data->size * 2);
            if (!new_buf) {
                perror("realloc");
                fclose(data->file);
                munmap(data->buffer, data->size);
                free(data);
                return NULL;
            }
            data->buffer = new_buf;
            data->size *= 2;
        }

        EVP_MD_Update(&data->mdctx, &data->buffer[data->pos], read);
        data->length += read;
        data->pos += read;

        if (data->pos == data->size) {
            log("Processed 1 MB");
        }
    }

    EVP_MD_Final(data->digest, data->mdctx);

    int largest_integer = -1;
    unsigned char *ptr = data->buffer;
    for (size_t i = 0; i < data->length; ++i) {
        if (isdigit((int) ptr[i])) {
            long long num = 0;
            size_t j = i;
            while (j < data->length && isdigit((int) ptr[j])) {
                num *= 10;
                num += (long long) (ptr[j] - '0');
                ++j;
            }
            if (num > largest_integer) {
                largest_integer = num;
            }
        }
        ptr++;
    }

    fclose(data->file);
    munmap(data->buffer, data->size);

    char *hexdigest = NULL;
    for (int i = 0; i < EVP_MD_SIZE(EVP_md5()); ++i) {
        hexdigest = realloc(hexdigest, strlen(hexdigest) + 3);
        sprintf(hexdigest + strlen(hexdigest), "%02x", data->digest[i]);
    }

    log("Finished processing file.");

    return data;
}

