def md5_hash(file_paths: List[str], temporary_directory: str = '.temp', max_threads: int = 4, log_every: int = 1048576):  # 1 MB
    if not os.path.exists(temporary_directory) or not os.access(temporary_directory, os.W_OK | os.R_OK | os.X_OK):
        raise FileNotFoundError(f"Invalid temporary directory: {temporary_directory}")

    hashes = {}
    executor = ThreadPoolExecutor(max_workers=max_threads)

    def process_file(file_path):
        nonlocal hashes
        with open(file_path, 'rb') as f:
            hash_obj = hashlib.md5()
            while True:
                data = f.read(4096)
                if not data:
                    break
                hash_obj.update(data)

                processed = len(data)
                if processed >= log_every:
                    timestamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                    logging.info(f"{timestamp} | {file_path} | {hash_obj.hexdigest()[:5]}...")
                    processed = 0

            hashes[file_path] = hash_obj.hexdigest()

    for file_path in file_paths:
        if not os.path.exists(file_path) or not os.access(file_path, os.R_OK):
            raise IsADirectoryError(f"Invalid file path: {file_path}")
        executor.submit(process_file, file_path)

    for _ in as_completed(executor.shutdown(wait=True), executor.submit):
        pass

    return hashes

