            raise IOError(f"Checkpoint file {checkpoint_filename} is unwritable")
        with open(checkpoint_filename, 'wb') as f:
            pickle.dump(hashes, f)

    hashes = read_checkpoint()
    for file_path in file_paths:
        if file_path not in hashes:
            # Process the file
            ...  # Similar to md5_hash function implementation
            hashes[file_path] = hash_obj.hexdigest()
            save_checkpoint(hashes)

    return hashes
