import os
import hashlib
import sys

class FileHashError(Exception):
    pass

def calculate_md5_hashes(file_paths, buffer_size=8192, skip_invalid=False):
    if len(file_paths) > 100:
        raise FileHashError("Too many files provided. Maximum limit is 100.")

    hashes = {}
    md5 = hashlib.md5()

    for file_path in file_paths:
        if not os.path.exists(file_path) or not os.path.isfile(file_path):
            print(f"Warning: File {file_path} does not exist or is not a file.")
            continue

        with open(file_path, 'rb') as f:
            if os.path.getsize(file_path) == 0:
                print(f"Warning: File {file_path} is empty.")
                if skip_invalid:
                    continue

            for chunk in iter(lambda: f.read(buffer_size), b''):
                md5.update(chunk)

        hashes[file_path] = md5.hexdigest()
        md5.reset()

    return hashes
```

