['```python
import os
import hashlib
import concurrent.futures
import logging
from typing import Dict, Optional

class FileProcessor:
    def __init__(self, buffer_size: int = 4096, max_workers: int = 100, log_warnings: bool = True, skip_invalid: bool = False):
        self.buffer_size = buffer_size
        self.max_workers = max_workers
        self.log_warnings = log_warnings
        self.skip_invalid = skip_invalid
        self.hash_map: Dict[str, str] = {}
        self.logger = logging.getLogger(__name__)

    def process_directory(self, directory: str):
        try:
            file_list = [f for f in os.scandir(directory) if f.is_file()]
            with concurrent.futures.ThreadPoolExecutor(max_workers=self.max_workers) as executor:
                futures = [executor.submit(self._process_file, file, self.buffer_size) for file in file_list]
                for future in concurrent.futures.as_completed(futures):
                    result = future.result()
                    file_name, hash_value = result[0], result[1]
                    if self.hash_map.get(file_name) != hash_value:
                        self.hash_map[file_name] = hash_value
                        if self.log_warnings:
                            self.logger.warning(f"File {file_name} has different MD5 hash than calculated.")
                if not self.skip_invalid and len(self.hash_map) != len(file_list):
                    self.logger.warning(f"Some files were skipped due to missing or corrupted data.")
        except Exception as e:
            self.logger.error(f"Error occurred while processing directory: {e}")

    def _process_file(self, file: os.PathLike, buffer_size: int) -> Tuple[str, str]:
        try:
            with open(file, "rb") as f:
                hasher = hashlib.md5()
                for chunk in iter(lambda: f.read(buffer_size), b""):
                    hasher.update(chunk)
                file_name = file.name
                return file_name, hasher.hexdigest()
        except PermissionError as e:
            self.logger.warning(f"Unable to read file {file}: {e}. Skipping...")
            return "", ""
        except Exception as e:
            self.logger.error(f"Error occurred while processing file {file}: {e}")
            return "", ""

if __name__ == "__main__":
    logging.basicConfig(format="%(levelname)s - %(message)s", level=logging.INFO)
    processor = FileProcessor()
    processor.process_directory("/path/to/your/directory")
```

This code defines a `FileProcessor` class that takes several parameters, including buffer size, maximum number of workers (threads), whether to log warnings, and whether to skip invalid files. The `process_directory` method processes the given directory asynchronously using a ThreadPoolExecutor from concurrent.futures.

The function reads files in chunks defined by the buffer_size parameter and calculates their MD5 hashes. It handles potential issues such as file permission errors, corrupted files, missing files, or network latency when dealing with remote files. The user can customize the buffer size and maximum file count for processing to balance performance and resource usage according to their specific needs.']

