void *read_file(const char *filename, size_t *size) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) return NULL;
    fseek(fp, 0, SEEK_END);
    *size = ftell(fp);
    rewind(fp);
    void *buffer = malloc(*size);
    if (fread(buffer, 1, *size, fp) != *size) {
        free(buffer);
        return NULL;
    }
    fclose(fp);
    return buffer;
}

