int filter_data(Weather** weather_data, int* temperatures, float* humidities, char** labels, int num_records, double temp_threshold, float hum_threshold, float max_avg_temp, int* num_selected) {
    int i, j, k;
    double avg_temp = 0.0;

    if(!weather_data || !temperatures || !humidities || !labels || num_records <= 0 || num_records != *num_selected) {
        perror("Invalid input");
        return -1;
    }

    Weather* selected_data = malloc(num_records * sizeof(Weather));
    if(!selected_data) {
        perror("Memory allocation failed");
        return -1;
    }

    for(i = 0; i < num_records; ++i) {
        if((*temperatures)[i] >= temp_threshold && (*humidities)[i] <= hum_threshold) {
            selected_data[k++] = *weather_data[i];
            avg_temp += selected_data[k - 1].temperature;
        }
    }

    if(k == 0) {
        free(selected_data);
        return -1;
    }

    avg_temp /= k;
    if(avg_temp > max_avg_temp) {
        double adjustment = (max_avg_temp - avg_temp) / k;
        for(i = 0; i < k; ++i)
            selected_data[i].temperature += adjustment;
    }

    *num_selected = k;

    // Reallocate memory for selected data and copy the data into it.
    Weather* selected_weather = malloc(k * sizeof(Weather));
    if(!selected_weather) {
        perror("Memory allocation failed");
        free(selected_data);
        return -1;
    }

    memcpy(selected_weather, selected_data, k * sizeof(Weather));
    free(selected_data);

    // Copy the filtered data back to the original pointers.
    for(i = 0; i < k; ++i) {
        weather_data[i] = &selected_weather[i];
        temperatures[i] = &(selected_weather[i]->temperature);
        humidities[i] = &(selected_weather[i]->humidity);
        strcpy(labels[i], selected_weather[i]->label);
    }

    return 0;
}
