    if (stat(path, &st) < 0 || fstat(fileno(fp), &st) != 0) {
        perror("Error stat'ing file");
        return;
    }

    fd_temp = open(temp_file, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR);
    if (fd_temp < 0) {
        perror("Error creating temporary file");
        return;
    }

    MD5_Init(&ctx);

    while ((bytes_read = fread(buffer, sizeof(unsigned char), sizeof(buffer), fp)) > 0) {
        MD5_Update(&ctx, buffer, bytes_read);
        if (st.st_size - ftell(fp) < sizeof(buffer)) {
            bytes_written = write(fd_temp, buffer, bytes_read);
            if (bytes_written != bytes_read) {
                perror("Error writing to temporary file");
                return;
            }
        }
    }

    if (ferror(fp)) {
        perror("Error reading from file");
        return;
    }

    fclose(fp);
    close(fd_temp);

    MD5_Final(digest, &ctx);

    // Implement resuming and checkpointing mechanism here...
