typedef struct {
    int value;
    long offset;
    int key;
} record;

void shuffle_records(record* records, size_t size, long* offsets, int limit);
bool adjust_values(record* records, size_t size, int limit);

// Dynamically allocate memory for arrays
long* create_offsets(size_t size) {
    long* offsets = (long*)malloc(size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error allocating memory for offsets.\n");
        return NULL;
    }
    return offsets;
}

int* create_keys(size_t size) {
    int* keys = (int*)malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error allocating memory for keys.\n");
        return NULL;
    }
    return keys;
}

record** create_records(size_t size) {
    record** records = (record**)malloc(size * sizeof(record*));
    if (!records) {
        fprintf(stderr, "Error allocating memory for records.\n");
        return NULL;
    }

    for (size_t i = 0; i < size; ++i) {
        records[i] = (record*)malloc(sizeof(record));
        if (!records[i]) {
            fprintf(stderr, "Error allocating memory for individual record.\n");
            return NULL;
        }
    }

    return records;
}

void shuffle_records(record* records, size_t size, long* offsets, int limit) {
    // Implement Fisher-Yates algorithm for in-place shuffling of the records based on their offsets
    for (size_t i = size - 1; i > 0; --i) {
        size_t j = rand() % (i + 1);

        if (j != i) {
            record temp = records[j];
            records[j] = records[i];
            records[i] = temp;
        }
    }
}

bool adjust_values(record* records, size_t size, int limit) {
    int sum = 0;
    for (size_t i = 0; i < size; ++i) {
        sum += records[i]->value;
    }

    if (sum > limit) {
        float factor = (float)limit / sum;
        for (size_t i = 0; i < size; ++i) {
            records[i]->value *= factor;
        }
    }

    return sum <= limit;
}
