#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_EXTENSION 8
#define VALUE_LIMIT 1000
#define NODE_SIZE 256

typedef struct {
    int value;
    struct node *next;
    char buffer[NODE_SIZE];
} Node;

void init_node(Node **node, const char *buffer) {
    (*node) = (Node *) malloc(sizeof(Node));
    if (!(*node)) exit(EXIT_FAILURE);
    memset((*node), 0, sizeof(**node));
    strncpy((*node)->buffer, buffer, NODE_SIZE);
    (*node)->next = NULL;
}

void free_node(Node **node) {
    if (!(*node)) return;
    free(*node);
    *node = NULL;
}

unsigned int calc_extension_length(const char *filename) {
    size_t len = strlen(filename);
    if (len < MAX_EXTENSION) return len - (MAX_EXTENSION - 1);
    else return MAX_EXTENSION - 1;
}

char* generate_extension(const char *filename) {
    int length = calc_extension_length(filename);
    char *ext = malloc(length + 1);
    if (!ext) exit(EXIT_FAILURE);
    memset(ext, 0, length + 1);
    strncpy(ext, filename + (strlen(filename) - length), length);
    return ext;
}

char* generate_new_filename(const char *original, const char *extension) {
    int original_len = strlen(original);
    char *new_filename = malloc(original_len + 1 + extension[0] + 1);
    if (!new_filename) exit(EXIT_FAILURE);
    memset(new_filename, 0, original_len + 1 + extension[0] + 1);
    strncpy(new_filename, original, original_len);
    strcat(new_filename, extension);
    return new_filename;
}

void merge_sort(Node **head, int left, int right) {
    if (left >= right) return;
    int mid = (left + right) / 2;
    merge_sort(head, left, mid);
    merge_sort(head, mid + 1, right);
    merge(head, left, mid, right);
}

void merge(Node **head, int left, int mid, int right) {
    Node *left_arr[right - left + 1];
    Node *right_arr[right - left + 1];
    int i, j;

    for (i = 0; i < (right - left + 1); ++i) {
        left_arr[i] = NULL;
        right_arr[i] = NULL;
    }

    Node *cursor = *head;
    for (i = left, j = 0; cursor != NULL && i <= mid; ++i, cursor = cursor->next) {
        init_node(&left_arr[j++], cursor->buffer);
    }

    for (cursor = *head, i = left, j = 0; cursor != NULL && i <= right; ++i, cursor = cursor->next) {
        if (i > mid) {
            init_node(&right_arr[j++], cursor->buffer);
        }
    }

    merge_sort(head, left, mid);
    merge_sort(head + mid - left + 1, mid + 1, right);

    for (i = left, j = k = 0; i <= right && j < (right - left + 1); ++i) {
        if (left_arr[j]->value <= right_arr[k]->value) {
            *head = left_arr[j++];
        } else {
            *head = right_arr[k++];
        }
        head = &(head->next);
    }

    while (left_arr[j]) {
        *head = left_arr[j++];
        head = &(head->next);
    }

    while (right_arr[k]) {
        *head = right_arr[k++];
        head = &(head->next);
    }
}

int compare_nodes(const void *a, const void *b) {
    return ((Node *) a)->value - ((Node *) b)->value;
}

void sort_nodes(Node **head) {
    qsort(*head, headlen(head), sizeof(Node), compare_nodes);
}

int headlen(Node **head) {
    int len = 0;
    for (Node *cursor = *head; cursor != NULL; cursor = cursor->next) ++len;
    return len;
}

int is_value_limit_exceeded(Node **head, int value_limit) {
    int sum = 0;
    Node *cursor = *head;
    while (cursor != NULL) {
        sum += cursor->value;
        cursor = cursor->next;
    }
    return sum > value_limit;
}

void adjust_values(Node **head, int value_limit) {
    int factor = value_limit / headlen(*head);
    Node *cursor = *head;
    while (cursor != NULL) {
        cursor->value *= factor;
        cursor = cursor->next;
    }
}

// ... Other functions for AES-256-CBC Cipher Initialization, File Storage System, and System Integration & Logging.
