typedef enum { GOOD, SUSPECT, BAD } quality_t;
typedef struct {
    int id;
    float value;
    quality_t status;
} sensor_data_t;

sensor_data_t* allocate_and_init(int size) {
    sensor_data_t *data = malloc(sizeof(sensor_data_t) * size);
    if (!data) return NULL;

    for (int i = 0; i < size; ++i) {
        data[i].id = i;
        data[i].value = rand();
        data[i].status = (quality_t)(rand() % 3);
    }

    return data;
}

void filter(sensor_data_t *data, int size, float min_val, float max_val, int min_qty, int max_qty) {
    int selected = 0, good = 0, suspect = 0, bad = 0;
    for (int i = 0; i < size; ++i) {
        if (data[i].value >= min_val && data[i].value <= max_val && data[i].status >= min_qty && data[i].status <= max_qty) {
            if (!selected++) continue;
            switch (data[i].status) {
                case GOOD: ++good; break;
                case SUSPECT: ++suspect; break;
                case BAD: ++bad; break;
            }
            memcpy(&data[selected], &data[i], sizeof(sensor_data_t));
        }
    }

    // Maintain a balanced representation of data quality statuses
    while (good < selected || suspect + bad < 2 * selected) {
        int idx = rand() % size;
        if (data[idx].status == GOOD && good < selected)
            memcpy(&data[selected++], &data[idx], sizeof(sensor_data_t));
        else if ((data[idx].status == SUSPECT || data[idx].status == BAD) && suspect + bad < 2 * selected) {
            switch (data[idx].status) {
                case SUSPECT: ++suspect; break;
                case BAD: ++bad; break;
            }
            memcpy(&data[selected++], &data[idx], sizeof(sensor_data_t));
        }
    }
}

