    } else {
        throw formatNotSupported();
    }

    auto it = data.begin();
    if (it != data.end() && *it == searchTerm) {
        it = data.insert_after(++it, std::move(insertionValue));
        count++;
    } else {
        data.push_back(std::move(insertionValue));
        count += data.size();
    }

    // Deallocate parser and any other resources here if necessary

