static pthread_mutex_t workers_lock = PTHREAD_MUTEX_INITIALIZER;

int init_network_service() {
    size_t size = sizeof(HTTPWorker) * worker_count;
    workers = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (workers == MAP_FAILED) {
        perror("mmap");
        return -1;
    }

    pthread_t tid;
    for (size_t i = 0; i < worker_count; ++i) {
        workers[i].request_id = i;
        workers[i].state = WAITING;
    }

    // Implement an accept function to handle incoming connections, start new requests and manage worker threads here.

    return 0;
}

void cleanup_network_service() {
    if (workers != MAP_FAILED) {
        munmap(workers, sizeof(HTTPWorker) * worker_count);
    }
}

// Implement a function to periodically check for completed requests and update response times.
void check_completed_requests() {
    pthread_mutex_lock(&workers_lock);

    time_t now = time(NULL);
    for (size_t i = 0; i < worker_count; ++i) {
        if (workers[i].state == COMPLETED) {
            workers[i].response_time = now - workers[i].response_time;
            workers[i].state = WAITING;
        }
    }

    pthread_mutex_unlock(&workers_lock);
}
