```python
import asyncio, os, sys, hashlib, logging, aiofiles, time, getpass
from urllib.parse import urlparse

class MD5FileProcessor:
    def __init__(self, buffer_size=8192, batch_size=200, retry_limit=3, backoff_interval=2.0, log_file='md5_processor.log', skip_invalid=False):
        self.buffer_size = buffer_size
        self.batch_size = batch_size
        self.retry_limit = retry_limit
        self.backoff_interval = backoff_interval
        self.skip_invalid = skip_invalid
        self.log_file = log_file
        self.workers = []

    async def worker(self):
        while True:
            files = await self.get_next_batch()
            if not files:
                break
            for file in files:
                try:
                    md5 = await self._process_file(file)
                    print(f"MD5 Hash of {file}: {md5}")
                except Exception as e:
                    logging.warning(f"Error processing file {file}: {e}", file=self.log_file, stacklevel=2)

    async def _process_file(self, file):
        if not os.path.exists(file) or not os.path.isfile(file) or os.stat(file).st_size == 0:
            raise FileNotFoundError(f"File {file} not found")
        with aiofiles.open(file, 'rb') as f:
            hash_obj = hashlib.md5()
            while True:
                data = await f.read(self.buffer_size)
                if not data:
                    break
                hash_obj.update(data)
            return hash_obj.hexdigest()

    async def get_next_batch(self):
        if not self.workers:
            self.workers = [asyncio.create_task(self.worker()) for _ in range(len(os.listdir('.')) // self.batch_size + 1)]
        files = []
        for i, worker in enumerate(self.workers):
            if not worker.done():
                files += await worker.gather(*([worker.get() for _ in range(self.batch_size)], timeout=5.0) or [])
            else:
                self.workers.pop(i)
        return files[::-1]

    async def run(self):
        try:
            await self.get_next_batch()
        finally:
            for worker in self.workers:
                worker.cancel()
            await asyncio.wait(self.workers)

def main():
    md5 = MD5FileProcessor()
    if len(sys.argv) > 1 and sys.argv[1] == '--distributed':
        md5.batch_size *= int(os.cpu_count() // 2) + 1
    try:
        asyncio.run(md5.run())
    except KeyboardInterrupt:
        logging.info("Shutdown requested", file=md5.log_file, stacklevel=2)
        for worker in md5.workers:
            worker.cancel()
        asyncio.wait(md5.workers)

if __name__ == '__main__':
    main()
```

To run the script in a distributed manner, simply add `--distributed` flag to the command line arguments:

