        with open(filepath, 'rb') as f:
            for chunk in iter(lambda: f.read(self.buffer_size), b''):
                hash_obj.update(chunk)
        return hash_obj.hexdigest()

    def _validate_file(self, filepath):
        if not os.path.exists(filepath) or not os.path.isfile(filepath) or os.path.getsize(filepath) == 0:
            return False
        return True

    @staticmethod
    def _retry_func(func, *args, **kwargs):
        retry_count = kwargs.pop('retry_count', 0)
        sleep_time = kwargs.pop('sleep_time', 0)
        if retry_count >= kwargs['retry_limit']:
            raise Exception("Maximum retry limit reached")
        try:
            return func(*args, **kwargs)
        except Exception as e:
            logging.warning(f"Error occurred while processing {args[0]}: {str(e)}. Retrying...")
            kwargs['retry_count'] += 1
            kwargs['sleep_time'] = min(sleep_time * 2, kwargs['backoff_interval'])
            return MD5Hasher._retry_func(func, *args, **kwargs)

    def _process_file(self, filepath: str, priority_level: Optional[int] = None, log_func: Callable[[str], None] = logging.info):
