                log_func(f"Warning: Skipping invalid file {filepath}")
            return
        try:
            hash_value = self._get_file_hash(filepath)
        except Exception as e:
            if not kwargs['skip_warnings']:
                log_func(f"Warning: Error while calculating MD5 for file {filepath}: {str(e)}")
            return
        if priority_level in self.priority_levels:
            self.priority_levels[priority_level].add(hash_value)
        else:
            self.priority_levels[0].add(hash_value)

    def process_directory(self, directory: str, log_func: Callable[[str], None] = logging.info, skip_warnings=False, num_workers=1):
        file_list = [f for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f))]
