import os
import hashlib
import concurrent.futures
import logging
from time import sleep

def set_config(buffer_size=8192, batch_size=200, retry_limits=3, backoff_interval=2.0):
    global BUFFER_SIZE, BATCH_SIZE, RETRY_LIMITS, BACKOFF_INTERVAL
    BUFFER_SIZE = buffer_size
    BATCH_SIZE = batch_size
    RETRY_LIMITS = retry_limits
    BACKOFF_INTERVAL = backoff_interval

def md5_calculator(dir_path, log_file=None, skip_invalid_files=False):
    file_list = [f for f in os.listdir(dir_path) if os.path.isfile(os.path.join(dir_path, f))]
    processed_files = 0

    with concurrent.futures.ThreadPoolExecutor(max_workers=os.cpu_count()) as executor:
        results = {}

        for batch in sorted(list(split(file_list, BATCH_SIZE)), reverse=True):
            future_to_file = {executor.submit(process_file, file, log_file, skip_invalid_files): file for file in batch}
            results.update({f: None for f in batch})
            for future in concurrent.futures.as_completed(future_to_file):
                file, _ = future_to_file[future]
                result = future.result()

                if result is not None:
                    results[file] = result
                    processed_files += 1

    for file, hash_value in results.items():
        if hash_value is not None:
            print(f'File: {file}, MD5 Hash: {hash_value}')
        else:
            logging.warning(f'Skipping file: {file} due to integrity issues')

def process_file(file, log_file=None, skip_invalid_files=False):
    try:
        with open(file, 'rb') as f:
            md5 = hashlib.md5()
            for chunk in iter(lambda: f.read(BUFFER_SIZE), b""):
                md5.update(chunk)

            return md5.hexdigest() if validate_file(file, log_file) else None
    except Exception as e:
        logging.error(f'Error processing file {file}: {e}')
        if skip_invalid_files:
            return None
        else:
            raise e

def validate_file(file, log_file=None):
    try:
        with open(file, 'rb'):
            pass
        return True
    except Exception as e:
        logging.warning(f'Validation error for file {file}: {e}')
        if log_file is not None:
            with open(log_file, 'a') as log:
                log.write(f'Error validating file {file}: {e}\n')
        return False

def split(iterable, n):
    return (itertools.islice(iterable, n))

if __name__ == "__main__":
    set_config()
    md5_calculator('/path/to/your/directory')
