import os
import hashlib
import asyncio
from aiofiles import (aopen, AIOFile)
from concurrent.futures import ProcessPoolExecutor

class FileProcessor:
    def __init__(self, batch_size=200, buffer_size=8192, retry_limit=3, backoff_interval=5, skip_invalid=False):
        self.batch_size = batch_size
        self.buffer_size = buffer_size
        self.retry_limit = retry_limit
        self.backoff_interval = backoff_interval
        self.skip_invalid = skip_invalid
        self.log = open('processing_log.txt', 'a')

    async def process_file(self, file):
        try:
            with AIOFile(file, mode='rb') as f:
                hash_object = hashlib.md5()
                while True:
                    chunk = await f.read(self.buffer_size)
                    if not chunk:
                        break
                    hash_object.update(chunk)
                return file, hash_object.hexdigest()
        except FileNotFoundError:
            if self.skip_invalid:
                print(f'Skipping invalid file: {file}')
                return None, None
            else:
                self.log.write(f'Warning: Invalid file: {file}\n')
                return None, None
        except (PermissionError, OSError) as e:
            if self.skip_invalid:
                print(f'Skipping invalid file with error: {e} - {file}')
                return None, None
            else:
                self.log.write(f'Warning: Error accessing file: {e} - {file}\n')
                return None, None
        except TimeoutError as e:
            self.log.write(f'Warning: Network timeout while processing file: {e} - {file}\n')
            if self.retry_limit > 0:
                return await asyncio.wait_for(self.process_file(file), timeout=self.backoff_interval)[0]
            else:
                print(f'Skipping file after retry limit exceeded: {file}')
                return None, None
        except Exception as e:
            self.log.write(f'Warning: Unexpected error while processing file: {e} - {file}\n')
            if self.retry_limit > 0:
                return await asyncio.wait_for(self.process_file(file), timeout=self.backoff_interval)[0]
            else:
                print(f'Skipping file after retry limit exceeded: {file}')
                return None, None

    def process_directory(self, directory):
        future_tasks = []
        for root, dirs, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                if os.path.isfile(file_path):
                    future_tasks.append(asyncio.ensure_future(self.process_file(file_path)))
        return asyncio.gather(*future_tasks)

def distributed_processing(directory, workers=1):
    with ProcessPoolExecutor(max_workers=workers) as executor:
        for chunk in [directory[i:i+self.batch_size] for i in range(0, len(directory), self.batch_size)]:
            executor.submit(FileProcessor().process_directory, chunk)
