import os
import hashlib
import asyncio
from aiofiles import (aiofiles, OSFile, OSSyncMode)
import logging
import time
from typing import NamedTuple, Optional

class FileProcessingConfig(NamedTuple):
    batch_size: int = 200
    buffer_size: int = 8192
    max_retries: int = 5
    backoff_interval: float = 1.5
    skip_invalid_files: bool = False
    workers: int = os.cpu_count() * 2

async def _process_file(file_path, hasher, config):
    try:
        async with aiofiles.open(file_path, mode='rb', buffering=config.buffer_size) as f:
            hash_obj = hasher()
            while True:
                data = await f.read(config.buffer_size)
                if not data:
                    break
                hash_obj.update(data)
            return hash_obj.hexdigest()
    except FileNotFoundError:
        if config.skip_invalid_files:
            logging.warning(f"Skipping invalid file: {file_path}")
            return None
        else:
            raise FileNotFoundError(f"File not found: {file_path}")
    except IsADirectoryError:
        if config.skip_invalid_files:
            logging.warning(f"Skipping invalid file: {file_path} (is a directory)")
            return None
        else:
            raise IsADirectoryError(f"{file_path} is not a valid file.")
    except PermissionError:
        if config.skip_invalid_files:
            logging.warning(f"Skipping invalid file: {file_path} (permissions error)")
            return None
        else:
            raise PermissionError(f"Permission error for file: {file_path}")
    except TimeoutError:
        if config.skip_invalid_files:
            logging.warning(f"Skipping invalid file: {file_path} (timeout error)")
            return None
        else:
            raise TimeoutError(f"Timeout error for file: {file_path}")

def process_directory(root_dir, hasher=hashlib.md5, config=FileProcessingConfig()):
    os.makedirs(config.workers * 2, exist_ok=True)

    tasks = []
    processed_files = 0
    log_file = open(f"logs_{os.getpid()}.log", "w+")

    async def worker():
        nonlocal tasks, processed_files
        while len(tasks) < config.workers:
            file_path = next((f for f in os.listdir(root_dir) if not f.startswith('.')), None)
            if not file_path:
                break
            task = asyncio.create_task(_process_file(os.path.join(root_dir, file_path), hasher, config))
            tasks.append(task)
        while len(tasks):
            done, _ = await asyncio.wait(tasks)
            for task in done:
                result = task.result()
                if result:
                    processed_files += 1
                    log_file.write(f"{result} - {os.path.join(root_dir, file_path)}\n")
        log_file.close()

    asyncio.run(asyncio.gather(*[worker() for _ in range(config.workers)]))
