typedef struct {
    const char *operation;
    const char *keyfile;
    const char *iv_file;
    int verbosity;
    int output_format;
} Config;

Config parse_config(const char *path) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        perror("Failed to open configuration file.");
        exit(EXIT_FAILURE);
    }

    Config config = {};
    char line[256];
    regex_t section_regex;
    regmatch_t match;

    regcomp(&section_regex, "^[A-Za-z0-9]+\\s*=\\s*(.*)$", REG_EXTENDED);

    while (fgets(line, sizeof(line), fp)) {
        memset(&match, 0, sizeof(match));

        if (regmatch(&section_regex, line, &match) && match.rm_eo == strlen(line) - 1) {
            char *key = strdup(line + match.rm_so);
            Config section = parse_section(key);
            if (section.operation) config = section;
        }
    }

    fclose(fp);
    regfree(&section_regex);
    return config;
}

Config parse_section(const char *line) {
    Config config = {};

    char **keys = split_string(line, '=');
    if (!keys[0] || !keys[1]) return config;

    for (int i = 0; keys[i]; ++i) {
        const char *key = keys[i];
        if (strcmp(key, "operation") == 0) config.operation = strdup(keys[++i]);
        else if (strcmp(key, "keyfile") == 0) config.keyfile = strdup(keys[++i]);
        else if (strcmp(key, "iv_file") == 0) config.iv_file = strdup(keys[++i]);
    }

    free(keys);
    return config;
}

void usage(const char *program_name) {
    printf("Usage: %s [options] <config-file>\n", program_name);
    printf("\nOptions:\n");
    printf("-v, --verbose\tIncrease output verbosity.\n");
    printf("-h, --help\tDisplay this help message and exit.\n");
}

int main(int argc, char **argv) {
    const char *config_file = NULL;
    int verbosity = 0;
    int c;

    while ((c = getopt(argc, argv, "vh")) != -1) {
        switch (c) {
            case 'v':
                ++verbosity;
                break;
            case 'h':
                usage(argv[0]);
                return EXIT_SUCCESS;
            default:
                usage(argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (optind >= argc) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    config_file = argv[optind];

    Config config = parse_config(config_file);
    if (!config.operation) {
        fprintf(stderr, "Configuration file does not contain a valid operation.\n");
        exit(EXIT_FAILURE);
    }

