meta_t* create_meta(data_t *data, time_t timestamp) {
    meta_t *new_meta = malloc(sizeof(meta_t));

    if (!new_meta) return NULL;

    new_meta->data = data;
    new_meta->timestamp = timestamp;

    return new_meta;
}

void add_to_arrays(short key, long offset, data_t *data, meta_t *meta, time_t timestamp) {
    pthread_mutex_lock(&mutex);

    if (offset < 0 || offset >= MAX_ELEMENTS) {
        fprintf(stderr, "Invalid offset: %ld\n", offset);
        pthread_mutex_unlock(&mutex);
        return;
    }

    if (keys[offset] != -1) {
        fprintf(stderr, "Array already contains an element at index: %ld\n", offset);
        pthread_mutex_unlock(&mutex);
        return;
    }

    keys[offset] = key;
    offsets[key] = offset;
    data_arr[offset] = *data;
    meta_arr[offset] = *meta;

    pthread_mutex_unlock(&mutex);
}

void destroy_data(data_t *data) {
    free(data->str);
    free(data);
}

void destroy_meta(meta_t *meta) {
    destroy_data(meta->data);
    free(meta);
}

void cleanup() {
    for (size_t i = 0; i < MAX_ELEMENTS; ++i) {
        if (keys[i] != -1) {
            destroy_data(&data_arr[i]);
            destroy_meta(&meta_arr[i]);
        }
    }

    pthread_mutex_destroy(&mutex);
}
