// Create a structure for the dynamic arrays with thread-safe mutexes
typedef struct {
    long *offsets;
    short *keys;
    data_t **data;
    meta_t **meta;
    pthread_mutex_t lock;
    size_t length;
} dynamic_array_t;

// Function to initialize a dynamic array with given length and pointers to the arrays of keys, offsets, and the two arrays of data and meta structures.
void init_dynamic_array(dynamic_array_t *arr, long *offsets, short *keys, size_t length) {
    arr->offsets = offsets;
    arr->keys = keys;
    arr->data = malloc(length * sizeof(data_t *));
    arr->meta = malloc(length * sizeof(meta_t));
    arr->length = length;

    pthread_mutex_init(&arr->lock, NULL);
}

// Function to safely push a new 'data' structure into the dynamic array.
void push_data(dynamic_array_t *arr, data_t *new_data) {
    pthread_mutex_lock(&arr->lock);

    size_t i;
    for (i = *arr->offsets; i < arr->length - 1; ++i) {
        if (!arr->keys[i]) {
            arr->keys[i] = true;
            arr->data[i] = new_data;
            arr->meta[i].data = new_data;
            arr->meta[i].timestamp = time(NULL);
            *(arr->offsets)++ = i;
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}

// Function to safely remove the 'data' structure with a given unique identifier from the dynamic array.
void remove_data(dynamic_array_t *arr, unsigned int id) {
    pthread_mutex_lock(&arr->lock);

    size_t i;
    for (i = 0; i < arr->length - *(arr->offsets); ++i) {
        if (arr->data[*(arr->offsets + i)]->id == id) {
            memset(arr->data[*(arr->offsets + i)], 0, sizeof(data_t));
            free(arr->data[*(arr->offsets + i)]->str);
            free(arr->data[*(arr->offsets + i)]);

            memcpy(arr->keys + *(arr->offsets + i), arr->keys + *(arr->offsets + i + 1), sizeof(short));
            memmove(arr->data + *(arr->offsets + i), arr->data + *(arr->offsets + i + 1),
                    (arr->length - *(arr->offsets) - i - 1) * sizeof(data_t *));
            memmove(arr->meta + *(arr->offsets + i), arr->meta + *(arr->offsets + i + 1),
                    (arr->length - *(arr->offsets) - i - 1) * sizeof(meta_t));

            *(arr->offsets)--;
            break;
        }
    }

    pthread_mutex_unlock(&arr->lock);
}
