```python
import os
import sys
import hashlib
from concurrent.futures import ThreadPoolExecutor, as_completed

def process_file(filepath, buffer_size=65536, max_files=100):
    md5 = hashlib.md5()
    with open(filepath, 'rb') as f:
        for chunk in iter(lambda: f.read(buffer_size), b''):
            md5.update(chunk)
    return (filepath, md5.hexdigest())

def process_directory(directory, buffer_size=65536, max_files=100):
    files = [f for f in os.listdir(directory) if os.path.isfile(os.path.join(directory, f))]
    valid_files = []

    with ThreadPoolExecutor(max_workers=max_files) as executor:
        results = list(executor.map(process_file, files))

        for result in results:
            filepath, hash_value = result
            try:
                if os.path.exists(filepath):
                    if os.stat(filepath).st_size > 0:
                        valid_files.append((filepath, hash_value))
                    else:
                        print(f"Warning: File '{filepath}' is empty.")
                else:
                    print(f"Warning: File '{filepath}' does not exist.")
            except PermissionError:
                print(f"Error: Insufficient permissions to access file '{filepath}'. Skipping...")
            except Exception as e:
                print(f"Error processing file '{filepath}': {e}. Skipping...")

    return valid_files
