    void sortNodes(Node* head) {
        if (!head || !head->next) return;

        Node *left = head, *middle = head, *right = head->next;
        while (right != NULL) {
            if (strcmp(left->str, middle->str) < 0) {
                swapNodes(left, middle);
                left = left->next;
                middle = left;
            } else {
                right = right->next;
                if (strcmp(middle->str, right->str) > 0) {
                    swapNodes(middle, right);
                    middle = middle->next;
                }
            }
        }

        sortNodes(left);
        sortNodes(right);
    }

    // Function to adjust node values to meet the storage limit
    void adjustValues(Node* head, float limit) {
        if (!head || !head->next) return;

        float sum = 0.0f;
        Node *current = head, *prev = NULL;
        while (current != NULL) {
            sum += current->value;
            current = current->next;
        }

        float adjustment = (sum - limit) / (*num_nodes);
        current = head;
        while (current != NULL) {
            current->value -= adjustment;
            if (current->value < 0.0f) current->value = 0.0f; // Ensure no negative values
            current = current->next;
        }
    }

    // Function to swap two nodes
    void swapNodes(Node* a, Node* b) {
        long temp_offset = a->offset;
        short temp_key = a->key;
        float temp_value = a->value;
        char *temp_str = a->str;

        a->offset = b->offset;
        a->key = b->key;
        a->value = b->value;
        a->str = b->str;

        b->offset = temp_offset;
        b->key = temp_key;
        b->value = temp_value;
        b->str = temp_str;
    }

    // Entry point for data collection and management
    Node* manageMemoryAndStreamData(Config config, size_t *num_nodes) {
        // Implement resuming/pausing data collection, file I/O, etc.
        // ...
    }

    int main() {
        srand(time(NULL));

        Config config = { .range_min = 100, .range_max = 200,
                          .storage_limit = 1000, .log_file = "myapp.log",
                          .append = true };

        size_t num_nodes;
        Node* nodes = manageMemoryAndStreamData(config, &num_nodes);

