static pthread_mutex_t mem_mutex = PTHREAD_MUTEX_INITIALIZER;

long* adjust_offset(long offset, long min_offset, long max_offset) {
    if (offset < min_offset) return &min_offset;
    if (offset > max_offset) return &max_offset;
    return (long*) offset;
}

int* find_unique_keys(int m, int key_min, int key_max) {
    int* keys = (int*) calloc(m, sizeof(int));
    for (int i = 0; i < m; ++i) {
        int key = rand() % (key_max - key_min + 1) + key_min;
        while (keys[key] != 0) key = rand() % (key_max - key_min + 1) + key_min;
        keys[key] = 1;
    }
    return keys;
}

Record* init_records(int m, int n, int* keys, long* offsets) {
    Record* records = (Record*) calloc(m * n, sizeof(Record));
    pthread_mutex_lock(&mem_mutex);
    for (int i = 0; i < m * n; ++i) {
        int key = keys[i];
        long offset = *adjust_offset(offsets[i], LONG_MIN, LONG_MAX);
        for (int j = 0; j < i; ++j) {
            if (records[j].key == key && records[j].offset == offset) goto next;
        }
        records[i].offset = offset;
        records[i].key = key;
        records[i].value = rand() % (VALUE_MAX - VALUE_MIN + 1) + VALUE_MIN;
        next: {}
    }
    pthread_mutex_unlock(&mem_mutex);
    return records;
}

void free_memory(Record* records, int m, int* keys, long* offsets) {
    if (records) free(records);
    if (keys) free(keys);
    if (offsets) free(offsets);
}

Record* create_data_structures(int m, int n, long min_offset, long max_offset, int key_min, int key_max, int value_min, int value_max) {
    pthread_mutex_lock(&mem_mutex);
    int* keys = find_unique_keys(m, key_min, key_max);
    long* offsets = (long*) calloc(n, sizeof(long));
    Record* records;
    if (!offsets || !keys) {
        printf("Error: Out of memory\n");
        free_memory(NULL, 0, keys, offsets);
        pthread_mutex_unlock(&mem_mutex);
        return NULL;
    }
    for (int i = 0; i < n; ++i) {
        offsets[i] = min_offset + rand() % ((max_offset - min_offset) * 2) - max_offset;
        offsets[i] = *adjust_offset(offsets[i], min_offset, max_offset);
    }
    records = init_records(m, n, keys, offsets);
    free_memory(NULL, 0, NULL, offsets);
    pthread_mutex_unlock(&mem_mutex);
    return records;
}
