constexpr unsigned int MAX_TRIES = 10;
constexpr unsigned int MAX_RETRIES = 1000;

struct Record {
    long offset;
    int key;
    int value;
};

class MemoryManager {
private:
    std::vector<long> offsets;
    std::vector<int> keys;
    std::deque<Record> records;
    std::mutex mtx;

    long adjustOffset(long value) const {
        return (value < min_offset ? min_offset : (value > max_offset ? max_offset : value));
    }

    bool findUniqueKey(int key) {
        if (std::find(keys.begin(), keys.end(), key) == keys.end()) {
            return true;
        }
        for (size_t i = 0; i < MAX_TRIES && keys.size() < MAX_RETRIES; ++i) {
            key += std::rand() % ((std::max(key_min, key + 1) - key) * 2);
            if (find(keys.begin(), keys.end(), key) == keys.end()) {
                break;
            }
        }
        return keys.size() < MAX_RETRIES;
    }

public:
    MemoryManager(unsigned int n, unsigned int m, long min_offset, long max_offset,
                   int key_min, int key_max, int value_min, int value_max)
        : offsets(n), keys(), records() {
        for (auto& o : offsets) {
            o = adjustOffset(o);
        }

        std::vector<int> tmp_keys;
        for (size_t i = 0; i < m; ++i) {
            int key = key_min + std::rand() % ((key_max - key_min + 1) * 2);
            if (!findUniqueKey(key)) {
                throw std::runtime_error("Unable to allocate unique keys");
            }
            tmp_keys.push_back(key);
        }
        keys.swap(tmp_keys);

        records.resize(m, {});
    }

    ~MemoryManager() {
        for (auto& r : records) {
            delete &r;
        }
        offsets.clear();
        keys.clear();
    }

    Record* allocateRecord() {
        std::unique_lock<std::mutex> lock(mtx);
        while (!records.empty()) {
            if (find(keys.begin(), keys.end(), records.front().key) == keys.end()) {
                break;
            }
            records.pop_front();
        }

        if (records.empty()) {
            throw std::runtime_error("Unable to allocate record");
        }
        auto* record = &records.front();
        record->value = static_cast<int>(std::rand() % ((value_max - value_min + 1) * 2)) + value_min;
        return record;
    }
};
