    pthread_mutexattr_setrobust(&attr, PTHREAD_MUTEX_ROBUST); // Robust mutex to handle race conditions and deadlocks

    pthread_t garbage_collector;
    struct timespec period = {.tv_sec = 10, .tv_nsec = 0}; // Garbage collection every 10 seconds

