    // Loop to set random values for each record structure's int field
    for (size_t i = 0; i < capacity; ++i) {
        records[i].value = rand() % 1000;
    }
}

// Garbage collection function to clean up unused 'meta' structures and their corresponding 'record' structures
void* garbage_collection(void *capacity_arg) {
    size_t capacity = *(size_t*) capacity_arg;
    long *offsets = NULL, *key_values = NULL;
    short *keys = NULL;
    record *records = NULL;
    meta *metas = NULL;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    while (1) {
        pthread_mutex_lock(&mutex);

        // Re-allocate memory to avoid memory fragmentation and to account for garbage collection
        if (!offsets || !keys || !records || !metas || !key_values) {
            offsets = realloc(offsets, (capacity * 2) * sizeof(long));
            keys = realloc(keys, (capacity * 2) * sizeof(short));
            records = realloc(records, (capacity * 2) * sizeof(record));
            metas = realloc(metas, (capacity * 2) * sizeof(meta));
            key_values = realloc(key_values, ((capacity * 2) * 2) * sizeof(int));
        }

        size_t num_free = 0;
        for (size_t i = 0; i < capacity; ++i) {
            if (!metas[i].ref) {
                num_free++;
            }
        }

        pthread_mutex_unlock(&mutex);

        if (num_free > capacity / 4) { // Free memory if more than a quarter of the data structures are free
            pthread_mutex_lock(&mutex);

            for (size_t i = 0; i < capacity; ++i) {
                if (!metas[i].ref) {
                    records += num_free;
                    metas += num_free;
                    offsets += num_free;
                    keys += num_free;
                    key_values += (2 * num_free); // Adjust for garbage collection and key-value pairs
                }
            }

            pthread_mutex_unlock(&mutex);

            free(records - num_free);
            free(metas - num_free);
            free(offsets - num_free);
            free(keys - num_free);
            free(key_values - (2 * num_free)); // Adjust for garbage collection and key-value pairs

            capacity *= 2; // Increase capacity to account for garbage collection
        }

        pthread_mutex_lock(&mutex);
        pthread_mutex_timedlock(&mutex, &period); // Sleep during garbage collection to minimize performance impact
        pthread_mutex_unlock(&mutex);
    }

    return NULL;
}
