```cpp
#include <iostream>
#include <vector>
#include <deque>
#include <unordered_map>
#include <random>
#include <algorithm>
#include <thread>
#include <mutex>

// Event structure
struct Event {
    char buffer[1024];
    Record* associatedRecord;
};

// Record structure
struct Record {
    double value;
    Event* event;
    time_t timestamp;
};

class DataManager {
private:
    std::vector<int> indices;
    std::vector<int> keys;
    std::vector<Record> records;
    std::deque<Event*> eventsToCleanup;
    std::unordered_map<Event*, Record*> eventMap;
    size_t maxRecords;
    time_t shuffleInterval;
    double sumLimit;
    mutex cleanupMutex;

public:
    DataManager(size_t maxRecords, time_t shuffleInterval, double sumLimit)
        : maxRecords(maxRecords), shuffleInterval(shuffleInterval), sumLimit(sumLimit) {}

    void addRecord(int index, int key, const Record& record) {
        indices.push_back(index);
        keys.push_back(key);
        records.emplace_back(record);
        eventMap[&records.back().event] = &records.back();
    }

    void garbageCollect() {
        std::unique_lock<std::mutex> lock(cleanupMutex);
        while (!eventsToCleanup.empty()) {
            auto event = eventsToCleanup.front();
            delete event;
            eventsToCleanup.pop_front();
            eventMap.erase(event);
        }
    }

    void shuffleRecords() {
        // Shuffle the records using a Fisher-Yates algorithm and adjust the sum if necessary
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(0, indices.size() - 1);

        for (size_t i = indices.size() - 1; i > 0; --i) {
            size_t j = dis(gen);
            std::swap(indices[i], indices[j]);
            std::swap(keys[i], keys[j]);
            std::swap(records[i], records[j]);
        }

        double currentSum = 0;
        for (const auto& record : records) {
            currentSum += record.value;
        }

        if (currentSum > sumLimit) {
            double adjustment = (currentSum - sumLimit) / records.size();
            for (auto& record : records) {
                record.value -= adjustment;
            }
        }
    }
};
```

