#define MAX_RECORDS 10000
#define RECORD_SIZE (sizeof(long) + sizeof(int))
#define MIN_KEY 1
#define MAX_KEY 100
#define LOG_FILE "memory_log.txt"

typedef struct {
    int value;
} Record;

struct system {
    void* memory;
    size_t memory_size;
    size_t num_records;
    pthread_mutex_t lock;
};

int initialize_system(struct system** system) {
    *system = malloc(sizeof(struct system));
    if (!(*system)) {
        fprintf(stderr, "Error: Failed to allocate memory for the system.\n");
        return -1;
    }

    (*system)->memory_size = RECORD_SIZE * MAX_RECORDS;
    (*system)->num_records = 0;
    (*system)->memory = mmap(NULL, (*system)->memory_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if ((*system)->memory == MAP_FAILED) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        free(*system);
        return -1;
    }

    (*system)->lock = PTHREAD_MUTEX_INITIALIZER;

    Record* records = calloc(MAX_RECORDS, sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        munmap((*system)->memory, (*system)->memory_size);
        free(*system);
        return -1;
    }

    // Initialize keys with a splayed distribution for efficient search.
    for (size_t i = 0; i < MAX_RECORDS; ++i) {
        records[i].value = MIN_KEY + (rand() % ((MAX_KEY - MIN_KEY) / 2)) * 2 + (MIN_KEY + (MAX_KEY - MIN_KEY) / 2);
    }

    // Sort the keys to create a splayed distribution.
    qsort(records, MAX_RECORDS, sizeof(Record), compare_records);

    (*system)->records = records;

    return 0;
}

int add_record(struct system* system, long offset, int key) {
    pthread_mutex_lock(&(system->lock));

    for (size_t i = 0; i < system->num_records; ++i) {
        if ((system->records[i].value == key) && (system->memory_size - RECORD_SIZE * (system->num_records + 1) >= offset - system->records[i].value)) {
            memcpy((char*)(system->memory + system->records[i].value) + sizeof(long), &offset, sizeof(long));
            system->records[i].value += RECORD_SIZE;
            system->num_records++;
            pthread_mutex_unlock(&(system->lock));
            return system->num_records - 1;
        }
    }

    // Reduce record size if memory exhaustion occurs.
    if (system->memory_size < offset + RECORD_SIZE * system->num_records) {
        RECORD_SIZE = RECORD_SIZE / 2;
    }

    pthread_mutex_unlock(&(system->lock));

    int index = 0;
    for (; index < system->num_records && records[index].value <= key; ++index);
    if (index == system->num_records) {
        --index;
    }

    if (system->memory_size - RECORD_SIZE * (system->num_records + 1) < offset - system->records[index].value) {
        fprintf(stderr, "Error: Failed to add record due to memory exhaustion.\n");
        return -1;
    }

    memcpy((char*)(system->memory + system->records[index].value) + sizeof(long), &offset, sizeof(long));
    system->records[index].value += RECORD_SIZE;
    system->num_records++;

    log_event("Added record", offset, key);

    return system->num_records - 1;
}

void log_event(const char* event_name, long offset, int key) {
    FILE* log_file = fopen(LOG_FILE, "a");
    if (log_file) {
        fprintf(log_file, "%s: offset=%ld, key=%d\n", event_name, offset, key);
        fclose(log_file);
    } else {
        fprintf(stderr, "Error: Failed to open the log file.\n");
    }
}

int compare_records(const void* a, const void* b) {
    return ((*(Record*)a).value - (*(Record*)b).value);
}
