#include <sys/mman.h>

typedef struct Data {
    float value;
    char *key;
} Data;

// Custom hash function for string identifiers
uint32_t hash(const char *str, uint32_t capacity) {
    uint32_t hash = 5381;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % capacity;
}

// Memory pool for Data structures
struct MemPool {
    size_t size;
    Data *pool;
    Data *freeList;
};

void memPoolInit(struct MemPool *mp, size_t size) {
    mp->size = size;
    mp->pool = mmap(NULL, sizeof(Data) * size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mp->pool == MAP_FAILED) {
        fprintf(stderr, "Memory allocation failed\n");
        exit(EXIT_FAILURE);
    }
    mp->freeList = (Data*)mp->pool;
}

Data* memPoolAlloc(struct MemPool *mp) {
    if (!mp->freeList) {
        void *newPool = mmap(NULL, sizeof(Data) * mp->size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (newPool == MAP_FAILED) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }
        memmove(newPool, mp->pool, sizeof(Data) * mp->size);
        munmap(mp->pool, sizeof(Data) * mp->size);
        mp->pool = newPool;
        mp->freeList = (Data*)mp->pool;
    }
    Data *result = mp->freeList++;
    return result;
}

void memPoolFree(struct MemPool *mp, Data *data) {
    data->key = NULL; // free key with appropriate mechanism
    data->value = 0.0f;
    mp->freeList = (Data*)data;
}

// Work-stealing queue for concurrent tasks
typedef struct WorkItem {
    void (*func)(void*);
    void *arg;
} WorkItem;

struct TaskQueue {
    pthread_mutex_t lock;
    pthread_cond_t cond;
    size_t head, tail;
    WorkItem queue[1024]; // adjust capacity as needed
};

void taskQueuePush(struct TaskQueue *q, void (*func)(void*), void *arg) {
    pthread_mutex_lock(&q->lock);
    while (q->head - q->tail == q->capacity) {
        pthread_cond_wait(&q->cond, &q->lock);
    }
    q->queue[q->tail] = (WorkItem){ .func = func, .arg = arg };
    q->tail = (q->tail + 1) % q->capacity;
    pthread_mutex_unlock(&q->lock);
}

void* taskQueuePop(struct TaskQueue *q) {
    void* result;
    pthread_mutex_lock(&q->lock);
    while (q->head - q->tail == 0) {
        pthread_cond_wait(&q->cond, &q->lock);
    }
    result = q->queue[q->head].arg;
    q->queue[q->head].func = NULL;
    q->head = (q->head + 1) % q->capacity;
    pthread_mutex_unlock(&q->lock);
    return result;
}

void manageMemoryAndStreamData(size_t offsetSize, size_t keySize, size_t dataCount, float *offsets, short *keys, struct MemPool mp, WorkItem taskQueue, FILE* stream) {
