    if (!threads) {
        perror("Error: Unable to allocate memory for threads");
        free(dir);
        closedir(directory);
        return NULL;
    }

    while ((entry = readdir(directory)) != NULL) {
        FileMetadata* file = &dir[currentIndex++];
        snprintf(file->path, sizeof(file->path), "%s", entry->d_name);

        strcpy(file->path, getcwd(NULL, 0));
        strcat(file->path, "/");
        strcat(file->path, entry->d_name);

        file->isValid = true;
    }
    closedir(directory);

    for (int i = 0; i < currentIndex; ++i) {
        pthread_create(&threads[i], NULL, processFile, &dir[i]);
    }

    for (int i = 0; i < currentIndex; ++i) {
        pthread_join(threads[i], (void**) &dir[i]);
        if (!dir[i]) {
            free(dir);
            free(threads);
            return NULL;
        }
    }

    free(threads);

    // Perform other operations, such as caching, logging, and analysis, based on the command line option.

    return dir;
}
