def retry_if_needed(func, max_retries=3, delay=5):
    attempts = 0
    while attempts < max_retries:
        try:
            return func()
        except Exception as e:
            logging.warning(f"Failed to execute function; retrying in {delay}s: {e}")
            time.sleep(delay)
            attempts += 1
    raise RuntimeError("Maximum retries reached")

