use std::env;
use rand::Rng;
use tokio::runtime::{Builder as RuntimeBuilder, Runtime};
use tokio::sync::mpsc::{channel, Receiver, Sender};
use tokio::task::spawn;

#[derive(Clone)]
struct Record {
    key: i32,
    value: i32,
}

async fn process_record(
    offsets: &mut [i64],
    keys: &[i32],
    records: &mut Vec<Record>,
    rng: &mut dyn rand::Rng,
) {
    let (tx, rx) = channel::<()>(1);
    let record_index = rng.gen_range(0..records.len());

    spawn(async move {
        records[record_index].value = rng.gen_range(1..100); // Set random value within 1-99 range
        offsets[record_index] += 1; // Increment offset
        tx.send(()).unwrap();
    });

    rx.recv().await;
}

fn main() {
    let args: Vec<String> = env::args().collect();
    if args.len() < 3 {
        eprintln!("Usage: {} <num_offsets> <num_keys>", args[0]);
        return;
    }

    let num_offsets = args[1].parse::<i64>().unwrap();
    let num_keys = args[2].parse::<i32>().unwrap();

    // Initialize offsets and keys arrays
    let mut offsets: Vec<i64> = vec![0; num_offsets as usize];
    let mut keys: Vec<i32> = vec![1..=num_keys].collect::<Vec<i32>>();

    // Initialize records vector with default values for all elements (0, 0)
    let mut records: Vec<Record> = vec![Record { key: 0, value: 0 }; num_keys as usize];

    // Initialize the Tokio runtime
    let rt = Runtime::builder()
        .enable_all()
        .threaded_scheduler(num_cpu_cores())
        .build()
        .unwrap();

    // Random number generator
    let mut rng = rand::thread_rng();

    for _ in 0..10 { // Process 10 records concurrently
        rt.block_on(async move {
            for _ in 0..10 {
                process_record(&mut offsets, &keys, &mut records, &mut rng).await;
            }
        });
    }

    // Print results
    for record in &records {
        println!("Key: {}, Value: {}", record.key, record.value);
    }
}

fn num_cpu_cores() -> usize {
    let cpu_count = num_cpus();
    if cpu_count > 1 {
        cpu_count - 1 // Leave one for the main thread
    } else {
        0
    }
}

use std::thread;
use std::sync::Arc;

fn num_cpus() -> usize {
    let mut cpus = vec![1; 1];
    unsafe {
        libc::sysconf(libc::_SC_NPROCESSORS_CONF)
            .unwrap() as usize
            .into_iter()
            .for_each(|x| cpus[0] += x);
    }
    cpus[0]
}
