        "vector" => Box::new(VecDeque::new()),
        "hash_map" => Box::new(HashMap::new()),
        _ => panic!("Invalid data structure specified"),
    }
    .into()
}

async fn generate_and_validate_record(rng: &mut thread_rng, data: &mut DataStructure) {
    let key = data.len();
    loop {
        let offset = rng.gen_range(0..100);
        match data.get_mut(key as usize) {
            Some(_) => (),
            None => break,
        }
    }
    data[key] = (key, offset);
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 4 {
        panic!("Expected 3 command line arguments");
    }

    let num_records = args[1].parse::<usize>().unwrap();
    let min_val = args[2].parse::<u32>().unwrap();
    let max_val = args[3].parse::<u32>().unwrap();
    let data_type = &args[2];

    let rng = thread_rng();
    let mut data = get_data_structure(data_type);

    let runtime = Runtime::new().unwrap();
    let handle = Handle::current();

    for _ in 0..num_records {
        let rng_clone = rng.clone();
        let data_ref = Arc::downgrade(&data);
        let task = async move { generate_and_validate_record(&rng_clone, &mut *data_upgrade.upgrade().unwrap()) };
        runtime.spawn(task).detach();
    }

    runtime.block_on(async {
        handle.handle_future(|_| {
            if let Some(ref mut data) = data_upgrade.upgrade() {
                drop(data);
            }
            Ok(())
        }).await
    });
}
