use rand::Rng;
use std::collections::{HashMap, VecDeque};
use tokio::runtime::{Runtime, Builder as TokioBuilder};
use tokio::sync::mpsc::channel;

mod error {
    #[derive(Debug)]
    pub enum Error {
        DuplicateKey,
    }
}

async fn generate_record(idx: usize) -> (String, f64) {
    let mut rng = rand::thread_rng();
    let key = format!("key_{}", idx);
    loop {
        let value = rng.gen::<f64>();
        if let Some(_) = map.iter().find(|(k, _)| k == &key) {
            continue;
        }
        return (key, value);
    }
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 4 {
        return Err(Box::new(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "Expected 3 arguments: number of records, range for random values, and data structure type (vector or hashmap).",
        )));
    }

    let num_records = args[1].parse::<usize>().unwrap();
    let range = args[2].parse::<(f64, f64)>.unwrap();
    let data_type = args[3].as_str();

    let (tx, rx) = channel::<(String, f64)>(num_records);
    let mut map = match data_type.to_lowercase().as_str() {
        "vector" | "" => VecDeque::new(),
        "hashmap" => HashMap::new(),
        _ => return Err(Box::new(error::Error::InvalidDataStructureType)),
    };

    let mut runtime = TokioBuilder::new_current_thread()
        .enable_all()
        .build()
        .unwrap();

    for idx in 0..num_records {
        runtime.spawn(async move {
            let (record, _) = generate_record(idx).await;
            match &mut map {
                VecDeque::ptr() => map.push_back(record),
                HashMap::ptr() => map.insert(record.0, record.1),
            }
        });
    }

    while let Some((key, value)) = rx.recv().await {
        match &mut map {
            VecDeque::ptr() => map.push_back((key, value)),
            HashMap::ptr() => map.insert(key, value),
        }
    }

    Ok(())
}
