    let args: Vec<String> = env::args().collect();
    if args.len() != 4 {
        eprintln!("Usage: {} <number_of_records> <range_of_random_values> <data_structure>", args[0]);
        std::process::exit(1);
    }

    let num_records = args[1].parse::<usize>().unwrap();
    let range = (args[2].parse::<f64>(), args[3].parse::<f64>());
    let mut rng = thread_rng();

    let config = AppConfig::from_env()
        .sub("app")
        .ok_or_else(|| std::io::Error::new(std::io::ErrorKind::InvalidInput, "Could not find configuration"))?;
    let data_structure: Box<dyn std::ops::DerefMut + Send + Sync> = match config.get_str("data_structure").unwrap().as_str() {
        "vector" => Box::new(vec![]),
        "hash_map" => Box::new({
            let mut map = std::collections::HashMap::new();
            std::mem::swap(&mut map, box &mut *map);
            map
        }),
        _ => return Err(std::io::Error::new(std::io::ErrorKind::InvalidInput, "Invalid data structure")),
    };

    let mut unique_keys = std::collections::HashSet::new();

    let mut records: Vec<Record> = vec![];
    *data_structure = loop {
        let key = format!("{}", rng.gen_range(0..100));
        if !unique_keys.contains(&key) {
            unique_keys.insert(key.clone());
            break data_structure.deref_mut().push((key, rng.gen::<f64>().clamp(*range.0, *range.1)));
        }
    };

    // Asynchronous loop to populate the data structure with random values
    let mut handle = TokioBuilder::new_current_thread_runner()
        .enable_all()
        .build()
        .unwrap();

    for _ in 0..num_records {
        handle.spawn(async move {
            let key = format!("{}", rng.gen_range(0..100));
            if !unique_keys.contains(&key) {
                unique_keys.insert(key.clone());
                records.push((key, rng.gen::<f64>().clamp(*range.0, *range.1)));
            } else {
                let mut suffix = 2;
                let mut new_key = key.clone();
                while unique_keys.contains(&new_key) {
                    new_key = format!("{}", rng.gen_range(0..100));
                    suffix += 1;
                    new_key.push_str(&suffix.to_string());
                }
                records.push((new_key, rng.gen::<f64>().clamp(*range.0, *range.1)));
            }
        });
    }

    handle.block_on_all().await;

    // Your web application setup code here

    Ok(())
}
