#include <stdio.h>
#include <time.h>
#include <pthread.h>
#include <stdarg.h>
#include <stdbool.h>

// Maximum number of logs allowed per second
#define MAX_LOGS_PER_SEC 1000
// Milliseconds between each log check
#define LOG_INTERVAL_MSEC 1000

typedef enum {
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_INFO,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_ERROR,
} LogLevel;

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static time_t last_log_check = 0;
static int current_logs = 0;

void centralized_log(LogLevel level, const char *format, ...) {
    time_t now = time(NULL);
    if (now - last_log_check >= LOG_INTERVAL_MSEC) {
        last_log_check = now;
        current_logs = 0;
    }

    pthread_mutex_lock(&log_mutex);
    if (current_logs + 1 > MAX_LOGS_PER_SEC) {
        // If the logging frequency exceeds the limit, skip this log and increment the counter.
        current_logs++;
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    char log_message[4096];
    snprintf(log_message, sizeof(log_message), "%s [%s] : ", ctime(&now), level_to_string(level));

    va_list args;
    va_start(args, format);
    vsnprintf(log_message + strlen(log_message), sizeof(log_message) - strlen(log_message), format, args);
    va_end(args);

    printf("%s\n", log_message);
    current_logs++;
    pthread_mutex_unlock(&log_mutex);
}

const char *level_to_string(LogLevel level) {
    switch (level) {
        case LOG_LEVEL_DEBUG:
            return "debug";
        case LOG_LEVEL_INFO:
            return "info";
        case LOG_LEVEL_WARNING:
            return "warning";
        case LOG_LEVEL_ERROR:
            return "error";
    }
}
```

This implementation uses a mutex to ensure thread-safety, a simple throttling strategy based on the number of logs per second, and a logging frequency check every 1000 milliseconds. It leverages `snprintf` and `va_start/va_end` for flexible message formatting.

Keep in mind that this example uses standard output for the centralized log service. To integrate with a real-world logging framework, replace the `printf` function call with an API call to your preferred logging library. Additionally, consider implementing custom tags, remote logging, or enhanced performance metrics as needed.']

