import java.util.concurrent.ConcurrentHashMap;
import java.util.Optional;

public class Pokemon {
    private final String name;
    private final List<String> weaknesses;

    public Pokemon(String name, List<String> weaknesses) {
        this.name = name;
        this.weaknesses = weaknesses;
    }

    // Getters and Setters for name and weaknesses

    public static List<String> getWeaknesses(Pokemon pokemon, TypeRepository typeRepo, NameProvider nameProvider) {
        String type = Optional.ofNullable(typeRepo.findByPokemonName(nameProvider.getPokemonName(pokemon)))
                .orElseThrow(() -> new IllegalStateException("Type not found for Pokemon: " + pokemon.getName()))
                .getType();

        List<String> weaknesses = new ArrayList<>();

        // Caching the types and their weaknesses for improved performance
        ConcurrentHashMap<String, List<String>> typeWeaknessCache = typeRepo.getCache();
        if (typeWeaknessCache.containsKey(type)) {
            weaknesses.addAll(typeWeaknessCache.get(type));
        } else {
            weaknesses.addAll(TypeRepository.getDefaultWeaknesses().getOrDefault(type, new ArrayList<>()));
        }

        return weaknesses;
    }
}

