    time_t start_time, end_time;
};

void worker_func(void *arg);  // Worker function called by pthread
void log_event(const char *, ...);  // External logging function

// Initialize network service with given configuration
void init_network_service() {
    struct config cfg;  // Load and parse configuration data here
    initialize_logging(&cfg.log_config);  // Configure logging framework

    int num_workers = cfg.num_workers;
    pthread_t workers[num_workers];
    struct Worker workers_pool[num_workers];

    for (int i = 0; i < num_workers; ++i) {
        workers_pool[i].id = i;
        workers_pool[i].loop = EV_DEFAULT_LOOP(EV_NOLOCK);
        workers_pool[i].is_busy = false;
    }

    // Initialize event loop and set up rate-limiting mechanism here

    for (int i = 0; i < num_workers; ++i) {
        pthread_create(&workers[i], NULL, worker_func, &workers_pool[i]);
    }

    // Main loop to keep the event loop running and handle incoming requests
}

void worker_func(void *arg) {
    struct Worker *worker = (struct Worker *) arg;

    while (true) {
        // Acquire request here using a rate-limiting mechanism

        worker->is_busy = true;
        worker->status = REQUEST_IN_PROGRESS;
        worker->start_time = time(NULL);

        // Process the request and calculate response time on completion

        worker->end_time = time(NULL);
        worker->response_time = worker->end_time - worker->start_time;
        worker->status = REQUEST_COMPLETED;

        worker->is_busy = false;
    }
}
```

