#define MAX_CAPACITY 10
sem_t resource_pool, mutex;
int num_resources = 5; // initialize the number of resources

// Function to initialize semaphores and resources
void init() {
    sem_init(&resource_pool, 0, num_resources);
    sem_init(&mutex, 0, 1);
}

// Function for requesting a resource from the pool
void acquire_resource(void) {
    sem_wait(&mutex);
    sem_wait(&resource_pool);
    sem_post(&mutex);
}

// Function for releasing a resource back to the pool
void release_resource(void) {
