use std::env;
use std::fs::{self, File};
use std::io::{BufReader, Write};
use std::path::Path;
use llvmlite::ir as llvm;
use regex::Regex;
use structopt::StructOpt;

#[derive(StructOpt)]
struct Options {
    /// Path to the input file.
    input: String,
    /// Custom output directory for LLVM IR files (default: current working directory).
    output_dir: Option<String>,
    /// Enable or disable logging (default: enabled).
    verbose: bool,
    /// Optimization level (default: -O3).
    optimization: String,
}

fn generate_llvm_ir(input: &str, verbose: bool) -> (bool, Vec<String>, Option<String>) {
    let mut log_messages = vec![];
    let re_c = Regex::new(r"\.c$").unwrap();
    let re_cpp = Regex::new(r"\.cpp$").unwrap();
    let re_rs = Regex::new(r"\.rs$").unwrap();

    let extension = Path::new(input).extension().and_then(|ext| ext.to_str());
    if !re_c.is_match(extension) && !re_cpp.is_match(extension) && !re_rs.is_match(extension) {
        log_messages.push("Unsupported file extension.".to_string());
        return (false, log_messages, None);
    }

    let mut code = String::new();
    match fs::File::open(input) {
        Ok(file) => BufReader::new(file).read_to_string(&mut code),
        Err(e) => {
            log_messages.push(format!("Error reading input file: {}", e));
            return (false, log_messages, None);
        }
    }.unwrap();

    let mut parser = match extension {
        Some("c") | Some("cpp") => CppLexerAndParser::new(&code),
        Some("rs") => RustLexerAndParser::new(&code),
        _ => unreachable!(),
    };

    let mut ctx = llvm::Context::create();
    let module = llvm::Module::new(None, "generated", &ctx);
    let builder = llvm::Builder::new().into_function(module.get_or_insert_function("main", function_type()), &mut ctx);

    let mut func_result = None;
    if parser.parse(&code) {
        // Perform semantic analysis, code generation, and optimization here based on the grammar and options provided.
        // For simplicity, this example will not implement these steps but instead return an empty function for demonstration purposes.
        let func = builder.get_insert_block(module.get_or_insert_function("main", function_type()).get_entry_block());
        func_result = Some(func.append_ret(builder.int32(0)));
    } else {
        log_messages.push("Parsing errors occurred.".to_string());
    }

    let output_dir = match options.output_dir {
        Some(ref dir) if fs::create_dir_all(dir).is_err() => {
            log_messages.push("Error creating output directory.".to_string());
            None
        },
        Some(ref dir) => Some(dir),
        None => Some(env::current_dir().unwrap()),
    };

    let file_name = format!("{}.ll", Path::new(input).file_name().unwrap().to_str().unwrap());
    let output_path = output_dir.as_ref().and_then(|d| d.join(file_name));
    if let Some(ref path) = output_path {
        if !fs::metadata(path).is_err() && !fs::permissions(path).map(|m| m.mode()).unwrap().perm() & 0o111 != 0 {
            log_messages.push("Output directory is not writable.".to_string());
        } else if let Ok(_) = File::create(path) {
            module.print(output_path, None);
        } else {
            log_messages.push("Error writing LLVM IR file.".to_string());
        }
    }

    (func_result.is_some(), log_messages, output_path)
}

fn main() {
    let options = Options::from_args();
    if options.verbose {
        env_logger::init().unwrap();
    }

    let (success, messages, output_path) = generate_llvm_ir(options.input, options.verbose);
    if success {
        println!("LLVM IR generated successfully!");
        if let Some(ref path) = output_path {
            println!("Path: {}", path.display());
        }
    } else {
        for msg in &messages {
            eprintln!("{}", msg);
        }
    }
}
```

