namespace RandomService {

class RandomGenerator {
public:
    RandomGenerator() {
        ++global_counter;
        generator.reseed(std::random_device()());
        thread_id = std::this_thread::get_id();
        generators[thread_id] = &generator;
    }

    ~RandomGenerator() {
        --global_counter;
        if (global_counter == 0) {
            delete generators[thread_id];
            generators.erase(thread_id);
        }
    }

    int generate(int min, int max) {
        std::uniform_int_distribution<> dist(min, max);
        return dist(generator);
    }

    float generateFloatingPoint(float min, float max) {
        std::uniform_real_distribution<> dist(min, max);
        return dist(generator);
    }

    static int getActiveGeneratorsCount() {
        return global_counter;
    }

private:
    static std::atomic<int> global_counter;
    std::thread::id thread_id;
    std::mt19937 *generator;
    static std::unordered_map<std::thread::id, std::mt19937*> generators;
};

std::atomic<int> RandomService::global_counter = 0;
std::unordered_map<std::thread::id, std::mt19937*> RandomService::generators;

} // namespace RandomService
```

To ensure lock-free access to the global counter and efficient handling of multiple threads, we will use `std::atomic<int>` for the global counter. The `RandomGenerator` class maintains a map of generators keyed by thread ID, which ensures that each thread has its own generator and minimizes contention.

