using System;
using System.Threading.Tasks;

public class DataProcessor
{
    private readonly RealTimeDataSource _dataSource;
    private readonly IMessageQueueService _messageQueue;
    private readonly IProcessingLogic _processor;

    public DataProcessor(RealTimeDataSource dataSource, IMessageQueueService messageQueue, IProcessingLogic processor)
    {
        _dataSource = dataSource;
        _messageQueue = messageQueue;
        _processor = processor;
    }

    public async Task<int> ProcessStreamAsync()
    {
        int processedMessages = 0;
        try
        {
            using (var stream = await _dataSource.OpenStreamAsync())
            {
                await foreach (var item in stream)
                {
                    var processedItem = await _processor.ProcessItemAsync(item);
                    if (_messageQueue.Enqueue(processedItem))
                    {
                        processedMessages++;
                    }
                }
            }
        }
        catch (Exception ex)
        {
            // Handle exceptions appropriately
            Console.WriteLine($"Error processing data: {ex.Message}");
        }
        return processedMessages;
    }
}
