using System.Collections.Concurrent;
using System.Threading.Tasks;

public class ParallelDataProcessor : DataProcessor
{
    private readonly ConcurrentQueue<string> _messageQueueBuffer = new();

    public ParallelDataProcessor(RealTimeDataSource dataSource, IMessageQueueService messageQueue, IProcessingLogic processor)
        : base(dataSource, messageQueue, processor) { }

    public async Task<int> ProcessStreamAsync()
    {
        int processedMessages = 0;

        var tasks = new List<Task>();
        using (var stream = await _dataSource.OpenStreamAsync())
        {
            CancellationTokenSource cts = new();

            // Start fetching data asynchronously with limited concurrency
            for (int i = 0; i < Environment.ProcessorCount * 2; i++)
            {
                tasks.Add(Task.Factory.StartNew(() => FetchDataAsync(stream, cts.Token), TaskCreationOptions.LongRunning));
            }

            await Task.WhenAny(tasks);
        }

        while (tasks.Count > 0)
        {
            tasks.RemoveAll(task => task.IsCompleted);

            foreach (var task in tasks)
            {
                _messageQueueBuffer.Enqueue(await task);
            }

            // Process buffered messages asynchronously with a configurable degree of parallelism
            int parallelism = Environment.ProcessorCount * 2;
            var processingTasks = new List<Task>();
            for (int i = 0; i < parallelism; i++)
            {
                processingTasks.Add(Task.Factory.StartNew(() => ProcessBufferedMessagesAsync(), TaskCreationOptions.LongRunning));
            }

            await Task.WhenAll(processingTasks);
        }

        return _messageQueueBuffer.Count + processedMessages;
    }

    private async Task FetchDataAsync(Stream stream, CancellationToken cancellationToken)
    {
        while (!cancellationToken.IsCancellationRequested)
        {
            await Task.Delay(100, cancellationToken);

            if (stream.Position < stream.Length && !cancellationToken.IsCancellationRequested)
            {
                var item = await Task.Run(() => stream.ReadByteAsync(), cancellationToken);

                if (item >= 0)
                {
                    _messageQueueBuffer.Enqueue(Encoding.UTF8.GetString(new[] { (char)item }));
                }
            }
        }
    }

    private async Task ProcessBufferedMessagesAsync()
    {
        while (_messageQueueBuffer.TryDequeue(out var item))
        {
            try
            {
                var processedItem = await _processor.ProcessItemAsync(item);
                if (_messageQueue.Enqueue(processedItem))
                {
                    // Increase the processedMessages count only after successful message enqueuing to avoid race conditions
                    lock (this)
                    {
                        Interlocked.Increment(ref processedMessages);
                    }
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Error processing buffered message: {ex.Message}");
            }
        }
    }
}
