    sqlite3_prepare_v2(db, sql, -1, &statement, 0);
    sqlite3_bind_int(statement, 1, t.id);
    sqlite3_bind_double(statement, 2, t.timestamp);
    sqlite3_bind_double(statement, 3, t.weightedSum);
    sqlite3_step(statement);
    sqlite3_finalize(statement);
}

