const focusedBooks = process.env.FOCUSED_BOOKS ? _.intersection(_.words(process.env.FOCUSED_BOOKS.split(',')), oldTestamentBooks) : oldTestamentBooks;

// Regular expressions for each book, case-insensitive and word boundaries
const regExps = focusedBooks.reduce((acc, book) => {
  acc[book] = new RegExp('\\b' + book.toLowerCase() + '\\b', 'g');
  return acc;
}, {});

// Caching mechanism for API responses
const cache = new Map();

async function extractBooksMentions(text) {
  let mentions = {};

  // Search for books in the text using the defined regular expressions
  focusedBooks.forEach(book => {
    const matches = text.match(regExps[book]);
    if (matches) {
      mentions[book] = matches.length;
    }
  });

  // If cache is empty or doesn't have the text, fetch data from the API and update the cache
  if (!cache.has(text)) {
    try {
      const apiResponse = await getBibleData(text);
      cache.set(text, apiResponse);
      processBookMentions(apiResponse, mentions);
    } catch (error) {
      handleApiError(error);
    }
  } else {
    processBookMentions(cache.get(text), mentions);
  }

  return mentions;
}

function processBookMentions(apiData, mentions) {
  apiData.books.forEach(book => {
    if (focusedBooks.includes(book)) {
      mentions[book] = (mentions[book] || 0) + 1;
    }
  });
}

async function getBibleData(text) {
  // Implement exponential backoff strategy and retries if needed
  let attempts = 0;
  const retryDelay = 500;
  while (attempts < 3) {
    try {
      const response = await axios.get(`${apiUrl}/books/${text}`);
      return response.data;
    } catch (error) {
      attempts++;
      if (attempts < 3) {
        console.log(`Attempt ${attempts} failed, retrying in ${retryDelay}ms...`);
        await new Promise(resolve => setTimeout(resolve, retryDelay));
      } else {
        throw error;
      }
    }
  }
}

function handleApiError(error) {
