public tuple<bool, string> RenderWidgetsInSidebar(Widget[] widgets, XmlDocument config)
{
    try
    {
        var sidebar = Document.CreateElement("sidebar");
        var maxWidgets = 10;

        if (!config.SelectSingleNode("/config/maxWidgets")?.InnerText.Equals(maxWidgets.ToString()) ?? false)
            throw new Exception("Invalid maximum widget count in configuration.");

        LoadWidgetPreferences(config, sidebar); // Parse layout preferences or styling rules

        var sortedWidgets = widgets.OrderByDescending(w => w.CreatedAt).ToList();
        for (int i = 0; i < maxWidgets && i < sortedWidgets.Count; i++)
        {
            if (sortedWidgets[i] == null || string.IsNullOrEmpty(sortedWidgets[i].Title))
                throw new Exception("Malformed widget data.");

            var card = Document.CreateElement("card");
            sidebar.AppendChild(card);

            var titleElement = Document.CreateElement("title");
            titleElement.InnerText = sortedWidgets[i].Title;
            card.AppendChild(titleElement);

            var descriptionElement = Document.CreateElement("description");
            descriptionElement.InnerText = sortedWidgets[i].Description ?? "";
            card.AppendChild(descriptionElement);

            var urlElement = Document.CreateElement("url");
            urlElement.InnerText = sortedWidgets[i].Url;
            card.AppendChild(urlElement);
        }

        return (true, string.Empty);
    }
    catch (XmlException ex)
    {
        return (false, $"Error parsing XML document: {ex.Message}");
    }
    catch (Exception ex)
    {
        return (false, $"An error occurred during widget rendering: {ex.Message}");
    }
}

