    for (auto v : vertices(g)) {
        if (get(vertex_name, v) > largest)
            largest = get(vertex_name, v);
    }
    cout << (largest == INT32_MIN ? "No integers provided" : to_string(largest));
}

void process_data(Graph& g, std::istream& is, size_t max_size) {
    Vertex v, w;
    size_t num_vertices = 0, num_edges = 0;
    is >> skipws;
    bool paused = false;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    auto add_vertex = [&](int name) {
        Vertex new_v = add_vertex(g);
        set_vertex_name(new_v, name);
        num_vertices++;
    };

    auto add_edge = [&](Vertex v, Vertex w) {
        Edge e = add_edge(v, w, g).first;
        num_edges++;
    };

    try {
        while (!is.eof() && (num_vertices < max_size || !paused)) {
            pthread_mutex_lock(&lock);
            if (is.eof())
                paused = false;
            else {
                int n;
                is >> n >> ws;
                if (!is)
                    throw MemoryAllocationError{"Memory allocation failure"};
                add_vertex(n);
                add_edge(v, w);
                paused = true;
            }
            pthread_mutex_unlock(&lock);
        }
    } catch (const exception& e) {
        cerr << "Error: " << e.what() << endl;
        if (!paused)
            return; // Graceful degradation strategy: ignore errors when resuming from pause
    } catch (...) {
        cerr << "Unknown error occurred" << endl;
        if (!paused)
            return; // Graceful degradation strategy: ignore errors when resuming from pause
    }

    print_largest(g);
}

int main() {
