import java.util.ConcurrentMap;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.Map.Entry;
import java.util.PriorityQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class WordFrequencyCounter {
    private final static int THREAD_COUNT = 4; // Adjust based on available CPU cores
    private final static int INITIAL_HASH_TABLE_SIZE = 1024;
    private final static double LOAD_FACTOR = 0.75;

    public static class WordCount implements Comparable<WordCount> {
        String word;
        int count;
        Lock lock;

        public WordCount(String word) {
            this.word = word;
            this.count = 1;
            this.lock = new ReentrantLock();
        }

        @Override
        public int compareTo(WordCount o) {
            return Integer.compare(o.count, count);
        }
    }

    private static class ThreadSafeHashMap<K, V> extends HashMap<K, V> {
        private final Lock lock = new ReentrantLock();

        @Override
        protected synchronized V get(Object key) {
            return super.get(key);
        }

        @Override
        protected synchronized void putValue(K key, V value) {
            super.put(key, value);
        }
    }

    public static void main(String[] args) throws IOException {
        if (args.length != 1) {
            System.err.println("Usage: java WordFrequencyCounter <file_path>");
            System.exit(1);
        }

        File file = new File(args[0]);
        if (!file.exists() || !file.isFile() || file.length() <= 0) {
            System.err.println("Invalid file path.");
            System.exit(1);
        }

        ThreadSafeHashMap<String, WordCount> wordMap = new ThreadSafeHashMap<>();
        long startTime = System.currentTimeMillis();
        int chunkSize = (int) Math.ceil((double) file.length() / THREAD_COUNT);

        ExecutorService executor = Executors.newFixedThreadPool(THREAD_COUNT);
        LinkedList<Chunk> chunks = new LinkedList<>();

        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            String line;
            while ((line = reader.readLine()) != null) {
                chunks.add(new Chunk(line));
            }
        }

        for (Chunk chunk : chunks) {
            executor.submit(() -> processChunk(chunk, wordMap));
        }

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        long elapsedTime = System.currentTimeMillis() - startTime;
        System.out.printf("Elapsed time: %.2fs\n", elapsedTime / 1000.0);

        System.out.println("Word frequencies:");
        for (Entry<String, WordCount> entry : wordMap.entrySet()) {
            System.out.printf("%s: %d\n", entry.getKey(), entry.getValue().count);
        }
    }

    private static void processChunk(Chunk chunk, ThreadSafeHashMap<String, WordCount> wordMap) {
        long startTime = System.currentTimeMillis();
        String[] words = chunk.getWords();

        for (String word : words) {
            WordCount count = wordMap.get(word);
            if (count == null) {
                count = new WordCount(word);
                wordMap.putValue(word, count);
            }
            count.lock.lock();
            try {
                count.count++;
            } finally {
                count.lock.unlock();
            }
        }

        long processingTime = System.currentTimeMillis() - startTime;
        // Log performance metrics here

        adjustHashTableSize(wordMap, words.length);
    }

    private static void adjustHashTableSize(ThreadSafeHashMap<String, WordCount> wordMap, int currentLoad) {
        if (currentLoad > wordMap.size() * LOAD_FACTOR) {
            wordMap.put(new Chunk("resize").getWordAt(0), new WordCount("resizer")); // Dummy word for resizing trigger
        }
    }

    private static class Chunk {
        private final String text;
        private int position;
        private final int length;

        public Chunk(String text) {
            this.text = text;
            this.length = text.length();
        }

        public String[] getWords() {
            if (position >= length) {
                return new String[0];
            }

            int startIndex = position;
            while (startIndex < length && Character.isWhitespace(text.charAt(startIndex))) {
                startIndex++;
            }
            int endIndex = startIndex;
            while (endIndex < length && !Character.isWhitespace(text.charAt(endIndex))) {
                endIndex++;
            }

            if (startIndex >= endIndex) {
                return new String[0];
            }

            position = endIndex + 1;
            return new String[]{text.substring(startIndex, endIndex)};
        }
    }
}
```

This code defines a `WordFrequencyCounter` class that processes large text files by counting the frequency of unique words in a given file. It uses a custom thread-safe hash map implementation (`ThreadSafeHashMap`) and parallel processing with multiple threads to optimize performance. The function also dynamically adjusts the hash table size based on the current load, logs detailed performance metrics, and cleans up temporary files and resources used during processing.']

