#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <map>
#include <string>
#include <thread>
#include <mutex>
#include <sys/stat.h>
#include <unistd.h>

using namespace std;

struct FileInput {
    ifstream file;
    string delimiter;
};

void process_line(vector<FileInput>& files, map<string, int>& results, mutex* m) {
    for (auto& file : files) {
        string line;
        if (!getline(file.file, line)) continue; // Break the loop if we reach EOF

        istringstream iss(line);
        string word;
        while (iss >> word) {
            unique_lock<mutex> lock(*m);
            results[word]++;
            lock.unlock();
        }
    }
}

int main(int argc, char* argv[]) {
    bool count_only = false, summary = false, output_file = false;
    string input_file, output_file_path, delimiter;
    int num_threads = 1;

    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "-h") || !strcmp(argv[i], "--help") || !strcmp(argv[i], "--manpage")) {
            cout << "Usage: [options] input_file\n"
                 << "\nOptions:\n"
                 << "-i, --input-file <file>   Specifies the input file to be processed.\n"
                 << "-c, --count-only          Prints only the total number of lines without reading the entire content.\n"
                 << "-s, --summary              Prints a summary of lines per unique word encountered in the input file.\n"
                 << "-o, --output-file <file>   Specifies an output file where results should be written instead of being printed to the console.\n"
                 << "-t, --threads <num>       Specifies the number of threads to use for parallel processing with the -s option.\n"
                 << "-d, --delimiter <delim>   Specifies a custom delimiter for categorizing words in the -s option.\n";
            return 0;
        } else if (!strcmp(argv[i], "-i") || !strcmp(argv[i], "--input-file")) {
            if (++i >= argc) {
                cerr << "Error: Missing input file for -i or --input-file option.\n";
                return 1;
            }
            input_file = argv[i];
        } else if (!strcmp(argv[i], "-c")) {
            count_only = true;
        } else if (!strcmp(argv[i], "-s")) {
            summary = true;
        } else if (!strcmp(argv[i], "--output-file")) {
            if (++i >= argc) {
                cerr << "Error: Missing output file for -o or --output-file option.\n";
                return 1;
            }
            output_file_path = argv[i];
        } else if (!strcmp(argv[i], "-t")) {
            if (++i >= argc) {
                cerr << "Error: Missing number of threads for -t or --threads option.\n";
                return 1;
            }
            num_threads = stoi(argv[i]);
        } else if (!strcmp(argv[i], "-d")) {
            if (++i >= argc) {
                cerr << "Error: Missing delimiter for -d or --delimiter option.\n";
                return 1;
            }
            delimiter = argv[i];
        } else {
            cerr << "Error: Unknown option: " << argv[i] << "\n";
            return 1;
        }
    }

    if (!input_file.empty()) {
        struct stat file_stat;
        if (stat(input_file.c_str(), &file_stat) < 0 || !S_ISREG(file_stat.st_mode)) {
            cerr << "Error: Cannot access input file: " << input_file << "\n";
            return 1;
        }

        ifstream input(input_file);
        if (!input) {
            cerr << "Error: Cannot open input file: " << input_file << "\n";
            return 1;
        }

        vector<FileInput> files;
        FileInput file_obj = {input, delimiter};
        files.push_back(file_obj);

        ofstream output;
        if (!output_file.empty()) {
            output.open(output_file_path);
            if (!output) {
                cerr << "Error: Cannot open output file: " << output_file_path << "\n";
                return 1;
            }
        }

        map<string, int> results;
        mutex m;

        vector<thread> threads;
        for (int i = 0; i < num_threads && !files.empty(); ++i) {
            files.erase(remove_if(files.begin(), files.end(), [](const FileInput& file) {
                return !file.file.good();
            }), files.end());

            if (!files.empty()) {
                thread t(&process_line, ref(files), ref(results), &m);
                threads.push_back(move(t));
            }
        }

        for (auto& t : threads) {
            t.join();
        }

        if (!count_only) {
            if (!output.is_open()) cout.flush();
            for (const auto& pair : results) {
                output << pair.first << ": " << pair.second << '\n';
                cout << pair.first << ": " << pair.second << '\n';
            }
        } else {
            cout << "Total number of lines: " << results.size() << "\n";
        }
    }

    return 0;
}
