['```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>
#include <semaphore.h>
#include <log4cxx/logger.h>
#include <log4cxx/basicconfigurator.h>

struct LinkMetric {
    time_t timestamp;
    double throughput;
    double latency;
    int packetLossPercentage;
    bool operationalState;
    sem_t lock;
};

typedef struct LinkListNode {
    struct LinkMetric metric;
    struct LinkListNode* next;
} LinkListNode;

LinkListNode* initLinkList() {
    Log4cxx::BasicConfigurator::configure();
    Log4cxx::LoggerPtr logger = Log4cxx::Logger::getLogger("network");

    LinkListNode *head = malloc(sizeof(LinkListNode));
    head->next = NULL;

    sem_init(&head->metric.lock, 0, 1);
    return head;
}

void addToLinkList(LinkListNode* head, struct LinkMetric newMetric) {
    LinkListNode *newNode = malloc(sizeof(LinkListNode));
    newNode->metric = newMetric;
    newNode->next = NULL;

    sem_wait(&head->metric.lock);
    LinkListNode* tail = head;
    while (tail->next != NULL) {
        tail = tail->next;
    }
    tail->next = newNode;
    sem_post(&head->metric.lock);
}

struct LinkMetric getNextLinkMetric(LinkListNode *head) {
    LinkListNode* current = head->next;
    struct LinkMetric returnMetric = current->metric;
    sem_wait(&current->metric.lock);
    if (current->next != NULL) {
        head->next = current->next;
    } else {
        head->next = NULL;
    }
    sem_post(&current->metric.lock);
    return returnMetric;
}

void freeLinkList(LinkListNode *head) {
    LinkListNode* current = head->next;
    while (current != NULL) {
        LinkListNode* temp = current;
        current = current->next;
        free(temp);
    }
    free(head);
}
```

