typedef struct MemoryPool {
    size_t capacity;
    size_t used;
    LinkMetric *free_list;
    pthread_mutex_t mutex;
} MemoryPool;

MemoryPool link_metric_pool = {.capacity = 1024, .used = 0, .free_list = NULL, .mutex = PTHREAD_MUTEX_INITIALIZER};

void init_link(LinkMetric **head, LinkMetric *new_metric) {
    pthread_mutex_lock(&link_metric_pool.mutex);
    if (link_metric_pool.free_list == NULL && link_metric_pool.used >= link_metric_pool.capacity) {
        expand_memory_pool();
    }
    LinkMetric *temp = link_metric_pool.free_list;
    link_metric_pool.free_list = temp->next;
    link_metric_pool.used--;
    new_metric->next = *head;
    *head = new_metric;
    pthread_mutex_unlock(&link_metric_pool.mutex);
}

void expand_memory_pool() {
    LinkMetric *new_elements = mmap(NULL, link_metric_pool.capacity * sizeof(LinkMetric), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_elements == MAP_FAILED) {
        log_error("Failed to expand memory pool");
        return;
    }
    LinkMetric *current = new_elements;
    for (size_t i = 0; i < link_metric_pool.capacity; ++i) {
        current->next = new_elements + i + 1;
        current->timestamp = 0;
        current->throughput = 0;
        current->latency = 0.0;
        current->packet_loss_percentage = 0;
        current->status = true;
        current->diagnostic_score = 0.0;
        current++;
    }
    link_metric_pool.free_list = new_elements;
    link_metric_pool.capacity *= 2;
}

