#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>
#include <atomic>
#include <queue>
#include <unordered_map>
#include <log4cxx/logger.h>
#include <memory_resource>

std::atomic<size_t> g_cacheSizeLimit;
std::atomic<bool> g_isRunning;
std::priority_queue<std::pair<time_t, CacheItem*>, std::vector<std::pair<time_t, CacheItem*>>, std::greater<>> lruQueue;
std::unordered_map<uint64_t, CacheItem*, std::hash<uint64_t>, std::equal_to<uint64_t>> cache;
std::mutex lruMutex;
std::condition_variable lruCondVar;
std::unique_ptr<log4cxx::Logger> logger;

struct CacheItem {
    time_t lastAccessed;
    size_t hitCount;
    size_t objectSize;
    bool isActive;

    CacheItem(size_t size, bool active) :
        lastAccessed(time(NULL)), hitCount(0), objectSize(size), isActive(active) {}
};

void lruEvictionThread() {
    while (g_isRunning) {
        std::unique_lock<std::mutex> lock(lruMutex);
        lruCondVar.wait(lock, [] { return !lruQueue.empty(); });
        auto item = lruQueue.top()->second;
        lruQueue.pop();
        lock.unlock();
        delete item;
    }
}

CacheItem* getOrInsert(uint64_t key, size_t size, bool active) {
    auto it = cache.find(key);
    CacheItem *item;

    std::unique_lock<std::mutex> lock(lruMutex);
    if (it != cache.end()) {
        item = it->second;
        item->lastAccessed = time(NULL);
        ++item->hitCount;
        lruQueue.push({item->lastAccessed, item});
    } else if (g_cacheSizeLimit <= cache.size()) {
        lock.unlock();
        auto oldestItemIt = lruQueue.top();
        CacheItem *oldestItem = oldestItemIt->second;
        delete oldestItem;
        lock.lock();
        it = cache.find(oldestItem->key);
        if (it != cache.end()) {
            cache.erase(it);
            g_cacheSizeLimit--;
        }
    } else {
        item = new CacheItem(size, active);
        cache[key] = item;
        g_cacheSizeLimit++;
    }

    return item;
}

void logCacheEvent(const char *event) {
    if (logger->getLevelCategorized() & log4cxx::Logger::DEBUG_i) {
        auto timeNow = std::chrono::system_clock::now().time_since_epoch();
        std::unique_ptr<char[], decltype(std::free)> msg(new char[1024], std::free);
        std::snprintf(msg.get(), 1024, "%s [%lu] - %s\n", eventdescr, timeNow.count(), event);
        logger->trace(msg.get());
    }
}

// Function for concurrent cache access with LRU eviction and logging
void* threadSafeCacheAccess(void *arg) {
    auto key = static_cast<uint64_t>(arg);
    CacheItem* item;

    while (g_isRunning) {
        item = getOrInsert(key, /*size*/, /*active*/);
        // Perform your operation on the cached object
        logCacheEvent("Access");
    }

    return nullptr;
}
