    double latency;
    int packet_loss_percentage;
    bool status;
    pthread_mutex_t lock;
} LinkMetric;

typedef struct Node {
    LinkMetric metric;
    struct Node* next;
    sem_t access_sem;
} LinkListNode;

Log4CXX_DECLARE_LOGGER(LinkListLogger);

void init_link_list(LinkListNode** head, const char* interface) {
    *head = (LinkListNode*)malloc(sizeof(LinkListNode));
    if (!(*head)) {
        Log4CXX_FATAL(LinkListLogger, "Failed to allocate memory for link list");
        return;
    }

    (*head)->next = NULL;
    pthread_mutex_init(&((*head)->metric.lock), NULL);
    sem_init(&((*head)->access_sem), 0, 1);

    // Configure logging and external network monitoring tools here
}

void add_link_metric(LinkListNode** head, const LinkMetric& metric) {
    LinkListNode* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }

    LinkListNode* new_node = (LinkListNode*)malloc(sizeof(LinkListNode));
    if (!new_node) {
        Log4CXX_ERROR(LinkListLogger, "Failed to allocate memory for new link metric");
        return;
    }

    pthread_mutex_init(&(new_node->metric.lock), NULL);
    sem_init(&(new_node->access_sem), 0, 1);
    new_node->metric = metric;
    new_node->next = NULL;

    current->next = new_node;
}

LinkMetric get_latest_link_metric(const LinkListNode* head) {
    LinkListNode* current = head->next;
    LinkMetric latest_metric = current->metric;

    while (current != NULL) {
        if (time(NULL) > current->metric.timestamp) {
            latest_metric = current->metric;
        }
        current = current->next;
    }

    return latest_metric;
}

void free_link_list(LinkListNode** head) {
    LinkListNode* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }

    pthread_mutex_destroy(&((*head)->metric.lock));
    sem_destroy(&((*head)->access_sem));
}
