void link_metric_insert(struct NetworkInterface *iface, LinkMetric *link) {
    sem_wait(&iface->lock);

    if (iface->head == NULL) {
        iface->head = link;
        iface->tail = link;
    } else {
        link->prev = iface->tail;
        iface->tail->next = link;
        iface->tail = link;
    }
    sem_post(&iface->lock);
}

void link_metric_delete(struct NetworkInterface *iface, LinkMetric *link) {
    sem_wait(&iface->lock);

    if (iface->head == link) {
        iface->head = link->next;
    } else if (iface->tail == link) {
        iface->tail = link->prev;
    } else {
        LinkMetric *curr = iface->head;
        while (curr->next != link && curr != NULL) {
            curr = curr->next;
        }
        if (curr->next == NULL) {
            // handle the case when the link to be deleted is not found
        } else {
            curr->next = link->next;
            link->prev->next = curr;
        }
    }
    free(link);
    sem_post(&iface->lock);
}

