#include <pthread.h>
#include <stdbool.h>
#include <stdlib.h>
#include <time.h>
#include <sys/types.h>
#include <sqlite3.h>

typedef struct _Session {
    char session_id[64];
    char auth_token[128];
    time_t last_activity;
    int timeout;
    enum SessionStatus { INACTIVE, ACTIVE } status;
    struct Session *next;
} Session;

typedef struct _HashTable {
    size_t capacity;
    Session **buckets;
    pthread_mutex_t mutex;
} HashTable;

void create_hash_table(HashTable *ht, size_t capacity) {
    ht->capacity = capacity;
    ht->buckets = calloc(capacity, sizeof(Session*));
    if (!ht->buckets) exit(1);
    ht->mutex = PTHREAD_MUTEX_INITIALIZER;
}

size_t hash(const char *key, size_t capacity) {
    unsigned long hash = 0;
    for (const char *c = key; *c != '\0'; c++) {
        hash = (*c + hash << 5) & ~((1 << 32) - 1);
    }
    return hash % capacity;
}

Session* create_session(char session_id[64], char auth_token[128], int timeout) {
    Session *s = malloc(sizeof(Session));
    if (!s) exit(1);
    strcpy(s->session_id, session_id);
    strcpy(s->auth_token, auth_token);
    s->last_activity = time(NULL);
    s->timeout = timeout;
    s->status = INACTIVE;
    s->next = NULL;
    return s;
}

void insert_session(HashTable *ht, Session *s) {
    pthread_mutex_lock(&ht->mutex);
    size_t index = hash(s->session_id, ht->capacity);
    s->next = ht->buckets[index];
    ht->buckets[index] = s;
    pthread_mutex_unlock(&ht->mutex);
}

Session* find_session(HashTable *ht, const char *session_id) {
    pthread_mutex_lock(&ht->mutex);
    size_t index = hash(session_id, ht->capacity);
    Session *current = ht->buckets[index];
    while (current != NULL) {
        if (strcmp(current->session_id, session_id) == 0) {
            pthread_mutex_unlock(&ht->mutex);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&ht->mutex);
    return NULL;
}

void remove_session(HashTable *ht, const char *session_id) {
    pthread_mutex_lock(&ht->mutex);
    size_t index = hash(session_id, ht->capacity);
    Session **current = &ht->buckets[index];
    Session *prev = NULL;
    while (*current != NULL) {
        if (strcmp((*current)->session_id, session_id) == 0) {
            if (prev == NULL) {
                *current = (*current)->next;
            } else {
                prev->next = (*current)->next;
            }
            free(*current);
            pthread_mutex_unlock(&ht->mutex);
            return;
        }
        prev = current;
        current = &((*current)->next);
    }
    pthread_mutex_unlock(&ht->mutex);
}

void update_clinic_session_status(HashTable *ht, const char *clinic_id, Session *s) {
    pthread_mutex_lock(&ht->mutex);
    s->status = ACTIVE;
    // Persist session data and update database
    // ...
    pthread_mutex_unlock(&ht->mutex);
}

bool update_clinic_session(HashTable *ht, const char *session_id, const char *auth_token, int timeout, const char *clinic_id) {
    Session *s = find_session(ht, session_id);
    if (!s) return false;

    strcpy(s->auth_token, auth_token);
    s->timeout = timeout;
    time_t now = time(NULL);
    s->last_activity = now;

    update_clinic_session_status(ht, clinic_id, s);

    return true;
}
