    while ((bytes_read = fread(buffer, 1, chunk_size, file)) > 0) {
        for (size_t i = 0; i < bytes_read; ++i) {
            if (i + 1 == bytes_read || buffer[i] == delimiter) {
                process_line(&buffer[i], delimiter, bytes_read - i);
                memmove(&buffer[0], &buffer[i + 1], bytes_read - i);
            }
        }
    }

