        return 0;
    }

    if (optind < argc)
        input_file = argv[optind];

    int input_fd = -1;

    if (input_file && strcmp(input_file, "-") != 0) {
        input_fd = open(input_file, O_RDONLY);

        if (input_fd == -1) {
            perror("Error opening file");
            return 1;
        }

        input = fdopen(input_fd, "r");
    }

    log_message(LOG_INFO, "Starting processing.");
    read_and_process(input, &delimiter, chunk_size);
    log_message(LOG_INFO, "Finished processing.");

    if (output_file) {
        int output_fd = open(output_file, O_WRONLY | O_CREAT | O_TRUNC, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);

