#include <pthread.h>

typedef struct {
    char ip[INET_ADDRSTRLEN];
    char subnet_mask[INET_ADDRSTRLEN];
    char gateway[INET_ADDRSTRLEN];
    int link_metrics; // List of link metrics not included in this example
    pthread_mutex_t mutex;
} InterfaceConfig;

typedef struct Node {
    InterfaceConfig config;
    struct Node *next;
} Node;

Node* interface_config_list = NULL;
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
int log_level = 0; // Log level: 0 for errors, 1 for warnings, 2 for info, 3 for debug

void interface_config_init(int log_level_) {
    log_level = log_level_;
}

void interface_config_set_log_level(int log_level_) {
    log_level = log_level_;
}

void* grow_list() {
    Node **current = &interface_config_list;
    while (*current) {
        current = &(*current)->next;
    }

    // Double the size of the list and create a new node at the end
    Node *new_node = malloc(sizeof(Node));
    if (!new_node) {
        fprintf(stderr, "Failed to allocate memory for new interface configuration.\n");
        return NULL;
    }

    new_node->next = NULL;
    pthread_mutex_init(&new_node->config.mutex, NULL);
    *current = new_node;

    return new_node;
}

void interface_config_add(const char* ip, const char* subnet_mask, const char* gateway, int link_metrics) {
    pthread_mutex_lock(&list_mutex);

    Node *new_node = grow_list();
    if (!new_node) {
        pthread_mutex_unlock(&list_mutex);
        return;
    }

    strncpy(new_node->config.ip, ip, sizeof(new_node->config.ip));
    strncpy(new_node->config.subnet_mask, subnet_mask, sizeof(new_node->config.subnet_mask));
    strncpy(new_node->config.gateway, gateway, sizeof(new_node->config.gateway));
    new_node->config.link_metrics = link_metrics;

    pthread_mutex_unlock(&list_mutex);

    if (log_level > 1) {
        printf("Added interface configuration: IP=%s, Subnet Mask=%s, Gateway=%s, Link Metrics=%d\n",
               new_node->config.ip, new_node->config.subnet_mask, new_node->config.gateway, new_node->config.link_metrics);
    }
}

void interface_config_remove(const char* ip) {
    pthread_mutex_lock(&list_mutex);

    Node *current = interface_config_list;
    Node *prev = NULL;

    while (current != NULL) {
        if (strcmp(current->config.ip, ip) == 0) {
            if (prev == NULL) {
                interface_config_list = current->next;
            } else {
                prev->next = current->next;
            }

            free(current);
            break;
        }

        prev = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}

void interface_config_log_interface(const char* ip) {
    pthread_mutex_lock(&list_mutex);

    Node *current = interface_config_list;
    while (current != NULL) {
        if (strcmp(current->config.ip, ip) == 0) {
            printf("Interface Configuration:\n");
            printf("IP: %s\n", current->config.ip);
            printf("Subnet Mask: %s\n", current->config.subnet_mask);
            printf("Gateway: %s\n", current->config.gateway);
            printf("Link Metrics: %d\n", current->config.link_metrics);
            break;
        }

        current = current->next;
    }

    pthread_mutex_unlock(&list_mutex);
}
