#define BUFFER_SIZE 0x100000 /* 1 MB */
#define CHUNK_SIZE 0x40000   /* 64 KB */
#define BATCH_SIZE 0x100     /* 256 chunks (4 MB) */

struct config {
    char *input, *output, *logfile;
    char delimiter;
    bool help, log_enabled;
};

struct file_handle {
    int fd;
    void *buffer;
    size_t pos, len;
