    pthread_mutex_t mutex;
} Session;

typedef struct ListNode {
    Session session;
    struct ListNode *prev, *next;
} ListNode;

struct SessionManager {
    unsigned int capacity; // Current size of the list
    unsigned int size; // Number of active sessions
    ListNode **sessions; // Pointer to dynamically allocated array of session pointers
    time_t timeout; // Session timeout in seconds
    pthread_mutex_t manager_mutex;
};

void init_session(Session *session, char *id, char *token) {
    snprintf(session->session_id, sizeof(session->session_id), "%s", id);
    snprintf(session->auth_token, sizeof(session->auth_token), "%s", token);
    session->expiration = time(NULL) + timeout;
    session->requests = NULL;
    pthread_mutex_init(&session->mutex, NULL);
}

SessionManager *create_session_manager(unsigned int capacity, time_t timeout) {
    if (capacity < 1 || timeout <= 0) return NULL;

    SessionManager *manager = malloc(sizeof(SessionManager));
    manager->capacity = capacity;
    manager->size = 0;
    manager->timeout = timeout;
    manager->sessions = calloc(capacity, sizeof(ListNode*));
    if (!manager->sessions) {
        free(manager);
        return NULL;
    }

    pthread_mutex_init(&manager->manager_mutex, NULL);
    return manager;
}

void add_session(SessionManager *manager, Session session) {
    if (manager->size == manager->capacity) resize_sessions(manager);

    ListNode *new_node = malloc(sizeof(ListNode));
    init_session(&new_node->session, session.session_id, session.auth_token);
    new_node->next = manager->sessions[manager->size];
    if (manager->sessions[manager->size])
        manager->sessions[manager->size]->prev = new_node;

    manager->sessions[manager->size] = new_node;
    pthread_mutex_init(&new_node->session.mutex, NULL);
    manager->size++;
}

Session *get_session(SessionManager *manager, const char *id) {
    for (unsigned int i = 0; i < manager->size; ++i) {
        pthread_mutex_lock(&manager->sessions[i]->session.mutex);

        if (strcmp(manager->sessions[i]->session.session_id, id) == 0 &&
            time(NULL) < manager->sessions[i]->session.expiration) {

            pthread_mutex_unlock(&manager->sessions[i]->session.mutex);
            return &manager->sessions[i]->session;
        }

        pthread_mutex_unlock(&manager->sessions[i]->session.mutex);
    }

    return NULL;
}

void remove_expired_sessions(SessionManager *manager) {
    for (unsigned int i = 0; i < manager->size; ++i) {
        pthread_mutex_lock(&manager->sessions[i]->session.mutex);

        if (time(NULL) > manager->sessions[i]->session.expiration) {
            ListNode *to_remove = manager->sessions[i];

            if (i != manager->size - 1) {
                to_remove->prev->next = to_remove->next;
                to_remove->next->prev = to_remove->prev;
            } else {
                manager->size--;
            }

            free(to_remove);
            manager->size--;
        }

        pthread_mutex_unlock(&manager->sessions[i]->session.mutex);
    }
}

void log_activity(const char *action, Session *session) {
