    void (*callback)(void*);
} ProcessData;

int check_data(ProcessData *data) {
    if (!data || !data->password || data->password[0] == '\0' || !data->connection || !data->callback)
        return 1;
    CURLcode res = curl_easy_getinfo(data->connection, CURLINFO_TITLE);
    if (res != CURLE_OK || !data->callback)
        return 1;
    return 0;
}

int process_file(char *path, char delimiter, ProcessData *data) {
    int chunk_size = 1024 * 1024; // 1 MB chunks
    char *buffer = mmap(NULL, chunk_size, PROT_READ, MAP_PRIVATE | MAP_NORESERVE, open(path, O_RDONLY), 0);
    if (buffer == MAP_FAILED)
        return -1;

    size_t pos = 0;
    size_t read = 0;
    char *token;

    while ((read = getdelim(&token, chunk_size, delimiter, buffer + pos, chunk_size - pos))) {
        if (check_data(data) != 0) {
            munmap(buffer, chunk_size);
            return -1;
        }

        // Process each token with the provided callback function.
        data->callback(token);

        pos += read + strlen(token) + delimiter;
        free(token);
    }

    if (pos < chunk_size) {
        // Handle EOF without calling munmap() on the last chunk.
        data->callback(buffer + pos);
    } else {
        munmap(buffer, chunk_size);
    }

    return 0;
}

