void create_linked_list(LinkedListNode** head, int interface_id) {
    *head = mmap(NULL, sizeof(LinkedListNode), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    if (*head == MAP_FAILED) {
        log_error("Failed to allocate memory for linked list");
        return;
    }
    (*head)->data = malloc(sizeof(LinkMetric));
    if ((*head)->data == NULL) {
        log_error("Failed to allocate memory for LinkMetric");
        munmap(*head, sizeof(LinkedListNode));
        *head = NULL;
        return;
    }
    sem_init(&((*head)->data->lock), 0, 1);
    (*head)->next = NULL;
}

void add_to_linked_list(LinkedListNode** head, LinkMetric* new_metric) {
    LinkedListNode* current = *head;
    if (current->next == NULL) {
        current->next = malloc(sizeof(LinkedListNode));
        if (current->next == NULL) {
            log_error("Failed to allocate memory for LinkedListNode");
            return;
        }
        current->next->data = new_metric;
        current->next->next = NULL;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = malloc(sizeof(LinkedListNode));
        if (current->next == NULL) {
            log_error("Failed to allocate memory for LinkedListNode");
            return;
        }
        current->next->data = new_metric;
        current->next->next = NULL;
    }
}

void update_linked_list(LinkedListNode* head, LinkMetric* updated_metric) {
    sem_wait(&head->data->lock);
    head->data = updated_metric;
    sem_post(&head->data->lock);
}

