void add_metric(Interface* intf, LinkMetric metric) {
    pthread_mutex_lock(&intf->metrics_lock);

    LinkMetric *head = intf->metrics;
    if (!head) {
        head = malloc(sizeof(LinkMetric));
        if (!head) {
            fprintf(stderr, "Failed to allocate memory for link metric\n");
            pthread_mutex_unlock(&intf->metrics_lock);
            return;
        }
