    LinkMetric *current = head;
    while (current && current->timestamp > metric.timestamp) {
        current = current->next;
    }

    if (!current) {
        head->prev = &metric;
        metric.next = head;
        head = &metric;
    } else {
        LinkMetric *new_metric = malloc(sizeof(LinkMetric));
        if (!new_metric) {
            fprintf(stderr, "Failed to allocate memory for link metric\n");
            pthread_mutex_unlock(&intf->metrics_lock);
            return;
        }
        new_metric->prev = current;
        new_metric->next = current->next;
        if (new_metric->next) {
            new_metric->next->prev = &metric;
        } else {
            current->next = &metric;
        }
        current->next = &metric;
        metric.prev = current;
        metric.next = NULL;
    }

