LinkMetrics *remove_by_name(const char *interface_name) {
    LinkMetrics *current = head, *prev;

    while (current != NULL) {
        pthread_mutex_lock(&list_mutex);

        if (strcmp(current->interface_name, interface_name) == 0) {
            if (current == head) {
                head = current->next;
            } else {
                prev->next = current->next;
            }

            LinkMetrics *temp = current;
            current = current->next;
            free(temp);
            pthread_mutex_unlock(&list_mutex);

            return temp;
        }

        prev = current;
        current = current->next;
        pthread_mutex_unlock(&list_mutex);
