5. Implement the cache eviction policies for LRU and LFU strategies:

```python
class LeastRecentlyUsedLruCache(object):
    def __init__(self, max_size):
        self.cache = {}
        self.lru = collections.OrderedDict()
        self.max_size = max_size

    def get(self, key, default=None):
        if key not in self.lru:
            return default
        value = self.cache[key]
        self.lru.move_to_end(key)  # move accessed keys to the end of the OrderedDict
        return value

    def set(self, key, value):
        if self.max_size <= len(self.cache):
            least_recently_used = next((k for k in self.lru), None)
            del self.cache[least_recently_used]
            del self.lru[least_recently_used]
        self.lru[key] = value  # update the access time of the key
        self.cache[key] = value

class LeastFrequentlyUsedLfuCache(object):
    def __init__(self, max_size, min_frequency=1):
        self.cache = {}
        self.freq = defaultdict(int)
        self.lru = collections.OrderedDict()
        self.max_size = max_size
        self.min_frequency = min_frequency

    def get(self, key, default=None):
        if key not in self.lru:
            return default
        frequency = self.freq[key]
        self.lru.move_to_end(key)  # move accessed keys to the end of the OrderedDict
        self.freq[key] += 1
        return self.cache[key]

    def set(self, key, value):
        if self.max_size <= len(self.cache):
            least_frequently_used = min((k for k in self.lru), key=lambda k: self.freq[k])
            del self.cache[least_frequently_used]
            del self.lru[least_frequently_used]
        self.lru[key] = value  # update the frequency of the key
        self.freq[key] += 1
        self.cache[key] = value
```

6. Implement the `get_eviction_policy()` function:

```python
def get_eviction_policy(strategy):
    if strategy == "lru":
        return LeastRecentlyUsedLruCache(cache_size)
    elif strategy == "lfu":
        return LeastFrequentlyUsedLfuCache(cache_size, min_frequency=1)
```']

