#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    uint32_t rx_frame_tag;
    size_t num_streams;
    size_t max_samples_per_stream;
    RX_STREAM_INFO* stream_info;
} NFAPI_RX_FRAME_PDU_T;

void nfapi_rx_pdu_init(NFAPI_RX_FRAME_PDU_T** p_frame_pdu, size_t num_streams) {
    *p_frame_pdu = malloc(sizeof(NFAPI_RX_FRAME_PDU_T));
    if (!(*p_frame_pdu)) return;
    // Initialize frame structure
    memset(*p_frame_pdu, 0, sizeof(NFAPI_RX_FRAME_PDU_T));
    (*p_frame_pdu)->num_streams = num_streams;

    // Allocate memory for stream information
    (*p_frame_pdu)->stream_info = calloc(num_streams, sizeof(RX_STREAM_INFO));
    if (!(*p_frame_pdu)->stream_info) {
        free(*p_frame_pdu);
        return;
    }

    // Initialize stream information and update max samples per stream
    size_t i;
    for (i = 0; i < num_streams; ++i) {
        (*p_frame_pdu)->stream_info[i].stream_id = i;
        (*p_frame_pdu)->stream_info[i].num_samples = 0;
    }
}

RX_STREAM_INFO* nfapi_rx_pdu_add_stream(NFAPI_RX_FRAME_PDU_T* frame_pdu) {
    if (frame_pdu->num_streams >= FRAME_MAX_STREAMS) return NULL;

    RX_STREAM_INFO* new_stream = realloc((frame_pdu->stream_info + frame_pdu->num_streams), sizeof(RX_STREAM_INFO));
    if (!new_stream) return NULL;
    frame_pdu->stream_info = new_stream;
    ++(frame_pdu->num_streams);

    // Initialize the newly added stream
    RX_STREAM_INFO* new_stream_ptr = frame_pdu->stream_info + frame_pdu->num_streams - 1;
    new_stream_ptr->stream_id = frame_pdu->num_streams - 1;
    new_stream_ptr->num_samples = 0;

    return new_stream_ptr;
}

void nfapi_rx_pdu_add_sample(NFAPI_RX_FRAME_PDU_T* frame_pdu, RX_STREAM_INFO* stream_info, float sample) {
    ++(stream_info->num_samples);
    if (stream_info->num_samples > frame_pdu->max_samples_per_stream) {
        frame_pdu->max_samples_per_stream = stream_info->num_samples;
    }
}

void nfapi_rx_pdu_update_stats(NFAPI_RX_FRAME_PDU_T* frame_pdu) {
    size_t i;
    float total_received_bytes = 0.0f;
    size_t total_samples = 0;

    for (i = 0; i < frame_pdu->num_streams; ++i) {
        RX_STREAM_INFO* stream_info = &frame_pdu->stream_info[i];
        float average_sample_rate = stream_info->num_samples > 0 ? (float)stream_info->num_samples / frame_pdu->duration : 0.0f;
        total_received_bytes += stream_info->num_samples * sizeof(float);
        total_samples += stream_info->num_samples;

        // Update average sample rate across all streams
        if (total_samples > 0) {
            frame_pdu->average_sample_rate = total_samples / frame_pdu->duration;
        }
    }

    frame_pdu->total_received_bytes = total_received_bytes;
}
