```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

typedef struct {
    char iface_id[32];
    uint32_t num_streams;
    RX_STREAM_INFO** streams;
} NIC_CONFIG;

typedef struct {
    uint32_t stream_id;
    uint32_t buffer_size;
    uint32_t sample_rate;
    uint32_t receive_window_size;
    size_t num_samples;
    uint8_t* samples;
} RX_STREAM_INFO;

void init_nic(NIC_CONFIG *nic, const char iface_id[32]) {
    nic->iface_id[0] = '\0';
    strcpy(nic->iface_id, iface_id);
    nic->num_streams = 0;
    nic->streams = NULL;
}

void add_stream(NIC_CONFIG *nic, uint32_t stream_id, uint32_t buffer_size, uint32_t sample_rate) {
    if (nic->num_streams == 0) {
        nic->streams = malloc(sizeof(RX_STREAM_INFO*));
        nic->streams[nic->num_streams] = NULL;
    } else {
        nic->streams = realloc(nic->streams, (nic->num_streams + 1) * sizeof(RX_STREAM_INFO*));
        for (int i = nic->num_streams - 1; i >= 0; --i) {
            if (!nic->streams[i])
                nic->streams[i] = NULL;
        }
    }

    RX_STREAM_INFO *new_stream = malloc(sizeof(RX_STREAM_INFO));
    new_stream->stream_id = stream_id;
    new_stream->buffer_size = buffer_size;
    new_stream->sample_rate = sample_rate;
    new_stream->receive_window_size = buffer_size / sample_rate;
    new_stream->num_samples = 0;
    new_stream->samples = malloc(new_stream->receive_window_size * sizeof(uint8_t));
    nic->streams[nic->num_streams++] = new_stream;
}

void update_stats(NIC_CONFIG *nic) {
    uint64_t total_packets = 0, total_bytes = 0;
    float throughput = 0.0;

    for (int i = 0; i < nic->num_streams; ++i) {
        RX_STREAM_INFO* stream = nic->streams[i];
        if (!stream) continue;

        total_packets += stream->num_samples;
        total_bytes += stream->num_samples * sizeof(uint8_t);
    }

    if (total_packets > 0) {
        throughput = (float)total_bytes / total_packets / (nic->num_streams * 1e6); // Average throughput in Mbps
    }

    printf("Total packets received: %" PRIu64 "\n", total_packets);
    printf("Average throughput: %.2f Mbps\n", throughput);
}
```

