    if (ctx->input) fclose(ctx->input);
    if (ctx->output) fclose(ctx->output);
    if (ctx->log) fclose(ctx->log);
    if (ctx->out_gz) gzclose(ctx->out_gz);
    free(ctx->rules);
    free(ctx);
}

