        if (nread <= 0) break;
        ctx->bytes_read += nread;

        size_t np = process_data(buf, nread, 1, ctx);
        ctx->bytes_processed += np;

        write_file(buf, np, 1, ctx);
        ctx->bytes_written += np;
    }

