#[derive(Deserialize)]
struct Config {
    data_structure: String,
    num_records: usize,
    range: (f64, f64),
}

fn aes256cbc_init(password: &str) -> *mut SymmCipher {
    let key = HMAC::new(SHA1, CString::new(password).unwrap()).finalize();
    let mut ctx = ManuallyDrop::new(AioContext::new());
    let iv = vec![0; openssl::symm::IV_len()];
    let cipher = openssl::cipher::CBC. encryption().unwrap();
    ctx.set_padding(openssl::aio::Padding::PKCS7);
    ctx.set_cipher(&cipher);
    ctx.set_key(&key, key.len());
    ctx.set_iv(&iv[..]);

    Box::into_raw(ctx) as *mut SymmCipher
}

fn aes256cbc_cleanup(cipher: ManuallyDrop<AioContext>) {
    unsafe { cipher.into_inner().free() }
}

async fn populate_data(num_records: usize, range: (f64, f64), data_structure: &mut Vec<Value> | &mut std::collections::HashMap<String, f64>) {
    let mut rng = rand::thread_rng();

    // Use rayon for efficient parallellization over the range of records.
    (0..num_records).into_par_iter().for_each(|_| {
        loop {
            let key = rng.gen::<String>();
            if !data_structure.contains_key(&key) {
                data_structure.insert(key, rng.gen::<f64>());
                break;
            }
        }
    });
}

#[tokio::main]
