int dns_resolve(const char *hostname, FILE **addr_ptr) {
    struct hostent *he;
    struct in_addr **addr_list;

    if ((he = gethostbyname(hostname)) == NULL) {
        return -1;
    }

    addr_list = he->h_addr_list;
    if (*addr_list == NULL) {
        return -1;
    }

    *addr_ptr = tmpfile();
    if (*addr_ptr == NULL) {
        return -1;
    }

    fprintf(*addr_ptr, "%s\n", inet_ntoa **addr_list[0]);
    fseek(*addr_ptr, ftell(*addr_ptr), SEEK_SET);

    return 0;
}

ssize_t read_chunk(int fd, void *buf, size_t count) {
    ssize_t n;
    do {
        n = read(fd, buf, count);
        if (n < 0 && errno != EINTR) {
            return -1;
        }
    } while (n < count && errno == EINTR);

    return n;
}

void parse_and_transform(const char *input_file, const char *output_file, const char *rules, size_t max_buffer_size, gzFile *outfp) {
    int in_fd, out_fd, bytes_read, bytes_processed = 0, bytes_written = 0;
    char buffer[1024];
    void *input_buf, *output_buf;
    size_t input_buf_size, output_buf_size;

    // Allocate input and output buffers
    input_buf_size = max_buffer_size * 1024;
    if ((input_buf = malloc(input_buf_size)) == NULL) {
        log_message("Failed to allocate input buffer\n");
        exit(EXIT_FAILURE);
    }

    output_buf_size = max_buffer_size * 1024;
    if ((output_buf = malloc(output_buf_size)) == NULL) {
        log_message("Failed to allocate output buffer\n");
        exit(EXIT_FAILURE);
    }

    // Open input and output files
    if ((in_fd = open(input_file, O_RDONLY)) < 0 || (out_fd = creat(output_file, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH)) < 0) {
        log_message("Failed to open input or output file\n");
        exit(EXIT_FAILURE);
    }

    // DNS resolution for the input file (assuming it is a hostname)
    FILE *addr;
    if (dns_resolve(basename(input_file), &addr) < 0) {
        log_message("Failed to resolve IP address of input file\n");
        exit(EXIT_FAILURE);
    }

    while ((bytes_read = read_chunk(in_fd, buffer, sizeof(buffer))) > 0) {
        size_t chunk_len;
        if (bytes_processed + bytes_read > max_buffer_size * 1024) {
            // Compress and write the processed data to the output file
            gzwrite(outfp, output_buf, bytes_processed);
            bytes_written += bytes_processed;
            bytes_processed = 0;
        }

        // Parse and transform the input data according to given rules
        chunk_len = parse_and_transform_chunk(buffer, sizeof(buffer), output_buf + bytes_processed, max_buffer_size - bytes_processed);
        if (chunk_len < 0) {
            log_message("Failed to parse and transform data\n");
            exit(EXIT_FAILURE);
        }

        bytes_processed += chunk_len;
    }

    // Write any remaining processed data to the output file
    if (bytes_processed > 0) {
        gzwrite(outfp, output_buf, bytes_processed);
        bytes_written += bytes_processed;
    }

    // Close input and output files
    fclose(addr);
    close(in_fd);
    close(out_fd);

    log_message("Bytes read: %zu\n", bytes_read);
    log_message("Bytes processed: %zu\n", bytes_processed);
    log_message("Bytes written: %zu\n", bytes_written);
}

int main(int argc, char **argv) {
    if (argc != 7) {
        log_message("Usage: ./program hostname input_file output_file rules max_buffer_size [compression]\n");
        return EXIT_FAILURE;
    }

    gzFile outfp = gzopen(argv[5], argv[6][0] == '1' ? "wb" : "w");
    if (outfp == NULL) {
        log_message("Failed to open output file for writing\n");
        return EXIT_FAILURE;
    }

    parse_and_transform(argv[2], argv[3], argv[4], atoi(argv[5]), outfp);

    gzclose(outfp);

    return EXIT_SUCCESS;
}
```

