    let mut key = vec![0; KEYSIZE];
    let mut hash = SHA1::new(OsRng);
    hash.update(password);
    hash.finalize().code(&mut key[..]);
    let mut encryptor = Aes128Cbc::newvec(&key, &Vec::from([0x00; BLOCK_SIZE]))?;
    Ok(encryptor.into_raw())
}
