#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG rx_ue;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node* next;
} node;

struct list {
    unsigned int size;
    node *head, *tail;
    pthread_mutex_t lock;
};

void init_list(struct list *list) {
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

node* create_node(const NFAPI_CRC_INDICATION_PDU_T *data) {
    node *new_node = (node *)malloc(sizeof(node));
    if (!new_node) {
        fprintf(stderr, "Out of memory\n");
        return NULL;
    }
    new_node->data = *data;
    new_node->next = NULL;
    return new_node;
}

void add_element(struct list *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->lock);
    node* new_node = create_node(data);
    if (!new_node) {
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (list->size == 0) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void update_element(struct list *list, const RNTI rnti, const NFAPI_CRC_INDICATION_PDU_T *data) {
    pthread_mutex_lock(&list->lock);
    node *current = list->head;
    bool found = false;
    int index = 0;

    while (current != NULL && !found) {
        if (current->data.rnti == rnti) {
            found = true;
            current->data = *data;
        }
        current = current->next;
        index++;
    }

    if (!found) {
        fprintf(stderr, "Element with RNTI %d not found\n", rnti);
    }

    pthread_mutex_unlock(&list->lock);
}

void remove_element(struct list *list, const RNTI rnti) {
    pthread_mutex_lock(&list->lock);
    node *current = list->head;
    node *prev = NULL;
    bool found = false;
    int index = 0;

    while (current != NULL && !found) {
        if (current->data.rnti == rnti) {
            found = true;
            if (index == 0) {
                list->head = current->next;
            } else {
                prev->next = current->next;
            }
            free(current);
            list->size--;
        }
        prev = current;
        current = current->next;
        index++;
    }

    if (!found) {
        fprintf(stderr, "Element with RNTI %d not found\n", rnti);
    }

    pthread_mutex_unlock(&list->lock);
}
