typedef struct {
    enum FRAME_TYPE frame_type;
    int tx_power_level;
    float snr, ber;
} PHY_FRAME_STATS;

typedef struct node {
    PHY_FRAME_STATS stats;
    struct node* next;
} Node;

struct list {
    unsigned long size;
    Node* head;
    Node* tail;
    pthread_mutex_t lock;
};

void init_list(struct list* list) {
    list->size = 0;
    list->head = NULL;
    list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

Node* create_node(PHY_FRAME_STATS stats) {
    Node* new_node = malloc(sizeof(Node));
    if (!new_node) return NULL;
    new_node->stats = stats;
    new_node->next = NULL;
    return new_node;
}

void add_to_list(struct list* list, PHY_FRAME_STATS stats) {
    pthread_mutex_lock(&list->lock);
    Node* new_node = create_node(stats);
    if (!new_node) {
        perror("Error allocating memory for new node");
        pthread_mutex_unlock(&list->lock);
        return;
    }
    if (list->size == 0) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->lock);
}

void update_frame(struct list* list, enum FRAME_TYPE frame_type, PHY_FRAME_STATS new_stats) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL) {
        if (current->stats.frame_type == frame_type) {
            current->stats = new_stats;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void remove_frame(struct list* list, enum FRAME_TYPE frame_type) {
    pthread_mutex_lock(&list->lock);
    Node *prev = NULL, *current = list->head;
    while (current != NULL) {
        if (current->stats.frame_type == frame_type) {
            if (prev == NULL) {
                list->head = current->next;
                if (list->size == 1) list->tail = NULL;
            } else {
                prev->next = current->next;
                if (current == list->tail) list->tail = prev;
            }
            free(current);
            list->size--;
            break;
        }
        prev = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->lock);
}

void clear_old_data(struct list* list, unsigned long max_age) {
    pthread_mutex_lock(&list->lock);
    Node *current = list->head;
    while (current != NULL && list->size > max_age) {
        Node *temp = current;
        current = current->next;
        free(temp);
        list->size--;
    }
    pthread_mutex_unlock(&list->lock);
}

void print_stats(struct list* list) {
    pthread_mutex_lock(&list->lock);
    float avg_snr = 0, max_ber = 0;
    unsigned long count_by_type[FRAME_NUM_TYPES] = {0};
    Node *current = list->head;
    while (current != NULL) {
        switch (current->stats.frame_type) {
            case FRAME_TYPE_1:
                count_by_type[0]++;
                break;
            // Add other frame types here...
            default:
                break;
        }
        avg_snr += current->stats.snr;
        if (current->stats.ber > max_ber) max_ber = current->stats.ber;
        current = current->next;
    }
    printf("Average SNR: %.2f\n", avg_snr / list->size);
    printf("Maximum BER: %.2f\n", max_ber);
    for (int i = 0; i < FRAME_NUM_TYPES; ++i) {
        if (count_by_type[i] > 0)
            printf("Count of type %d frames: %lu\n", i, count_by_type[i]);
    }
    pthread_mutex_unlock(&list->lock);
}
