public class FileHasher {
    private static final int MAX_CHUNK_SIZE = 1024 * 1024; // 1 MB
    private static final int MIN_RETRY_DELAY_MILLIS = 500;
    private static final int MAX_RETRIES = 5;
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static final ConcurrentHashMap<String, FileLock> fileLocks = new ConcurrentHashMap<>();
    private static final AtomicLong processedFilesCounter = new AtomicLong(0);
    private static final AtomicLong failedFilesCounter = new AtomicLong(0);
    private static final AtomicLong totalProcessingTimeNanos = new AtomicLong(0);

    public Map<String, BigInteger> computeMD5Hashes(List<String> filePaths) {
        Map<String, BigInteger> md5Hashes = new HashMap<>();
        ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(1);
        Future<Void> failureLogger = executor.submit(() -> {
            while (true) {
                Thread.sleep(60_000); // Log statistics every minute
                logExecutionStatistics();
            }
        });
        for (String filePath : filePaths) {
            if (filePath == null || filePath.isEmpty()) {
                continue;
            }
            try {
                File file = new File(filePath);
                if (!file.exists() || !file.isFile() || file.length() > MAX_CHUNK_SIZE) {
                    failedFilesCounter.incrementAndGet();
                    continue;
                }
                FileLock lock = takeFileLock(file);
                try {
                    if (lock != null && !lock.tryLock()) {
                        continue; // Another thread is processing this file, move on to the next one
                    }
                    Path path = Paths.get(filePath);
                    MessageDigest md5 = MessageDigest.getInstance("MD5");
                    try (InputStream inputStream = Files.newInputStream(path)) {
                        long startTimeNanos = System.nanoTime();
                        int bytesRead;
                        byte[] buffer = new byte[MAX_CHUNK_SIZE];
                        while ((bytesRead = inputStream.read(buffer)) != -1) {
                            md5.update(buffer, 0, bytesRead);
                        }
                        BigInteger hash = new BigInteger(1, md5.digest());
                        md5Hashes.put(filePath, hash);
                        processedFilesCounter.incrementAndGet();
                    } catch (IOException e) {
                        System.err.println("Failed to compute MD5 for " + filePath + ": " + e.getMessage());
                        failedFilesCounter.incrementAndGet();
                    } finally {
                        releaseFileLock(file, lock);
                    }
                    totalProcessingTimeNanos.addAndGet((System.nanoTime() - startTimeNanos));
                } catch (InterruptedException e) {
                    System.err.println("Interrupted while taking or releasing file lock for " + filePath);
                }
            } catch (Exception e) {
                System.err.println("Error processing file path: " + filePath + ": " + e.getMessage());
            }
        }
        failureLogger.cancel(true);
        return md5Hashes;
    }

    private static FileLock takeFileLock(File file) {
        return fileLocks.putIfAbsent(file.getAbsolutePath(), new FileLock(file));
    }

    private static void releaseFileLock(File file, FileLock lock) {
        if (lock != null) {
            fileLocks.remove(file.getAbsolutePath(), lock);
            lock.release();
        }
    }

    // Implement custom protocol for efficient file retrieval here

    private static void logExecutionStatistics() {
        long processed = processedFilesCounter.get();
        long failed = failedFilesCounter.get();
        double averageProcessingTimeMillis = (double) totalProcessingTimeNanos.get() / (1_000_000_000L * processed);
        System.out.printf("Processed files: %d, Failed files: %d, Average processing time (ms): %.2f%n", processed, failed, averageProcessingTimeMillis);
    }
}

class FileLock implements Lock {
    private final File file;
    private final ReentrantLock lock = new ReentrantLock();

    public FileLock(File file) {
        this.file = file;
    }

    @Override
    public void lock() throws InterruptedException {
        lock.lockInterruptibly();
    }

    @Override
    public boolean tryLock() {
        return lock.tryLock();
    }

    @Override
    public void unlock() {
        lock.unlock();
    }

    @Override
    public void lockInterruptibly() throws InterruptedException {
        while (!lock.tryLock()) {
            if (Thread.interrupted()) {
                throw new InterruptedException();
            }
            Thread.sleep(MIN_RETRY_DELAY_MILLIS);
        }
    }

    @Override
    public boolean tryLockLong(long time, TimeUnit unit) throws InterruptedException {
        return lock.tryLock(time, unit);
    }
}
```
