#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>

typedef struct {
    RX_UE_INFORMATION_TAG rxtag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcindication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
    pthread_mutex_t lock;
} Node;

struct list {
    Node *head;
    Node *tail;
    size_t size;
    size_t capacity;
    size_t valid_range_min;
    size_t valid_range_max;
};

void init_list(struct list* list, size_t initial_capacity, size_t valid_range_min, size_t valid_range_max) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    list->capacity = initial_capacity;
    list->valid_range_min = valid_range_min;
    list->valid_range_max = valid_range_max;

    for (size_t i = 0; i < initial_capacity; ++i) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            perror("Memory allocation failure");
            exit(EXIT_FAILURE);
        }

        node->data.rnti = (RNTI) -1;
        node->next = NULL;
        pthread_mutex_init(&node->lock, NULL);
        if (!list->head) {
            list->head = node;
            list->tail = node;
        }
    }
}

void destroy_list(struct list* list) {
    Node *current = list->head;
    while (current != NULL) {
        Node *temp = current;
        current = current->next;
        free(temp);
    }
    list->head = NULL;
    list->tail = NULL;
}

void resize_list(struct list* list, size_t new_capacity) {
    if (new_capacity <= list->size) return;

    Node **nodes = malloc(sizeof(Node *) * new_capacity);
    if (!nodes) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    size_t i;
    for (i = 0; i < list->size && i < new_capacity; ++i) {
        nodes[i] = &list->head[i];
    }

    for (; i < new_capacity; ++i) {
        Node* node = malloc(sizeof(Node));
        if (!node) {
            perror("Memory allocation failure");
            exit(EXIT_FAILURE);
        }

        node->data.rnti = (RNTI) -1;
        node->next = NULL;
        pthread_mutex_init(&node->lock, NULL);
        nodes[i] = node;
    }

    list->head = &nodes[0];
    list->tail = &nodes[new_capacity - 1];
    list->capacity = new_capacity;
}

void add_element(struct list* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    if (list->size >= list->capacity) resize_list(list, list->capacity * 2);

    Node* new_node = malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failure");
        exit(EXIT_FAILURE);
    }

    pthread_mutex_init(&new_node->lock, NULL);

    new_node->data = *data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->tail->lock);
    list->tail->next = new_node;
    list->tail = new_node;
    ++list->size;
    pthread_mutex_unlock(&list->tail->lock);
}

void remove_element(struct list* list, RNTI rnti) {
    if (list->size == 0) return;

    Node *current = list->head;
    Node *prev = NULL;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            pthread_mutex_lock(&current->lock);

            if (current == list->head) {
                list->head = current->next;
            } else if (current == list->tail) {
                list->tail = prev;
                list->tail->next = NULL;
            } else {
                prev->next = current->next;
            }

            free(current);
            --list->size;
            pthread_mutex_unlock(&current->lock);
            return;
        }

        prev = current;
        current = current->next;
    }
}

void update_crcflag(struct list* list, RNTI rnti, bool new_crcflag) {
    if (list->size == 0) return;

    Node *current = list->head;

    while (current != NULL) {
        if (current->data.rnti == rnti) {
            pthread_mutex_lock(&current->lock);
            current->data.crcindication.crcflag = new_crcflag;
            pthread_mutex_unlock(&current->lock);
            return;
        }
        current = current->next;
    }
}

void dump_list(const struct list* list, const char* filename) {
    FILE *file = fopen(filename, "w");

    if (!file) {
        perror("Failed to open output file");
        exit(EXIT_FAILURE);
    }

    Node *current = list->head;
    while (current != NULL) {
        fprintf(file, "[%lu]: RXTAG=%d, RNTI=%ld, CRCFLAG=%s\n", current - list->head, current->data.rxtag,
                current->data.rnti, current->data.crcindication.crcflag ? "true" : "false");
        current = current->next;
    }

    fclose(file);
}
