#include <pthread.h>
#include <stdbool.h>

typedef struct LTEPacket {
    unsigned int frame_num;
    unsigned int subframe_num;
    void* buffer;
    struct LTEPacket *next;
} LTEPacket;

struct LTEList {
    LTEPacket *head;
    LTEPacket *tail;
    unsigned int capacity;
    unsigned int size;
    pthread_mutex_t lock;
};

void* LTEPacket_new(unsigned int frame_num, unsigned int subframe_num, void* buffer) {
    LTEPacket* packet = (LTEPacket*)malloc(sizeof(LTEPacket));
    if (!packet) return NULL;

    packet->frame_num = frame_num;
    packet->subframe_num = subframe_num;
    packet->buffer = buffer;
    packet->next = NULL;

    return packet;
}

struct LTEList* lte_list_new(unsigned int capacity) {
    struct LTEList *list = (struct LTEList*)malloc(sizeof(struct LTEList));
    if (!list) return NULL;

    list->head = list->tail = NULL;
    list->capacity = capacity;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);

    return list;
}

bool lte_list_is_full(struct LTEList* list) {
    if (list->size >= list->capacity)
        return true;
    return false;
}

void lte_list_add(struct LTEList *list, LTEPacket *packet) {
    pthread_mutex_lock(&list->lock);

    if (!lte_list_is_full(list)) {
        if (list->head == NULL) {
            list->head = packet;
            list->tail = packet;
        } else {
            list->tail->next = packet;
            list->tail = packet;
        }
        list->size++;
    }

    pthread_mutex_unlock(&list->lock);
}

LTEPacket* lte_list_remove(struct LTEList *list) {
    pthread_mutex_lock(&list->lock);

    if (list->head == NULL) {
        pthread_mutex_unlock(&list->lock);
        return NULL;
    }

    LTEPacket* temp = list->head;
    list->head = list->head->next;
    list->size--;

    if (list->size == 0) {
        list->tail = NULL;
    }

    pthread_mutex_unlock(&list->lock);

    return temp;
}

void lte_list_update(struct LTEList *list, LTEPacket* packet, void* new_buffer) {
    pthread_mutex_lock(&list->lock);

    LTEPacket* current = list->head;
    while (current != NULL) {
        if (current == packet) {
            packet->buffer = new_buffer;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->lock);
}

void lte_list_dump(struct LTEList *list, const char* filename) {
    pthread_mutex_lock(&list->lock);

    FILE *file = fopen(filename, "w");
    if (!file) {
        pthread_mutex_unlock(&list->lock);
        return;
    }

    LTEPacket* current = list->head;
    while (current != NULL) {
        fprintf(file, "[Frame: %d, Subframe: %d, Buffer Pointer: %p]\n", current->frame_num, current->subframe_num, current->buffer);
        current = current->next;
    }

    fclose(file);
    pthread_mutex_unlock(&list->lock);
}
