import concurrent.futures
import aiohttp
import time
from collections import defaultdict, deque
import logging
from datetime import timedelta

class AsyncHttpSession:
    def __init__(self):
        self._session = aiohttp.ClientSession()

    async def get(self, url, cache_timeout=None):
        if not url:
            return None, None

        cached_response = self._cache.get(url)
        if cached_response:
            if time.time() - cached_response['timestamp'] < (cache_timeout or timedelta(hours=1)):
                return cached_response['content'], cached_response['ctype']

        try:
            async with self._session.get(url) as response:
                content, ctype = await response.read(), response.headers['Content-Type']
                self._cache[(url, timestamp())] = (content, ctype)
                return content, ctype
        except Exception as e:
            logging.error(f"Failed to retrieve {url}: {e}")
            return None, None

def process_urls(url_batch, cache_timeout=None):
    results = defaultdict(lambda: (0, 0, None))
    start_time = time.time()

    with concurrent.futures.ThreadPoolExecutor(max_workers=min(len(url_batch), 100)) as executor:
        futures = [executor.submit(AsyncHttpSession().get, url, cache_timeout) for url in url_batch]

    for future in concurrent.futures.as_completed(futures):
        content, ctype = future.result()
        if content is not None:
            results[(future.args[0])][1] += 1
            results[(future.args[0])][2] = ctype
        else:
            results[(future.args[0])][0] += 1

    elapsed_time = time.time() - start_time
    avg_processing_time = sum(results[k][0] for k in results) / len(url_batch) if url_batch else 0

    logging.info(f"Processed {len(url_batch)} URLs, retrieved {sum(v[1] for v in results.values())} successfully, failed {sum(v[0] for v in results.values())}, average processing time: {avg_processing_time}")
    return dict(results)

def timestamp():
    return int(time.time() * 1000)

