use std::env;
use std::fmt::Write;
use std::ffi::{CString, CStr};
use reqwest::Client;
use reqwest_middleware::LoggerMiddleware;
use reqwest_logger::{oauth2::OAuth2LoggingBuilder, RequestLogEvent};
use chrono::Utc;
use serde_json::json;
use openssl::{
    evp::{sha1 as sha1_evp, SHA1},
    pkey::PKey,
    rsa::Rsa,
    hash::HMAC,
    cipher::{aes::AES128CBC, Cipher},
};
use libc::{cfree, free};

pub struct HttpClient {
    client: Client,
}

impl HttpClient {
    pub fn new() -> Self {
        let client = Client::new();

        // Set up logging and HTTP client
        let log_format = "%!{timestamp}%!{status}%!{request}%!{response}";
        let logging_builder = OAuth2LoggingBuilder::default()
            .with_filter(move |event: &RequestLogEvent| {
                event.headers.get("Authorization").is_none()
            })
            .with_format(log_format);

        Client::builder()
            .add_middlewares(vec![LoggerMiddleware::new(logging_builder)])
            .build()
            .unwrap();

        HttpClient { client }
    }

    pub async fn get(&self, url: &str) -> reqwest::Result<reqwest::Response> {
        self.client.get(url).send().await
    }

    pub async fn post<T>(&self, url: &str, headers: &HashMap<String, String>, body: T) -> reqwest::Result<reqwest::Response>
    where T: serde::Serialize {
        let request_json = json!(body);
        self.client
            .post(url)
            .headers(headers)
            .json(&request_json)
            .send()
            .await
    }

    pub async fn put<T>(&self, url: &str, headers: &HashMap<String, String>, body: T) -> reqwest::Result<reqwest::Response>
    where T: serde::Serialize {
        let request_json = json!(body);
        self.client
            .put(url)
            .headers(headers)
            .json(&request_json)
            .send()
            .await
    }

    pub async fn delete(&self, url: &str) -> reqwest::Result<reqwest::Response> {
        self.client.delete(url).send().await
    }
}
