extern crate openssl;
use std::ffi::{CString, CStr};
use std::os::raw::c_char;

pub struct AesContext {
    ctx: *mut openssl::aes::AES128CBC,
    password: Vec<u8>,
}

impl Drop for AesContext {
    fn drop(&mut self) {
        unsafe {
            openssl::evp::EVP_cleanup();
            openssl::aes::AES128CBC_ctx_free(self.ctx);
            free(self.password.as_ptr() as *mut c_char);
        }
    }
}

impl AesContext {
    pub fn new(password: &str) -> Self {
        let password = CString::new(password).unwrap();
        let mut key = [0u8; 32];
        sha1_evp().update(&password).finalize(&mut key);

        let iv = [0x00u8; 16];
        let cipher = AES128CBC::new(key, &iv)?;
        Self {
            ctx: cipher.into_context(),
            password,
        }
    }

    pub unsafe fn encrypt(&self, data: &[u8]) -> Vec<u8> {
        let mut out = vec![0; data.len()];
        let len = openssl::aes::AES128CBC_encrypt(self.ctx, data.as_ptr(), out.as_mut_ptr());
        out[..len].to_vec()
    }

    pub unsafe fn decrypt(&self, data: &[u8]) -> Vec<u8> {
        let mut out = vec![0; data.len()];
        let len = openssl::aes::AES128CBC_decrypt(self.ctx, data.as_ptr(), out.as_mut_ptr());
        out[..len].to_vec()
    }
}

pub fn modify_filename(filename: &str) -> *mut c_char {
    let filename = CString::new(filename).unwrap();
    let ext_pos = filename.find(".").unwrap_or(filename.len());

    // Allocate memory for new string and the extension part separately
    let mut len = (ext_pos + 5) as usize;
    let new_str = vec![0; len].into_boxed_slice();
    let ext = vec![0; filename[ext_pos..].len() + 4].into_boxed_slice();

    // Copy filename without the extension part
    unsafe {
        std::ptr::copy_nonoverlapping(
            filename.as_ptr().add(0..ext_pos),
            new_str.as_mut_ptr(),
            ext_pos,
        );
    }

    // Create a new extension using the provided filename characters
    let mut ext_len = 4;
    let c: u8 = match filename[ext_pos + 1..].chars().nth(0).unwrap() {
        '.' => {
            if let Some(c) = filename[ext_pos + 2..].chars().nth(0) {
                c as u8
            } else {
                ext_len += 1;
                0
            }
        }
        _ => 0,
    };

    if c != 0 {
        unsafe {
            std::ptr::copy_nonoverlapping(
                filename.as_ptr().add(ext_pos + 1),
                ext.as_mut_ptr(),
                filename[ext_pos + 1..].len(),
            );
        }
        // Replace the last dot with the new extension character
        unsafe {
            let ptr = ext.as_mut_ptr().add(ext_len);
            *ptr = c as u8;
        }
    } else {
        match filename[ext_pos..].chars().nth(0).unwrap() {
            '1'..='9' => {
                // New extension is the same file type with a trailing digit incremented
                let num = filename[ext_pos + 2..].parse::<u32>().unwrap();
                unsafe {
                    std::ptr::copy_nonoverlapping(
                        filename.as_ptr().add(ext_pos + 1),
                        ext.as_mut_ptr(),
                        filename[ext_pos + 1..].len(),
                    );
                }
                ext[ext_len] = (num + 1) as u8;
            }
            _ => {
                // New extension is a new file type with a single digit incremented
                let last_char: u8 = filename[filename.len() - 1];
                if last_char >= '0' && last_char <= '9' {
                    unsafe {
                        std::ptr::copy_nonoverlapping(
                            filename.as_ptr().add(ext_pos + 1),
                            ext.as_mut_ptr(),
                            filename[ext_pos + 1..].len(),
                        );
                    }
                    ext[ext_len] = (last_char as u32 - '0' as u32 + 2) as u8;
                } else {
                    ext[ext_len] = b'.';
                    ext[ext_len + 1] = last_char;
                }
            }
        };
    }

    // Concatenate the new extension to the filename without the extension part
    let mut result = vec![0; len];
    unsafe {
        std::ptr::copy_nonoverlapping(
            new_str.as_ptr(),
            result.as_mut_ptr(),
            new_str.len(),
        );
        std::ptr::copy_nonoverlapping(ext.as_ptr(), result.as_mut_ptr().add(ext_pos), ext.len());
    }

    CString::new(result).unwrap().into_raw()
}
