use std::process::{Command, Output};
use std::sync::SyncLazy;
use std::time::Instant;
use rustc_driver::catch_with_exit_code;
use rustc_driver::cli::CargoConfig;
use rustc_driver::config::DriverConfig;
use rustc_driver::{RustcCommand, RunCompiler};
use tempfile::TempDir;
use ice::IceHook;
use log::{error, info};

static ICE_HOOK: SyncLazy<IceHook> = SyncLazy::new(|| IceHook::new());

fn compile() -> std::result::Result<i32, Box<dyn std::error::Error>> {
    let temp_dir = TempDir::new("rustc-temp")?;

    let mut config = DriverConfig::new();
    config.add_hook(ICE_HOOK);

    let cargo_config = CargoConfig::default();
    let rustc_command = RustcCommand::new(&cargo_config, &config)?;

    // Measure the time taken for the compilation
    let start = Instant::now();

    // Set memory limit (replace with your desired value)
    const MAX_RSS: u64 = 500_000_000;

    let mut max_rss = MAX_RSS as usize;
    let mut initial_rss = 0;

    // Get the resident set size before compilation
    match Command::new("ps")
        .arg("-o")
        .arg("rss")
        .arg(&temp_dir.path())
        .output() {
        Ok(output) => {
            initial_rss = output.stdout.trim().parse::<usize>().unwrap();
        }
        Err(_) => {
            error!("Failed to get initial RSS value.");
            return Err(Box::new(std::io::Error::new(
                std::io::ErrorKind::Other,
                "Failed to check initial memory usage.",
            )));
        }
    }

    let mem_pressure = |rss: usize| {
        if rss > max_rss {
            error!(
                "Memory pressure detected. Current RSS is {} (max allowed is {})",
                rss, max_rss
            );
            return Err(Box::new(std::io::Error::new(
                std::io::ErrorKind::ResourceUnavailable,
                "Exceeded memory limit.",
            )));
        }
    };

    let mut rss = initial_rss;

    // Run the Rust compiler with a custom logging hook installed
    let exit_code = catch_with_exit_code(|run| {
        run.driver(&rustc_command, &temp_dir)?;

        // Measure the resident set size after compilation
        match Command::new("ps")
            .arg("-o")
            .arg("rss")
            .arg(&temp_dir.path())
            .output() {
            Ok(output) => {
                let current_rss = output.stdout.trim().parse::<usize>().unwrap();
                rss = current_rss;
                mem_pressure(rss)?;
                info!(
                    "Compilation completed in {} seconds. Current RSS is {}",
                    start.elapsed().as_secs_f64(),
                    rss
                );
            }
            Err(_) => {
                error!("Failed to get current memory usage.");
                return Err(Box::new(std::io::Error::new(
                    std::io::ErrorKind::Other,
                    "Failed to check current memory usage.",
                )));
            }
        }

        Ok(run.exit_code())
    })?;

    // Log detailed information about the compilation process
    let intermediate_files = run.intermediate_file_list();
    info!(
