['```csharp
using System;
using System.Collections.Generic;
using System.IO;
using Newtonsoft.Json;
using Newtonsoft.Json.Linq;

public class RandomValueGenerator
{
    private Dictionary<string, Range> Ranges { get; set; } = new Dictionary<string, Range>();
    private static Random _random;

    public RandomValueGenerator()
    {
        LoadRanges();
        _random = new Random();
    }

    private void LoadRanges()
    {
        string jsonString = File.ReadAllText("settings.json");
        Ranges = JsonConvert.DeserializeObject<Dictionary<string, Range>>(jsonString);
    }

    public void SaveRanges(string fileName)
    {
        string jsonString = JsonConvert.SerializeObject(Ranges, Formatting.Indented);
        File.WriteAllText(fileName, jsonString);
    }

    private class Range
    {
        public double Min { get; set; }
        public double Max { get; set; }
        public bool IsExclusiveUpperBound { get; set; }

        public Range(double min, double max, bool isExclusiveUpperBound = false)
        {
            if (min > max)
                throw new ArgumentException("Minimum value cannot be greater than maximum value.");

            Min = min;
            Max = max;
            IsExclusiveUpperBound = isExclusiveUpperBound;
        }

        public double GenerateValue(Type type)
        {
            if (type == typeof(int))
                return IsExclusiveUpperBound ? (double)(_random.Next((int)Math.Ceiling(Min), (int)Max + 1)) : (double)_random.Next((int)Min, (int)Max + 1);
            else if (type == typeof(float))
                return IsExclusiveUpperBound ? (float)(_random.NextDouble() * (Math.Ceiling(Max) - Math.Floor(Min)) + Min) : (float)_random.NextDouble() * (Max - Min);
            else
                throw new ArgumentException("Invalid data type.");
        }
    }

    public T GenerateValue<T>(string rangeName, Type type = null)
    {
        if (!Ranges.TryGetValue(rangeName, out var range))
            throw new KeyNotFoundException($"Range '{rangeName}' not found.");

        object value;
        if (type != null)
            value = Activator.CreateInstance(type);
        else
            value = range.GenerateValue(typeof(T));

        return type == null ? (T)value : (T)Convert.ChangeType(value, typeof(T));
    }

    public override string ToString()
    {
        var builder = new System.Text.StringBuilder();

        foreach (var range in Ranges)
        {
            builder.AppendLine($"Range: {range.Key} - Min: {range.Value.Min} Max: {range.Value.Max}");
        }

        return builder.ToString();
    }
}
```

