  function worker(accum, num) {
    return callback(accum, num).catch(error => {
      if (error.retries === 3) {
        throw error;
      } else {
          console.log(`Failed: ${accum}, Current: ${num}`);
          error.retries++;
          worker(accumulator, num);
      }
    });
  }

  for (let i = 0; i < arr.length; i++) {
    const num = arr[i];
    if (workers.size < concurrencyLimit) {
      workers.add(true);
      promises.push(worker(accumulator, num).finally(() => workers.delete(true)));
      accumulator = accumulator + num;
    } else {
      promises.push(new Promise(resolve => setTimeout(() => resolve(accumulator + num), 0)));
    }
  }

  return Promise.allSettled(promises).then((results) => {
    let hasRejected = results.some(({ status }) => status === 'rejected');
    if (hasRejected) {
      throw new Error('Reduction failed due to one or more errors');
    }
    return results.reduce((acc, { value }) => acc + value, 0);
  });
};
```

