#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <dirent.h>
#include <sys/stat.h>
#include <time.h>
#include <json-c/json.h>

typedef struct FileData {
    char name[256];
    off_t size;
    time_t mtime;
} FileData;

typedef struct DirData {
    char path[256];
    json_object *children;
} DirData;

json_object* dir_to_json(const char *path, off_t max_size, bool exclude_large_files) {
    DIR *dir = opendir(path);
    if (!dir) return NULL;

    struct dirent *entry;
    FileData file_data;
    DirData dir_data;
    json_object *root = json_object();

    while ((entry = readdir(dir))) {
        snprintf(file_data.name, sizeof(file_data.name), "%s/", path);
        strncat(file_data.name, entry->d_name, sizeof(file_data.name) - strlen(path));

        struct stat st;
        if (lstat(file_data.name, &st) == -1) continue;

        file_data.size = st.st_size;
        file_data.mtime = st.st_mtime;

        if (S_ISDIR(st.st_mode)) {
            if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) continue;

            snprintf(dir_data.path, sizeof(dir_data.path), "%s", file_data.name);
            dir_data.children = json_object();

            if (json_object_array_add(root, dir_to_json(file_data.name, max_size, exclude_large_files))) {
                json_object_put(dir_data.children); // free children on failure
            }
        } else {
            if (exclude_large_files && file_data.size > max_size) continue;

            json_object *file = json_object();
            json_object_objectadd(file, "name", json_string(file_data.name));
            json_object_objectadd(file, "size", json_newlong(file_data.size));
            json_object_objectadd(file, "mtime", json_newint((int) file_data.mtime));

            if (json_object_array_add(root, file)) {
                json_object_put(file); // free file on failure
            }
        }
    }

    closedir(dir);
    return root;
}

char* dir_to_json_string(const char *path, off_t max_size, bool exclude_large_files) {
    json_object *root = dir_to_json(path, max_size, exclude_large_files);
    if (!root) return NULL;

    char *json_str = json_object_to_json_string(root);
    json_object_put(root); // free root on success
    return json_str;
}
```
