public class UserManager {
    private final Map<String, UserProfile> userProfiles;
    private final String userDirectory;
    private final String roleAssignmentServiceUrl;
    private final int retryIntervalSeconds;
    private final ScheduledExecutorService retryService;

    public UserManager(Map<String, UserProfile> userProfiles, String userDirectory, String roleAssignmentServiceUrl, int retryIntervalSeconds) {
        this.userProfiles = userProfiles;
        this.userDirectory = userDirectory;
        this.roleAssignmentServiceUrl = roleAssignmentServiceUrl;
        this.retryIntervalSeconds = retryIntervalSeconds;
        this.retryService = Executors.newScheduledThreadPool(1);
    }

    public User addUserToGroup(String userId, String groupName) {
        Preconditions.checkNotNull(userProfiles, "userProfiles must not be null");
        Preconditions.checkArgument(!userProfiles.containsKey(userId), "User already exists in the system.");

        AtomicReference<User> userRef = new AtomicReference<>();

        Runnable userCreationTask = () -> {
            try {
                Path userHomePath = Paths.get(userDirectory, userId);
                if (!Files.exists(userHomePath)) {
                    Files.createDirectories(userHomePath);
                }
                UserProfile defaultProfileTemplate = // load predefined template
                UserProfile userProfile = new UserProfile(userId, defaultProfileTemplate);
                Files.write(Paths.get(userHomePath.resolve("profile.json")), userProfile.toJsonBytes());
                userRef.set(userProfile);
            } catch (IOException e) {
                // Log error message and return null
            }
        };

        Runnable userAdditionTask = () -> {
            User user = userProfiles.get(userId);
            if (user == null) {
                // User profile is missing, execute user creation task if not running yet
                if (!userCreationTask.isDone()) {
                    new Thread(userCreationTask).start();
                }
                try {
                    user = userCreationTask.get();
                } catch (Exception e) {
                    // User creation failed, log error message and return null
                }
            }

            if (user != null) {
                // Attempt to add user to group and trigger role assignment process asynchronously
                HttpUrlConnection.sendPostRequest(roleAssignmentServiceUrl + "/addToGroup/" + userId + "/" + groupName);
                return user;
            }
        };

        if (!userDirectory.isWritable() || !Files.exists(Paths.get(userDirectory))) {
            // Log error message and return null
        } else if (Files.exists(Paths.get(userDirectory)) && !Files.isWritable(Paths.get(userDirectory))) {
            // Log error message and return null
        } else {
            new Thread(userAdditionTask).start();
        }

        retryService.scheduleAtFixedRate(() -> {
            if (userRef.get() != null) {
                retryService.shutdownNow();
                return;
            }
            userAdditionTask.run();
        }, 0, retryIntervalSeconds, TimeUnit.SECONDS);

        return userRef.get();
    }
}
