#include <arpa/inet.include>
#include <boost/property_tree/json_parser.hpp>
#include <boost/regex.hpp>
#include <iostream>
#include <stdexcept>
#include <string>
#include <sstream>
#include <ctime>

bool isValidJWT(const std::string& json) {
    namespace pt = boost::property_tree;
    try {
        pt::json_parser::read_json(json, pt::json_parser::trim_all);
    } catch (const pt::json_parser::parse_error &e) {
        std::cerr << "Invalid JSON structure: " << e.what() << '\n';
        return false;
    }

    pt::ptree root;
    try {
        pt::read_json(json, root);
    } catch (const pt::json_parser::parse_error &e) {
        std::cerr << "Invalid JSON structure: " << e.what() << '\n';
        return false;
    }

    if (!root.get<std::string>("typ").compare("JWT")) {
        time_t currentTime = static_cast<time_t>(std::floor(std::time(0)));
        long expValue = root.get<long>("exp");

        if (expValue <= currentTime) {
            return false;
        }

        std::string jwtStr = root.get<std::string>("jwt");
        bool isReservedKeyword = std::find(KEYWORDS_START, KEYWORDS_END, jwtStr) != KEYWORDS_END;

        if (isReservedKeyword) {
            return false;
        }

        long nbfValue = root.get_optional<long>("nbf").defaulted(-1);
        bool isAzpValidUrl = true;
        long iatValue = root.get_optional<long>("iat").defaulted(-1);

        if (nbfValue != -1 && nbfValue > expValue) {
            return false;
        }

        if (root.get_optional("azp")) {
            std::string azp = root.get<std::string>("azp");
            isAzpValidUrl = std::regex_match(azp, std::regex("http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|\\.*|\\%)+"));
        }

        if (iatValue != -1 && iatValue > expValue) {
            return false;
        }

        pt::ptree customClaims = root.get_child("custom_claims");
        if (customClaims.empty() || !validateCustomClaims(customClaims)) {
            return false;
        }
    } else {
        return false;
    }

    return true;
}

bool validateCustomClaims(const pt::ptree& customClaims) {
    for (auto& field : customClaims) {
        if (field.first == "email_verified" && field.second.get<bool>() != true) {
            return false;
        }

        // Recursively validate nested fields in case of multi-level structures
        bool isValid = validateCustomClaims(field.second);
        if (!isValid) {
            return false;
        }
    }

    return true;
}

