using System;
using System.Collections.Generic;
using System.Data;
using System.Globalization;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using StackExchange.Redis;
using CsvHelper;

namespace ProcessCSV
{
    public class Processor
    {
        private readonly ConnectionMultiplexer _redis;
        private readonly IWriterCsv _csvWriter;
        private readonly TimeSpan _timeout;

        public Processor(ConnectionMultiplexer redis, IWriterCsv csvWriter, TimeSpan timeout)
        {
            _redis = redis;
            _csvWriter = csvWriter;
            _timeout = timeout;
        }

        public void ProcessFile(string filePath)
        {
            var startTime = DateTime.Now;
            using var reader = new StreamReader(filePath);

            if (reader.ReadLine().Split(',').FirstOrDefault() == "Tabulator") // Dynamic format detection
            {
                _csvReader = new TabularCsvWriter(_csvWriter);
            }
            else
            {
                _csvReader = new CsvWriter(_csvWriter);
            }

            using var csv = new CsvReader(reader, CultureInfo.InvariantCulture);

            var records = new List<IDictionary<string, string>>();
            var concurrentWriters = Enumerable.Range(0, Environment.ProcessorCount).Select(_ => new Task(() => ProcessAndWriteRecordAsync(csv, _redis, records))).ToList();

            try
            {
                while (csv.Read())
                {
                    concurrentWriters.ForEach(t => t.Start());
                    Task.WaitAll(concurrentWriters.ToArray(), _timeout);

                    concurrentWriters.Clear();
                    concurrentWriters = concurrentWriters.Select(_ => new Task(() => ProcessAndWriteRecordAsync(csv, _redis, records))).ToList();
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred during processing: {ex.Message}");
            }

            concurrentWriters.ForEach(t => t.Start());
            Task.WaitAll(concurrentWriters.ToArray(), _timeout);

            var elapsedTime = DateTime.Now - startTime;
            Console.WriteLine($"Processing completed in {elapsedTime.TotalSeconds} seconds.");
        }

        private async void ProcessAndWriteRecordAsync(CsvReader csv, ConnectionMultiplexer redis, List<IDictionary<string, string>> records)
        {
            try
            {
                var record = csv.Read();
                if (record != null)
                {
                    records.Add(record);
                    await WriteToCacheAsync(redis, record);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine($"An error occurred during processing a record: {ex.Message}");
            }
        }

        private async Task WriteToCacheAsync(ConnectionMultiplexer redis, IDictionary<string, string> record)
        {
            using (var database = redis.GetDatabase())
            {
                await database.HashSetAsync("Records", record);
            }
        }
    }
}
```
