bool processAndDecrypt(const std::string& jsonStr, const std::string& key, const std::string& iv, const std::string& secretKey) {
    try {
        json j = json::parse(jsonStr);
        if (!j.contains("access_token") || !j.contains("expires_in") || !j.contains("token_type"))
            return false;

        const std::string& accessToken = j["access_token"].get<std::string>();
        const int expiresIn = j["expires_in"].get<int>();
        const std::string& tokenType = j["token_type"].get<std::string>();
        const bool isBearer = tokenType == "Bearer";

        if (!isBearer || expiresIn <= 0)
            return false;

        TripleDES des(reinterpret_cast<const unsigned char*>(key.c_str()), reinterpret_cast<const unsigned char*>(iv.c_str()));
        std::string base64AccessToken = accessToken;
        auto data = Base64::decode(base64AccessToken);

        auto currentTime = std::chrono::system_clock::now().time_since_epoch().count();
        if (currentTime > expiresIn)
            return false;

        std::string decryptedToken = des.decrypt(data);
        HMACSHA256 hmac(secretKey);
        auto hmacValue = hmac.calculate(decryptedToken);

        // Retry up to three times for network failures during the HMAC verification step
        int retriesLeft = 3;
        for (int i = 0; i < 4 || retriesLeft > 0; ++i) {
            Poco::Net::HTTPClientSession session;
            Poco::URI uri("https://authentication-service.com/validate");
            std::stringstream requestBody;
            requestBody << "access_token=" << decryptedToken << "&hmac=" << Base64::encode(hmacValue);
            Poco::Net::HTTPRequest request(Poco::Net::HTTPRequest::POST, uri.toString(), requestBody.str());
            request.setContentLength((int)requestBody.tellp());
            session.sendRequest(request);
            Poco::Net::HTTPResponse response;
            bool success = session.receiveResponse(response);
            if (success && response.getStatus() == 200) {
                return true;
            }
            --retriesLeft;
        }
    } catch (const std::exception& e) {
        std::cerr << "Error parsing JSON: " << e.what() << '\n';
    }

    return false;
}
