public class HashGenerator
{
    private static readonly Logger _logger = LogManager.GetCurrentClassLogger();
    private readonly ConcurrentDictionary<string, (string Input, DateTime Timestamp, DateTime ExpiresAt)> _cache;
    private const int CacheSize = 1000;
    private const int CacheEvictionPolicy = 3; // Number of accesses before evicting from cache
    private TimeSpan _cacheExpirationTime;

    public HashGenerator()
    {
        _cache = new ConcurrentDictionary<string, (string Input, DateTime Timestamp, DateTime ExpiresAt)>();
        _cacheExpirationTime = TimeSpan.FromMinutes(5);
    }

    public string GenerateHash(string input)
    {
        var currentRequestTimestamp = DateTime.UtcNow;
        var md5 = MD5.Create();
        var timestampedInput = $"{input}{currentRequestTimestamp:yyyy-MM-ddTHH:mm:ss.fffZ}";

        if (_cache.TryGetValue(timestampedInput, out var cachedResult))
        {
            // Cache hit - check if the cached result is still valid
            if (cachedResult.ExpiresAt > currentRequestTimestamp)
                return cachedResult.Input;
        }

        byte[] data = md5.ComputeHash(Encoding.UTF8.GetBytes(timestampedInput));
        string hash = BitConverter.ToString(data).Replace("-", "").ToLower();

        // Cache miss - add the new result to the cache
        _cache[timestampedInput] = (hash, currentRequestTimestamp, currentRequestTimestamp + _cacheExpirationTime);

        LogIfNeeded("Generating Hash for Input: " + input, Level.Info);

        return hash;
    }

    private void LogIfNeeded(string message, NLog.LogLevel level)
    {
        if (message.Contains("error") || message.Contains("exception"))
            _logger.Error(message);
        else
            _logger.Log(level, message);
    }
}
