use std::collections::{HashMap, HashSet};
use serde::{Deserialize, Serialize};
use serde_json::from_str;
use std::env;
use std::fs;
use std::io::{BufRead, BufWriter};
use std::path::PathBuf;
use std::sync::Mutex;
use std::time::{Duration, SystemTime};

const CONFIGSTORE_FILE: &str = "configstore.json";
type ConfigStore = HashMap<String, serde_json::Value>;

#[derive(Serialize, Deserialize)]
struct Config {
    data: ConfigStore,
}

// Helper function to get a normalized absolute path for the given path string
fn normalize_path(path: &str) -> PathBuf {
    let mut p = PathBuf::from(path);
    if !p.is_abs() {
        p.make_absolute().unwrap();
    }
    p
}

// Function to initialize the config store, creating and setting up the environment variable accordingly
fn init_configstore() -> Result<(), Box<dyn std::error::Error>> {
    let cwd = std::env::current_dir().unwrap();
    let mut path = normalize_path(CONFIGSTORE_FILE);
    path.push(&cwd);

    // Check if CONFIGSTORE_PATH is set, handle accordingly
    let configstore_path = env::var("CONFIGSTORE_PATH");
    let is_set = configstore_path.is_ok();
    let store_path: PathBuf;

    if is_set {
        store_path = normalize_path(configstore_path.unwrap());
    } else {
        fs::create_dir_all(&cwd)?;
        store_path = path;
        env::set_var("CONFIGSTORE_PATH", store_path.to_str().unwrap());
    }

    // Check if the file exists and is a file, handle accordingly
    if !store_path.is_file() {
        fs::File::create(store_path)?;
    } else {
        eprintln!("Warning: Config store path '{}' already exists but is not a file.", store_path.display());
    }

    Ok(())
}

fn load_configstore() -> Result<Config, Box<dyn std::error::Error>> {
    let store_path = normalize_path(CONFIGSTORE_PATH.unwrap_or_else(|_| {
        init_configstore()?;
        CONFIGSTORE_PATH.unwrap()
    }));

    // Load the configuration file
    let mut config_file = fs::File::open(&store_path)?;
    let config_str = std::io::BufReader::new(config_file)
        .lines()
        .fold(String::new(), |acc, line| acc + &line.unwrap());
    let config: Config = from_str(&config_str).map_err(|e| e.into())?;

    // Validate and update the configuration file content if necessary
    // ... (You may use a library like serde_json to validate the JSON structure)

    Ok(config)
}

fn handle_sub_files(config: &Config, args: &[String]) -> Result<Config, Box<dyn std::error::Error>> {
    let mut data = config.data.clone();
    for (i, arg) in args.iter().enumerate() {
        let sub_path = normalize_path(format!("CONFIGSTORE_PATH_SUB_{}", i).as_str());
        let path = match env::var(sub_path) {
            Ok(val) => val.unwrap(),
            Err(_) => continue,
        };

        // Check if the sub-file exists and is a file, load and merge its content into the main configuration structure
        if fs::metadata(path).is_ok() && fs::File::open(&path).is_ok() {
            let linked_config = load_configstore()?;
            data.extend(linked_config.data);
        }
    }

    Ok(Config { data })
}

fn main() -> Result<(), Box<dyn std::error::Error>> {
    // Perform initial setup and configuration loading
    let mut config = load_configstore()?;

    // Handle command-line arguments for sub-files
    let args: Vec<String> = env::args().collect();
    if args.len() > 1 {
