            _active_instances = active_instances

            def __call__(cls, *args, **kwargs):
                with cls.instances_lock:
                    if cls not in LimitInstancesMeta._active_instances or len(LimitInstancesMeta._active_instances[cls]) >= max_instances:
                        time.sleep(0.1)
                    instance = super().__call__(*args, **kwargs)
                LimitInstancesMeta._active_instances[cls] += [instance]
                return instance

        return type(cls.__name__, (cls,), {'__metaclass__': LimitInstancesMeta})

