    struct list_node *next;
    pthread_mutex_t lock;
} ListNode;

typedef struct {
    unsigned int size;
    ListNode** nodes;
    pthread_mutex_t lock;
} List;

List* create_list(unsigned int size) {
    List* list = malloc(sizeof(List));
    if (!list) return NULL;
    list->size = size;
    list->nodes = calloc(size, sizeof(ListNode*));
    if (!list->nodes) {
        free(list);
        return NULL;
    }
    pthread_mutex_init(&list->lock, NULL);
    for (unsigned int i = 0; i < size; ++i) {
        list->nodes[i] = malloc(sizeof(ListNode));
        if (!list->nodes[i]) {
            free(list->nodes);
            free(list);
            return NULL;
        }
        pthread_mutex_init(&(list->nodes[i]->lock), NULL);
    }
    return list;
}

void destroy_list(List* list) {
    for (unsigned int i = 0; i < list->size; ++i) {
        ListNode *node = list->nodes[i];
        free(node);
    }
    free(list->nodes);
    free(list);
}

ListNode* get_node(List* list, unsigned int index) {
    if (index >= list->size || index < 0) return NULL;
    pthread_mutex_lock(&list->lock);
    ListNode *node = list->nodes[index];
    pthread_mutex_unlock(&list->lock);
    return node;
}

bool insert(List* list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    for (unsigned int i = 0; i < list->size; ++i) {
        ListNode *node = get_node(list, i);
        if (!node || node->data.tag == data->tag && node->data.rnti == data->rnti) return false;
    }
    ListNode* new_node = malloc(sizeof(ListNode));
    if (!new_node) return false;
    pthread_mutex_init(&new_node->lock, NULL);
    new_node->data = *data;
    new_node->next = NULL;

    pthread_mutex_lock(&list->lock);
    for (unsigned int i = 0; i < list->size; ++i) {
        if (!get_node(list, i)) {
            get_node(list, i) = new_node;
            break;
        }
    }
    pthread_mutex_unlock(&list->lock);
    return true;
}

bool remove(List* list, unsigned int index) {
    if (index >= list->size || index < 0) return false;
    pthread_mutex_lock(&list->lock);
    ListNode *current = list->nodes[index];
    if (!current) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    ListNode *prev = NULL;
    while (current != NULL) {
        prev = current;
        current = current->next;
    }
    if (prev == NULL) {
        pthread_mutex_unlock(&list->lock);
        return false;
    }
    ListNode *temp = prev->next;
    free(prev);
    prev = temp;
    prev->next = current->next;
    pthread_mutex_unlock(&list->lock);
    free(current);
    return true;
}

const NFAPI_CRC_INDICATION_PDU_T* find(List* list, const RX_UE_INFORMATION_TAG tag, uint32_t rnti) {
    for (unsigned int i = 0; i < list->size; ++i) {
        ListNode *node = get_node(list, i);
        if (!node || node->data.tag != tag || node->data.rnti != rnti) continue;
        pthread_mutex_lock(&node->lock);
        const NFAPI_CRC_INDICATION_PDU_T* result = &node->data;
        pthread_mutex_unlock(&node->lock);
        return result;
    }
    return NULL;
}
