```c
#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

// Maximum number of resources and threads
#define MAX_RESOURCES 1000
#define MAX_THREADS 100

// Resource pool struct
typedef struct {
    sem_t sem_resource_pool;
    int resources;
} ResourcePool;

// Thread-safe logger struct
typedef struct {
    FILE *logfile;
    char name[32];
} Logger;

void log_operation(Logger *logger, const char *operation) {
    time_t rawtime;
    struct tm *timeinfo;
    char time_buffer[80];

    char *timestamp = ctime(&rawtime);
    timestamp[strlen(timestamp) - 1] = '\0'; // remove newline character

    timeinfo = localtime(&rawtime);
    strftime(time_buffer, sizeof(time_buffer), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(logger->logfile, "[%s] [%s] - %s\n", time_buffer, logger->name, operation);
}

ResourcePool *resource_pool_init() {
    ResourcePool *rp = malloc(sizeof(ResourcePool));
    if (!rp) return NULL;

    sem_init(&rp->sem_resource_pool, 0, MAX_RESOURCES);
    rp->resources = MAX_RESOURCES;

    Logger logger = { .logfile = fopen("resource_log.txt", "w+"), .name = "ResourcePool" };
    log_operation(&logger, "initialized");

    return rp;
}

int resource_pool_acquire(ResourcePool *rp) {
    int result;

    sem_wait(&rp->sem_resource_pool);

    if (--rp->resources < 0) {
        fprintf(stderr, "Error: Negative number of resources\n");
        exit(1);
    }

    log_operation(&logger, "acquired");

    result = 1;
    return result;
}

void resource_pool_release(ResourcePool *rp) {
    if (++rp->resources > MAX_RESOURCES) {
        fprintf(stderr, "Error: Number of resources exceeded limit\n");
        exit(1);
    }

    log_operation(&logger, "released");

    sem_post(&rp->sem_resource_pool);
}

void resource_pool_destroy(ResourcePool *rp) {
    fclose(logger.logfile);
    free(rp);
}

