import java.security.MessageDigest;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.io.FileWriter;
import java.io.IOException;

public class ConcurrentResourceManager {
    private static final int MAX_RESOURCES = 1000;
    private static final int MAX_THREADS = 100;

    private ResourcePool resourcePool;
    private ExecutorService executor;
    private FileWriter logFile;

    public ConcurrentResourceManager() {
        resourcePool = new ResourcePool(MAX_RESOURCES);
        executor = Executors.newFixedThreadPool(MAX_THREADS);
        try {
            logFile = new FileWriter("resource_log.txt");
        } catch (IOException e) {
            System.err.println("Error creating log file: " + e.getMessage());
            System.exit(1);
        }
    }

    private void executeTask(Runnable task, String input) {
        task.run();
        md5Hash(input);
    }

    public void acquireResourcesAndExecuteTask(Runnable task, String input) {
        while (!resourcePool.acquireResource()) {
            try {
                TimeUnit.MILLISECONDS.sleep(10);
            } catch (InterruptedException e) {
                System.err.println("Thread interrupted: " + e.getMessage());
            }
        }

        executor.execute(() -> executeTask(task, input));
    }

    private void releaseResources() {
        resourcePool.releaseResource();
    }

    public void run() {
        for (int i = 0; i < MAX_THREADS; ++i) {
            executor.execute(() -> {
                String input = "Large input string"; // Placeholder for actual large input string
                acquireResourcesAndExecuteTask(new Task(), input);
                releaseResources();
            });
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            System.err.println("Main thread interrupted: " + e.getMessage());
        }
    }

    private void md5Hash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            md.update(input.getBytes(StandardCharsets.UTF_8));
            BigInteger number = new BigInteger(1, md.digest());

            String hashedInput = String.format("%32s", number).replaceAll("-", "");
            logFile.write(hashedInput + " - " + System.currentTimeMillis() + "\n");
        } catch (Exception e) {
            System.err.println("Error calculating MD5 hash: " + e.getMessage());
        }
    }
}
```

