#include <pthread.h>
#include <semaphore.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#define LOG_FILE "debug.log"

sem_t* create_semaphore(int value) {
    int fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    sem_t* sem = sem_open("my_semaphore", O_EXCL | O_CREAT, S_IRUSR | S_IWUSR, value);

    if (sem == SEM_FAILED) {
        perror("sem_open");
        fprintf(fd, "Error: semaphore creation failed\n");
        exit(EXIT_FAILURE);
    }

    return sem;
}

void delete_semaphore(sem_t* sem) {
    if (sem_close(sem) == -1) {
        perror("sem_close");
        fprintf(open(LOG_FILE, O_WRONLY | O_APPEND), "Error: semaphore closing failed\n");
    }

    if (sem_unlink("my_semaphore") == -1) {
        perror("sem_unlink");
        fprintf(open(LOG_FILE, O_WRONLY | O_APPEND), "Error: semaphore deletion failed\n");
    }
}

void enter_critical_section(sem_t* sem) {
    if (sem_wait(sem) == -1) {
        perror("sem_wait");
        fprintf(open(LOG_FILE, O_WRONLY | O_APPEND), "Error: semaphore waiting failed\n");
        exit(EXIT_FAILURE);
    }
}

void leave_critical_section(sem_t* sem) {
    if (sem_post(sem) == -1) {
        perror("sem_post");
        fprintf(open(LOG_FILE, O_WRONLY | O_APPEND), "Error: semaphore posting failed\n");
        exit(EXIT_FAILURE);
    }
}
```

This code creates a function to create and delete a semaphore in C using the `pthread.h` and `semaphore.h` libraries. The semaphore is created with a specified initial value, and any errors during creation, deletion, or operation are logged to a specified file for debugging purposes. A `create_semaphore()` function creates the semaphore using `sem_open()`, ensuring thread safety by using an exclusive open mode and checking for errors. The `delete_semaphore()` function closes and unlinks the semaphore, also checking for errors.

The `enter_critical_section()` and `leave_critical_section()` functions ensure that the semaphore is only used within a critical section by calling `sem_wait()` and `sem_post()`, respectively. These functions check for errors during the operations and log them to the specified file before exiting the program if an error occurs.

The code assumes the existence of a log file named "debug.log" in the working directory, which should be created prior to using this code in your application.']

