#include <arpa/inet.h>
#include <ctype.h>

struct line_count {
    size_t total;
};

struct word_count {
    size_t *counts;
    size_t size;
};

void *process_file(void *arg) {
    struct stat file_stat;
    char *map = NULL;
    int fd, ret;
    size_t bytes_per_line;

    // Get the input file descriptor and its size.
    const char *filename = (const char *) arg;
    ret = fstat(fileno((FILE *) filename), &file_stat);
    if (ret == -1) {
        perror("fstat");
        return NULL;
    }

    // Map the entire file into memory.
    map = mmap(NULL, file_stat.st_size, PROT_READ, MAP_PRIVATE, fileno((FILE *) filename), 0);
    if (map == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    // Determine the size of a line based on newline character and round up for alignment.
    bytes_per_line = sizeof(char) * (strlen("\n") + 1);
    size_t num_lines = file_stat.st_size / bytes_per_line;

    // Process the lines in chunks for efficiency.
    struct line_count line_count;
    line_count.total = 0;
    const size_t chunk_size = 1024 * 64;
    for (size_t i = 0; i < num_lines; i += chunk_size) {
        size_t end = (i + chunk_size > num_lines) ? num_lines : (i + chunk_size);
        const char *start = map + bytes_per_line * i;
        process_lines(start, end - i, &line_count);
    }

    // Unmap the file from memory and close the file descriptor.
    munmap(map, file_stat.st_size);
    fclose((FILE *) filename);

    return &line_count;
}

void process_lines(const char *start, size_t length, struct line_count *count) {
    const char *line = start;
    while (length > 0 && (*line != '\n')) {
        ++line;
        --length;
    }

    if (length > 0) {
        (*count).total += length + 1; // Include the newline character.
    }
}

void build_word_counts(const struct line_count *line_counts, size_t num_lines, struct word_count *word_count) {
    for (size_t i = 0; i < num_lines; ++i) {
        const char *line = line_counts[i].total ? ((const char *) line_counts[i].data) : "";
        size_t len = strlen(line);
        for (size_t j = 0; j < len; ++j) {
            if (isalpha((unsigned char) line[j])) {
                unsigned long index = tolower((unsigned char) line[j]) - 'a';
                if (index >= word_count->size) {
                    reallocate_word_count(word_count, index + 1);
                }
                ++(word_count->counts[index]);
            }
        }
    }
}

void reallocate_word_count(struct word_count *word_count, size_t new_size) {
    if (new_size > word_count->size) {
        word_count->counts = realloc(word_count->counts, sizeof(size_t) * new_size);
        if (!word_count->counts) {
            fprintf(stderr, "Realloc failed.\n");
            exit(EXIT_FAILURE);
        }
        word_count->size = new_size;
    }
}

void print_summary(const struct word_count *word_count) {
    if (word_count->size > 0) {
        for (size_t i = 0; i < word_count->size; ++i) {
            printf("%c: %zu\n", 'a' + i, word_count->counts[i]);
        }
    }
}

int main(int argc, char **argv) {
    int opt;
    bool count_only = false, summary = false, print_output = true, manpage = false;
    const char *input_files = NULL, *output_file = NULL;

    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
