                input_files = optarg;
                break;
            case 'o':
                output_file = optarg;
                print_output = false;
                break;
            default:
                manpage = true;
        }
    }

    if (manpage) {
        printf("Usage:\n%s [options] ...\n\n", argv[0]);
        printf("Options:\n");
        printf("-h, --help                       Show this help message and exit.\n");
        printf("-c, --count-only                 Only print the total number of lines across all specified input files.\n");
        printf("-s, --summary                    Print a summary of lines per unique word encountered in the combined input files.\n");
        printf("-i, --input-file=FILE             Specifies the input file(s) to be processed. Accept multiple filenames separated by spaces.\n");
        printf("-o, --output-file=FILE            Specifies an output file where results should be written instead of being printed to console.\n");
        exit(EXIT_SUCCESS);
