import os
import hashlib
import asyncio
import aiofiles
import requests
from functools import lru_cache
import socket
import logging
from time import sleep
from urllib.parse import urlparse

class MD5Processor:
    def __init__(self, buffer_size=8192, batch_size=200, retry_limits=3, backoff_interval=2, num_workers=1, dns_cache_size=1000):
        self.buffer_size = buffer_size
        self.batch_size = batch_size
        self.retry_limits = retry_limits
        self.backoff_interval = backoff_interval
        self.num_workers = num_workers
        self.dns_cache_size = dns_cache_size
        self.log = logging.getLogger(__name__)

    async def _async_read(self, file, chunk_size):
        async with aiofiles.open(file, mode='rb') as f:
            reader = iter((await f.read(chunk_size)), b'')
            return await self._async_iterate(reader)

    async def _async_iterate(self, iterator):
        while True:
            try:
                item = next(iterator)
            except StopIteration:
                return
            else:
                yield item
                await sleep(0.01)

    async def _process_file(self, file):
        try:
            hash_obj = hashlib.md5()
            async with aiofiles.open(file, mode='rb') as f:
                async for chunk in self._async_iterate((await f.read(self.buffer_size))):
                    hash_obj.update(chunk)
                return hash_obj.hexdigest()
        except Exception as e:
            self.log.warning(f"File {file} failed processing with error: {str(e)}")
            if not self.skip_invalid_files:
                raise
            else:
                return None

    async def _process_batch(self, files):
        tasks = [self._process_file(file) for file in files]
        results = await asyncio.gather(*tasks)
        return {os.path.basename(file): result for file, result in zip(files, results)}

    @lru_cache(maxsize=None if self.dns_cache_size == 0 else self.dns_cache_size)
    def get_ip(self, hostname):
        try:
            socket.inet_pton(socket.AF_INET, hostname)
        except Exception:
            parsed = urlparse(hostname)
            if parsed.scheme == '':
                response = requests.get(f'http://{hostname}/')
                if response.status_code == 200 and response.content:
                    return response.content[0:4] + b'\x00\x04'
                else:
                    raise Exception(f"Invalid IPv4 address or hostname '{hostname}'")
            elif parsed.scheme in ('http', 'https'):
                if parsed.netloc.count(':') > 1:
                    host, port = parsed.netloc.split(':')
                    response = requests.get(f'{parsed.scheme}://{host}:{port}/')
                else:
                    response = requests.get(hostname)
                if response.status_code == 200 and response.content:
                    return response.content[0:16].split(b'\x00')[0] + b'\xff\xff'
                else:
                    raise Exception(f"Invalid IPv6 address or hostname '{hostname}'")
            else:
                raise Exception(f"Unsupported protocol '{parsed.scheme}' for hostname '{hostname}'")
        return socket.inet_aton(hostname)

    async def _process_files(self, directory):
        files = [file for file in os.listdir(directory) if os.path.isfile(os.path.join(directory, file))]
        batches = [files[i:i + self.batch_size] for i in range(0, len(files), self.batch_size)]

        tasks = []
        for batch in batches:
            tasks.append(self._process_batch(batch))
        results = await asyncio.gather(*tasks)

        hash_dict = {}
        processed = 0
        for batch_result in results:
            for file, hash_ in batch_result.items():
                if hash_ is not None:
                    hash_dict[file] = hash_
                    processed += 1
        self.log.info(f"Processed {processed} files.")
        return hash_dict

    def run(self, directory, skip_invalid_files=False):
        if not os.path.isdir(directory) or not os.access(directory, os.R_OK):
            self.log.error("Invalid or unreadable directory.")
            return
        future = asyncio.run_coroutine_threadsafe(self._process_files(directory), self.num_workers)
        result = future.result()
        return result
