    int tx_power_level;
    float snr, ber;
    time_t timestamp;
} PHY_FRAME_STATS;

// Custom allocator for efficient memory usage and cache locality
void* custom_malloc(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL && size != 0) {
        fprintf(stderr, "Out of memory\n");
        exit(-1);
    }
    return ptr;
}

// Dynamic array structure with custom allocator and error handling
typedef struct dyn_array {
    PHY_FRAME_STATS* data;
    size_t capacity, size;
    void (*alloc)(size_t);
} dyn_array;

void dyn_array_init(dyn_array *array, size_t initial_capacity, void(*alloc)(size_t)) {
    array->data = (PHY_FRAME_STATS*)custom_malloc(initial_capacity * sizeof(PHY_FRAME_STATS));
    if (!array->data) {
        fprintf(stderr, "Failed to allocate memory for dyn_array\n");
        exit(-1);
    }
    array->alloc = alloc;
    array->capacity = initial_capacity;
    array->size = 0;
}

void dyn_array_resize(dyn_array *array, size_t new_capacity) {
    PHY_FRAME_STATS* temp_data = (PHY_FRAME_STATS*)custom_malloc((new_capacity + 1) * sizeof(PHY_FRAME_STATS));
    if (!temp_data) {
        fprintf(stderr, "Failed to allocate memory for dyn_array resize\n");
        exit(-1);
    }

    if (array->size > 0) {
        memcpy(temp_data, array->data, array->size * sizeof(PHY_FRAME_STATS));
    }

    custom_free(array->data);
    array->data = temp_data;
    array->capacity = new_capacity;
}

void dyn_array_append(dyn_array *array, const PHY_FRAME_STATS *item) {
    if (array->size == array->capacity) {
        dyn_array_resize(array, array->capacity * 2);
    }

    array->data[array->size] = *item;
    array->size++;
}

// Other functions for updating and removing elements based on FRAME_TYPE and providing statistical summaries are omitted for brevity.
