// Define the custom memory allocator function (my_malloc)
void* my_malloc(size_t size, int aligned) {
    void *ptr = malloc(size);

    if (aligned && ((size_t) ptr % sizeof(NFAPI_CRC_INDICATION_PDU_T)) != 0) {
        size += sizeof(NFAPI_CRC_INDICATION_PDU_T) - ((size_t) ptr % sizeof(NFAPI_CRC_INDICATION_PDU_T));
