#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct {
    uint32_t CQI_REPORT_TAG;
    uint16_t SRB_ID;
    int CQI_VALUE;
} NR_CQI_INDICATION_PDU_T;

struct slab_node {
    struct slab_node *next;
    size_t obj_size;
    void *pool_start;
};

struct slab {
    struct slab_node *slabs;
    size_t total_objects;
    size_t used_objects;
};

struct cc_data {
    pthread_mutex_t mutex;
    struct slab cqi_slab;
};

struct connected_component {
    int id;
    struct cc_data *cc_data;
};

void* cqi_slab_alloc(struct slab *slab, size_t obj_size) {
    void *obj = NULL;
    if (slab->used_objects < slab->total_objects) {
        obj = ((char *)slab->pool_start + slab->used_objects * obj_size);
        slab->used_objects++;
    } else {
        struct slab_node *new_slab = malloc(sizeof(struct slab_node));
        if (!new_slab) return NULL;
        new_slab->obj_size = obj_size;
        new_slab->next = slab->slabs;
        new_slab->pool_start = mmap(NULL, obj_size * slab->total_objects, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
        if (new_slab->pool_start == MAP_FAILED) {
            free(new_slab);
            return NULL;
        }
        slab->slabs = new_slab;
        obj = ((char *)new_slab->pool_start + obj_size * slab->used_objects);
        slab->total_objects *= 2;
        slab->used_objects++;
    }
    return obj;
}

NR_CQI_INDICATION_PDU_T* cqi_pool_alloc(struct connected_component *cc) {
    void *obj = NULL;
    pthread_mutex_lock(&cc->cc_data->mutex);
    obj = cqi_slab_alloc(&cc->cc_data->cqi_slab, sizeof(NR_CQI_INDICATION_PDU_T));
    if (obj) {
        NR_CQI_INDICATION_PDU_T *pdu = obj;
        pdu->CQI_REPORT_TAG = rand();
        pdu->SRB_ID = rand() % 1024;
        pdu->CQI_VALUE = (rand() % 32) + 16; // Generate random signal quality metric between 16 and 47
    }
    pthread_mutex_unlock(&cc->cc_data->mutex);
    return obj ? (NR_CQI_INDICATION_PDU_T *)obj : NULL;
}

// Initialize the connected component with a slab allocator for NR_CQI_INDICATION_PDU_T structures.
void init_connected_component(struct connected_component *cc, size_t total_objects) {
    cc->id = -1;
    cc->cc_data = malloc(sizeof(struct cc_data));
    if (!cc->cc_data) return;
    pthread_mutex_init(&cc->cc_data->mutex, NULL);
    struct slab *cqi_slab = &cc->cc_data->cqi_slab;
    cqi_slab->slabs = NULL;
    cqi_slab->total_objects = total_objects;
    cqi_slab->used_objects = 0;
}
```

