use tokio::task;
use url::Url;
use reqwest::Client;
use serde::{Deserialize, Serialize};
use std::collections::{HashMap, Vec};
use std::sync::{Arc, Mutex};
use std::thread;

type OffsetVec = Vec<i64>;
type KeyVec = Vec<i32>;
type RecordVec = Vec<Record>;

#[derive(Serialize, Deserialize, Debug)]
struct ApiResponse {
    offsets: OffsetVec,
    keys: KeyVec,
}

#[derive(Serialize, Deserialize, Debug)]
struct Record {
    id: i32,
    value: i32,
}

const TIMEOUT: std::time::Duration = std::time::Duration::from_secs(5);
const MAX_RETRIES: usize = 3;
const TASK_COUNT: usize = 10;

async fn fetch_data() -> ApiResponse {
    let client = Client::new();
    let offset_url = Url::parse("https://api.example.com/offsets").unwrap();
    let key_url = Url::parse("https://api.example.com/keys").unwrap();

    let response_offset = client
        .get(offset_url)
        .send()
        .retry(MAX_RETRIES, |req| req.timeout(TIMEOUT))
        .await?
        .json::<ApiResponse>()
        .await?;

    let response_key = client
        .get(key_url)
        .send()
        .retry(MAX_RETRIES, |req| req.timeout(TIMEOUT))
        .await?
        .json::<ApiResponse>()
        .await?;

    ApiResponse { offsets: response_offset.offsets, keys: response_key.keys }
}

fn main() {
    let data = Arc::new(Mutex::new(fetch_data().await));
    let offset_vec = data.lock().unwrap().offsets;
    let key_vec = data.lock().unwrap().keys;

    let records: RecordVec = offset_vec
        .iter()
        .zip(key_vec.iter())
        .map(|(o, k)| {
            let record = Arc::new(Mutex::new(Record { id: *k, value: 0 }));
            task::spawn(async move {
                // Perform concurrent data transformation
                let mut record_ref = record.lock().unwrap();
                record_ref.value = (*o * *record_ref.value).clamp(i32::MIN, i32::MAX);
            })
            .join()
            .await
            .unwrap()
        })
        .collect();

    let mut output: Vec<String> = Vec::new();

    for record in &records {
        let id = *record.lock().unwrap().id;
        let value = *record.lock().unwrap().value;
        output.push(format!("{} {} {}", id, value));
    }

    // Write formatted output to a file
    std::fs::write("output.txt", output.join("\n")).unwrap();
}
