#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    NFAPI_CRC_INDICATION_PDU_T CRC_INDICATION_REL8_TAG;
} element_t;

typedef struct hash_node {
    element_t data;
    size_t key;
    struct hash_node *next;
} hash_node_t;

struct list {
    size_t size;
    hash_node_t** nodes;
    pthread_mutex_t lock;
};

// Custom memory allocator with cache optimizations
void* mem_alloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) return NULL;

    // Cache alignment for specific hardware architecture
    ptr = (char*)ptr + sizeof(void*) * alignof(element_t);

    return ptr;
}

// Memory pool to minimize heap fragmentation
void* mem_pool_alloc(struct list* list) {
    void* ptr;

    // Use a free list for efficient memory recycling
    if (!list->nodes[0]) {
        ptr = mem_alloc(list->size * sizeof(element_t));
        if (!ptr) return NULL;

        list->nodes[0] = (hash_node_t*)ptr;
        for (size_t i = 1; i < list->size; ++i) {
            list->nodes[i] = list->nodes[i - 1] + sizeof(element_t);
        }
    } else {
        ptr = list->nodes[0];
        list->nodes[0] = ((hash_node_t*)ptr + 1);
    }

    return ptr;
}

// Hash function with good distribution properties
size_t hash(size_t key) {
    size_t hash = 0;
    for (size_t i = 0; i < sizeof(key) * CHAR_BIT; ++i) {
        hash = ((hash << 5) + hash) + (key & 1);
        key >>= 1;
    }
    return hash % list->size;
}

void init_list(struct list* list, size_t size) {
    list->size = size;
    list->nodes = calloc(size + 1, sizeof(hash_node_t*));
    if (!list->nodes) return;

    pthread_mutex_init(&list->lock, NULL);
}

void destroy_list(struct list* list) {
    for (size_t i = 0; i < list->size; ++i) {
        hash_node_t* node = list->nodes[i];
        while (node) {
            hash_node_t* next = node->next;
            free(node);
            node = next;
        }
    }
    free(list->nodes);
    pthread_mutex_destroy(&list->lock);
}

void insert(struct list* list, const element_t* data) {
    pthread_mutex_lock(&list->lock);

    size_t key = hash(data->RX_UE_INFORMATION_TAG);
    hash_node_t* node = (hash_node_t*)mem_pool_alloc(list);
    if (!node) {
        node = calloc(1, sizeof(hash_node_t));
        if (!node) {
            pthread_mutex_unlock(&list->lock);
            return;
        }
    }

    node->data = *data;
    node->key = key;
    node->next = list->nodes[key];
    list->nodes[key] = node;

    pthread_mutex_unlock(&list->lock);
}

element_t* find(struct list* list, uint32_t RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);

    size_t key = hash(RX_UE_INFORMATION_TAG);
    hash_node_t* node = list->nodes[key];

    while (node) {
        if (node->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            element_t* result = malloc(sizeof(element_t));
            *result = node->data;
            pthread_mutex_unlock(&list->lock);
            return result;
        }
        node = node->next;
    }

    pthread_mutex_unlock(&list->lock);
    return NULL;
}

void remove(struct list* list, uint32_t RX_UE_INFORMATION_TAG) {
    pthread_mutex_lock(&list->lock);

    size_t key = hash(RX_UE_INFORMATION_TAG);
    hash_node_t* prev = NULL;
    hash_node_t* node = list->nodes[key];

    while (node) {
        if (node->data.RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG) {
            if (prev) {
                prev->next = node->next;
            } else {
                list->nodes[key] = node->next;
            }

            free(node);
            pthread_mutex_unlock(&list->lock);
            return;
        }
        prev = node;
        node = node->next;
    }

    pthread_mutex_unlock(&list->lock);
}
```

