int read_config_file(const char *path, Config **config) {
    FILE *file = fopen(path, "r");
    if (!file) {
        log(1, "Error opening configuration file: %s", path);
        return 1;
    }

    // Parse the configuration file and validate the parameters.
    // Set up cipher based on the parsed parameters.

    fclose(file);
    *config = malloc(sizeof(Config));
    (*config)->path = strdup(path);
    // ...
    return 0;
}

int load_algorithms() {
