typedef struct DataPacket {
    uint32_t id;
    time_t timestamp;
    size_t payloadSize;
    char *payload; // Compressed using zlib
    void *metadata; // Source and destination metadata
    uint16_t checksum; // Calculated on the fly for packet integrity check
    struct DataPacket *prev, *next;
    enum State { UNPROCESSED, PROCESSED } state;
} DataPacket;

#define MAX_PAYLOAD_SIZE 1048576 // 1MB

// Sorted doubly-linked list structure
typedef struct DList {
    DataPacket *head, *tail;
    pthread_mutex_t lock;
} DList;

void initChecksum(DataPacket *dp) {
    dp->checksum = 0;
    for (size_t i = 0; i < dp->payloadSize; ++i)
        dp->checksum += dp->payload[i];
    dp->checksum %= 65536; // Modulo to ensure checksum fits within 16-bit field
}

int compareTimestamps(const void *a, const void *b) {
    return (*(time_t *)a - *(time_t *)b);
}

void addPacket(DList *list, DataPacket *dp) {
    pthread_mutex_lock(&list->lock);
    if (list->head == NULL || dp->timestamp < list->head->timestamp) {
        if (list->head) list->head->prev = dp;
        dp->next = list->head;
        list->head = dp;
        if (!list->tail) list->tail = list->head;
    } else {
        DataPacket *current = list->head;
        while (current->next && current->next->timestamp < dp->timestamp)
            current = current->next;
        dp->prev = current;
        dp->next = current->next;
        if (current->next) current->next->prev = dp;
        current->next = dp;
        if (dp->timestamp > list->tail->timestamp) list->tail = dp;
    }
    pthread_mutex_unlock(&list->lock);
}

void processPacket(DataPacket *dp) {
    if (dp->state == PROCESSED) return;

    // Perform any necessary processing here, including decompression of payload, validation of metadata, etc.

    dp->state = PROCESSED;
}

int isCorrupted(DataPacket *dp) {
    uint16_t calculatedChecksum = 0;
    for (size_t i = 0; i < dp->payloadSize; ++i)
        calculatedChecksum += dp->payload[i];
    calculatedChecksum %= 65536;
    return calculatedChecksum != dp->checksum;
}

void initDList(DList *list) {
    list->head = list->tail = NULL;
    pthread_mutex_init(&list->lock, NULL);
}

DataPacket* createPacket(uint32_t id, time_t timestamp, size_t payloadSize, void *metadata) {
    DataPacket *dp = mmap(NULL, sizeof(DataPacket), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    dp->id = id;
    dp->timestamp = timestamp;
    dp->payloadSize = payloadSize > MAX_PAYLOAD_SIZE ? MAX_PAYLOAD_SIZE : payloadSize;
    dp->payload = malloc(dp->payloadSize);
    // Compress payload here if necessary, using zlib or another library
    memcpy(dp->payload, <compressed payload data>, dp->payloadSize);
    dp->metadata = metadata;
    initChecksum(dp);
    dp->prev = dp->next = NULL;
    dp->state = UNPROCESSED;
    return dp;
}

void exportList(DList *list, const char *filename) {
    // Write the doubly-linked list to a standardized format here, such as JSON or CSV
}

void garbageCollect(DList *list) {
    pthread_mutex_lock(&list->lock);
    DataPacket *current = list->head;
    while (current != NULL) {
        DataPacket *next = current->next;
        if (current->state == PROCESSED) {
            free(current->payload);
            free(current);
            current = next;
            continue;
        }
        current = next;
    }
    pthread_mutex_unlock(&list->listLock);
}
