typedef struct State {
    void* data;
    struct State* next;
} State;

typedef struct FSA {
    unsigned int id;
    char* className;
    State* head;
    void* (*create)(unsigned int); // constructor for the class
    void (*destroy)(void*); // destructor for the class
} FSA;

State* deserialize(unsigned char* data, size_t size, FSA* fsa) {
    State* current = NULL;
    State* new_state = NULL;
    unsigned int data_index = 0;

    if (!data || !fsa || !fsa->create || !fsa->destroy)
        return NULL;

    // Allocate memory for the new state and call its constructor
    new_state = fsa->create(fsa->id);
    if (!new_state) {
        fprintf(stderr, "Error: Unable to allocate memory or call constructor for class %s\n", fsa->className);
        return NULL;
    }

    // Deserialize the state data from the byte array and set the new state's data
    memcpy(new_state->data, &data[data_index], sizeof(void*));
    data_index += sizeof(void*);

    current = fsa->head;
    while (current && data_index < size) {
        // Deserialize the next pointer and update the current state's 'next' pointer
        if (current->data + sizeof(State*) >= &data[data_index]) {
            memcpy(current->next, &data[data_index], sizeof(void*));
            data_index += sizeof(void*);
        } else {
            // Not enough data in the byte array to deserialize the next pointer.
            fprintf(stderr, "Error: Insufficient data in byte array to deserialize state list\n");
            fsa->destroy(new_state); // Clean up any allocated memory for the new state and return NULL
            return NULL;
        }

        current = current->next ? current->next : NULL;
    }

    if (current) {
        // Update the 'next' pointer of the last state in the original list to point to the newly created state list
        current->next = new_state;
    } else {
        fsa->head = new_state;
    }

    return new_state;
}
