typedef struct {
    uint32_t CQI_REPORT_TAG;
    uint16_t SRB_ID;
    int16_t CQI_VALUE; // Signal quality metric (randomly generated)
} NR_CQI_INDICATION_PDU_T;

typedef struct slab {
    struct slab *next, *prev;
    size_t size;
    pthread_mutex_t lock;
    void *objects;
} SLAB;

SLAB *slabs = NULL;
pthread_mutex_t pool_lock = PTHREAD_MUTEX_INITIALIZER;
unsigned int num_slabs = 0, max_slabs = 16, curr_load = 0, free_slots = max_slabs * SLAB_SIZE;

void init_slab(SLAB **head, size_t size) {
    SLAB *new_slab = (SLAB *)malloc(sizeof(SLAB));
    new_slab->size = size;
    new_slab->objects = calloc(SLAB_SIZE, size);
    new_slab->next = new_slab->prev = NULL;
    pthread_mutex_init(&new_slab->lock, NULL);
    if (*head == NULL) {
        *head = new_slab;
        return;
    }
    SLAB *last = *head;
    while (last->next != NULL) last = last->next;
    last->next = new_slab;
    new_slab->prev = last;
}

NR_CQI_INDICATION_PDU_T *get_nr_cqi() {
    pthread_mutex_lock(&pool_lock);
    if (free_slots > 0) {
        SLAB *slab = slabs;
        free_slots--;
        pthread_mutex_unlock(&pool_lock);
        return slab->objects;
    }
    // Add code to dynamically resize the pool and create new slabs when necessary.
    pthread_mutex_unlock(&pool_lock);
    return NULL;
}

void put_nr_cqi(NR_CQI_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pool_lock);
    SLAB *slab = slabs;
    for (int i = 0; i < num_slabs; ++i, slab = slab->next) {
        if (slab->free_objects > 0) {
            free_slots++;
            pthread_mutex_unlock(&pool_lock);
            memset(slab->objects + slab->free_objects * sizeof(NR_CQI_INDICATION_PDU_T), 0, sizeof(NR_CQI_INDICATION_PDU_T));
            slab->free_objects--;
            return;
        }
    }
    // Add code to dynamically resize the pool and split existing slabs when necessary.
    pthread_mutex_unlock(&pool_lock);
}

void init_pool() {
    init_slab(&slabs, sizeof(NR_CQI_INDICATION_PDU_T));
}
