        long currentTime = System.currentTimeMillis();
        if (currentTime - lastMaintenanceExecution >= TimeUnit.DAYS.toMillis(1)) {
            executeWithDelay();
            updateMonitoringSystem("Maintenance started");
            lastMaintenanceExecution = currentTime;
        }
    }

    private void executeWithDelay() {
        long delay = (long) Math.floor((6 * 60 * 60 * 1000) * Math.pow(RANDOM.nextDouble(), 2));
