char* sanitize_url(const char* input, const char* path) {
    size_t url_len = strlen(input);
    size_t max_url_len = URL_MAX_LENGTH - (strlen(path) + 2); // Account for leading and trailing slashes in the appended path

    if(url_len > max_url_len) {
        url_len = max_url_len;
        input[url_len] = '\0';
    }

    char* protocol = strchr(input, ':');
    if(!protocol || (protocol - input > url_len)) { // No protocol found or protocol is out of bounds
        protocol = strdup("http");
    }

    size_t host_start = protocol ? (protocol - input) + strlen(protocol) : 0;
    size_t host_len = input[host_start] == '/' ? 0 : url_len - host_start;

    if(host_len > HOST_MAX_LENGTH) {
        host_len = HOST_MAX_LENGTH;
    }

    char* host = memccpy(malloc(host_len + 1), input + host_start, '/', host_len);
    if(!host || host[host_len] != '/') { // No terminating slash found or host is out of bounds
        host[host_len] = '\0';
        for(size_t i = 0; i < host_len; ++i) {
            if(isalnum(*host + i) || *host + i == '.' || *host + i == '_') {} // Allow alphanumeric, dot, and underscore characters in the host
            else {
                memmove(host + i, host + (i + 1), host_len - i);
                --host_len;
                --i;
            }
        }
    }

    size_t port_start = strchr(host, ':');
    if(port_start) {
        char* end;
        unsigned long int port = strtol(port_start + 1, &end, 10);
        if(*end || port < 1 || port > 65535) { // Invalid port number
            port = 80;
        }
        snprintf(host, host_len + 2, "%s:%u", host, (unsigned int)port);
    } else {
        snprintf(host, host_len + 1, "%s:80", host);
    }

    size_t path_start = strchr(input, '/');
    if(!path_start) { // No path found
        path_start = input;
    } else if(path_start > url_len) { // Path is out of bounds
        path_start = 0;
    }

    size_t path_len = url_len - (path_start ? (path_start - input) : 0);
    if(path_len > PATH_MAX_LENGTH) {
        path_len = PATH_MAX_LENGTH;
    }

    char* path_buffer = malloc(path_len + 2); // Account for leading and trailing slashes in the final path
    memccpy(path_buffer, input + path_start, '/', path_start - (path_start ? (path_start - input) : 0));
    path_buffer[path_len] = '/';
    path_buffer[path_len + 1] = '\0';

    char* new_path = malloc(strlen(path) + strlen(path_buffer) + 2); // Account for leading and trailing slashes
    snprintf(new_path, strlen(path) + strlen(path_buffer) + 3, "/%s%s", path, path_buffer);

    char* output = realloc(malloc(url_len + strlen(new_path) + 1), url_len + strlen(new_path) + 2); // Account for null terminator
    memccpy(output, input, host_start < url_len ? host_start : 0, host_start < url_len ? host_start : url_len);
    memccpy(output + host_start, new_path, 0, strlen(new_path));

    free(host);
    free(path_buffer);
    free(path);

    return output;
}
