<?php
namespace MyApp\Utils;

class StringAndHashUtility {
    private static $characterSets = [
        'lowercase' => array_merge(range('a', 'z'), range('0', '9')),
        'uppercase' => array_merge(range('A', 'Z'), range('0', '9')),
        // Add more character sets here as needed
    ];
    private static $hashingAlgorithms = ['sha256', 'blowfish'];
    private static $cache = [];
    private static $lock = [];
    private static $logFile;

    public static function setLogFile($file) {
        self::$logFile = $file;
    }

    public static function generateRandomString($length, $characterSet = 'lowercase') {
        if (!array_key_exists($characterSet, self::$characterSets)) {
            throw new Exception("Invalid character set specified");
        }
        $cacheKey = md5(json_encode([$length, $characterSet]));

        if (isset(self::$cache[$cacheKey])) {
            return self::$cache[$cacheKey];
        }

        lock(self::$lock[$cacheKey]); // Use a simple lock here for demonstration purposes
        $randomString = '';
        $charset = self::$characterSets[$characterSet];
        for ($i = 0; $i < $length; $i++) {
            $randomString .= $charset[array_rand($charset)];
        }
        unlock(self::$lock[$cacheKey]);

        if (isset(self::$cache[$cacheKey])) {
            self::$cache[$cacheKey] = $randomString;
        }

        logOperation("Generated a random string of length {$length} using character set '{$characterSet}'");

        return $randomString;
    }

    public static function hashPassword($password, $algorithm = 'sha256') {
        if (!in_array($algorithm, self::$hashingAlgorithms)) {
            throw new Exception("Invalid hashing algorithm specified");
        }
        $cacheKey = md5($password . $algorithm);

        if (isset(self::$cache[$cacheKey])) {
            return self::$cache[$cacheKey];
        }

        lock(self::$lock[$cacheKey]); // Use a simple lock here for demonstration purposes
        $hashedPassword = password_hash($password, $algorithm);
        unlock(self::$lock[$cacheKey]);

        if (isset(self::$cache[$cacheKey])) {
            self::$cache[$cacheKey] = $hashedPassword;
        }

        logOperation("Hashed password using algorithm '{$algorithm}'");

        return $hashedPassword;
    }

    private static function logOperation($message) {
        if (!self::$logFile) {
            return;
        }
        file_put_contents(self::$logFile, $message . "\n", FILE_APPEND);
    }

    private static function lock($key) {
        global $lock;
        while (true) {
            if (!isset(self::$lock[$key])) {
                self::$lock[$key] = Semaphore::create();
                break;
            }
            usleep(1000 * rand(0, 10)); // Adjust the sleep interval as needed for concurrency control
        }
    }

    private static function unlock($key) {
        global $lock;
        if (isset(self::$lock[$key])) {
            self::$lock[$key]->release();
            unset(self::$lock[$key]);
        }
    }
}
```

