#define MAX_CACHE_SIZE (10 * 1024 * 1024) // 10MB max cache size
#define EXPONENTIAL_BACKOFF_BASE 1000
#define CIRCUIT_BREAKER_THRESHOLD 5

typedef enum { JSON, XML, BINARY } DataFormat;

struct CacheEntry {
    time_t last_access;
    void *data;
    size_t data_size;
    DataFormat format;
};

struct ConfigService {
    const char *host;
    int port;
    struct sockaddr_in addr;
    int socket;
};

struct Cache {
    struct CacheEntry *entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
};

void cache_init(struct Cache *cache, size_t capacity) {
    cache->capacity = capacity;
    cache->count = 0;
    cache->entries = malloc(capacity * sizeof(struct CacheEntry));
    memset(cache->entries, 0, capacity * sizeof(struct CacheEntry));
    pthread_mutex_init(&cache->lock, NULL);
}

void cache_destroy(struct Cache *cache) {
    if (cache == NULL || cache->entries == NULL) return;
    free(cache->entries);
    pthread_mutex_destroy(&cache->lock);
}

struct CacheEntry *cache_get(struct Cache *cache, const char *key, DataFormat format) {
    struct CacheEntry *entry = NULL;
    time_t current_time = time(NULL);

    pthread_mutex_lock(&cache->lock);
    for (size_t i = 0; i < cache->count; ++i) {
        if (strcmp(key, cache->entries[i].data) == 0 && cache->entries[i].format == format) {
            entry = &cache->entries[i];
            entry->last_access = current_time;
            break;
        }
    }
    pthread_mutex_unlock(&cache->lock);

    if (entry == NULL || cache->count >= cache->capacity) {
        // Evict least recently used entry if cache is full or cache entry not found
        size_t LRU_index = 0;
        time_t LRU_time = current_time;
        for (size_t i = 0; i < cache->count; ++i) {
            if (cache->entries[i].last_access > LRU_time) {
                LRU_index = i;
                LRU_time = cache->entries[i].last_access;
            }
        }
        pthread_mutex_lock(&cache->lock);
        if (LRU_index < cache->count && strcmp(key, cache->entries[LRU_index].data) != 0) { // Avoid evicting the requested key if it's the LRU entry
            free(cache->entries[LRU_index].data);
            --cache->count;
        }
        pthread_mutex_unlock(&cache->lock);
    }

    if (entry == NULL) { // Load from config service if cache miss
        // Implement the logic to fetch data from external configuration service and populate entry here
        // Don't forget to update the last_access field in the CacheEntry
    }

    return entry;
}

