#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdlib.h>
#include <pthread.h>
#include <openssl/md5.h>
#include <time.h>
#include <sys/mman.h>
#include <xmlparser/tinyxml2.cpp>

typedef struct {
    char* path;
    int fd;
    size_t pos;
    pthread_mutex_t lock;
} file_data;

static int num_threads = 4;
static long tile_size = 1024 * 64;
static long world_width = 1024;
static long world_height = 1024;
static float camera_speed = 1.0f;

void* read_file(void* data) {
    file_data* fdata = static_cast<file_data*>(data);
    char* buffer = mmap(NULL, tile_size, PROT_READ, MAP_PRIVATE, fdata->fd, fdata->pos);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        exit(1);
    }
    // Process the buffer and update fdata->pos accordingly
    munmap(buffer, tile_size);
    pthread_mutex_unlock(&fdata->lock);
    close(fdata->fd);
    free(fdata);
    return NULL;
}

unsigned char* compute_md5(char* data, size_t len) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, data, len);
    MD5_Final(digest, &ctx);
    return digest;
}

void process_files(char** paths, int num_paths) {
    file_data* files[num_paths];
    for (int i = 0; i < num_paths; ++i) {
        struct stat st;
        if (lstat(paths[i], &st) == -1) continue;
        if (!S_ISREG(st.st_mode)) continue;
        if (st.st_size > 1024 * 1024) continue;
        files[num_files++] = malloc(sizeof(file_data));
        files[num_files - 1]->path = strdup(paths[i]);
        files[num_files - 1]->fd = open(paths[i], O_RDONLY);
        if (files[num_files - 1]->fd == -1) continue;
        files[num_files - 1]->pos = 0;
        pthread_mutex_init(&files[num_files - 1]->lock, NULL);
    }

    pthread_t threads[num_threads];
    for (int i = 0; i < num_threads && num_files > 0; ++i) {
        if (pthread_create(&threads[i], NULL, read_file, files[--num_files])) {
            break;
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }
}
