    mac_frame_pdu->creation_time = time(NULL);
    mac_frame_pdu->packets = NULL;
    mac_frame_pdu->log = log;
}

void resize_packet_buffer(MAC_STREAM_INFO** packets, unsigned int new_size) {
    MAC_STREAM_INFO* new_buff = realloc(*packets, new_size * sizeof(MAC_STREAM_INFO));
    if (!new_buff) {
        // Handle allocation failure here, e.g., by logging an error and returning early.
    }
    *packets = new_buff;
}

void add_packet(MAC_FRAME_PDU_T* mac_frame_pdu, MAC_STREAM_INFO packet) {
    unsigned int current_size = mac_frame_pdu->packets ? sizeof(*mac_frame_pdu->packets) / sizeof(MAC_STREAM_INFO) : 0;
    if (current_size >= mac_frame_pdu->buffer_size) {
        resize_packet_buffer(mac_frame_pdu->packets, current_size + 1);
    }
    mac_frame_pdu->packets[current_size] = packet;
    mac_frame_pdu->total_transmitted_bytes += packet.size;
    mac_frame_pdu->total_packets++;
    if (mac_frame_pdu->total_packets == 1) {
        mac_frame_pdu->average_packet_size = (double)mac_frame_pdu->total_transmitted_bytes / mac_frame_pdu->total_packets;
    } else {
        mac_frame_pdu->average_packet_size = (mac_frame_pdu->total_transmitted_bytes - mac_frame_pdu->old_transmitted_bytes) / (mac_frame_pdu->total_packets - mac_frame_pdu->old_num_packets);
        mac_frame_pdu->old_transmitted_bytes = mac_frame_pdu->total_transmitted_bytes;
        mac_frame_pdu->old_num_packets = mac_frame_pdu->total_packets;
    }
}

