    public double DefaultMinValue { get; set; } = 0.0;
    public double DefaultMaxValue { get; set; } = 1.0;
    public double SamplingFrequency { get; set; } = 1.0;
    public string SettingsFile { get; set; }

    public FileHashGenerator()
    {
        _ranges = new Dictionary<string, Range>();
        _random = new Random();
    }

    public void LoadRangesFromFile()
    {
        if (string.IsNullOrEmpty(SettingsFile)) throw new InvalidOperationException("Settings file path is not set.");

        var serializer = new JsonSerializer();
        using (var reader = new StreamReader(SettingsFile))
            _ranges = serializer.Deserialize<Dictionary<string, Range>>(reader);
    }

    public void SaveRangesToFile()
    {
        if (string.IsNullOrEmpty(SettingsFile)) throw new InvalidOperationException("Settings file path is not set.");

        var serializer = new JsonSerializer();
        using (var writer = new StreamWriter(SettingsFile))
            serializer.Serialize(writer, _ranges);
    }

    public void AddRange(string key, double min, double max)
    {
        if (min > max) throw new ArgumentException("Minimum value must be less than or equal to the maximum value.");
        _ranges[key] = new Range { Min = min, Max = max };
    }

    public double GenerateValue(string key)
    {
        if (_ranges.TryGetValue(key, out var range))
            return range.Min + (_random.NextDouble() * (range.Max - range.Min));
        throw new KeyNotFoundException($"Range with key '{key}' not found.");
    }
}

public async Task<Tuple<string, string>> CalculateMD5Hash(string filePath, int chunkSize = 1024 * 1024, int maxConcurrentThreads = 4, string tempDir = null)
{
    if (string.IsNullOrEmpty(filePath)) throw new ArgumentNullException(nameof(filePath));

    tempDir = tempDir ?? Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData) + @"\TempHashCalculations";
    Directory.CreateDirectory(tempDir);

    var md5 = MD5.Create();
    using (var fileStream = File.OpenRead(filePath))
    {
        var chunkTaskSource = new CancellationTokenSource();
        var tasks = Enumerable.Range(0, maxConcurrentThreads)
            .Select(i => Task.Run(() => CalculateMD5HashChunkAsync(md5, fileStream, chunkSize, chunkTaskSource.Token)))
            .ToList();

        await Task.WhenAll(tasks);
        chunkTaskSource.Cancel();
    }

    using (var ms = new MemoryStream())
    {
        md5.ComputeHash(ms);
        return Tuple.Create(BitConverter.ToString(ms.ToArray()).Replace("-", "").ToLowerInvariant(), null);
    }
}

private async Task CalculateMD5HashChunkAsync(MD5 md5, Stream fileStream, int chunkSize, CancellationToken cancellationToken)
{
    var buffer = new byte[chunkSize];
    while (true)
    {
        int read;
        try
        {
            read = await fileStream.ReadAsync(buffer, 0, buffer.Length);
        }
        catch (OperationCanceledException)
        {
            return;
        }
        if (read <= 0) break;
        md5.TransformBlock(buffer, 0, read, _ , _);
    }
    md5.TransformFinalBlock(_ , 0, 0);
}
