import java.io.File;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;

public class PduGenerator {
    private static final int MAX_FILE_SIZE = 1048576; // 1 MB in bytes
    private static final String MD5_ALGORITHM = "MD5";

    public Map<String, String> processFilePathsAndGeneratePduList(List<String> filePaths) {
        Map<String, String> hashMap = new HashMap<>();
        if (filePaths == null || filePaths.isEmpty()) {
            return hashMap;
        }

        for (String filePath : filePaths) {
            if (!isValidStringSize(filePath, MAX_FILE_SIZE)) {
                continue;
            }

            File file = new File(filePath);
            if (!file.exists() || !file.isFile()) {
                System.err.println("Invalid file: " + filePath);
                continue;
            }

            if (file.length() > MAX_FILE_SIZE) {
                System.err.println("File size exceeds limit: " + filePath);
                continue;
            }

            try {
                MessageDigest messageDigest = MessageDigest.getInstance(MD5_ALGORITHM);
                byte[] hashBytes = messageDigest.digest(file.toPath().toByteArray());
                BigInteger bigIntHash = new BigInteger(1, hashBytes);
                String md5Hex = bigIntHash.toString(16);

                hashMap.put(filePath, md5Hex);
            } catch (Exception e) {
                System.err.println("Error computing MD5 for file: " + filePath + ", error: " + e.getMessage());
            }
        }

        return hashMap;
    }

    private static boolean isValidStringSize(String str, int limit) {
        if (str == null || str.length() > limit) {
            return false;
        }
        return true;
    }

    public List<NFAPI_CRC_INDICATION_PDU_T> generatePduList(Map<String, String> hashes) {
        List<NFAPI_CRC_INDICATION_PDU_T> pduList = new ArrayList<>();
        Random random = new Random();

        for (Map.Entry<String, String> entry : hashes.entrySet()) {
            NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
            pdu.RX_UE_INFORMATION_TAG = "RX_UE_INFO";
            pdu.RNTI = Long.valueOf(Math.abs(random.nextLong()));
            pdu.CRC_INDICATION_REL8_TAG.CRCFLAG = (random.nextBoolean()) ? 1 : 0;
            pdu.CRC_INDICATION_REL8_TAG.CRC32 = "0x" + Long.toHexString(entry.getValue().hashCode());

            pduList.add(pdu);
        }

        return pduList;
    }

    public static class NFAPI_CRC_INDICATION_PDU_T {
        public String RX_UE_INFORMATION_TAG;
        public long RNTI;
        public CRC_INDICATION_REL8_TAG_T CRC_INDICATION_REL8_TAG = new CRC_INDICATION_REL8_TAG_T();
    }

