import java.io.File;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class PduGenerator {

    private static final int MAX_FILE_SIZE = 1048576; // 1 MB in bytes
    private static final int NUM_THREADS = Runtime.getRuntime().availableProcessors();

    public static Map<String, String> processFilePathsAndGeneratePduList(List<String> filePaths) {
        if (filePaths == null || filePaths.isEmpty()) return new HashMap<>();

        Map<String, String> fileHashes = new ConcurrentHashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool(NUM_THREADS);

        for (String filePath : filePaths) {
            if (!isValidStringSize(filePath, MAX_FILE_SIZE)) continue;
            File file = new File(filePath);
            if (!file.exists() || !file.isFile()) continue;
            if (file.length() > MAX_FILE_SIZE) throw new IllegalArgumentException("File size exceeds the maximum allowed limit");

            executor.submit(() -> {
                try {
                    MessageDigest md = MessageDigest.getInstance("MD5");
                    md.reset();
                    byte[] fileContent = new byte[(int) file.length()];
                    FileInputStream fis = new FileInputStream(file);
                    fis.read(fileContent);
                    fis.close();
                    md.update(fileContent);

                    String hashValue = new BigInteger(1, md.digest()).toString(16);
                    while (hashValue.length() < 32) {
                        hashValue = "0" + hashValue;
                    }
                    fileHashes.put(filePath, hashValue);
                } catch (Exception e) {
                    System.err.println("Error processing file: " + filePath + ", Error message: " + e.getMessage());
                }
            });
        }
        executor.shutdown();
        while (!executor.isTerminated()) {}

        return generatePduList(fileHashes);
    }

    private static boolean isValidStringSize(String str, int limit) {
        if (str == null || str.length() > limit) return false;
        return true;
    }

    private static List<NFAPI_CRC_INDICATION_PDU_T> generatePduList(Map<String, String> fileHashes) {
        List<NFAPI_CRC_INDICATION_PDU_T> pduList = new ArrayList<>();

        for (int i = 0; i < fileHashes.size(); ++i) {
            NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
            pdu.RX_UE_INFORMATION_TAG = i + 1;
            pdu.RNTI = (byte) (i % 256);
            pdu.CRC_INDICATION_REL8_TAG = new byte[4]; // CRC flag is randomly set here
            pdu.CRC_INDICATION_REL8_TAG[(int) (Math.random() * pdu.CRC_INDICATION_REL8_TAG.length)] = (byte) (i % 256);
            pdu.CRCFLAG = (i + 1) % 2 == 0 ? true : false;
            pduList.add(pdu);
        }

        return pduList;
    }

    // Define NFAPI_CRC_INDICATION_PDU_T structure here...
}
