import java.io.*;
import java.math.BigInteger;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import org.apache.commons.io.FileUtils;

public class PduGenerator {

    private static final int MAX_FILE_SIZE = 1048576; // 1 MB in bytes
    private static final String[] VALID_EXTENSIONS = {"txt", "csv", "log"};
    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private static final ConcurrentHashMap<String, Boolean> crcFlags = new ConcurrentHashMap<>();

    public static Map<String, String> processFilePathsAndGeneratePduList(List<String> filePaths) {
        Map<String, String> fileHashes = new HashMap<>();
        for (String filePath : filePaths) {
            if (filePath == null || !isValidStringSize(filePath, MAX_FILE_SIZE)) continue;
            Path path = Paths.get(filePath);
            try {
                if (!Files.exists(path) || !Files.isReadable(path)) continue;
                String extension = path.toFile().getName().toLowerCase().substring(path.toFile().getName().lastIndexOf('.'));
                if (!Arrays.asList(VALID_EXTENSIONS).contains(extension)) continue;
                byte[] hashBytes = getMd5Hash(Files.readAllBytes(path));
                fileHashes.put(filePath, new BigInteger(1, hashBytes).toString(16));
            } catch (IOException | NoSuchAlgorithmException e) {
                Logger.getLogger(PduGenerator.class.getName()).log(Level.SEVERE, "Error processing file: {0}", filePath);
            }
        }

        List<NFAPI_CRC_INDICATION_PDU_T> pduList = new ArrayList<>();
        for (Map.Entry<String, String> entry : fileHashes.entrySet()) {
            RX_UE_INFORMATION_TAG rxInfoTag = new RX_UE_INFORMATION_TAG();
            // Set relevant fields of RX_UE_INFORMATION_TAG based on requirements not provided
            NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T(rxInfoTag, new RNTI(), getCrcIndicationTag());
            // Set relevant fields of NFAPI_CRC_INDICATION_PDU_T based on requirements not provided
            pduList.add(pdu);
        }

        return fileHashes;
    }

    private static boolean isValidStringSize(String str, int maxSize) {
        if (str == null || str.isEmpty()) return false;
        return str.length() <= maxSize;
    }

    private static byte[] getMd5Hash(byte[] data) throws NoSuchAlgorithmException {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        digest.update(data);
        return digest.digest();
    }

    private static CRC_INDICATION_REL8_TAG getCrcIndicationTag() {
        Boolean crcFlag = crcFlags.getAndUpdate((k) -> !k ? true : false); // Toggle the flag value
        return new CRC_INDICATION_REL8_TAG(crcFlag);
    }
}
```

