import java.util.concurrent.*;
import java.util.regex.Pattern;

public class Processor {
    private static final int MAX_FILE_SIZE = 1048576; // 1 MB in bytes
    private static final Pattern VALID_EXTENSIONS = Pattern.compile("\\.(txt|csv|log)$");

    public Map<String, String> processFilePathsAndGeneratePduList(List<String> filePaths) {
        Map<String, String> hashMap = new HashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        List<Callable<Pair<String, Boolean>>> tasks = new ArrayList<>();
        for (String filePath : filePaths) {
            if (filePath == null || !isValidStringSize(filePath, MAX_FILE_SIZE)) continue;
            tasks.add(() -> Pair.of(filePath, isValidFile(filePath)));
        }

        try {
            List<Future<Pair<String, Boolean>>> results = executor.invokeAll(tasks);
            for (Future<Pair<String, Boolean>> result : results) {
                if (result.get().getSecond()) {
                    byte[] md5HashBytes = computeMD5(result.get().getFirst());
                    hashMap.put(result.get().getFirst(), new BigInteger(1, md5HashBytes).toString(16));
                }
            }
        } catch (InterruptedException | ExecutionException e) {
            logError(e);
        } finally {
            executor.shutdown();
        }

        // Generate PDU list here using hashMap and other necessary data structures/functions

        return hashMap;
    }

    private boolean isValidStringSize(String str, int maxSize) {
        if (str == null || str.length() > maxSize) return false;
        return str.endsWith("/") || str.length() <= maxSize - 1;
    }

    private boolean isValidFile(String filePath) {
        File file = new File(filePath);
        if (!file.exists() || !file.isFile()) return false;
        if (filePath.length() > MAX_FILE_SIZE) return false;
        if (!VALID_EXTENSIONS.matcher(file.getName()).matches()) return false;
        try {
            Files.probeContentType(Paths.get(filePath)); // Throws DataStorageException if file does not exist or is not readable
        } catch (IOException e) {
            logError(e);
            return false;
        }
        return true;
    }

    private byte[] computeMD5(String filePath) {
        try (FileInputStream fis = new FileInputStream(filePath);
             MessageDigest md = MessageDigest.getInstance("MD5")) {
            byte[] buffer = new byte[1024];
            int bytesRead;
            while ((bytesRead = fis.read(buffer)) != -1) {
                md.update(buffer, 0, bytesRead);
            }
            return md.digest();
        } catch (IOException | NoSuchAlgorithmException e) {
            logError(e);
            throw new RuntimeException(e);
        }
    }

    private void logError(Throwable t) {
        // Log the error to your preferred logging service here
    }
}
