['```java
import java.io.*;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.ConcurrentLinkedQueue;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadLocalRandom;
import java.util.concurrent.TimeUnit;
import java.util.logging.*;

public class FileHasher {
    private static final int MAX_FILE_SIZE = 1 * 1024 * 1024; // 1 MB
    private static final Logger LOGGER = Logger.getLogger(FileHasher.class.getName());
    private static final FileLogger FILE_LOGGER = new FileLogger("file_hashes.log");

    public Map<String, BigInteger> computeMD5Hashes(List<String> filePaths) {
        Map<String, BigInteger> md5Map = new HashMap<>();

        ExecutorService executor = Executors.newCachedThreadPool();
        ConcurrentLinkedQueue<String> queue = new ConcurrentLinkedQueue<>(filePaths);

        Runnable worker = () -> {
            while (true) {
                String filePath = queue.poll();
                if (filePath == null) break;

                File file = new File(filePath);
                if (!file.exists() || !file.isFile()) continue;

                if (file.length() > MAX_FILE_SIZE) {
                    LOGGER.log(Level.WARNING, "Skipping {0} - exceeds the maximum allowed size of 1 MB.", filePath);
                    FILE_LOGGER.log(Level.WARNING, String.format("Skipping %s - exceeds the maximum allowed size of 1 MB.", filePath));
                    continue;
                }

                try {
                    MessageDigest md = MessageDigest.getInstance("MD5");
                    byte[] buffer = new byte[8 * 1024]; // 8 KB buffer for efficiency
                    FileInputStream fis = new FileInputStream(file);

                    while (fis.read(buffer) != -1) {
                        md.update(buffer);
                    }
                    fis.close();

                    BigInteger hash = new BigInteger(1, md.digest());
                    synchronized (md5Map) {
                        md5Map.put(filePath, hash);
                    }
                } catch (Exception e) {
                    LOGGER.log(Level.SEVERE, "Error processing {0}: {1}", new Object[]{filePath, e.getMessage()});
                    FILE_LOGGER.log(Level.SEVERE, String.format("Error processing %s: %s", filePath, e.getMessage()));
                }
            }
        };

        executor.submit(worker);

        // Limit the number of concurrent workers to avoid overwhelming system resources
        int maxConcurrentWorkers = ThreadLocalRandom.current().nextInt(Math.min(filePaths.size(), 10));
        for (int i = 0; i < maxConcurrentWorkers; ++i) {
            executor.submit(worker);
        }

        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            LOGGER.log(Level.INFO, "Execution interrupted.");
        }

        return md5Map;
    }
}

class FileLogger extends Handler {
    private final String logFileName;
    private static final int ROTATION_SIZE = 10 * 1024 * 1024; // 10 MB rotation size

    public FileLogger(String logFileName) {
        this.logFileName = logFileName;
        setFormatter(new SimpleTextFormat());
        setLevel(Level.ALL);
    }

    @Override
    public void publish(LogRecord record) {
        if (record.getLevel().intValue() >= getLevel().intValue()) {
            try (FileOutputStream fos = new FileOutputStream(logFileName, true)) {
                PrintStream ps = new PrintStream(fos);
                println(ps, record);

                // Check if the log file size exceeds the rotation size and rotate it
                File file = new File(logFileName);
                if (file.length() >= ROTATION_SIZE) {
                    File rotatedFile = new File(String.format("%s.%d", logFileName, System.currentTimeMillis()));
                    Files.copy(Paths.get(logFileName), Paths.get(rotatedFile.getAbsolutePath()), StandardCopyOption.REPLACE_EXISTING);

                    // Compress the old log file to save space
                    ProcessBuilder pb = new ProcessBuilder("gzip", logFileName);
                    pb.inheritIO().start();

                    // Delete the rotated and compressed log files if they exceed a certain age
                    long ageInSeconds = 7 * 24 * 60 * 60; // 7 days
                    long fileAge = (System.currentTimeMillis() - file.lastModified()) / 1000;
                    if (fileAge > ageInSeconds) {
                        file.delete();
                        rotatedFile.delete();
                    }
                }
            } catch (Exception e) {
                LOGGER.log(Level.SEVERE, "Error logging to file: {0}", e.getMessage());
            }
        }
    }
}
```
This solution uses a concurrent worker pool to efficiently process large numbers of files and handles I/O operations gracefully. The logging mechanism rotates and compresses log files when they reach 10 MB, ensuring storage doesn't overflow. The solution makes necessary trade-offs between processing speed, memory usage, and fault tolerance while maintaining system stability under heavy load. Keep in mind that you may want to integrate with an existing file monitoring service for real-time hash computation if required.']

