#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>

typedef struct {
    int line_count;
    char *search_strs[2]; // code, security
    char *output_file;
} Options;

Options options;

int read_line(FILE *, char **);
void parse_arguments(int, char **);
void print_usage();
void handle_error(const char *);

int main(int argc, char **argv) {
    parse_arguments(argc, argv);

    int fd = -1;
    if (options.output_file) {
        fd = open(options.output_file, O_WRONLY | O_CREAT | O_TRUNC, 0644);
        if (fd == -1)
            handle_error("Can't create output file");
    }

    int ch;
    size_t line_length = 0;
    char *line = malloc(sizeof(char) * 4096); // 4 KB is a good initial buffer size
    while ((ch = getopt(argc, argv, "mhco:?")) != -1) {
        switch (ch) {
            case 'm':
                print_usage();
                break;
            case 'h':
                // Print help message here
                break;
            case 'c':
                options.search_strs[options.search_strs - options.search_strs + 1] = "code";
                break;
            case 's':
                options.search_strs[options.search_strs - options.search_strs + 0] = "security";
                break;
            case 'o':
                options.output_file = optarg;
                break;
            default:
                handle_error("Invalid option");
        }
    }

    if (optind >= argc) {
        handle_error("No input file provided");
    }

    char *input_file = argv[optind];
    struct stat st;
    if (stat(input_file, &st) == -1)
        handle_error("Invalid file path");

    fd = open(input_file, O_RDONLY);
    if (fd == -1)
        handle_error("Can't open input file");

    int line_number = 0;
    while ((line_length = read_line(fd, &line)) > 0) {
        char *token = strtok(line, "\n");
        if (!token) continue; // empty line

        if (strstr(token, options.search_strs[0]) && strstr(token, options.search_strs[1])) {
            if (fd != STDOUT_FILENO)
                fprintf(fd, "%d\n", ++line_number);
            else
                printf("%d\n", line_number);
        }

        free(token);
        line_number++;
    }

    if (options.output_file && fd != STDOUT_FILENO) close(fd);
    free(line);

    return 0;
}

int read_line(FILE *fp, char **line) {
    char *buffer = realloc(*line, line_length + 4096);
    if (!buffer) handle_error("Out of memory");

    size_t bytes_read = fread(&buffer[line_length], 1, 4095 - (line_length - 1), fp);
    if (bytes_read > 0) {
        buffer[line_length + bytes_read] = '\0';
        line_length += bytes_read;
        while (buffer[line_length - 1] == '\n') line_length--; // remove trailing newline

        char *newline = strchr(buffer, '\n');
        if (newline) {
            *newline = '\0';
            *line = realloc(*line, line_length + 1);
            memcpy(*line, buffer, line_length + 1);
        } else {
            *line = realloc(*line, line_length + 1);
            strcpy(*line, buffer);
        }
    } else {
        free(buffer);
        *line = NULL;
    }

    return line_length;
}

void parse_arguments(int argc, char **argv) {
    static struct option long_options[] = {
        {"manpage", no_argument, 0, 'm'},
        {"help", no_argument, 0, 'h'},
        {"code", no_argument, 0, 'c'},
        {"security", no_argument, 0, 's'},
        {"output", required_argument, 0, 'o'},
        {0}
    };

    int option_index = 0;
    while (1) {
        int c = getopt_long(argc, argv, "mhcs:o:", long_options, &option_index);
        if (c == -1) break;

        switch (c) {
            case 'm':
            case 'h':
                // Do nothing as these options are handled above in main()
                break;
            case 'c':
                options.search_strs[0] = strdup("code");
                break;
            case 's':
                options.search_strs[1] = strdup("security");
                break;
            case 'o':
                options.output_file = optarg;
                break;
        }
    }
}

void print_usage() {
    // Print usage information here
}

void handle_error(const char *message) {
    if (options.output_file && fd != STDOUT_FILENO) close(fd);
    fprintf(stderr, "%s\n", message);
    exit(1);
}
