int main(int argc, char **argv) {
    const int max_args = 10000;
    char **args = malloc(max_args * sizeof(char*));
    int arg_index = 0;
    int c;
    FILE *input_file = NULL;
    FILE *output_file = stdout;
    size_t max_lines = ~0ULL;
    char file_type = 't'; // default to text file
    bool print_manpage = false, print_cs_lines = false;

    static struct option long_options[] = {
        {"manpage", no_argument, NULL, 'h'},
        {"output", required_argument, NULL, 'o'},
        {"max-lines", required_argument, NULL, 'l'},
        {"file-type", required_argument, NULL, 'f'},
        {NULL, 0, NULL, 0}
    };

    while ((c = getopt_long(argc, argv, "h:o:l:f:", long_options, NULL)) != -1) {
        switch (c) {
            case 'h':
                print_manpage = true;
                break;
            case 'o':
                if ((output_file = fopen(optarg, "w")) == NULL) {
                    fprintf(stderr, "Error: Invalid output file path.\n");
                    return 1;
                }
                break;
            case 'l':
                max_lines = (size_t)strtoull(optarg, NULL, 10);
                if (max_lines > ~0ULL / 2) { // to avoid integer overflow
                    fprintf(stderr, "Error: Max lines limit exceeded.\n");
                    return 1;
                }
                break;
            case 'f':
                file_type = optarg[0];
                if (file_type != 't' && file_type != 'c' && file_type != 'j') { // assume CSV, JSON, or plain text
                    fprintf(stderr, "Error: Unsupported file type.\n");
                    return 1;
                }
                break;
            default:
                print_manpage = true;
        }
        args[arg_index++] = argv[optind - 1]; // store the argument before option in args array
    }

    if (print_manpage || arg_index < 2) {
        printf("Usage: program [options] input_file\n");
        printf("Options:\n");
        printf("-h, --manpage          Print detailed usage instructions.\n");
        printf("-o <output_file>       Redirect output to the specified file instead of stdout.\n");
        printf("-l <max_lines>         Limit the number of lines to process from the input file to the specified value.\n");
        printf("-f <file_type>         Specify the type of file (e.g., plain text, CSV, JSON), and adjust parsing logic accordingly.\n");
        return 0;
    }

    input_file = fopen(args[arg_index - 1], "r");
    if (!input_file) {
        fprintf(stderr, "Error: Invalid input file path.\n");
        return 1;
    }

    size_t line_count = 0, total_chars = 0, avg_len = 0;
    char line[4096];

    while (fgets(line, sizeof(line), input_file) && fgetpos(input_file, &pos) && (max_lines == ~0ULL || line_count < max_lines)) {
        size_t len = strlen(line);
        total_chars += len;
        if (print_cs_lines && !(strstr(line, "code") || strstr(line, "security"))) continue;
        line_count++;
        avg_len = (avg_len * line_count + len) / ++line_count;
    }

    if (output_file != stdout) {
        fprintf(output_file, "Lines: %zu\n", line_count);
        fprintf(output_file, "Average Line Length: %.2f\n", avg_len);
        fprintf(output_file, "Total Characters: %zu\n", total_chars);
    } else {
        printf("Lines: %zu\n", line_count);
        printf("Average Line Length: %.2f\n", avg_len);
        printf("Total Characters: %zu\n", total_chars);
    }

    fclose(input_file);
