import java.io.*;
import java.math.BigInteger;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.concurrent.*;
import javax.json.*;
import org.apache.commons.io.FileUtils;
import org.apache.commons.validator.rfc822.DataLengthValidator;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

public class FileProcessor {

    private static final int MAX_FILE_SIZE = 1048576; // 1 MB
    private static final String JSON_SCHEMA_PATTERN = ".json$";
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();

    public Map<String, String> processFilePathsAndGeneratePduList(List<String> filePaths, String jsonSchemaPattern) throws IOException {
        Map<String, String> md5Hashes = new HashMap<>();
        ExecutorService executor = Executors.newCachedThreadPool();

        DataLengthValidator validator = new DataLengthValidator(MAX_FILE_SIZE);
        Function<String, Boolean> isValidPath = path -> Files.exists(Paths.get(path)) && validator.isValid(FileUtils.readFileToString(new File(path), "UTF-8"));

        Predicate<String> hasJsonSchema = path -> path.matches(jsonSchemaPattern) && isValidJsonSchema(path);

        Callable<Map.Entry<String, String>> fileProcessor = path -> {
            if (!isValidPath.apply(path)) {
                logSkippedFile(path);
                return null;
            }
            try {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] messageDigest = md.digest(Files.readAllBytes(Paths.get(path)));
                BigInteger no = new BigInteger(1, messageDigest);
                String hashedFilePath = path + (isValidStringSize(path, 260) ? "/" : null);
                md5Hashes.put(hashedFilePath, no.toString(16));
                return new AbstractMap.SimpleEntry<>(hashedFilePath, no.toString(16));
            } catch (Exception e) {
                logError(e, path);
                return null;
            }
        };

        List<Callable<Map.Entry<String, String>>> tasks = filePaths.stream().filter(hasJsonSchema).map(fileProcessor).collect(Collectors.toList());
        try {
            List<Future<Map.Entry<String, String>>>) results = executor.invokeAll(tasks);
            for (Future<Map.Entry<String, String>> result : results) {
                if (result.isDone()) {
                    Map.Entry<String, String> entry = result.get();
                    if (entry != null) {
                        md5Hashes.put(entry.getKey(), entry.getValue());
                    }
                }
            }
        } finally {
            executor.shutdown();
        }

        // Generate PDU List...
    }

    private boolean isValidJsonSchema(String path) throws IOException {
        try (InputStream is = new FileInputStream(path)) {
            JsonNode jsonNode = OBJECT_MAPPER.readTree(is);
            return OBJECT_MAPPER.treeAsFlatNoUnknown()
                .validateAgainst(JsonSchemaFactory.instance().getJsonSchema(new File("json-schema.json")).get(), true)
                .as(JsonMappingException.class) == null;
        } catch (JsonMappingException ex) {
            logSkippedFile(path, "Invalid JSON schema.");
            return false;
        }
    }

    private String isValidStringSize(String s, int maxLength) {
        if (s != null && s.length() <= maxLength) {
            return s + "/";
        } else {
            return null;
        }
    }

    private void logSkippedFile(String path, String message) {
        System.err.printf("Skipping file %s due to: %s%n", path, message);
    }

    private void logError(Exception e, String path) {
        System.err.printf("Error processing file %s: %s%n", path, e.getMessage());
        e.printStackTrace();
    }
}
