double calculate_balancing_factor(double current_load, double smoothing_factor);

void process_traffic_statistics(TRAFFIC_STATISTICS_PDU_T *traffic_stats_buffer, uint32_t N) {
    TRAFFIC_STATISTICS_PDU_T *current_pdu;

    // Allocate memory for the array of traffic_stats_buffer structures
    current_pdu = (TRAFFIC_STATISTICS_PDU_T *)malloc(N * sizeof(TRAFFIC_STATISTICS_PDU_T));

    if (!current_pdu) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (uint32_t i = 0; i < N; ++i) {
        current_pdu[i].cell_info.id = i + 1; // Set cell ID for each structure

        if ((current_pdu[i].cell_id > UINT32_MAX / 2) || (current_pdu[i].cell_id < 1)) {
            fprintf(stderr, "Invalid CELL_ID value: %u\n", current_pdu[i].cell_id);
            continue;
        }

        current_pdu[i].node_status = get_node_status(current_pdu[i].cell_id); // Retrieve node status data
        current_pdu[i].calculate_balancing_factor = calculate_balancing_factor; // Assign function pointer

        // Initialize other fields with zero or appropriate default values
        current_pdu[i].load = 0.0;
        current_pdu[i].historical_load = 0.0;
    }

    // Loop through traffic_stats_buffer and calculate balancing factors
    for (uint32_t i = 0; i < N; ++i) {
        if (current_pdu[i].node_status.metrics[0] > 0.0) {
            current_pdu[i].load = current_pdu[i].node_status.metrics[0]; // Update current traffic load
            current_pdu[i].historical_load += current_pdu[i].load * (1 / N); // Update historical traffic load with smoothed value
            current_pdu[i].calculate_balancing_factor(current_pdu[i].load, 0.5); // Calculate balancing factor using given function and smoothing factor
        }
    }

    free(current_pdu); // Deallocate memory when done
}
