import java.io.*;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.ConcurrentHashMap;
import java.util.Map;
import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class MD5Hasher {
    private static final Logger log = LoggerFactory.getLogger(MD5Hasher.class);
    private static final int THREAD_POOL_SIZE = Integer.parseInt(System.getProperty("md5.threads", "10"));
    private static final ConcurrentHashMap<String, BigInteger> cache = new ConcurrentHashMap<>();

    public static Map<String, BigInteger> computeMD5Hashes(List<String> filePaths) {
        ExecutorService executor = Executors.newFixedThreadPool(THREAD_POOL_SIZE);
        Map<String, Future<BigInteger>> tasks = new ConcurrentHashMap<>();
        Map<String, BigInteger> results = new ConcurrentHashMap<>();

        for (String filePath : filePaths) {
            if (filePath == null || !Files.exists(Paths.get(filePath)) || !Files.isReadable(Paths.get(filePath)) || Files.size(Paths.get(filePath)) > 1_000_000) {
                log.error("File {} is not valid or exceeds 1 MB in size.", filePath);
                continue;
            }

            Future<BigInteger> task = executor.submit(() -> computeMD5(filePath));
            tasks.put(filePath, task);
        }

        for (Map.Entry<String, Future<BigInteger>> entry : tasks.entrySet()) {
            try {
                BigInteger hash = entry.getValue().get();
                results.put(entry.getKey(), hash);
                cache.putIfAbsent(entry.getKey(), hash);
            } catch (Exception e) {
                log.error("Error computing MD5 for {}", entry.getKey(), e);
            }
        }

        executor.shutdown();
        return results;
    }

    private static BigInteger computeMD5(String filePath) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] buffer = new byte[8192];
            FileInputStream fis = new FileInputStream(filePath);

            while (fis.read(buffer) != -1) {
                md.update(buffer);
            }

            return new BigInteger(1, md.digest());
        } catch (Exception e) {
            throw new RuntimeException("Error computing MD5 for " + filePath, e);
        }
    }
}
```

