        if (parsedUrl.openConnection().getContentLength() <= maxSize) {
            // Append query parameter to the URL if it meets the criteria
            StringBuilder builder = new StringBuilder(url);
            int queryIndex = url.indexOf('?');
            if (queryIndex == -1) {
                builder.append("?sizeCheck=true");
            } else {
                builder.append("&sizeCheck=true");
            }
            return builder.toString();
        }
        return null;
    }

    private static String computeSHA256(URL url) throws IOException {
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");
        try (InputStream is = url.openStream()) {
            ByteBuffer buffer = ByteBuffer.allocate(1024);
            int bytesRead;
            while ((bytesRead = is.read(buffer.array())) != -1) {
                buffer.rewind();
                sha256.update(buffer.array(), 0, bytesRead);
            }
        }
        byte[] hashBytes = sha256.digest();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < hashBytes.length; ++i) {
            if (Integer.toHexString(0xff & hashBytes[i]).length() == 1) {
                sb.append('0');
            }
            sb.append(Integer.toHexString(0xff & hashBytes[i]));
        }
        return sb.toString();
    }
