void *mem_alloc(struct MemPool *mp, size_t size) {
    if (mp->num_allocated + size > mp->size) {
        void *new_pool = mmap(NULL, mp->size * 2, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_pool == MAP_FAILED) {
