import java.io.File;
import java.math.BigInteger;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ConcurrentMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.net.URL;
import org.apache.commons.io.FilenameUtils;

public class FileProcessing {
    private static final int MAX_FILE_SIZE = 1048576; // 1 MB in bytes
    private static final String[] VALID_FILE_EXTENSIONS = {"txt", "csv", "log"};
    private static final ExecutorService executor = Executors.newCachedThreadPool();
    private static final String THIRD_PARTY_LOGGING_URL; // Dynamically configured through environment variables or configuration files

    public static Map<String, String> processFilePathsAndGeneratePduList(List<String> filePaths) {
        Map<String, String> md5Hashes = new HashMap<>();
        for (String filePath : filePaths) {
            if (!isNullOrEmpty(filePath)) {
                File file = new File(filePath);
                if (file.exists() && file.canRead()) {
                    String normalizedFilePath = normalizeFilePath(filePath);
                    if (isValidSize(normalizedFilePath, MAX_FILE_SIZE) && isValidFileType(normalizedFilePath)) {
                        try {
                            MessageDigest md = MessageDigest.getInstance("MD5");
                            byte[] fileContent = Files.readAllBytes(file.toPath());
                            md.update(fileContent);
                            String md5Hash = new BigInteger(1, md.digest()).toString(16).toUpperCase();
                            md5Hashes.put(normalizedFilePath, md5Hash);
                        } catch (NoSuchAlgorithmException | Exception e) {
                            logError(e);
                        }
                    }
                }
            }
        }
        populatePduList(md5Hashes);
        executor.shutdown();
        try {
            executor.awaitTermination(1, TimeUnit.HOURS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        return md5Hashes;
    }

    private static String normalizeFilePath(String filePath) {
        if (!filePath.endsWith("/")) {
            return filePath + "/";
        } else {
            return filePath;
        }
    }

    private static boolean isValidSize(String path, int limit) {
        File file = new File(path);
        long fileSize = file.length();
        return (fileSize <= limit);
    }

    private static boolean isValidFileType(String path) {
        String extension = FilenameUtils.getExtension(path);
        for (String validExtension : VALID_FILE_EXTENSIONS) {
            if (extension.equalsIgnoreCase(validExtension)) {
                return true;
            }
        }
