import java.io.*;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.*;

public class FileMD5Hasher {
    private static final Logger LOGGER = Logger.getLogger(FileMD5Hasher.class.getName());

    public Map<String, String> calculateMD5Hashes(String input) {
        if (input == null || input.isEmpty()) {
            LOGGER.warning("Invalid or empty input provided.");
            return new HashMap<>();
        }

        List<String> paths = Arrays.asList(input.split(",")).stream()
                .distinct()
                .peek(this::validatePath)
                .collect(Collectors.toList());

        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        Map<String, Future<String>> tasks = new ConcurrentHashMap<>();
        for (String path : paths) {
            Callable<String> task = () -> processFile(path);
            Future<String> future = executor.submit(task);
            tasks.put(path, future);
        }
        executor.shutdown();

        Map<String, String> result = new HashMap<>();
        while (!executor.isTerminated()) {
            try {
                Future<String> future = tasks.remove(executor.take());
                String hash = future.get();
                if (hash != null) {
                    result.put(future.getKey(), hash);
                }
            } catch (InterruptedException | ExecutionException e) {
                LOGGER.log(Level.SEVERE, "Error processing file: ", e);
            }
        }
        return result;
    }

    private void validatePath(String path) {
        if (path == null || path.isEmpty() || paths.contains(path)) {
            throw new IllegalArgumentException("Invalid or duplicate file path provided.");
        }
    }

    private String processFile(String path) {
        try {
            File file = new File(path);
            if (!file.exists() || !file.isFile()) {
                LOGGER.warning("File does not exist or is not a regular file: " + path);
                return null;
            }
            if (file.length() > (10 * (1024 * 1024))) {
                LOGGER.warning("File size exceeds the maximum allowed (10 MB): " + path);
                return null;
            }

            byte[] bytes = new byte[((int) file.length())];
            FileInputStream fis = new FileInputStream(file);
            fis.read(bytes);
            MessageDigest md = MessageDigest.getInstance("MD5");
            md.update(bytes);
            BigInteger number = new BigInteger(1, md.digest());
            String hashedPath = String.format("%s:%s", path, number.toString(16));

            LOGGER.info("Processing file: " + hashedPath + ", size: " + file.length() + ", start time: " + System.currentTimeMillis());
            return hashedPath;
        } catch (IOException | NoSuchAlgorithmException e) {
            LOGGER.log(Level.SEVERE, "Error reading or hashing file: ", e);
            return null;
        }
    }
}
```

