import java.io.*;
import java.math.BigInteger;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

public class InventorySystem {
    private Map<String, Product> products = new ConcurrentHashMap<>();
    private ExecutorService executor = Executors.newCachedThreadPool();
    private final int MAX_FILE_SIZE = 1048576; // 1 MB

    public void initialize(List<String> filePaths) throws IOException {
        Map<String, String> md5Hashes = new ConcurrentHashMap<>();

        for (String filePath : filePaths) {
            try {
                if (!new File(filePath).exists() || !Files.isReadable(new File(filePath).toPath())) {
                    throw new FileNotFoundException("File not found or unreadable: " + filePath);
                }
                byte[] md5 = MessageDigest.getInstance("MD5").digest(Files.readAllBytes(new File(filePath).toPath()));
                md5Hashes.put(filePath, new BigInteger(1, md5).toString(16));
            } catch (Exception e) {
                System.err.println("Error reading file: " + e.getMessage());
            }
        }

        for (String filePath : filePaths) {
            executor.submit(() -> loadProductsFromFile(md5Hashes.get(filePath), filePath));
        }

        while (!executor.isTerminated()) {
            // Wait for all tasks to complete before proceeding
        }
    }

    private void loadProductsFromFile(String md5Hash, String filePath) throws IOException {
        try (BufferedReader reader = new BufferedReader(new FileReader(filePath))) {
            String line;
            while ((line = reader.readLine()) != null) {
                Product product = parseProduct(line);
                if (product == null) continue;
                synchronized (products) {
                    products.putIfAbsent(product.getId(), product);
                }
            }
        } catch (Exception e) {
            System.err.println("Error reading file: " + e.getMessage());
        }
    }

    private Product parseProduct(String line) {
        // Assuming the format is as follows: id,name,description,category,price,stock_quantity,last_sale_date,weight,dimensions
        String[] fields = line.split(",");
        if (fields.length < 8) return null;

        Product product = new Product();
        product.setId(fields[0].trim());
        product.setName(fields[1].trim());
        product.setDescription(fields[2].trim());
        product.setCategory(fields[3].trim());
        product.setPrice(Double.parseDouble(fields[4].trim()));
        product.setStockQuantity(Integer.parseInt(fields[5].trim()));
        product.setLastSaleDate(fields[6].trim());
        product.setWeight(Double.parseDouble(fields[7].trim()));
        // For dimensions, assume it is in the format "width,height,depth" and split by ',' to get individual values
        String[] dimensions = fields[8].split(",");
        if (dimensions.length == 3) {
            product.setDimensions(new double[]{Double.parseDouble(dimensions[0].trim()), Double.parseDouble(dimensions[1].trim()), Double.parseDouble(dimensions[2].trim())});
        }

        return product;
    }

    // Methods for managing the inventory system (add, update, delete, query) omitted due to space constraints

    private String md5Hash(String str) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("MD5");
        byte[] hash = digest.digest(str.getBytes());
        BigInteger bigInteger = new BigInteger(1, hash);
        return bigInteger.toString(16);
    }
}
