#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <getopt.h>
#include <fcntl.h>
#include <errno.h>

static char *output_file = NULL;
static int case_sensitive = 0;
static int print_manpage = 0;

struct line_count {
    size_t lines;
    char buffer[4096];
};

int readline(FILE *stream, struct line_count *lc) {
    size_t bytes_read;
    if (fgets(lc->buffer, sizeof(lc->buffer), stream) == NULL) {
        return EOF;
    }
    bytes_read = strlen(lc->buffer);
    if (bytes_read > 0 && lc->buffer[bytes_read - 1] == '\n') {
        --bytes_read;
        lc->buffer[bytes_read] = '\0';
        ++lc->lines;
        return 1;
    }
    return bytes_read > 0 ? 1 : EOF;
}

int main(int argc, char **argv) {
    int opt;
    FILE *input_file = stdin;
    FILE *output_stream = stdout;

    static const struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"case-sensitive", no_argument, 0, 'c'},
        {"output-file", required_argument, 0, 'o'},
        {"manpage", no_argument, 0, 'm'},
        {0, 0, 0, 0}
    };

    while ((opt = getopt_long(argc, argv, "hc:o::m", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage: %s [options] input_file\n", argv[0]);
                exit(EXIT_SUCCESS);
            case 'c':
                case_sensitive = 1;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'm':
                print_manpage = 1;
                break;
            default:
                fprintf(stderr, "Invalid option: %c\n", optopt);
                exit(EXIT_FAILURE);
        }
    }

    if (print_manpage) {
        // Implement man page here
        return EXIT_SUCCESS;
    }

    if (argc - optind != 1) {
        fprintf(stderr, "Requires exactly one argument: input file\n");
        exit(EXIT_FAILURE);
    }

    input_file = fopen(argv[optind], "r");
    if (!input_file) {
        perror("Error opening input file");
        return EXIT_FAILURE;
    }

    output_stream = print_manpage ? stdout : (output_file ? freopen(output_file, "w", stdout) : NULL);
    if (!output_stream && output_file) {
        perror("Error redirecting output to output file");
        return EXIT_FAILURE;
    }

    struct line_count lc = {0};
    while (readline(input_file, &lc)) {}

    fprintf(output_stream, "Total lines: %zu\n", lc.lines);

    if (fclose(input_file) || fclose(output_stream)) {
        perror("Error closing files");
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
