    public void processFiles(List<String> filePaths) {
        List<CompletableFuture<Void>> futures = new ArrayList<>();
        for (String filePath : filePaths) {
            if (!validateFileExistsAndAccessible(filePath)) continue;
            futures.add(CompletableFuture.runAsync(() -> processFile(filePath)));
        }
        CompletableFuture.allOf(futures.toArray(new CompletableFuture[0])).join();
    }

    private boolean validateFileExistsAndAccessible(String filePath) {
        // Check if the file exists and is accessible, handle exceptions gracefully
        Path path = Paths.get(filePath);
        if (!Files.exists(path) || !Files.isReadable(path)) {
            LOGGER.warning("File not found or inaccessible: " + filePath);
            return false;
        }
        return true;
    }

