            LOGGER.info("SHA-256 hash: " + sha256Hash);
            LOGGER.info("Metadata: " + metadata);
        } catch (IOException | InterruptedException | ExecutionException e) {
            LOGGER.severe("Error processing file: " + filePath, e);
        }
    }

