#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <thread>
#include <mutex>
#include <filesystem>
#include <system_error>
#include <format>
#include <cmath>

std::mutex print_mutex;
long long totalLines = 0;

void processFiles(const std::string& input) {
    namespace fs = std::filesystem;
    auto paths = split(input, ',');
    std::vector<fs::path> filePaths;

    for (const auto& path : paths) {
        if (path.empty()) continue;

        try {
            fs::path p(path);
            if (!fs::exists(p) || !fs::is_regular_file(p)) throw std::runtime_error("Invalid file path.");
            if (p.size() > 10 * (1 << 20)) throw std::runtime_error("File size exceeds 10 MB limit.");

            auto startTime = std::chrono::high_resolution_clock::now();
            std::ifstream file(path);
            if (!file) throw std::runtime_error("Failed to open the file.");

            long long linesInFile = 0;
            std::string line;
            std::vector<int> values;

            while (std::getline(file, line)) {
                ++linesInFile;
                auto valuesStream = split(line, ' ');
                for (const auto& value : valuesStream) {
                    values.push_back(std::stoi(value));
                }
            }

            long long chunkSize = values.size() / 3 + (values.size() % 3 != 0);
            for (long long i = 0; i < chunkSize - 1; ++i) {
                std::cout << values[i] << ',';
            }
            std::cout << round(static_cast<double>(std::accumulate(values.end() - 3, values.end(), 0.0) / 3)) << '\n';

            file.close();
            totalLines += linesInFile;

            auto endTime = std::chrono::high_resolution_clock::now();
            auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(endTime - startTime).count();
            std::cout << "Processed file '" << path << "' in " << duration << "ms\n";
        } catch (const std::exception& e) {
            std::cerr << "Error processing file '" << path << "': " << e.what() << '\n';
        }
    }
}

std::vector<std::string> split(const std::string& s, char delim) {
    std::stringstream ss(s);
    std::string item;
    std::vector<std::string> tokens;
    while (std::getline(ss, item, delim)) {
        tokens.push_back(item);
    }
    return tokens;
}

int main(int argc, char* argv[]) {
    if (argc < 2) return -1;

    std::string fileInput = "";
    for (int i = 1; i < argc; ++i) {
        if (!fileInput.empty()) fileInput += ", ";
        fileInput += argv[i];
    }

    processFiles(fileInput);
    std::lock_guard<std::mutex> lock(print_mutex);
    std::cout << "Processed a total of " << totalLines << " lines across all files.\n";

    return 0;
}
```
