#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/stat.h>
#include <getopt.h>
#include <locale.h>
#include <wchar.h>

#define MAX_LINE_LENGTH 4096
#define BUFFER_SIZE (MAX_LINE_LENGTH * sizeof(wchar_t))

struct arg_options {
    int help;
    int verbose;
    int stats;
    char *output_file;
    int count;
};

int main(int argc, char **argv) {
    struct arg_options opts = { 0 };
    char c;

    setlocale(LC_ALL, "");

    const char *short_opts = "hvso:c:";
    const struct option long_opts[] = {
        {"help", no_argument, NULL, 'h'},
        {"verbose", no_argument, NULL, 'v'},
        {"stats", no_argument, NULL, 's'},
        {"output-file", required_argument, NULL, 'o'},
        {"count", required_argument, NULL, 'c'},
        {0, 0, 0, 0}
    };

    while ((c = getopt_long(argc, argv, short_opts, long_opts, NULL)) != -1) {
        switch (c) {
            case 'h':
                printf("Usage: %s [options] <input_file>\n", argv[0]);
                return 0;
            case 'v':
                opts.verbose = 1;
                break;
            case 's':
                opts.stats = 1;
                break;
            case 'o':
                opts.output_file = optarg;
                break;
            case 'c':
                opts.count = atoi(optarg);
                break;
            default:
                printf("Error: Invalid option --%c\n", c);
                return 1;
        }
    }

    if (argc - optind < 1) {
        fprintf(stderr, "Error: Missing input file.\n");
        return 1;
    }

    char *input_file = argv[optind];

    int fd = open(input_file, O_RDONLY);
    if (fd == -1) {
        perror("Error opening file");
        return 1;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("Error getting file statistics");
        return 1;
    }

    if (!S_ISREG(st.st_mode)) {
        fprintf(stderr, "Error: Input file is not a regular file.\n");
        return 1;
    }

    FILE *input = fdopen(fd, "r");

    size_t line_count = 0;
    wchar_t buffer[BUFFER_SIZE];

    while (getwchar_s(buffer, BUFFER_SIZE - 1, input) > 0) {
        if (line_count++ >= opts.count) break;

        if (opts.verbose) printf("%ls\n", buffer);
    }

    if (opts.stats) {
        printf("Number of lines processed: %zu\n", line_count);
    }

    if (opts.output_file && opts.verbose < 2) fclose(input);

    return 0;
}
