class JsonResourceBundle : public ResourceBundle {
public:
    std::map<std::string, Product> products;
    int load(const char* path) {
        Json::CharReaderBuilder builder;
        Json::CharReader* reader = builder.newCharReader();
        Json::Value root;
        std::istringstream iss;
        size_t numItems = 0;

        if (reader->parse(iss, root, false)) {
            for (auto& item : root) {
                Product product;
                product.id = item["id"].asString();
                product.name = item["name"].asString();
                // Set remaining fields...

                products[product.id] = product;
                numItems++;
            }
        } else {
            std::cerr << "Error parsing JSON: " << reader->getLastError() << std::endl;
        }

        delete reader;
        return numItems;
    }

    size_t getNumItems() const override {
        return products.size();
    }
};

class CsvResourceBundle : public ResourceBundle {
public:
    std::vector<Product> products;
    int load(const char* path) {
        std::ifstream file(path);
        size_t numItems = 0;

        if (file.is_open()) {
            std::string line;
            while (std::getline(file, line)) {
                std::istringstream iss(line);
                Product product;
                // Parse each field...

                products.push_back(product);
                numItems++;
            }
            file.close();
        } else {
            std::cerr << "Error opening CSV file: " << path << std::endl;
        }

        return numItems;
    }

    size_t getNumItems() const override {
        return products.size();
    }
};

std::string MD5(const std::string& str) {
    unsigned char digest[SHA256_DIGEST_LENGTH];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, str.c_str(), str.size());
    SHA256_Final(digest, &ctx);

    std::string result;
    for (unsigned i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
        result += std::hex << std::setw(2) << std::uppercase
                           << static_cast<int>(digest[i]);
    }

    return result;
}

std::map<std::string, std::string> loadResourceBundle(const char* path) {
    struct stat fileInfo;
    if (stat(path, &fileInfo) != 0 || fileInfo.st_size > 1048576) {
        std::cerr << "Error: File too large or does not exist" << std::endl;
        return {};
    }

    ResourceBundle* bundle = nullptr;
    auto extension = strrchr(path, '.');
    if (!extension) {
        std::cerr << "Error: Unsupported file format" << std::endl;
        return {};
    }

    if (strcmp(extension, ".json") == 0) {
        bundle = new JsonResourceBundle();
    } else if (strcmp(extension, ".csv") == 0) {
        bundle = new CsvResourceBundle();
    } else {
        std::cerr << "Error: Unsupported file format" << std::endl;
        return {};
    }

    try {
        int numItems = bundle->load(path);
        if (numItems <= 0) {
            delete bundle;
            return {};
        }

        // Implement filtering, ML integration, and other functionalities here...

        delete bundle;
        return bundle->getProductMap();
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        delete bundle;
        return {};
    }
}
