import java.io.*;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

import org.jsoup.Jsoup;
import org.jsoup.nodes.Document;
import org.jsoup.nodes.Element;
import org.jsoup.parser.Parser;

public class Fetcher {
    private static final int MAX_SIZE_LIMIT = 10 * 1024 * 1024; // 10 MB
    private static final List<String> ALLOWED_CONTENT_TYPES = List.of("application/json", "application/xml", "application/yaml");

    public Map<String, Map<String, Object>> fetchAndProcessWebResources(List<String> urls) {
        Map<String, Map<String, Object>> results = new HashMap<>();
        ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

        for (String url : urls) {
            if (url == null || url.isBlank()) continue;
            String sanitizedUrl = validateAndSanitizeUrl(url);
            if (sanitizedUrl == null) continue;

            try {
                URL resourceUrl = new URL(sanitizedUrl);
                Map<String, Object> metadata = fetchMetadata(resourceUrl);
                if (metadata != null && !isAllowedResourceType(metadata)) continue;

                if (metadata == null || !results.putIfAbsent(url, metadata).equals(metadata)) {
                    executor.submit(() -> downloadAndStoreContent(resourceUrl, url));
                }
            } catch (IOException e) {
                logError("fetchAndProcessWebResources", e);
            }
        }

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        return results;
    }

    private String validateAndSanitizeUrl(String url) {
        // Implement URL validation and sanitization logic here
    }

    private Map<String, Object> fetchMetadata(URL resourceUrl) throws IOException {
        HttpURLConnection connection = (HttpURLConnection) resourceUrl.openConnection();
        try {
            if (!isAllowedContentType(connection)) return null;
            connection.setRequestProperty("Accept", "*/*");
            connection.connect();

            long contentLength = connection.getContentLengthLong();
            if (contentLength > MAX_SIZE_LIMIT) return null;

            String lastModified = connection.getDateHeader("Last-Modified");
            String mimeType = connection.getContentType();

            return Map.of("lastModified", lastModified, "contentLength", contentLength, "mimeType", mimeType);
        } finally {
            connection.disconnect();
        }
