```java
import java.io.*;
import java.net.URL;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.ConcurrentMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.regex.Pattern;

public class ImageProcessor {
    private static final int MAX_THREADS = 10;
    private static final long RETRY_BACKOFF_MULTIPLIER = 2;
    private static final int BYTES_PER_KB = 1024;
    private static final Pattern IMAGE_MIME_TYPE_PATTERN;
    private final RateLimiter rateLimiter;
    private final ExternalApiService externalApiService;
    private final CachingLayer cachingLayer;
    private final EmailNotifier emailNotifier;
    private final SmsNotifier smsNotifier;
    private final Logger logger;

    // Initialize pattern and other dependencies
    static {
        IMAGE_MIME_TYPE_PATTERN = Pattern.compile("image\\/.*");
    }

    public ImageProcessor(RateLimiter rateLimiter, ExternalApiService externalApiService, CachingLayer cachingLayer, EmailNotifier emailNotifier, SmsNotifier smsNotifier, Logger logger) {
        // Set dependencies
        this.rateLimiter = rateLimiter;
        this.externalApiService = externalApiService;
        this.cachingLayer = cachingLayer;
        this.emailNotifier = emailNotifier;
        this.smsNotifier = smsNotifier;
        this.logger = logger;
    }

    public Map<String, String> processImageUrlsAndGenerateNFAPIList(List<String> imageUrls, String mimeTypePattern) throws IOException {
        // Validate inputs and initialize results
        if (imageUrls == null || imageUrls.isEmpty()) {
            return new HashMap<>();
        }

        ExecutorService executor = Executors.newFixedThreadPool(Math.min(MAX_THREADS, imageUrls.size()));
        Map<String, String> results = new HashMap<>();
        ConcurrentMap<String, Boolean> processedUrls = new ConcurrentHashMap<>();

        // Process each URL concurrently
        for (String url : imageUrls) {
            if (!processedUrls.putIfAbsent(url, true)) {
                continue;
            }

            Runnable urlProcessorTask = () -> processImageUrlAndStoreResult(url, results, processedUrls, mimeTypePattern);
            executor.submit(urlProcessorTask);
        }

        executor.shutdown();
        executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);

        // Notify users when all images are processed
        if (!results.isEmpty()) {
            EmailNotificationData emailData = generateEmailNotificationData(results);
            if (emailNotifier != null) {
                emailNotifier.send(emailData);
            }

            SmsNotificationData smsData = generateSmsNotificationData(results);
            if (smsNotifier != null) {
                smsNotifier.send(smsData);
            }
        }

        return results;
    }

    // Helper function to process a single URL and store the result in the results map
    private void processImageUrlAndStoreResult(String url, Map<String, String> results, ConcurrentMap<String, Boolean> processedUrls, String mimeTypePattern) throws IOException {
        if (!isValidUrlSize(url)) {
            logger.log(Level.INFO, "Skipping image URL: {}", url);
            return;
        }

        boolean validMimeType = IMAGE_MIME_TYPE_PATTERN.matcher(getContentTypeFromUrl(url)).matches();
        if (!validMimeType) {
            logger.log(Level.INFO, "Skipping image URL with invalid MIME type: {}", url);
            return;
        }

        String validatedUrl = isValidUrlSize(url) ? url : addQueryParameterForUrlValidation(url);
        MessageDigest sha256 = MessageDigest.getInstance("SHA-256");

        // Rate limit the API call to external metadata service
        rateLimiter.acquire();

        try {
            // Retrieve metadata about the image from the external API and validate its schema if required
            ImageMetadata metadata = externalApiService.getImageMetadata(validatedUrl);
            validateImageSchema(metadata);

            // Read the image content and compute its SHA-256 hash asynchronously using InputStream
            try (InputStream inputStream = new URL(validatedUrl).openStream()) {
                byte[] imageBytes = readBytesFromInputStream(inputStream);
                if (imageBytes.length <= BYTES_PER_KB * 10) { // 10 MB limit
                    sha256.update(imageBytes);
                    results.put(validatedUrl, bytesToHex(sha256.digest()));
                } else {
                    logger.log(Level.INFO, "Skipping image URL exceeding the size limit: {}", validatedUrl);
                }
            }
        } catch (Exception e) {
            logger.log(Level.SEVERE, "Error processing image URL: {}, Exception: {}", validatedUrl, e.getMessage());
        } finally {
            rateLimiter.release();
        }
    }

    // Helper function to generate email and SMS notifications data for the processed images
    private EmailNotificationData generateEmailNotificationData(Map<String, String> results) {
        StringBuilder summary = new StringBuilder();
        int successCount = 0;
        int errorCount = 0;

        for (Map.Entry<String, String> entry : results.entrySet()) {
            if (entry.getValue() != null) {
                successCount++;
                summary.appendFormat("* %s (%s)\n", entry.getKey(), entry.getValue());
            } else {
                errorCount++;
                summary.appendFormat("* %s\n", entry.getKey());
            }
        }

        return new EmailNotificationData(successCount + " successful image hash computations.", errorCount + " images failed to process due to various issues.");
    }

    // Helper function to generate SMS notification data for the processed images
    private SmsNotificationData generateSmsNotificationData(Map<String, String> results) {
        StringBuilder message = new StringBuilder();

        int successCount = 0;
        int errorCount = 0;

        for (Map.Entry<String, String> entry : results.entrySet()) {
            if (entry.getValue() != null) {
                successCount++;
            } else {
                errorCount++;
            }
        }

        message.appendFormat("%d successful image hash computations.", successCount);
        if (errorCount > 0) {
            message.appendFormat(", %d images failed to process due to various issues.", errorCount);
        }

        return new SmsNotificationData(message.toString());
    }
