use std::env;
use std::error::Error;
use std::time::Instant;
use tokio::runtime::{Builder as RuntimeBuilder, Runtime};
use tokio::sync::RwLock;
use reqwest::Client;
use rand::{thread_rng, RngCore};
use serde::Deserialize;
use structopt::StructOpt;

const RATE_LIMIT: u64 = 1000;
const MIN_VALUE: i32 = 0;
const MAX_VALUE: i32 = 100;

type OffsetVec = Vec<i64>;
type KeyVec = Vec<i32>;
type Record = (i32, i32);

#[derive(Deserialize)]
struct ApiResponse {
    offsets: OffsetVec,
    keys: KeyVec,
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn Error>> {
    let args = Opt::from_args();
    let memory_limit = args.memory_limit;

    let mut offsets = OffsetVec::new();
    let mut keys = KeyVec::new();
    let mut records = Vec::with_capacity(offsets.len());

    if let Some(api_url) = args.api_url {
        let client = Client::new();
        let mut attempts = 0;
        let backoff = exponential_backoff(Instant::now(), RATE_LIMIT, &args.api_key);

        loop {
            match client.get(api_url).header("Authorization", args.api_key).send().await {
                Ok(response) => {
                    if attempts > 0 {
                        println!("API request successful after {} attempts", attempts);
                    }
                    let response = response.json::<ApiResponse>().await?;
                    offsets = response.offsets;
                    keys = response.keys;
                    break;
                }
                Err(e) => {
                    if attempts < RATE_LIMIT && backoff.can_retry() {
                        println!("API request failed: {}", e);
                        attempts += 1;
                        tokio::time::sleep(backoff.delay()).await;
                    } else {
                        return Err(e.into());
                    }
                }
            }
        }
    }

    let mut memory_used = 0;

    for offset in &offsets {
        let key = keys[memory_used as usize % keys.len()];
        let record = (key, rand::thread_rng().gen_range(MIN_VALUE, MAX_VALUE));
        records.push(record);
        memory_used += offset.next_pow_of_two() as usize + std::mem::size_of::<i32>() + std::mem::size_of::<Record>();

        if memory_used > memory_limit {
            break;
        }
    }

    let seed = args.seed.map(|s| s.parse().unwrap());
    let mut rng = thread_rng().with_seed(seed);

    // Asynchronous loop to populate records with random values
    let records = Arc::new(RwLock::new(records));
    let start = Instant::now();
    tokio::spawn(async move {
        let mut processed = 0;
        while processed < records.read().await.len() {
            let index = rng.gen_range(0..records.read().await.len());
            if let Some(record) = records.write().await.get_mut(index) {
                record.1 = rng.gen_range(MIN_VALUE, MAX_VALUE);
                processed += 1;
            }
        }
        println!("Finished populating records in: {}", start.elapsed().as_secs_f64());
    });

    // Your production environment code here...

    Ok(())
}

struct Opt {
    memory_limit: Option<u64>,
    api_url: Option<String>,
    api_key: Option<String>,
    seed: Option<String>,
}

impl FromArgs for Opt {}

fn exponential_backoff(current: Instant, limit: u64, api_key: &str) -> Backoff {
    let backoff = Backoff { current, limit };

    move || {
        let elapsed = backoff.current.elapsed();
        let sleep_duration = (elapsed + backoff.limit as u128) / 2;
        Instant::now() + tokio::time::Duration::from_secs_f64(sleep_duration as f64 / 1_000_000_000)
    }
}

struct Backoff {
    current: Instant,
    limit: u64,
}
