            indications[i].pokemonType = pokemons[pokemonIndex].type;
            indications[i].pokemonName = pokemons[pokemonIndex].name;

            // Determine and set the weakness based on the Pokemon's type
            for (size_t j = 0; j < NUM_TYPES; ++j) {
                if (indications[i].pokemonType == pokemons[j].type &&
                    pokemons[j].weaknesses[NUM_TYPES - 1].name != NULL) {
                    indications[i].pokemonName = strcat(indications[i].pokemonName, " is weak against ");
                    indications[i].pokemonName = strcat(indications[i].pokemonName, pokemons[j].weaknesses[NUM_TYPES - 1].name);
                }
            }
        }
    }
}
