import okhttp3.*;

public class HashValidator {
    private static final ExecutorService executor = Executors.newFixedThreadPool(10);
    private static final ConcurrentHashMap<String, BigInteger> cache = new ConcurrentHashMap<>();
    private static OkHttpClient client = new OkHttpClient();
    private static final String SERVICE_URL = "http://external-validation-service.com/validate";

    public static void validateAndCacheHash(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            md.update(input.getBytes(StandardCharsets.UTF_8));
            BigInteger hash = new BigInteger(1, md.digest());
            cache.putIfAbsent(input, hash);
        } catch (NoSuchAlgorithmException e) {
            // Handle exception
        }
    }

    public static void validateHash(String input) {
        validateAndCacheHash(input);
        Call call = client.newCall(RequestBuilder.buildRequest(SERVICE_URL + "?hash=" + input));

        try (Response response = call.execute()) {
            if (!response.isSuccessful()) {
                // Handle failure cases, such as service unavailability or transient errors
                validateHash(input);
            } else {
                if (cache.getIfPresent(input).equals(new BigInteger(response.body().bytes()))) {
                    // Valid hash
                } else {
                    // Incorrect hash
                }
            }
        } catch (IOException e) {
            // Handle exceptions when communicating with the service
            validateHash(input);
        }
    }

    private static RequestBuilder requestBuilder() {
        return new Request.Builder().get();
    }

    private static class RequestBuilder {
        private Request.Builder builder;

        private RequestBuilder() {
            this.builder = requestBuilder();
        }

        public RequestBuilder url(String url) {
            this.builder.url(url);
            return this;
        }

        public Request buildRequest(String... params) {
            Url url = this.builder.build().url();
            StringBuilder sb = new StringBuilder(url.toString());
            for (String param : params) {
                if (!sb.toString().contains("?")) {
                    sb.append("?");
                } else {
                    sb.append("&");
                }
                sb.append(param);
            }
            return this.builder.build();
        }
    }
}
