import java.io.File;
import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.ConcurrentMap;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.Queue;
import java.util.regex.Pattern;
import java.nio.file.Files;
import java.time.Instant;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileProcessor {
    private static final Pattern FILE_PATTERN = Pattern.compile("^[\\w:/]+(\\.[\\w:/]+)*$");
    private static ConcurrentMap<String, BigInteger> checksumCache;
    private static ExecutorService executor;

    public static ConcurrentMap<String, BigInteger> processFilePaths(String filePathsStr) {
        if (filePathsStr == null || filePathsStr.isEmpty()) {
            throw new IllegalArgumentException("Empty or null input string.");
        }

        checksumCache = new HashMap<>();
        executor = Executors.newCachedThreadPool();

        Queue<String> fileQueue = new LinkedList<>(Arrays.asList(filePathsStr.split(",")))
            .stream()
            .filter(fp -> !fp.isEmpty())
            .map(this::validateFilePath)
            .collect(Collectors.toCollection(LinkedList::new));

        ConcurrentMap<String, BigInteger> result = new HashMap<>();

        while (!fileQueue.isEmpty()) {
            File currentFile = fileQueue.poll();
            if (currentFile != null && processFile(result, currentFile)) {
                fileQueue.addAll(getDuplicatesRemoval(fileQueue, currentFile));
            }
        }

        return result;
    }

    private static boolean validateFilePath(String filePath) {
        Matcher matcher = FILE_PATTERN.matcher(filePath);
        return matcher.matches();
    }

    private static Queue<File> getDuplicatesRemoval(Queue<String> filePaths, File currentFile) {
        Queue<File> newFiles = new LinkedList<>();
        for (String fp : filePaths) {
            File checkFile = new File(fp);
            if (!checkFile.equals(currentFile)) {
                newFiles.add(checkFile);
            }
        }
        return newFiles;
    }

    private static boolean processFile(ConcurrentMap<String, BigInteger> result, File file) {
        try {
            if (Files.size(file.toPath()) > 10 * (1024 * 1024)) {
                System.out.println("Skipping " + file.getAbsolutePath() + ", file size is too large.");
                return false;
            }

            byte[] md5 = MessageDigest.getInstance("MD5").digest(Files.readAllBytes(file.toPath()));
            BigInteger checksum = new BigInteger(1, md5);

            if (!checksumCache.containsKey(checksum.toString())) {
                Runnable validateHashTask = () -> validateHashAsync(checksumCache, file);
                executor.submit(validateHashTask);
                checksumCache.putIfAbsent(checksum.toString(), null);
            }

            result.putIfAbsent(file.getAbsolutePath(), checksum);
        } catch (Exception e) {
            System.err.println("Error processing " + file.getAbsolutePath() + ": " + e.getMessage());
        }
        return true;
    }

    private static void validateHashAsync(ConcurrentMap<String, BigInteger> cache, File file) {
        try {
            String hashUrl = "http://your-external-data-service.com/validate?checksum=" + encodeBase64(MessageDigest.getInstance("MD5").digest(Files.readAllBytes(file.toPath()))) + "&path=" + URLEncoder.encode(file.getAbsolutePath(), StandardCharsets.UTF_8);
            URL url = new URL(hashUrl);
            HttpsURLConnection connection = (HttpsURLConnection) url.openConnection();
            connection.setRequestMethod("GET");
            int responseCode = connection.getResponseCode();
            if (responseCode == 200) {
                String responseBody = new Scanner(url.openStream(), StandardCharsets.UTF_8).useDelimiter("Z").next();
                if (validateChecksumResponse(responseBody, file)) {
                    cache.putIfAbsent(file.getAbsolutePath(), parseBigIntegerFromBase64(responseBody));
                }
            } else {
                System.err.println("Validation request for " + file.getAbsolutePath() + " failed with response code: " + responseCode);
            }
        } catch (Exception e) {
            System.err.println("Error validating hash of " + file.getAbsolutePath() + ": " + e.getMessage());
        } finally {
            executor.execute(() -> cache.remove(file.getAbsolutePath()));
        }
    }

    private static boolean validateChecksumResponse(String responseBody, File file) {
        // Implement the logic to validate the response body based on the actual implementation of your external data service.
        return true;
    }

    private static BigInteger parseBigIntegerFromBase64(String base64) {
        byte[] decodedBytes = Base64.getDecoder().decode(base64);
        return new BigInteger(1, decodedBytes);
    }

    private static String encodeBase64(byte[] array) {
        return Base64.getEncoder().encodeToString(array);
    }
}
