    private static final Pattern FILE_PATH_PATTERN = Pattern.compile("^[a-zA-Z]:\\/|[a-zA-Z]\\/[a-zA-Z0-9]+(/|\\.)*$");
    private static final long MAX_FILE_SIZE = 20 * (1024 * 1024); // 20 MB
    private static final ExecutorService EXECUTOR = Executors.newCachedThreadPool();

    public Map<String, BigInteger> processFilePaths(String inputString) {
        Queue<String> fileQueue = new LinkedList<>(Arrays.asList(inputString.split(",")))
            .stream()
            .filter(this::isValidFilePath)
            .distinct()
            .collect(Collectors.toCollection(() -> new LinkedList<>()));

        Map<String, BigInteger> result = new ConcurrentHashMap<>();

        while (!fileQueue.isEmpty()) {
            File file = new File(fileQueue.poll());
            if (validatePermissions(file) && validateSize(file) && validateDateRange(file)) {
                BigInteger hash = getMD5Hash(file);
                if (hash != null) {
                    synchronized (result) {
                        result.putIfAbsent(file.getAbsolutePath(), hash);
                    }
                    EXECUTOR.submit(() -> validateHashOnService(file, hash, result));
                }
            }
        }

        return result;
    }

    private boolean isValidFilePath(String filePath) {
        return !filePath.isEmpty() && FILE_PATH_PATTERN.matcher(filePath).matches();
    }

    private BigInteger getMD5Hash(File file) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] digest = md.digest(Files.readAllBytes(file.toPath()));
            return new BigInteger(1, digest);
        } catch (Exception e) {
            LOGGER.error("Failed to calculate MD5 hash for {}", file.getAbsolutePath(), e);
            return null;
        }
    }

    private boolean validatePermissions(File file) {
        // Implement permission check logic here
    }

    private boolean validateSize(File file) {
        return file.length() <= MAX_FILE_SIZE;
    }

    private boolean validateDateRange(File file) {
        LocalDate currentDate = LocalDate.now();
        try {
            LocalDate fileDate = DATE_FORMAT.parse(file.getName().split("\\.")[0]);
            if (isValidDateRange(currentDate, fileDate)) {
                return true;
            }
        } catch (Exception e) {
            LOGGER.error("Failed to parse date from {} or invalid date format", file.getAbsolutePath());
        }
        return false;
    }

    private boolean isValidDateRange(LocalDate currentDate, LocalDate fileDate) {
        // Implement date range validation logic here
    }

    private void validateHashOnService(File file, BigInteger hash, Map<String, BigInteger> result) {
        try {
            // Validate hash on external service
