                synchronized (result) {
                    result.put(file.getAbsolutePath(), hash);
                }
            } else {
                LOGGER.warn("Hash validation failed for {} - possible transient error", file.getAbsolutePath());
            }
        } catch (Exception e) {
            LOGGER.error("Failed to validate hash for {} due to an error: {}", file.getAbsolutePath(), e);
        }
    }

    private BigInteger validateChecksumOnService(File file) throws Exception {
