static size_t read_file(const char *filename, size_t max_records, void **buf) {
    int fd = open(filename, O_RDONLY);
    if (fd == -1) {
        perror("open");
        return 0;
    }

    struct stat st;
    if (fstat(fd, &st) == -1) {
        perror("fstat");
        close(fd);
        return 0;
    }

    size_t file_size = st.st_size;
    void *data = malloc(file_size);
    if (!data) {
        perror("malloc");
        close(fd);
        return 0;
    }

    ssize_t bytes_read = read(fd, data, file_size);
    if (bytes_read != file_size) {
        perror("read");
        free(data);
        close(fd);
        return 0;
    }

    close(fd);
    *buf = data;
    return file_size;
}

