} NFAPI_CRC_INDICATION_PDU_T;

typedef struct node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct node *next;
} Node;

struct list {
    int size;
    Node **arr;
    pthread_mutex_t mutex;
};

void log(const char *msg) {
    // Implement logging functionality here.
}

void init_list(struct list *list, int capacity) {
    if (capacity <= 0 || capacity > 10000) {
        log("Invalid capacity.");
        return;
    }

    list->size = 0;
    list->arr = malloc(capacity * sizeof(Node*));
    for (int i = 0; i < capacity; ++i) {
        list->arr[i] = NULL;
    }

    pthread_mutex_init(&list->mutex, NULL);
}

void free_list(struct list *list) {
    for (int i = 0; i < list->size; ++i) {
        Node* current = list->arr[i];
        while (current != NULL) {
            Node* temp = current;
            current = current->next;
            free(temp);
        }
    }

    free(list->arr);
    pthread_mutex_destroy(&list->mutex);
}

void add_element(struct list *list, const NFAPI_CRC_INDICATION_PDU_T *data) {
    int index = data->rnti % list->size;

    // Atomic insertion using linked list.
    Node* newNode = malloc(sizeof(Node));
    if (!newNode) {
        log("Out of memory.");
        return;
    }
    newNode->data = *data;
    newNode->next = NULL;

    pthread_mutex_lock(&list->mutex);

    if (list->arr[index] == NULL) {
        list->arr[index] = newNode;
        ++list->size;
    } else {
        Node* current = list->arr[index];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = newNode;
    }

    pthread_mutex_unlock(&list->mutex);
}

void update_element(struct list *list, const RNTI rnti, const NFAPI_CRC_INDICATION_PDU_T *data) {
    int index = rnti % list->size;

    Node* current = list->arr[index];
    if (current == NULL) {
        log("RNTI not found.");
        return;
    }

    // Update the data with new values, correct CRC, and logging.
    pthread_mutex_lock(&list->mutex);

    while (current != NULL && current->data.rnti != rnti) {
        current = current->next;
    }

    if (current == NULL) {
        log("RNTI not found.");
        pthread_mutex_unlock(&list->mutex);
        return;
    }

    // Update the data with new values, correct CRC, and logging.
    current->data = *data;

    pthread_mutex_unlock(&list->mutex);
}

void remove_element(struct list *list, const RNTI rnti) {
    int index = rnti % list->size;

    Node* current = list->arr[index];
    if (current == NULL) {
        log("RNTI not found.");
        return;
    }

    pthread_mutex_lock(&list->mutex);

    if (current->data.rnti == rnti) {
        list->arr[index] = current->next;
        --list->size;
    } else {
        Node* temp = current;
        current = current->next;
        while (current != NULL && current->data.rnti != rnti) {
            temp = current;
            current = current->next;
        }

        if (current == NULL) {
            pthread_mutex_unlock(&list->mutex);
            return;
        }

        temp->next = current->next;
        free(current);
        --list->size;
    }

    pthread_mutex_unlock(&list->mutex);
}

