#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define DataRecord structure
typedef struct {
    time_t timestamp;
    unsigned long sequence_number;
    char* payload;
} DataRecord;

void processDynamicDataWithMemoryManagement(size_t N, size_t maxRecords, FILE *fp) {
    pthread_mutex_t listMutex; // For synchronization with the dynamic list

    // Initialize mutex
    pthread_mutex_init(&listMutex, NULL);

    DataRecord* records = malloc(N * sizeof(DataRecord));
    if (!records) {
        perror("Memory allocation error");
        return;
    }

    long timestamps[N];
    unsigned long sequenceNumbers[N];
    char** payloads = malloc(N * sizeof(char*));
    if (!payloads) {
        free(records);
        perror("Memory allocation error");
        return;
    }

    for (size_t i = 0; i < N; ++i) {
        payloads[i] = malloc(rand() % 100); // Set a maximum payload size of 100 bytes
        if (!payloads[i]) {
            perror("Memory allocation error");
            for (size_t j = 0; j < i; ++j) free(payloads[j]);
            free(records);
            free(sequenceNumbers);
            free(timestamps);
            free(payloads);
            return;
        }
    }

    for (size_t i = 0, sequenceNumber = 0; i < N && fscanf(fp, "%ld%lu", &timestamps[i], &sequenceNumbers[i]) == 2; ++i) {
        // Validate unique identifiers
        bool isDuplicate = false;
        for (size_t j = 0; j < i; ++j)
            if (sequenceNumbers[i] == sequenceNumbers[j]) {
                fprintf(stderr, "Error: Duplicate unique identifier found.\n");
                isDuplicate = true;
                break;
            }
        // Correct behavior when duplicate identifiers are encountered
        if (isDuplicate) continue;

        records[i].timestamp = timestamps[i];
        records[i].sequence_number = sequenceNumbers[i];
        records[i].payload = payloads[i];
        // Generate random data for the payload
        for (size_t j = 0; j < rand() % 100; ++j)
            *(records[i].payload + j) = (char)(rand() % 256);
    }

    if (ferror(fp)) {
        perror("Error reading from file");
        cleanUpAndExit();
    }

    // Process the dynamic list
    DataRecord* listHead = NULL;
    DataRecord* listTail = NULL;
    size_t numProcessedRecords = 0;

    while (numProcessedRecords < N && !feof(fp)) {
        if (fscanf(fp, "%ld%lu", &timestamps[i], &sequenceNumbers[i]) == 2) {
            DataRecord* newRecord = malloc(sizeof(DataRecord));
            if (!newRecord) {
                perror("Memory allocation error");
                cleanUpAndExit();
            }
            newRecord->timestamp = timestamps[i];
            newRecord->sequence_number = sequenceNumbers[i];
            newRecord->payload = payloads[i];
            // Generate random data for the payload if no data was provided in the file
            for (size_t j = 0; j < rand() % 100; ++j)
                *(newRecord->payload + j) = (char)(rand() % 256);

            // Append new record to the list, ensuring maximum size constraint is adhered to
            if (!listHead || numProcessedRecords < maxRecords) {
                if (numProcessedRecords > 0 && !feof(fp)) {
                    DataRecord* current = listHead;
                    while (current->next) current = current->next;
                    current->next = newRecord;
                } else {
                    listHead = newRecord;
                    listTail = newRecord;
                }
                numProcessedRecords++;
            } else {
                free(newRecord);
            }
        }
    }

    // Print average payload size, if any records were provided
    if (numProcessedRecords > 0) {
        double avgPayloadSize = 0.0;
        for (size_t i = 0; i < numProcessedRecords; ++i)
            avgPayloadSize += strlen(records[i].payload);
        printf("Average payload size: %.2f\n", avgPayloadSize / numProcessedRecords);
    } else {
        printf("No records provided.\n");
    }

    cleanUpAndExit();
}

void cleanUpAndExit() {
    if (records) free(records);
    for (size_t i = 0; i < numProcessedRecords; ++i) free(payloads[i]);
    free(sequenceNumbers);
    free(timestamps);
    free(payloads);
    pthread_mutex_destroy(&listMutex);
    exit(EXIT_SUCCESS);
}
```

