std::string generateNewFilename(const std::string& originalFileName) {
    // Parse the original filename to determine the directory path, base name, and extension
    size_t lastDot = originalFileName.find_last_of('.');
    std::string directoryPath = originalFileName.substr(0, lastDot);
    std::string baseName = originalFileName.substr(lastDot + 1);
    std::string extension = originalFileName.substr(originalFileName.length() - 4);

    // Replace the original extension with a new one that includes a numeric sequence derived from the base name's characters
    int sequenceNumber = std::stoi(baseName.substr(0, 4));
    if (sequenceNumber < 1000) {
        sequenceNumber = 1000 + sequenceNumber;
    }
    std::string newBaseName = baseName.substr(4);
    std::stringstream ss;
    ss << std::setw(4) << std::setfill('0') << sequenceNumber << newBaseName;
    std::string newFileName = directoryPath + "/" + ss.str() + extension;

    return newFileName;
}
