typedef struct {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint16_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

int isValidStringSize(const char *str) {
    if (strlen(str) > MAX_STRING_SIZE)
        return -1; // String size exceeds limit

    for (size_t i = 0; str[i]; ++i) {
        if (!isalnum(str[i]))
            return -2; // Invalid character found
    }
    return strnlen(str, MAX_STRING_SIZE) + 1;
}

pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static NFAPI_CRC_INDICATION_PDU_T *list = NULL;
static size_t capacity = 0, size = 0;
static char buffer[32] = {0}; // Circular log buffer
static int log_index = 0;

void log(const NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&mutex);
    snprintf(buffer + log_index, sizeof(buffer) - log_index, "%lu %04x %d\n", time(NULL), pdu->rnti, pdu->crcflag);
    log_index = (log_index + 1) % sizeof(buffer);
    pthread_mutex_unlock(&mutex);
}

NFAPI_CRC_INDICATION_PDU_T* generateNfalibPduList(int N) {
    if (N <= 0) return NULL;

    const int list_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;

    // Check memory usage and return error if exceeds threshold
    if (list_size > THRESHOLD && size > 0) {
        fprintf(stderr, "Error: Memory usage exceeded\n");
        return NULL;
    }

    const int max_capacity = THRESHOLD / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (size + N > max_capacity) {
        size += N; // Reallocate memory for the newly created structures
        list = realloc(list, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    int system_configuration = 1; // Placeholder for system configuration

    for (int i = size; i < size + N; ++i) {
        list[i].rx_ue_information_tag = 0x0002;
        list[i].rnti = rand() % (MAX_RNTI + 1);
        if (list[i].rnti >= system_configuration) continue; // Skip invalid RNTIs
        list[i].crc_indication_rel8_tag = 0x003A;
        list[i].crcflag = rand() % 2;
        log(&list[i]);
    }

    return list + size;
}
```

