#include <semaphore.h>
#include <sys/mman.h>

typedef struct {
    MAC_FRAME_TAG tag;
    uint32_t stream_id;
    size_t packets_count;
    size_t buffer_size;
    size_t packet_rate;
    void* packet_buf; // dynamically allocated array of MAC_STREAM_INFO elements
    sem_t buf_sem; // Semaphore for synchronizing access to the buffer
} MAC_FRAME_PDU_T;

typedef struct StreamManager {
    MAC_FRAME_PDU_T* pdu_list;
    size_t num_streams;
    sem_t streams_sem; // Semaphore for protecting access to the stream list
} StreamManager;

StreamManager* create_stream_manager(size_t num_streams) {
    StreamManager* sm = mmap(NULL, sizeof(StreamManager), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!sm) return NULL;

    sm->pdu_list = calloc(num_streams, sizeof(MAC_FRAME_PDU_T));
    if (!sm->pdu_list) goto err;

    sm->num_streams = num_streams;

    sem_init(&sm->streams_sem, 0, 1);
    for (size_t i = 0; i < num_streams; ++i) {
        sem_init(&sm->pdu_list[i].buf_sem, 0, sm->pdu_list[i].buffer_size / MAC_STREAM_INFO_SIZE);
    }

    return sm;
err:
    if (sm) munmap(sm, sizeof(StreamManager));
    return NULL;
}

MAC_FRAME_PDU_T* get_pdu(StreamManager* sm, uint32_t stream_id) {
    sem_wait(&sm->streams_sem);

    for (size_t i = 0; i < sm->num_streams; ++i) {
        if (sm->pdu_list[i].stream_id == stream_id) {
            sem_post(&sm->streams_sem);
            return &sm->pdu_list[i];
        }
    }

    sem_post(&sm->streams_sem);
    return NULL;
}

void add_stream(StreamManager* sm, uint32_t stream_id, size_t buffer_size, size_t packet_rate) {
    if (buffer_size < MAC_STREAM_INFO_MIN_BUFFER_SIZE || packet_rate <= 0) {
        fprintf(stderr, "Invalid buffer size or packet rate for stream %u\n", stream_id);
        return;
    }

    MAC_FRAME_PDU_T* pdu = get_pdu(sm, stream_id);
    if (!pdu) {
        pdu = &sm->pdu_list[sm->num_streams];
        ++sm->num_streams;
    }

    pdu->stream_id = stream_id;
    pdu->buffer_size = buffer_size;
    pdu->packet_rate = packet_rate;

    void* buf = malloc(pdu->buffer_size);
    if (!buf) {
        fprintf(stderr, "Failed to allocate memory for stream %u\n", stream_id);
        return;
    }

    sem_init(&pdu->buf_sem, 0, pdu->buffer_size / MAC_STREAM_INFO_SIZE);
    pdu->packet_buf = buf;
}

// Implement other functions for handling data processing, logging, and configuration changes here.
```

