    private static final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());

    public void processSensorData(String configFilePath, String outputPath, Runnable callback) {
        try (BufferedReader reader = Files.newBufferedReader(Paths.get(configFilePath), StandardCharsets.UTF_8)) {
            String line;
            Map<String, Device> devices = new HashMap<>();
            while ((line = reader.readLine()) != null) {
                if (line.startsWith("#")) continue; // ignore comments
                String[] parts = line.split("\\s+");
                if (parts.length < 3) throw new IllegalArgumentException("Invalid configuration line format");
                Device device = DeserializeDevice(parts);
                devices.put(device.getId(), device);
            }

            List<Future<?>> futures = new ArrayList<>();
            for (Map.Entry<String, Device> entry : devices.entrySet()) {
                futures.add(executor.submit(() -> processDeviceData(entry.getValue())));
            }
            executor.shutdown();
            while (!executor.isTerminated() && !futures.isEmpty()) {
                if (futures.poll().isDone()) {}
            }

            generateReport(devices, outputPath);
            callback.run(); // call the provided callback function when processing is complete
        } catch (IOException | InterruptedException e) {
            LOGGER.error("Error while processing data", e);
            ThirdPartyLibrary.logAndTrackError(e);
        } finally {
            executor.shutdownNow();
        }
    }

    // Add other required methods such as processDeviceData, generateReport, DeserializeDevice, and any other helper methods
}
