   import java.io.File;
   import java.math.BigInteger;
   import java.nio.file.Files;
   import java.security.MessageDigest;
   import java.time.Instant;
   import java.util.ConcurrentHashMap;
   import java.util.Deque;
   import java.util.LinkedList;
   import java.util.Map;
   import java.util.concurrent.atomic.AtomicLong;
   import java.util.concurrent.locks.ReentrantLock;
   import org.slf4j.Logger;
   import org.slf4j.LoggerFactory;

   public class ConcurrentMD5Cache {
       private static final Logger LOGGER = LoggerFactory.getLogger(ConcurrentMD5Cache.class);
       private static final int CACHE_MAX_SIZE = 1000_000;
       private static final long TIME_TO_LIVE_MS = 60_000L; // 1 minute
       private static final long REF_COUNT_THRESHOLD = 100;

       private final ConcurrentHashMap<String, CacheObject> cache;
       private final ReentrantLock lock;
       private final AtomicLong refCount = new AtomicLong();
       private final Deque<CacheObject> lru = new LinkedList<>();
       private final Deque<CacheObject> lfu = new LinkedList<>();

       public ConcurrentMD5Cache() {
           cache = new ConcurrentHashMap<>(CACHE_MAX_SIZE);
           lock = new ReentrantLock();
       }

       public BigInteger computeMD5(String filePath) throws Exception {
           CacheObject object = cache.get(filePath);
           if (object != null && !object.isStatus()) {
               long lastAccessed = object.getLastAccessed();
               long currentTime = Instant.now().toEpochMilli();
               if ((currentTime - lastAccessed) > TIME_TO_LIVE_MS || object.getHitCount() >= REF_COUNT_THRESHOLD) {
                   removeFromCache(object);
                   object = null;
               } else {
                   incrementHitCountAndReferenceCount(object);
               }
           }

           if (object == null) {
               lock.lock();
               try {
                   object = cache.get(filePath);
                   if (object == null) {
                       object = new CacheObject(filePath, Instant.now().toEpochMilli(), 1L, 0L, false, refCount.getAndIncrement());
                       cache.putIfAbsent(filePath, object);
                   }
               } finally {
                   lock.unlock();
               }

               if (!object.isStatus()) {
                   File file = new File(filePath);
                   BigInteger md5;
                   try {
                       byte[] fileBytes = Files.readAllBytes(file.toPath());
                       MessageDigest messageDigest = MessageDigest.getInstance("MD5");
                       md5 = new BigInteger(1, messageDigest.digest(fileBytes));
                   } catch (Exception e) {
                       throw new Exception("Error computing MD5 for file: " + filePath, e);
                   }

                   object.setMd5(md5);
                   object.setStatus(true);
                   object.setLastAccessed(Instant.now().toEpochMilli());
                   incrementHitCountAndReferenceCount(object);
               }
           }

           return object.getMd5();
       }

       private void removeFromCache(CacheObject object) {
           if (object != null && cache.containsKey(object.getFilePath())) {
               lock.lock();
               try {
                   cache.remove(object.getFilePath());
                   lru.removeIf(cacheObj -> cacheObj == object);
                   lfu.forEach(cacheObj -> {
                       if (cacheObj.getHitCount() <= object.getHitCount()) {
                           lru.addLast(cacheObj);
                       } else {
                           lfu.remove(cacheObj);
                           lfu.addLast(cacheObj);
                       }
                   });
                   refCount.getAndAdd(-1);
               } finally {
                   lock.unlock();
               }
           }
       }

       private void incrementHitCountAndReferenceCount(CacheObject object) {
           if (object != null) {
               long newHitCount = object.getHitCount() + 1;
               long newRefCount = object.getReferenceCount() + 1;
               object.setHitCount(newHitCount);
               object.setReferenceCount(newRefCount);
               if (!lru.contains(object)) {
                   lru.addLast(object);
               }
               while (lru.size() > CACHE_MAX_SIZE) {
                   CacheObject evicted = lru.pollFirst();
                   removeFromCache(evicted);
               }
           }
       }
   }

   class CacheObject {
       private final String filePath;
       private volatile long lastAccessed;
       private volatile long hitCount;
       private volatile long referenceCount;
       private volatile boolean status;
       private volatile BigInteger md5;

       public CacheObject(String filePath, long lastAccessed, long hitCount, long referenceCount, boolean status) {
           this.filePath = filePath;
           this.lastAccessed = lastAccessed;
           this.hitCount = hitCount;
           this.referenceCount = referenceCount;
           this.status = status;
       }

       public String getFilePath() {
           return filePath;
       }

       public long getLastAccessed() {
           return lastAccessed;
       }

       public long getHitCount() {
           return hitCount;
       }

       public long getReferenceCount() {
           return referenceCount;
       }

       public boolean isStatus() {
           return status;
       }

       public BigInteger getMd5() {
           return md5;
       }

       public void setLastAccessed(long lastAccessed) {
           this.lastAccessed = lastAccessed;
       }

       public void setHitCount(long hitCount) {
           this.hitCount = hitCount;
       }

       public void setReferenceCount(long referenceCount) {
           this.referenceCount = referenceCount;
       }

       public void setStatus(boolean status) {
           this.status = status;
       }

       public void setMd5(BigInteger md5) {
           this.md5 = md5;
       }
   }
