    def __init__(self):
        self.settings = {}
        self.api_cache = {}
        self.last_update = 0

    async def update_from_api(self, api_url):
        if api_url in self.api_cache and time.time() - self.api_cache[api_url] < timedelta(minutes=5).total_seconds():
            return self.api_cache[api_url]
        try:
            async with aiohttp.ClientSession() as session:
                async with session.get(api_url, timeout=10) as response:
                    data = await response.read()
                    if data and response.status == 200:
                        self.api_cache[api_url] = time.time()
                        return data
        except TimeoutError:
            pass
        return None

