std::vector<Product> filter(const std::vector<Product>& data, double weight_threshold, float dimension_threshold, int num_samples) {
    std::vector<Product> filtered_data;
    for (auto& p : data) {
        if (p.weight <= weight_threshold &&
            (p.dimensions[0] > dimension_threshold || p.dimensions[1] > dimension_threshold || p.dimensions[2] > dimension_threshold)) {
            filtered_data.push_back(p);
            if (filtered_data.size() == num_samples) break;
        }
    }
    // Adjust weights to meet the average weight constraint
    double total_weight = 0;
    for (auto& p : filtered_data) total_weight += p.weight;
    double avg_weight = total_weight / filtered_data.size();
    if (avg_weight > weight_threshold) {
        double adjustment = (avg_weight - weight_threshold) / filtered_data.size();
        for (auto& p : filtered_data) p.weight -= adjustment;
    }
    return filtered_data;
