void process_file(char *filename) {
    FILE *file = fopen(filename, "r");
    char lines[MAX_LINES][LINE_LENGTH];
    size_t lines_count = 0;

    if (!file) {
        printf("Error opening file.\n");
        return;
    }

    while (getline(&lines[lines_count], LINE_LENGTH, file) != -1) {
        ++lines_count;
        float average = 0.0;
        int fields_count = sscanf(lines[lines_count - 1], "%d,%d,%f,%f", &average, &average, &average, &average);

        if (fields_count == 4) {
            average = (average + average) / 2.0;
            printf("Average: %.2f\n", average);
        } else {
            printf("Invalid line format: %s\n", lines[lines_count - 1]);
