#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <semaphore.h>
#include <sys/mman.h>

#define MAX_ELEMENTS 10000
#define NUM_THREADS 8

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node *next;
};

struct list {
    struct list_node **nodes;
    size_t num_elements;
    pthread_mutex_t lock;
    sem_t sem; // for concurrency handling
};

void init_list(struct list *list) {
    list->num_elements = 0;
    list->nodes = calloc(MAX_ELEMENTS, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    pthread_mutex_init(&list->lock, NULL);
    sem_init(&list->sem, 0, NUM_THREADS);
}

void add_element(struct list *list, const NFAPI_CRC_INDICATION_PDU_T* data) {
    // Implement error handling and validation
    if (list->num_elements >= MAX_ELEMENTS) return;

    pthread_mutex_lock(&list->lock);
    sem_wait(&list->sem);

    list->nodes[list->num_elements] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
