    sem_wait(&list->sem);

    if (list->nodes[rnti] != NULL) {
        memcpy(list->nodes[rnti], data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    pthread_mutex_unlock(&list->lock);
    sem_post(&list->sem);
}

void remove_element(struct list *list, RNTI rnti) {
    // Implement error handling and validation
    if (rnti >= MAX_ELEMENTS) return;

    pthread_mutex_lock(&list->lock);
    sem_wait(&list->sem);

    if (list->nodes[rnti] != NULL) {
        free(list->nodes[rnti]);
        list->nodes[rnti] = NULL;
        list->num_elements--;
    }

