    size_t num_streams;
    TCP_STREAM streams[]; // array of stream structures
} TCP_CONNECTION;

void init_connection(TCP_CONNECTION* conn, int id) {
    conn->id = id;
    conn->last_activity = time(NULL);
    conn->num_streams = 0;
}

void add_stream(TCP_CONNECTION* conn, size_t stream_id, size_t buffer_size, int timeout) {
    if (buffer_size <= 0 || timeout <= 0) {
        printf("Invalid parameters for stream %zu\n", stream_id);
        return;
    }

    // Allocate memory for the stream and its packet buffer
    conn->streams[conn->num_streams].buffer = (char*) malloc(buffer_size);
    if (!conn->streams[conn->num_streams].buffer) {
        printf("Failed to allocate memory for stream %zu\n", stream_id);
        return;
    }

    conn->streams[conn->num_streams].buffer_size = buffer_size;
    conn->streams[conn->num_streams].timeout = timeout;
    conn->streams[conn->num_streams].packet_count = 0;

    // Increment the number of streams in the connection
    conn->num_streams++;
}

void update_statistics(TCP_CONNECTION* conn) {
    size_t total_received_bytes = 0;
    size_t num_active_streams = 0;

    for (size_t i = 0; i < conn->num_streams; ++i) {
        if (conn->streams[i].packet_count > 0) {
            total_received_bytes += conn->streams[i].buffer_size * conn->streams[i].packet_count;
            num_active_streams++;
        }
    }

    // Calculate average packet size, latency, and other statistics based on the updated values
}
