```c
#ifndef MEM_ALLOC_H
#define MEM_ALLOC_H

typedef struct MemAlloc {
    void *mem_pool;
    size_t aligned_size;
    size_t alignment;
} MemAlloc;

MemAlloc* mem_alloc_create(size_t aligned_size, size_t alignment);
void* mem_alloc_align(MemAlloc *allocator, size_t size);
void mem_alloc_free(MemAlloc *allocator);

#endif //MEM_ALLOC_H

#include "mem_alloc.h"
#include <stdlib.h>
#include <stdio.h>

MemAlloc* mem_alloc_create(size_t aligned_size, size_t alignment) {
    MemAlloc *allocator = malloc(sizeof(MemAlloc));
    allocator->aligned_size = aligned_size;
    allocator->alignment = alignment;
    allocator->mem_pool = malloc(aligned_size);
    return allocator;
}

void* mem_alloc_align(MemAlloc *allocator, size_t size) {
    void *ptr = (char *)allocator->mem_pool + ((unsigned long)allocator->mem_pool % allocator->alignment);
    ptr += allocator->alignment - ((unsigned long)ptr % allocator->alignment);
    if (((unsigned long)ptr + size) > (unsigned long)allocator->mem_pool + allocator->aligned_size) {
        printf("Error: Allocation out of bounds.\n");
        return NULL;
    }
    void *result = ptr;
    allocator->mem_pool = (char *)allocator->mem_pool + size + allocator->alignment;
    return result;
}

void mem_alloc_free(MemAlloc *allocator) {
    free(allocator->mem_pool);
    free(allocator);
}
