        curl_easy_setopt(curl, CURLOPT_URL, "http://api.weatherapi.com/v1/current.json?key=YOUR_API_KEY&q=" + std::string(city));
        curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
        curl_easy_perform(curl);
        if (curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE) == CURL_HTTP_OK) {
            data.data = malloc(data.size);
            memcpy(data.data, data.parsed_result, data.size);
        }
        curl_easy_cleanup(curl);
    }
    if (data.data) {
        data.temperature = *((float *)&data.data[10]);
        data.humidity = *((float *)&data.data[38]);
    } else {
        data.temperature = NAN;
        data.humidity = NAN;
    }
    return data;
}

