        self.timestamp_range = self.parse_timestamp_range(sys.argv[2:4])

    def parse_timestamp_range(self, args):
        start, end = None, None
        if args:
            try:
                start = datetime.datetime.strptime(args[0], "%Y-%m-%d %H:%M:%S")
                end = datetime.datetime.strptime(args[1], "%Y-%m-%d %H:%M:%S")
                if end < start:
                    raise ValueError("End timestamp must be later than the start timestamp.")
            except ValueError as e:
                print(f"Invalid timestamp format: {e}")
        return start, end

    def is_valid_filepath(self, filepath):
        if not os.path.isfile(filepath) or not os.access(filepath, os.R_OK):
            raise FileNotFoundError(f"File '{filepath}' does not exist or is not readable.")
        if os.path.getsize(filepath) > 1000000:
            raise ValueError(f"File '{filepath}' exceeds the 1 MB size limit.")
        return filepath

    def process_logs_and_files(self, filepaths):
        processed = {}
        task_queue = queue.Queue()
        for filepath in filepaths:
            if filepath not in processed:
                processed[filepath] = True
                task_queue.put((filepath, self.is_valid_filepath))

        def worker():
            while not task_queue.empty():
                function, args = task_queue.get()
                try:
                    result = function(*args)
                except Exception as e:
                    print(f"Error processing file '{args[0]}': {e}")
                finally:
                    self.process_file(result, *args)
                    task_queue.task_done()

        for _ in range(self.threads):
            threading.Thread(target=worker).start()

        # Wait for all tasks to complete
        task_queue.join()

    def process_file(self, filepath, validated_filepath):
        if validated_filepath:
            self.process_single_file(filepath)

    def process_single_file(self, filepath):
        with open(filepath, "r") as f:
            lines = f.readlines()

        sequence_number = self.extract_sequence_number(lines)
        log_entries = {}

        for line in lines:
            entry = self.parse_log_entry(line)
            if entry and (not self.keyword_filter or self.matches_filter(entry)):
                log_entries[entry] = log_entries.get(entry, 0) + 1

        self.lock.acquire()
        for entry, count in log_entries.items():
            self.log_entries[entry] = self.log_entries.get(entry, 0) + count
        self.lock.release()

        hashes = self.compute_hashes(filepath)
        self.log_summary(filepath, sequence_number, hashes)

    def extract_sequence_number(self, lines):
        try:
            return int(lines[-1].strip())
        except ValueError:
            pass
        return None

    def parse_log_entry(self, line):
        # Implement a regular expression or other parsing method to extract log entries from each line
        pass

    def matches_filter(self, entry):
        if not self.keyword_filter:
            return True
        return any(keyword in entry for keyword in self.keyword_filter.split())

    def compute_hashes(self, filepath):
        sha256 = hashlib.sha256()
        md5 = hashlib.md5()
        try:
            with open(filepath, "rb") as f:
                while True:
                    data = f.read(1024)
                    if not data:
                        break
                    sha256.update(data)
                    md5.update(data)
        except Exception as e:
            print(f"Error computing hashes for file '{filepath}': {e}")
            return "", ""  # Return empty strings if an error occurs during hash computation

        return sha256.hexdigest(), md5.hexdigest()

