        try {
            requestQueue.put(request);
        } catch (InterruptedException e) {
            LOGGER.log(Level.WARNING, "Failed to add load request to queue", e);
            return null;
        }

        if (!requestQueue.offer(request)) {
            LOGGER.log(Level.WARNING, String.format("Unable to enqueue request due to exceeding maximum concurrent loads (%d).", MAX_CONCURRENT_LOADS));
            return null;
        }

        Runnable loadTask = () -> {
            MoSTState state = null;
            try (ObjectInputStream objectInput = new ObjectInputStream(new FileInputStream(request.filePath))) {
                state = (MoSTState) objectInput.readObject();
            } catch (IOException | ClassNotFoundException e) {
                LOGGER.log(Level.SEVERE, String.format("Failed to load state from file %s", request.filePath), e);
            } finally {
                if (state == null && request != null) {
                    LOGGER.log(Level.INFO, String.format("State not loaded from file %s - marking as failed.", request.filePath));
                } else {
                    LOGGER.log(Level.INFO, String.format("Successfully loaded state from file %s.", request.filePath));
                }
            }
            return state;
        };

        executor.submit(loadTask);

        return estimateCompletionTime(request);
    }

    private MoSTState estimateCompletionTime(LoadRequest request) {
        // Replace this with a proper estimation algorithm based on system metrics and historical load patterns
        long estimatedTime = System.currentTimeMillis() + (long) Math.pow(2, request.trackingId % 10) * 100;
        return request;
    }

    private static class LoadRequest {
        final String filePath;
        final long trackingId;

        public LoadRequest(String filePath, long trackingId) {
            this.filePath = filePath;
            this.trackingId = trackingId;
        }
    }
}
```
