```java
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.util.ConcurrentModificationException;
import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.UUID;

public class MoSTStateLoader {
    private final String logFile = "most_state_load.log";
    private static Queue<LoadRequest> loadQueue = new LinkedList<>();
    private static ExecutorService executor = Executors.newFixedThreadPool(10);
    private static long totalLoadedSize = 0;

    public void loadStateFromFile(String filePath) throws IOException, ClassNotFoundException {
        if (loadQueue.size() >= 10) {
            System.out.println("Waiting for previous requests to complete...");
            waitForRequests();
        }

        LoadRequest request = new LoadRequest(UUID.randomUUID().toString(), filePath);
        loadQueue.add(request);
        executor.submit(() -> loadStateInternal(request));
    }

    private void loadStateInternal(LoadRequest request) {
        try (ObjectInputStream ois = new ObjectInputStream(new BufferedInputStream(Files.newInputStream(Path.of(request.filePath), StandardOpenOption.READ))) ) {
            MoSTState mostState = (MoSTState) ois.readObject();
            // Handle exception if necessary
            System.out.println("Loaded state for ID: " + request.id);
            totalLoadedSize += Files.size(Path.of(request.filePath));
        } catch (Exception e) {
            logError(request, e);
        } finally {
            loadQueue.removeIf(l -> l.id.equals(request.id));
            updateETC();
        }
    }

    private void waitForRequests() {
        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.NANOSECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
    }

    private void updateETC() {
        // Implement ETC calculation based on current system metrics and historical load patterns
    }

    private void logError(LoadRequest request, Exception e) {
        String line = "Error loading state for ID: " + request.id + ", Error Message: " + e.getMessage() + "\n";
        Files.writeString(Path.of(logFile), line, StandardOpenOption.APPEND);
    }
}

class LoadRequest {
    String id;
    String filePath;

    public LoadRequest(String id, String filePath) {
        this.id = id;
        this.filePath = filePath;
    }
}
