        structures[i].crc_indication_rel8_tag_crcflag = rand() % 2 == 0 ? true : false;
    }

    pthread_mutex_lock(&mutex);
    unsigned long current_time = std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::high_resolution_clock::now().time_since_epoch()).count();
    if (current_time - last_creation_time < NANOSEC_PER_SEC / MAX_CREATE_RATE) {
        // Wait until the next allowed time to create structures
        unsigned long sleep_duration = std::min(NANOSEC_PER_SEC / MAX_CREATE_RATE - (current_time - last_creation_time), NANOSEC_PER_SEC);
        usleep(sleep_duration);
    }
    creation_counter += N;
    last_creation_time = current_time;
    pthread_mutex_unlock(&mutex);

    return structures;
}
