#define MAX_STRUCTURES 1000000
#define STRUCTURE_RATE 1000
#define MEMORY_THRESHOLD 5000000
#define CPU_THRESHOLD 80

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct MemoryPool {
    NFAPI_CRC_INDICATION_PDU_T *pool;
    size_t capacity;
    size_t size;
    sem_t mutex;
    sem_t notFull;
    sem_t notEmpty;
} MemoryPool;

void LogError(const char *message) {
    // Implement logging functionality here
}

bool CheckThresholds() {
    long memoryUsage, cpuUsage;
    // Implement function to get current memory usage and CPU usage here
    if (memoryUsage > MEMORY_THRESHOLD || cpuUsage > CPU_THRESHOLD) {
        LogError("Memory or CPU usage exceeded the threshold. Triggering alert.");
        return true;
    }
    return false;
}

void InitMemoryPool(MemoryPool *pool, size_t capacity) {
    pool->pool = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pool->pool) {
        LogError("Failed to allocate memory for the memory pool.");
        exit(1);
    }
    pool->capacity = capacity;
    pool->size = 0;
    sem_init(&pool->mutex, 0, 1);
    sem_init(&pool->notFull, 0, capacity);
    sem_init(&pool->notEmpty, 0, 0);
}

NFAPI_CRC_INDICATION_PDU_T *AllocStructure(MemoryPool *pool) {
    sem_wait(&pool->notFull);
    sem_wait(&pool->mutex);
    NFAPI_CRC_INDICATION_PDU_T *structure = &pool->pool[pool->size];
    pool->size++;
    sem_post(&pool->mutex);
    structure->RX_UE_INFORMATION_TAG = rand();
    structure->RNTI = rand();
    structure->CRC_INDICATION_REL8_TAG = rand() % 65535;
    structure->CRCFLAG = (rand() % 2) == 0 ? true : false;
    return structure;
}

void FreeStructure(MemoryPool *pool, NFAPI_CRC_INDICATION_PDU_T *structure) {
    sem_wait(&pool->mutex);
    pool->pool[pool->size - 1] = *structure;
    pool->size--;
    sem_post(&pool->mutex);
    sem_post(&pool->notEmpty);
}

void NotifyOnMaxCapacity(void (*callback)(void)) {
    callback();
}

void ManageList(MemoryPool *pool, pthread_t threadId) {
    struct timespec prevTime, currTime;
    double seconds = 0.0;
    int structureCount = 0;

    clock_gettime(CLOCK_MONOTONIC, &prevTime);

    while (true) {
        if (CheckThresholds()) {
            break;
        }

        sem_wait(&pool->notEmpty);
        sem_wait(&pool->mutex);
        if (structureCount >= MAX_STRUCTURES || structureCount >= pool->capacity) {
            NotifyOnMaxCapacity(NotifyOnMaxCapacity);
            break;
        }
        NFAPI_CRC_INDICATION_PDU_T *structure = AllocStructure(pool);
        sem_post(&pool->mutex);

        structureCount++;

        clock_gettime(CLOCK_MONOTONIC, &currTime);
        seconds += (currTime.tv_sec - prevTime.tv_sec) + (currTime.tv_nsec - prevTime.tv_nsec) / 1_000_000_000;
        if ((seconds >= 1 && structureCount % STRUCTURE_RATE != 0) || structureCount == MAX_STRUCTURES) {
            break;
        }
    }
}
