       pthread_mutex_lock(&queue_lock);
       size_t copy_num_pending = num_pending;
       *num_messages = copy_num_pending;

       if (copy_num_pending == 0) {
           pthread_mutex_unlock(&queue_lock);
           return NULL;
       }

       NFAPI_CRC_INDICATION_PDU* messages = malloc(copy_num_pending * sizeof(NFAPI_CRC_INDICATION_PDU));

       if (!messages) {
           fprintf(stderr, "Memory allocation error\n");
           pthread_mutex_unlock(&queue_lock);
           return NULL;
       }

       memcpy(messages, pending_messages, copy_num_pending * sizeof(NFAPI_CRC_INDICATION_PDU));

       for (size_t i = 0; i < copy_num_pending; ++i) {
           pending_messages[i].transmitted = true;
           pthread_mutex_destroy(&pending_messages[i].lock);
       }

       memmove(pending_messages, pending_messages + copy_num_pending, (100 - copy_num_pending) * sizeof(NFAPI_CRC_INDICATION_PDU));
       num_pending -= copy_num_pending;

       pthread_mutex_unlock(&queue_lock);

       return messages;
   }
