#include <limits.h>

#define COMMENT_DELIMITER "#"
#define MEMORY_THRESHOLD (10 * 1024 * 1024) // 10MB as an example threshold

struct log_data {
    FILE* log_file;
    sem_t lock;
};

static struct log_data log;

void init_logging(const char* filename) {
    if (!(log.log_file = fopen(filename, "a"))) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }
    sem_init(&log.lock, 0, 1);
}

void log_error(const char* msg) {
    sem_wait(&log.lock);
    fprintf(log.log_file, "%s\n", msg);
    fflush(log.log_file);
    sem_post(&log.lock);
}

void* read_and_count_lines(void* arg) {
    char* mapped_memory = NULL;
    struct stat file_stats;
    int fd = *(int*)arg;

    if (fstat(fd, &file_stats) == -1) {
        perror("fstat");
        exit(EXIT_FAILURE);
    }

    size_t map_size = file_stats.st_size > MEMORY_THRESHOLD ? MEMORY_THRESHOLD : file_stats.st_size;
    mapped_memory = mmap(NULL, map_size, PROT_READ, MAP_PRIVATE, fd, 0);

    if (mapped_memory == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }

    char* line_start = mapped_memory;
    size_t lines_count = 0;

    while ((line_start = strchr(line_start, '\n')) != NULL) {
        if (strncmp(line_start, COMMENT_DELIMITER, strlen(COMMENT_DELIMITER)) == 0) {
            continue;
        }
        lines_count++;
        line_start += strlen(COMMENT_DELIMITER) + 1; // Advance past the newline character
    }

    munmap(mapped_memory, map_size);
    close(fd);

    return &lines_count;
}

int main(int argc, char* argv[]) {
    int opt = 0;
    const char* input_file = NULL;
    const char* output_file = "output.txt";

    while ((opt = getopt(argc, argv, "c:o:m")) != -1) {
        switch (opt) {
            case 'c':
                COMMENT_DELIMITER = optarg;
                break;
            case 'o':
                output_file = optarg;
                break;
            case 'm':
                init_logging("error.log");
                break;
            default:
                log_error("Usage: ./program [options] input_file\n"
                          "-c, --comment=COMMENT_DELIMITER: Specify comment delimiter (default: #)\n"
                          "-o, --output=OUTPUT_FILE: Output file name (default: output.txt)\n"
                          "-m, --manpage: Print usage information and exit");
                return EXIT_SUCCESS;
        }
    }

    if (!input_file) {
        log_error("Usage: ./program [options] input_file\n"
                  "-c, --comment=COMMENT_DELIMITER: Specify comment delimiter (default: #)\n"
                  "-o, --output=OUTPUT_FILE: Output file name (default: output.txt)\n"
                  "-m, --manpage: Print usage information and exit");
        return EXIT_SUCCESS;
    }

    int* threads_results = malloc(num_threads * sizeof(int));
    pthread_t* threads = malloc(num_threads * sizeof(pthread_t));
    int num_threads = sysconf(_SC_NPROCESSORS_ONLN); // Number of threads based on system CPU cores

    int fd = open(input_file, O_RDONLY);

    if (fd == -1) {
        perror("open");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < num_threads; ++i) {
        int* thread_arg = &fd + i * sizeof(int);
        if (pthread_create(&threads[i], NULL, read_and_count_lines, thread_arg) != 0) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }
    }

    for (size_t i = 0; i < num_threads; ++i) {
        void* result;
        if (pthread_join(threads[i], &result) != 0) {
            perror("pthread_join");
            exit(EXIT_FAILURE);
        }
        threads_results[i] = *(int*)result;
    }

    int total_lines = 0;
    for (size_t i = 0; i < num_threads; ++i) {
        total_lines += threads_results[i];
    }

    fprintf(stdout, "Total lines: %d\n", total_lines);
    fprintf(stdout, "Writing output to %s\n", output_file);
    FILE* out_file = fopen(output_file, "w");
    if (out_file == NULL) {
        perror("fopen");
        exit(EXIT_FAILURE);
    }

    fprintf(out_file, "%d\n", total_lines);
    fclose(out_file);

    free(threads_results);
    free(threads);

    return EXIT_SUCCESS;
}
