public class FileProcessor {
    private static final int MAX_FILE_SIZE = 10 * (1024 * 1024); // 10 MB
    private static final Pattern DELIMITER_PATTERN = Pattern.compile("\\p{javaWhitespace}+");
    private ExecutorService executor;
    private ConcurrentMap<String, String> fileMd5Hashes;

    public FileProcessor() {
        this.fileMd5Hashes = new LinkedHashMap<>();
        int availableProcessors = Runtime.getRuntime().availableProcessors();
        this.executor = Executors.newFixedThreadPool(Math.min(availableProcessors * 2, 10));
    }

    public Map<String, String> processFiles(List<String> filePaths, char delimiter) {
        Map<String, String> processedFiles = new LinkedHashMap<>();

        for (String filePath : filterInvalidFilePaths(filePaths)) {
            if (!hasPermissionsForReading(filePath)) {
                continue;
            }
            File file = new File(filePath);
            if (file.length() > MAX_FILE_SIZE) {
                System.out.println("Skipping file: " + filePath + " due to size limitations.");
                continue;
            }

            String md5Hash = calculateMD5(file);
            processedFiles.putIfAbsent(filePath, md5Hash);
            if (fileMd5Hashes.containsKey(md5Hash)) {
                fileMd5Hashes.merge(md5Hash, 1, Integer::sum);
            } else {
                fileMd5Hashes.put(md5Hash, 1);
            }
        }

        executeValidationTasks();

        return processedFiles;
    }

    private List<String> filterInvalidFilePaths(List<String> filePaths) {
        return filePaths.stream()
                .filter(str -> !str.isEmpty())
                .distinct()
                .toList();
    }

    private boolean hasPermissionsForReading(String filePath) {
        File file = new File(filePath);
        if (!file.canRead()) {
            System.out.println("Permission denied for file: " + filePath);
            return false;
        }
        return true;
    }

    private String calculateMD5(File file) {
        try (MessageDigest messageDigest = MessageDigest.getInstance("MD5")) {
            byte[] bytesOfMessage = Files.readAllBytes(file.toPath());
            messageDigest.update(bytesOfMessage);
            return new BigInteger(1, messageDigest.digest()).toString(16);
        } catch (IOException | NoSuchAlgorithmException e) {
            System.err.println("Error calculating MD5 hash for file: " + file.getAbsolutePath() + ". Error: " + e.getMessage());
            return "";
        }
    }

    private void executeValidationTasks() {
        executor.shutdown();
        while (!executor.isTerminated()) {}

        for (Map.Entry<String, Integer> entry : fileMd5Hashes.entrySet()) {
            if (entry.getValue() > 1) {
                System.out.println("Duplicate hash found: " + entry.getKey());
            }

            if (validateHashWithExternalService(entry.getKey())) {
                fileMd5Hashes.remove(entry.getKey());
                System.out.println("Hash validation failed for file: " + entry.getKey());
            } else {
                fileMd5Hashes.put(entry.getKey(), null);
            }
        }
    }

    private boolean validateHashWithExternalService(String md5Hash) {
        // Implement the logic to call the external data service here, returning true if validation is successful and false otherwise.
        return false;
    }
}
