void processInputAndEncrypt(int* arr, size_t maxSize, int value) {
    if (arr == nullptr || maxSize <= 0) throw invalid_argument("Invalid input parameters");

    if ((size_t)value >= maxSize) {
        // Handle overflow condition gracefully
        cerr << "Overflow: Maximum array size exceeded" << endl;
        return;
    }

    arr[value]++; // Encrypt the value by incrementing it
