void countLines(istream& in, function<void(unsigned long)> callback) {
    unsigned long lineCount = 0;
    string line;
    while (getline(in, line)) ++lineCount;
    callback(lineCount);
}

map<string, unsigned long> summarize(istream& in, const string& delimiter) {
    map<string, unsigned long> wordCounts;
    string word;
    stringstream ss;

    while (getline(in, word)) {
        ss.clear(); ss.str(word);
        string temp;
        while (getline(ss, temp, delimiter.c_str()[0])) {
            auto it = wordCounts.find(temp);
            if (it == wordCounts.end()) it = wordCounts.emplace(temp, 0).first;
            it->second++;
        }
    }
    return wordCounts;
}

void writeSummaryToFile(const string& outputFile, const map<string, unsigned long>& summary, const string& delimiter) {
    ofstream out(outputFile);
    if (!out.is_open()) throw runtime_error("Could not open output file");

    for (auto& [word, count] : summary) {
        out << word << delimiter;
        for (size_t i = 0; i < delimiter.length() - 1; ++i) out << ' ';
        out << count << endl;
    }
}

void processInput(istream& in, function<void()> callback, function<void(const string&)> encryptFunction) {
    if (callback) callback();
    for (string line; getline(in, line); ) {
        encryptFunction(line);
    }
}

