    po::options_description desc("Allowed options");
    desc.add_options()
        ("help,h", "Produce help message")
        ("input-file,i", po::value<string>(), "Input file to process")
        ("count-only,c", "")
        ("summary,s", po::value<string>()->default_value(","), "Summary of lines per unique word, using a custom delimiter (e.g., ',\"')")
        ("output-file,o", po::value<string>(), "Output file where results should be written")
        ("threads,t", po::value<int>()->default_value(thread::hardware_concurrency()), "Number of threads to use for parallel processing")
        ("delimiter,d", po::value<string>()->default_value(","), "Custom delimiter for categorizing words in the summary option")
        ("manpage,M", "");

    po::variables_map vm;
    po::store(parse_command_line(argc, argv, desc), vm);
    if (vm.count("help")) {
        cout << desc << endl;
        return 0;
    }
    po::notify(vm);

    ifstream inputFile;
    ofstream outputFile;
    string inputFilePath = vm["input-file"].as<string>();
    string outputFilePath = vm["output-file"].as<string>();

    if (vm.count("count-only")) {
        if (!inputFilePath.empty()) throw invalid_argument("Cannot specify both an input file and count-only option");
        int threadCount = vm["threads"].as<int>();
        vector<future<unsigned long>> results;
        results.resize(threadCount);

        for (unsigned i = 0; i < threadCount; ++i) {
            auto func = bind(countLines, placeholders::_1, bind(processInput, placeholders::_2, []() {}, processInputAndEncrypt));
            results[i] = async(launch::async, func, make_tuple(cin, ref(threadCount)));
