import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import java.util.stream.Collectors;

public class FileProcessor {
    private static List<String> parseCommaSeparatedFilePaths(String commaSeparatedFilePaths) {
        String[] filePaths = commaSeparatedFilePaths.split(",");
        List<String> paths = new ArrayList<>();

        for (String path : filePaths) {
            if (path.isEmpty()) continue;
            try {
                File file = new File(URI.create(path).getPath());

                if (!file.exists() || !file.isFile() || !file.canRead()) {
                    throw new IOException("Could not read file: " + path);
                }
                paths.add(path);
            } catch (Exception e) {
                System.err.println("Error reading file: " + e.getMessage());
            }
        }
        return paths;
    }

    public static void processFiles(String commaSeparatedFilePaths, String delimiter) throws IOException {
        List<String> paths = parseCommaSeparatedFilePaths(commaSeparatedFilePaths);

        Map<String, Integer> wordCountMap = new HashMap<>();
        Pattern pattern = Pattern.compile("(?<=\\G" + delimiter + "|\\b)(.*?)(" + delimiter + "|$)");

        for (String path : paths) {
            BufferedReader reader = new BufferedReader(new FileReader(path));
            try {
                String line;
                while ((line = reader.readLine()) != null) {
                    Matcher matcher = pattern.matcher(line);
                    while (matcher.find()) {
                        wordCountMap.put(matcher.group(1), wordCountMap.getOrDefault(matcher.group(1), 0) + 1);
                    }
                }
            } finally {
                reader.close();
            }
        }

        System.out.println("Summary:");
        for (Map.Entry<String, Integer> entry : wordCountMap.entrySet()) {
            System.out.println(entry.getKey() + delimiter + entry.getValue());
        }
    }
}
