```c
// Lock variable to protect access to the vehicles array
pthread_mutex_t vehiclesLock;

void addVehicle(struct Vehicle* vehicle) {
    pthread_mutex_lock(&vehiclesLock);
    memcpy(vehicles + numVehicles, vehicle, sizeof(struct Vehicle));
    numVehicles++;
    pthread_mutex_unlock(&vehiclesLock);
}

void updateVehicle(size_t index, struct Vehicle* updatedVehicle) {
    pthread_mutex_lock(&vehiclesLock);
    memcpy(vehicles + index, updatedVehicle, sizeof(struct Vehicle));
    pthread_mutex_unlock(&vehiclesLock);
}

void removeVehicle(size_t index) {
    pthread_mutex_lock(&vehiclesLock);
    memmove(vehicles + index, vehicles + index + 1, (numVehicles - index) * sizeof(struct Vehicle));
    numVehicles--;
    pthread_mutex_unlock(&vehiclesLock);
}
