                    return 0;
                } else {
                    fprintf(stderr, "Error in command line arguments.\n");
                    return 1;
                }
        }
    }

    if (optind < argc)
        input_file = argv[optind];
    if (!input_file) {
        if (manpage) {
            printf("Usage:\n%s [-h] [-c <character_set>] [-o <output_file>] input_file\n", argv[0]);
            return 0;
        } else {
            fprintf(stderr, "Missing input file.\n");
            return 1;
        }
    }

    FILE *fp = fopen(input_file, "r");
    if (!fp) {
        perror("Failed to open the file.");
        return 1;
    }

    while (fgets(NULL, sizeof(char), fp)) count_lines++;
    rewind(fp);

    FILE *ofp = fopen(output_file, "w");
    if (!ofp) {
        perror("Failed to open the output file.");
        return 1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        fprintf(ofp, "%s", line);
    }

    fclose(fp);
    fclose(ofp);
    printf("Counted %d lines in the input file.\n", count_lines);
    return 0;
}
