#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <unistd.h>
#include <sys/stat.h>
#include <getopt.h>

static char output_file[256] = "output.txt";
static int compact_format = 0;
static int manpage = 0;

void print_usage(const char *progname) {
    printf("Usage: %s [OPTIONS]\n", progname);
    printf("\t-i <input_directory>\n");
    printf("\t--manpage\n");
    printf("\t-cs\n");
    printf("\t-o <output_file>\n");
}

int main(int argc, char *argv[]) {
    int opt;
    DIR *dir;
    struct dirent *entry;
    FILE *input_file = NULL;
    FILE *output_file = stdout;

    while ((opt = getopt(argc, argv, "i:o:cs--manpage")) != -1) {
        switch (opt) {
            case 'i':
                strncpy(input_dir, optarg, sizeof(input_dir));
                break;
            case 'c':
                compact_format = 1;
                break;
            case 'o':
                strncpy(output_file, optarg, sizeof(output_file));
                output_file = fopen(output_file, "w");
                if (!output_file) {
                    perror("Could not open output file.");
                    return 1;
                }
                break;
            case ':':
                fprintf(stderr, "Missing argument for option -%c.\n", optopt);
                return 1;
            case '?':
                if (isprint(optopt))
                    fprintf(stderr, "Unknown option `-%c'.\n", optopt);
                else
                    fprintf(stderr, "Unknown option character `\\x%x'.\n", optopt);
                return 1;
            case '--manpage':
                manpage = 1;
                break;
        }
    }

    if (!input_dir[0]) {
        print_usage(argv[0]);
        return 0;
    }

    dir = opendir(input_dir);
    if (!dir) {
        perror("Could not open input directory.");
        return 1;
    }

    struct stat file_stat;
    size_t lines_count = 0;

    while ((entry = readdir(dir)) != NULL) {
        snprintf(input_file, sizeof(input_file), "%s/%s", input_dir, entry->d_name);
        if (stat(input_file, &file_stat) == -1 || !S_ISREG(file_stat.st_mode)) continue;

        input_file = fopen(input_file, "r");
        if (!input_file) {
            perror("Could not open file.");
            continue;
        }

        char c;
        while ((c = getc(input_file)) != EOF) {
            if (c == '\n') lines_count++;
        }
        fclose(input_file);

        printf("%s: %lu lines\n", entry->d_name, lines_count);
        lines_count = 0;
    }
    closedir(dir);

    if (manpage) print_usage(argv[0]);

    return 0;
}
```
