#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <dirent.h>
#include <sys/stat.h>
#include <pthread.h>

typedef struct {
    char dir[256];
    char pattern[256];
    int line_numbers;
    FILE *output_file;
    int compact;
} Args;

void* process_directory(void *data);
int is_match(const char *filename, const char *pattern);

int main(int argc, char **argv) {
    Args args = {};
    int i, opt;
    while ((opt = getopt(argc, argv, "d:o:f:hc:")) != -1) {
        switch (opt) {
            case 'd': strcpy(args.dir, optarg); break;
            case 'o': args.output_file = fopen(optarg, "w"); break;
            case 'f': strcpy(args.pattern, optarg); break;
            case 'c': args.compact = 1; break;
            case 'h': printf("Usage: %s [options]\n"
                             "-d <directory>          Specifies one or more directories containing text files to process.\n"
                             "--help                   Display this help message.\n"
                             "-c                       Output line numbers in a compact format.\n"
                             "-o <output_file>         Redirect the final report to a specified file instead of the console.\n"
                             "-f <file_pattern>       Specifies a file pattern to match within the directories (e.g., \"*.txt\").\n", argv[0]);
            default: printf("Invalid option: %c\n", optopt); return 1;
        }
    }

    pthread_t threads[256];
    DIR *root = opendir(args.dir);
    if (!root) {
        perror("Failed to open directory");
        return 1;
    }

    struct dirent *entry;
    while ((entry = readdir(root)) != NULL) {
        char path[512];
        snprintf(path, sizeof(path), "%s/%s", args.dir, entry->d_name);
        if (entry->d_type == DT_DIR && strcmp(entry->d_name, ".") && strcmp(entry->d_name, "..")) {
            process_directory(&args, path);
        } else if (is_match(entry->d_name, args.pattern)) {
            process_file(&args, path);
        }
    }
    closedir(root);

    if (args.output_file) fclose(args.output_file);
    return 0;
}

int is_match(const char *filename, const char *pattern) {
    if (!pattern[0]) return 1;
    size_t pattern_len = strlen(pattern);
    if (strncmp(filename + (pattern_len - strlen(pattern)), pattern, pattern_len)) return 0;
    size_t i;
    for (i = 0; filename[i] && i < pattern_len - 1; ++i) {
        if (filename[i] != '.') continue;
        if (!filename[i + 1]) return 0;
        for (size_t j = 1; j < pattern_len - i - 1; ++j) {
            if (pattern[j + i + 1] == '*' && pattern[j + i] != '.') break;
            if (filename[i + 1 + j] != pattern[j + i + 1]) return 0;
        }
    }
    return 1;
}

void* process_directory(void *data, const char *path) {
    Args *args = data;
    DIR *dir = opendir(path);
    if (!dir) {
        perror("Failed to open directory");
        pthread_exit(NULL);
    }

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char path2[512];
        snprintf(path2, sizeof(path2), "%s/%s", path, entry->d_name);
        if (entry->d_type == DT_DIR && strcmp(entry->d_name, ".") && strcmp(entry->d_name, "..")) {
            process_directory(data, path2);
        } else if (is_match(entry->d_name, args->pattern)) {
            process_file(data, path2);
        }
    }
    closedir(dir);
    pthread_exit(NULL);
}

void process_file(Args *args, const char *path) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        perror("Failed to open file");
        return;
    }

    char c;
    size_t line_num = 0;
    while ((c = fgetc(fp)) != EOF) {
        if (c == '\n') ++line_num;
        if (args->compact && line_num % 1000 == 0) {
            fprintf(args->output_file, "%zu\t%s\n", line_num, basename(path));
        } else {
            fprintf(args->output_file, "%zu: %s\n", line_num + 1, path);
        }
    }
    fclose(fp);
    args->line_numbers += line_num;
}

// Implement multithreading using pthread_join to collect the results from each thread.
