import java.io.*;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.util.concurrent.Semaphore;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.Arrays;
import java.util.concurrent.atomic.AtomicLong;
import java.nio.charset.StandardCharsets;

public class FileProcessor {
    private static final int MAX_FILE_SIZE = 1048576; // 1 MB in bytes
    private static final int RETRY_ATTEMPTS = 3;
    private static final AtomicLong totalFilesProcessed = new AtomicLong();
    private static final AtomicLong averageProcessingTime = new AtomicLong();
    private static final AtomicLong failures = new AtomicLong();
    private static Semaphore semaphore;

    public static void processFiles(List<String> filePaths, String hashAlgorithm) {
        if (semaphore == null) {
            semaphore = new Semaphore(Runtime.getRuntime().availableProcessors());
        }

        Executors.newCachedThreadPool().submit(() -> {
            try {
                Files.walkFileTree(Paths.get(""), new SimpleFileVisitor<Path>() {
                    @Override
                    public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) throws IOException {
                        semaphore.acquire();
                        return FileVisitResult.CONTINUE;
                    }

                    @Override
                    public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) throws IOException {
                        if (!attrs.isRegularFile() || attrs.size() > MAX_FILE_SIZE) return FileVisitResult.CONTINUE;

                        try (BufferedReader reader = new BufferedReader(new FileReader(file.toFile()));
             MessageDigest digest = MessageDigest.getInstance(hashAlgorithm)) {

                            FileLock lock = file.getFileSystem().getFileLock(file, false);
                            lock.noncachingLock();

                            try {
                                String line;
                                while ((line = reader.readLine()) != null) {
                                    digest.update(line.getBytes(StandardCharsets.UTF_8));
                                }

                                totalFilesProcessed.incrementAndGet();
                                averageProcessingTime.addAndGet(System.nanoTime() - startTime);
                            } finally {
                                lock.releaseLock();
                                reader.close();
                            }
                        } catch (Exception e) {
                            failures.incrementAndGet();
                            log.error("Error processing file: {}", file, e);
                        }

                        semaphore.release();
                        return FileVisitResult.CONTINUE;
                    }

                    @Override
                    public FileVisitResult postVisitDirectory(Path dir, IOException exc) throws IOException {
                        if (exc != null) log.error("Error visiting directory: {}", dir, exc);
                        semaphore.release();
                        return FileVisitResult.CONTINUE;
                    }
                });
            } catch (IOException e) {
                log.error("Error traversing filesystem", e);
            } finally {
                semaphore.drainPermits();
            }
        });
    }
}
