    def add_file_path(self, file_path):
        if not file_path: return
        self.file_queue.put(file_path)

    def process_files(self, hash_algorithm='md5'):
        while not self.file_queue.empty():
            self.semaphore.acquire()
            try:
                file_path = self.file_queue.get_nowait()
                if not os.path.exists(file_path) or not os.access(file_path, os.R_OK): continue

                file_lock = Lock()
                with file_lock:
                    with open(file_path, 'r') as f:
                        lines = sorted(f.readlines())
                        sequence_number = lines[-1].strip()

                self.total_files_processed += 1
                start_time = time()
                hash = hashlib.new(hash_algorithm).update(sequence_number.encode()).hexdigest()
                processing_time = time() - start_time
                self.average_processing_time += processing_time
            except Exception as e:
                self.failures += 1
                self.log.error("Error processing file: {}", file_path, e)
            finally:
                self.semaphore.release()

    def get_statistics(self):
        total_files = self.total_files_processed
        avg_processing_time = self.average_processing_time / total_files if total_files > 0 else 0
        return {
            'Total Files Processed': self.total_files_processed,
            'Average Processing Time (s)': avg_processing_time,
            'Failures Encountered': self.failures
        }
