#include <stdio.h>
#include <stdlib.h>
#include <getopt.h>
#include <sys/stat.h>
#include <string.h>

typedef struct {
    char *input_file;
    char *output_file;
    int line_count;
} options;

void usage(char *argv[]) {
    printf("Usage: %s [options]\n", argv[0]);
    printf("-h, --help                 Show this help message\n");
    printf("-c, --cs                   Specify character set for string generation (comma-separated)\n");
    printf("-o, --output_file           Output file (default: stdout)\n");
}

options parse_args(int argc, char **argv) {
    options opts;
    int opt;
    const char *const short_opts = "hcs:o:";
    const struct option long_opts[] = {
        {"manpage", no_argument, 0, 'h'},
        {"character_set", required_argument, 0, 'c'},
        {"output_file", required_argument, 0, 'o'},
        {0, 0, 0, 0}
    };

    memset(&opts, 0, sizeof(opts));

    while ((opt = getopt_long(argc, argv, short_opts, long_opts)) != -1) {
        switch (opt) {
            case 'h':
                usage(argv);
                exit(0);
            case 'c':
                opts.cs = optarg;
                break;
            case 'o':
                opts.output_file = optarg;
                break;
            default:
                usage(argv);
                exit(1);
        }
    }

    if (optind < argc) {
        opts.input_file = argv[optind];
    } else {
        opts.input_file = "";
    }

    return opts;
}

void line_count(FILE *file, int *lines) {
    char c;
    while ((c = fgetc(file)) != EOF) {
        if (c == '\n') ++*lines;
    }
}

int main(int argc, char **argv) {
    options opts = parse_args(argc, argv);
    FILE *input = fopen(opts.input_file, "r");
    FILE *output = stdout;
    if (opts.output_file && strcmp(opts.output_file, "-")) {
        output = fopen(opts.output_file, "w");
    }

    if (!input) {
        perror("Error opening input file");
        return 1;
    }

    int lines = 0;
    line_count(input, &lines);
    rewind(input);

    printf("Lines in file: %d\n", lines);

    fclose(input);
    if (output != stdout) fclose(output);
    return 0;
}
