<?php

class StringGenerator {
    private $charsets = [];
    private $hashes = ['sha256', 'sha384', 'sha512'];
    private $cache = [];
    private $log;

    public function __construct() {
        ini_set('memory_limit', '100M');
        $this->log = new SplFileObject('logs.log', 'w');
    }

    public function addCharset($charset) {
        $this->charsets[] = $charset;
    }

    public function generateRandomString($length, $hashAlgorithm = null) {
        if (!isset($this->cache[$length])) {
            $this->cache[$length] = str_shuffle(implode('', $this->charsets));
        }
        $string = substr($this->cache[$length], 0, $length);
        $hash = $hashAlgorithm ? hash($hashAlgorithm, $string) : null;
        $this->logStringGeneration($string, $hashAlgorithm);
        return [$string, $hash];
    }

    public function secureHashPassword($password, $hashAlgorithm) {
        $hashed = hash($hashAlgorithm, $password);
        $this->logPasswordHash($password, $hashAlgorithm);
        return $hashed;
    }

    private function logStringGeneration($string, $hashAlgorithm) {
        if ($this->log && strlen(trim($this->log->fgetContents())) >= 10 * (1024 * 1024)) {
            $this->log->rewind();
            $this->log->truncate(0);
        }
        $this->log->fwrite("String generated: {$string}, Hash algorithm: {$hashAlgorithm}\n");
    }

    private function logPasswordHash($password, $hashAlgorithm) {
        if ($this->log && strlen(trim($this->log->fgetContents())) >= 10 * (1024 * 1024)) {
            $this->log->rewind();
            $this->log->truncate(0);
        }
        $this->log->fwrite("Password hashed: {$password}, Hash algorithm: {$hashAlgorithm}\n");
    }
}
