typedef struct _node {
    NFAPI_RX_FRAME_PDU_T data;
    pthread_mutex_t mutex;
    struct _node* next;
    pthread_rwlock_t rw_lock; // Read-write lock for concurrent read and write access
} Node;

typedef struct {
    Node* head;
    Node* tail;
    int size;
    pthread_rwlock_t rw_list_lock; // Read-write lock for list operations
} DynamicList;

DynamicList* create_dynamic_list() {
    DynamicList* list = malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->size = 0;
    pthread_rwlock_init(&list->rw_list_lock, NULL);
    return list;
}

Node* create_node(NFAPI_RX_FRAME_PDU_T data) {
    Node* node = malloc(sizeof(Node));
    if (!node) return NULL;
    node->data = data;
    pthread_mutex_init(&node->mutex, NULL);
    node->next = NULL;
    pthread_rwlock_init(&node->rw_lock, NULL);
    return node;
}

void insert(DynamicList* list, NFAPI_RX_FRAME_PDU_T data) {
    Node* new_node = create_node(data);
    if (!new_node) return;

    pthread_rwlock_wrlock(&list->rw_list_lock);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_rwlock_unlock(&list->rw_list_lock);
}

NFAPI_RX_FRAME_PDU_T* find(DynamicList* list, uint32_t rnti) {
    Node *current = list->head;
    while (current != NULL) {
        pthread_rwlock_rdlock(&current->rw_lock);
        if (current->data.RX_UE_INFORMATION_TAG.ueIdentity.rnti == rnti) {
            pthread_rwlock_unlock(&current->rw_lock);
            return &current->data;
        }
        current = current->next;
        pthread_rwlock_unlock(&current->rw_lock);
    }
    return NULL;
}

void delete(DynamicList* list, uint32_t rnti) {
    Node *current = list->head;
    Node *prev = NULL;

    pthread_rwlock_wrlock(&list->rw_list_lock);
    while (current != NULL) {
        pthread_rwlock_rdlock(&current->rw_lock);
        if (current->data.RX_UE_INFORMATION_TAG.ueIdentity.rnti == rnti) {
            if (prev == NULL) { // head node to be deleted
                list->head = current->next;
                if (list->head == NULL) list->tail = NULL;
            } else {
                prev->next = current->next;
                if (current == list->tail) list->tail = prev;
            }
            free(current);
            list->size--;
            pthread_rwlock_unlock(&list->rw_list_lock);
            pthread_rwlock_unlock(&current->rw_lock);
            return;
        }
        prev = current;
        current = current->next;
        pthread_rwlock_unlock(&current->rw_lock);
    }
    pthread_rwlock_unlock(&list->rw_list_lock);
}
