public class ChecksumValidator {
    private final Configuration config;
    private final MessageDigest md5;
    private final OkHttpClient client;
    private final Cache<String, Map<String, BigInteger>> cache;

    public ChecksumValidator() throws Exception {
        File xml = new File("config.xml");
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        Document doc = factory.newDocumentBuilder().parse(xml);
        this.config = parseConfiguration(doc);
        this.md5 = MessageDigest.getInstance("MD5");
        this.client = new OkHttpClient();
        this.cache = CacheBuilder.newBuilder()
                .maximumWeightPercentage(config.getCacheWeight())
                .expireAfterAccess(config.getCacheDuration(), TimeUnit.SECONDS)
                .build();
    }

    public void validateChecksum(String input) {
        String hash = md5Hash(input);
        Map<String, BigInteger> cached = cache.getIfPresent(hash);
        if (cached != null && cached.containsKey("checksum")) {
            // Cache hit, checksum is valid
            logMetric("Cache Hit", "1");
            return;
        }

        ExecutorCompletionService<Void> executor = new ExecutorCompletionService<>(Executors.newFixedThreadPool(config.getThreadCount()));
        for (int i = 0; i < config.getMaxRetries(); i++) {
            Future<Void> future = executor.submit(() -> validateChecksumInternally(input, hash));
            if (!future.isDone()) {
                executor.take().thenAcceptAsync(ignored -> {}, executor);
            }
        }
    }

    private void validateChecksumInternally(String input, String hash) {
        try {
            Response response = client.newCall(new Request.Builder()
                    .url(config.getExternalServiceUrl())
                    .post(RequestBody.create(null, input))
                    .build())
                    .execute();
            if (response.isSuccessful()) {
                Map<String, BigInteger> responseData = parseResponse(response.body().string());
                if (responseData.containsKey("checksum")) {
                    synchronized (cache) {
                        cache.put(hash, responseData);
                    }
                    logMetric("Checksum Valid", "1");
                } else {
                    logMetric("Checksum Invalid", "1");
                }
            } else {
                logError("Request failed with status code: " + response.code());
            }
        } catch (IOException e) {
            logError(e.getMessage());
        }
    }

    private String md5Hash(String input) {
        byte[] digest = md5.digest(input.getBytes());
        BigInteger bi = new BigInteger(1, digest);
        return bi.toString(16);
    }

