import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;
import java.util.concurrent.ConcurrentLinkedQueue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class DataProcessor {
    private static final String DB_URL = "jdbc:mysql://localhost:3306/mydatabase";
    private static final String DB_USER = "username";
    private static final String DB_PASSWORD = "password";

    public void processData(Queue<String> dataSource) {
        Connection connection = null;
        try {
            connection = DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
            PreparedStatement statement = connection.prepareStatement("INSERT INTO hashes (data, hash) VALUES (?, ?)");
            ExecutorService executor = Executors.newFixedThreadPool(10); // Adjust the number of threads based on your system's capabilities

            List<String> batchData = new ArrayList<>();

            Runnable dataProcessor = () -> {
                while (!batchData.isEmpty()) {
                    String data = batchData.remove();
                    byte[] hash = getMD5(data);
                    statement.setString(1, data);
                    statement.setBytes(2, hash);
                    statement.addBatch();
                }
                statement.executeBatch();
            };

            while (!dataSource.isEmpty()) {
                String data = dataSource.poll();
                if (batchData.size() >= 1000) { // Adjust the batch size based on your requirements and constraints
                    executor.submit(dataProcessor);
                } else {
                    batchData.add(data);
                }
            }

            executor.shutdown();
        } catch (Exception e) {
            System.err.println("Error processing data: " + e.getMessage());
        } finally {
            if (connection != null) {
                try {
                    connection.close();
                } catch (Exception e) {
                    System.err.println("Error closing database connection: " + e.getMessage());
                }
            }
        }
    }

    private byte[] getMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes());
            BigInteger number = new BigInteger(1, messageDigest);
            StringBuilder hashtext = new StringBuilder(number.toString(16));
            while (hashtext.length() < 32) {
                hashtext.insert(0, "0");
            }
            return hashtext.toString().getBytes();
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
