    pthread_mutex_lock(&queue->queue_mutex);
    queue->messages[(queue->tail + 1) % queue->max_queue_size] = message;
    queue->tail = (queue->tail + 1) % queue->max_queue_size;
    pthread_mutex_unlock(&queue->queue_mutex);
    sem_post(&queue->queue_sem); // Signal that a message was added to the queue
}

NR_DL_CCCH_MESSAGE_T ccch_queue_dequeue(CCCH_QUEUE* queue) {
    NR_DL_CCCH_MESSAGE_T result;
    sem_wait(&queue->queue_sem); // Wait if the queue is empty
    pthread_mutex_lock(&queue->queue_mutex);
    if (queue->head != queue->tail) {
        result = queue->messages[queue->head];
        queue->head = (queue->head + 1) % queue->max_queue_size;
