import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.ConcurrentLinkedQueue;
import java.util.LinkedList;
import java.util.Properties;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class DataProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(DataProcessor.class);

    private ConcurrentLinkedQueue<String> inputQueue;
    private DistributedDatabase db;
    private Properties props;
    private MessageDigest md5;
    private ExecutorService executor;
    private int maxConcurrentWrites;
    private long currentWorkload;
    private long processedItems;
    private long failedItems;
    private static final int BATCH_SIZE = 1000; // Adjust this value based on your specific use case

    public DataProcessor(DistributedDatabase db, Properties props) {
        this.db = db;
        this.props = props;
        md5 = MessageDigest.getInstance("MD5");
        inputQueue = new ConcurrentLinkedQueue<>();
        executor = Executors.newCachedThreadPool();
        maxConcurrentWrites = Integer.parseInt(props.getProperty("maxConcurrentWrites"));
    }

    public void enqueue(String data) {
        inputQueue.offer(data);
    }

    public void process() {
        currentWorkload = inputQueue.size();
        LOGGER.info("Starting to process workload of {} items", currentWorkload);

        Runnable hashAndSaveTask = new HashAndSaveTask();
        while (!inputQueue.isEmpty()) {
            // Limit the number of concurrent write operations based on maxConcurrentWrites property
            synchronized (executor) {
                if (executor.getActiveCount() < maxConcurrentWrites) {
                    executor.execute(hashAndSaveTask);
                } else {
                    try {
                        executor.wait();
                    } catch (InterruptedException e) {
                        Thread.currentThread().interrupt();
                        LOGGER.error("Interrupted while waiting for an available thread", e);
                    }
                }
            }
        }

        if (!executor.isShutdown()) {
            executor.shutdownNow();
        }

        LOGGER.info("Processed {} items, failed to process {} items", processedItems, failedItems);
    }

    private class HashAndSaveTask implements Runnable {
        @Override
        public void run() {
            while (true) {
                String data = inputQueue.poll();
                if (data == null) {
                    break;
                }

                byte[] hash = md5.digest(data.getBytes(StandardCharsets.UTF_8));

                try {
                    db.put(hashToString(hash), data);
                    processedItems++;
                } catch (Exception e) {
                    failedItems++;
                    // Implement a retry strategy here, for example by waiting and re-enqueuing the item
                }
            }
        }
    }

    private String hashToString(byte[] hash) {
        StringBuilder sb = new StringBuilder();
        for (byte b : hash) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
