typedef struct {
    int id;
    void *property;
} Vertex;

typedef struct {
    Vertex *v1, *v2;
    int weight;
} Edge;

typedef struct Graph {
    int vertices_count, edges_count;
    Vertex **vertices, *empty_vertex;
    Edge **edges;
    int max_vertices, max_edges;
    pthread_mutex_t mutex;
} Graph;

Graph *create_graph(int max_vertices, int max_edges) {
    Graph *g = malloc(sizeof(Graph));
    g->max_vertices = max_vertices;
    g->max_edges = max_edges;
    g->vertices_count = 0;
    g->edges_count = 0;
    g->empty_vertex = calloc(1, sizeof(Vertex));
    g->vertices = malloc(g->max_vertices * sizeof(Vertex*));
    for (int i = 0; i < g->max_vertices; ++i) {
        g->vertices[i] = g->empty_vertex;
    }
    g->edges = malloc(g->max_edges * sizeof(Edge*));
    pthread_mutex_init(&g->mutex, NULL);
    return g;
}

void add_vertex(Graph *g, Vertex *v) {
    if (g->vertices_count >= g->max_vertices) return;
    v->id = g->vertices_count++;
    pthread_mutex_lock(&g->mutex);
    g->vertices[g->vertices_count - 1] = v;
    pthread_mutex_unlock(&g->mutex);
}

void add_edge(Graph *g, Edge *e) {
    if (g->edges_count >= g->max_edges) return;
    pthread_mutex_lock(&g->mutex);
    g->edges[g->edges_count++] = e;
    pthread_mutex_unlock(&g->mutex);
}

