        }

        if (fields.front() == "END_USER") {
            profiles.push_back(currentUser);
            currentUser = UserProfile();
        }
    }

    inputFile.close();
}

void processBatch(const std::vector<UserProfile>& profiles, std::ofstream* outputFile) {
    if (profiles.empty()) {
        return;
    }

    auto numThreads = std::thread::hardware_concurrency();
    std::vector<std::future<void>> futures;

    for (size_t i = 0; i < profiles.size(); ++i) {
        size_t index = i;
        futures.emplace_back(std::async(std::launch::async, [=]() { processOperation("batch", profiles[index], outputFile); }));

        if ((i + 1) % numThreads == 0) {
            for (auto& future : futures) {
                future.wait();
            }
            futures.clear();
        }
    }

    for (auto& future : futures) {
        future.wait();
    }
}

