void setNetworkStats(TCP_CONNECTION_REQUEST* request) {
    request->bandwidth = getBandwidth(); // replace with your function to retrieve bandwidth
    request->latency = random() % 5 + 3 * 0.1; // random latency between 3 and 8 tenths of a second
    request->congestionLevel = (double)(random() % 100) / 100.0; // random congestion level between 0 and 1
}

void setPacketProperties(NETWORK_LAYER_PACKET* packet, double latency) {
    int packetSize = latency * request->bandwidth * 2 + 16 * random() / RAND_MAX; // packet size based on bandwidth and latency
    packet->packetSize = packetSize % 65536; // ensure it fits in a 16-bit field
    packet->type = random() % 10; // random packet type
}

void setConnectionRequest(TCP_CONNECTION_REQUEST* request) {
    srand(time(NULL));

    setNetworkStats(request);
    request->packet.packetSize = 0;
    request->packet.type = 0;

    setPacketProperties(&request->packet, request->latency);
}

TCP_CONNECTION_REQUEST* createConnectionRequests(unsigned int numRequests) {
    TCP_CONNECTION_REQUEST* requests = malloc(numRequests * sizeof(TCP_CONNECTION_REQUEST));

    for (int i = 0; i < numRequests; ++i) {
        setConnectionRequest(&requests[i]);
    }

    return requests;
}
