void init_array(NFAPI_CRC_INDICATION_PDU_T*** array, size_t* capacity) {
    *array = malloc(*capacity * sizeof(**array));
    if (!*array) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
}

void resize_array(NFAPI_CRC_INDICATION_PDU_T*** array, size_t new_capacity, size_t* current_size) {
    NFAPI_CRC_INDICATION_PDU_T** temp = malloc(new_capacity * sizeof(**temp));
    if (!temp) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    if (*current_size > 0) {
        memcpy(temp, *array, *current_size * sizeof(**array));
        free(*array);
    }

    *array = temp;
    *capacity = new_capacity;
}

void push_back(NFAPI_CRC_INDICATION_PDU_T*** array, size_t* capacity, size_t* current_size, const NFAPI_CRC_INDICATION_PDU_T* element) {
    if (*current_size >= *capacity) {
        resize_array(array, *capacity * 2 + 1, current_size);
    }
    (*array)[*current_size] = *element;
    ++(*current_size);
}

void pop_back(NFAPI_CRC_INDICATION_PDU_T*** array, size_t* capacity, size_t* current_size) {
    if (*current_size > 0) {
        --(*current_size);
        if (*current_size < *capacity / 2 && *capacity > 16) {
            resize_array(array, *capacity / 2 + 1, current_size);
        }
    }
}

void set_element(NFAPI_CRC_INDICATION_PDU_T*** array, size_t index, const NFAPI_CRC_INDICATION_PDU_T* element) {
