typedef struct {
    size_t capacity, size;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t mutex; // Remove this for thread-safety without locks or mutexes
} ThreadSafeDynamicArray;

ThreadSafeDynamicArray* create_tsda(size_t initial_capacity) {
    ThreadSafeDynamicArray* tsd = malloc(sizeof(ThreadSafeDynamicArray));
    if (!tsd) return NULL;

    tsd->data = calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!tsd->data) {
        free(tsd);
        return NULL;
    }

    pthread_mutex_init(&tsd->mutex, NULL);
    tsd->capacity = initial_capacity;
    tsd->size = 0;
    return tsd;
}

void destroy_tsda(ThreadSafeDynamicArray* tsd) {
    if (!tsd) return;

    free(tsd->data);
    pthread_mutex_destroy(&tsd->mutex);
    free(tsd);
}

size_t get_next_index(ThreadSafeDynamicArray* tsd) {
    return tsd->size % tsd->capacity;
}

void push_back(ThreadSafeDynamicArray* tsd, const NFAPI_CRC_INDICATION_PDU_T* data) {
    size_t index = get_next_index(tsd);

    // Resize if necessary
    if (tsd->size == tsd->capacity) {
        tsd->capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(tsd->data, tsd->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            fprintf(stderr, "Out of memory!\n");
            return;
        }
        tsd->data = new_data;
    }

    pthread_mutex_lock(&tsd->mutex);
    tsd->data[index] = *data;
    ++tsd->size;
    pthread_mutex_unlock(&tsd->mutex);
}

