import java.math.BigInteger;
import java.nio.charSet.StandardCharsets;
import java.security.MessageDigest;
import java.util.ConcurrentMap;
import java.util.HashMap;
import java.util.LinkedList;
import java.util.Queue;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class HashGenerator {
    private static final Logger LOGGER = LoggerFactory.getLogger(HashGenerator.class);

    private static final int BATCH_SIZE = 100;
    private static final int MAX_THREADS = Runtime.getRuntime().availableProcessors() * 2;
    private static final OkHttpClient httpClient = new OkHttpClient();

    public ConcurrentMap<String, BigInteger> generateHashes(List<String> strings) {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);
        Queue<List<String>> batchQueue = new LinkedList<>();

        for (int i = 0; i < strings.size(); i += BATCH_SIZE) {
            int batchEnd = Math.min(i + BATCH_SIZE, strings.size());
            batchQueue.offer(strings.subList(i, batchEnd));
        }

        ConcurrentMap<String, BigInteger> hashes = new HashMap<>();

        while (!batchQueue.isEmpty()) {
            List<String> currentBatch = batchQueue.poll();
            executor.submit(() -> {
                for (String str : currentBatch) {
                    try {
                        BigInteger hash = calculateSHA256(str);
                        synchronized (hashes) {
                            hashes.put(str, hash);
                        }
                    } catch (Exception e) {
                        LOGGER.error("Failed to generate SHA-256 for {}", str, e);
                        if (shouldFallback(e)) {
                            BigInteger fallbackHash = getExternalHash(str);
                            synchronized (hashes) {
                                hashes.put(str, fallbackHash);
                            }
                        }
                    }
                }
            });
        }

        executor.shutdown();
        executor.awaitTermination(1, TimeUnit.HOURS);

        return hashes;
    }

    private BigInteger calculateSHA256(String str) throws Exception {
        MessageDigest digest = MessageDigest.getInstance("SHA-256");
        byte[] hashBytes = digest.digest(str.getBytes(StandardCharsets.UTF_8));
        BigInteger hash = new BigInteger(1, hashBytes);
        return hash;
    }

    private BigInteger getExternalHash(String str) {
        Request request = new Request.Builder()
                .url("https://hashing-api.com/sha256/" + URLEncoder.encode(str, StandardCharsets.UTF_8))
                .build();

        Response response = httpClient.newCall(request).execute();
        if (!response.isSuccessful()) {
            throw new RuntimeException("Failed to fetch SHA-256 from external service: " + response);
        }

        String responseBody = response.body().string();
        return new BigInteger(responseBody, 16);
    }

    private boolean shouldFallback(Exception e) {
        // Customize the fallback logic based on the error type and severity
        return e instanceof SocketTimeoutException || e instanceof UnknownHostException;
    }
}
