};

void init_custom_allocator(struct custom_allocator* alloc) {
    alloc->memory_pool = malloc(1 << 20); // Initial allocation of 1MB
    alloc->total_size = alloc->used_size = alloc->free_size = 1 << 20;
    alloc->mutex = PTHREAD_MUTEX_INITIALIZER;
}

void* custom_alloc(void* data, size_t size, struct custom_allocator* alloc) {
    pthread_mutex_lock(&alloc->mutex);
    if (alloc->free_size >= size) {
        void* ptr = alloc->memory_pool + alloc->free_size;
        alloc->free_size -= size;
        alloc->used_size += size;
        pthread_mutex_unlock(&alloc->mutex);
        return ptr;
    } else {
        pthread_mutex_unlock(&alloc->mutex);
        void* ptr = malloc(size);
        if (!ptr) {
            // Handle out-of-memory condition
        }
        alloc->used_size += size;
        return ptr;
    }
}

void custom_free(void* data, size_t size, struct custom_allocator* alloc) {
    pthread_mutex_lock(&alloc->mutex);
    alloc->free_size += size;
    alloc->used_size -= size;
    pthread_mutex_unlock(&alloc->mutex);
    free(data);
}

