import org.json.JSONObject;
import java.io.*;
import java.net.URI;
import java.nio.file.*;
import java.time.Instant;
import java.util.ConcurrentLinkedQueue;
import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

public class FileMetadataProcessor {
    private static final int MAX_CONCURRENT = 10;
    private static final int MAX_RETRIES = 3;
    private static final long RETRY_BACKOFF_MILLIS = TimeUnit.SECONDS.toMillis(2);
    private static final String FALLBACK_SERVICE_URL = "https://metadata-service.com/getMetadata";
    private static final ExecutorService pool = Executors.newFixedThreadPool(MAX_CONCURRENT);
    private static final ConcurrentLinkedQueue<File> queue = new ConcurrentLinkedQueue<>();
    private static final Map<String, JSONObject> results = new HashMap<>();

    public static Map<String, JSONObject> process(List<String> filePaths) {
        for (String filePath : filePaths) {
            queue.offer(new File(filePath));
        }
        processQueue();
        return results;
    }

    private static void processQueue() {
        while (!queue.isEmpty()) {
            File file = queue.poll();
            if (file == null || !file.exists() || !file.isFile()) {
                continue;
            }
            String key = file.getPath();
            Path metadataPath = getMetadataPath(key);
            if (Files.exists(metadataPath)) {
                try {
                    JSONObject value = new JSONObject(Files.readString(metadataPath));
                    results.put(key, value);
                } catch (IOException | JSONException e) {
                    // Handle parsing errors gracefully
                }
            } else {
                pool.submit(() -> processFile(file)).exceptionally((Throwable t) -> {
                    if (!t.getCause().getMessage().contains("No such file or directory")) {
                        System.err.println("Error processing file: " + file.getPath() + ", error: " + t.getMessage());
                    }
                    return null;
                });
            }
        }
    }

    private static Path getMetadataPath(String key) {
        return Files.createDirectories(Paths.get("metadata")).thenResolve(Paths.get(key + ".json"));
    }

    private static JSONObject processFile(File file) {
        try (CloseableHttpClient client = HttpClients.createDefault()) {
            URI uri = new URI(FALLBACK_SERVICE_URL + "?path=" + URLEncoder.encode(file.getPath(), "UTF-8"));
            int retries = MAX_RETRIES;
            do {
                HttpGet request = new HttpGet(uri);
                CloseableHttpResponse response = client.execute(request);
                if (response.getStatusLine().getStatusCode() == 200) {
                    String metadataJson = EntityUtils.toString(response.getEntity());
                    JSONObject json = new JSONObject(metadataJson);
                    results.put(FilenameUtils.getBaseName(file.getPath()) + "_" + file.getName(), json);
                    saveToFile(getMetadataPath(results.keySet().iterator().next()), json.toString());
                    return json;
                } else {
                    retries--;
                }
            } while (retries > 0 && !response.getStatusLine().isSuccess());
        } catch (IOException | URISyntaxException e) {
            // Handle network errors gracefully
        }

        try {
            FileType fileType = FileType.fromFile(file);
            Instant lastModified = Files.getLastModifiedTime(file.toPath());
            long size = Files.size(file.toPath());
            JSONObject json = new JSONObject()
                    .put("type", fileType.getValue())
                    .put("size", size)
                    .put("lastModified", lastModified.toEpochMilli());
            results.put(FilenameUtils.getBaseName(file.getPath()) + "_" + file.getName(), json);
            saveToFile(getMetadataPath(results.keySet().iterator().next()), json.toString());
            return json;
        } catch (IOException e) {
            // Handle local I/O errors gracefully
        }

        return null;
    }

    private static void saveToFile(Path path, String content) throws IOException {
        try (Writer writer = new BufferedWriter(new FileWriter(path.toFile()))) {
            writer.write(content);
        }
    }
}

enum FileType {
    TEXT("text/plain"),
    IMAGE("image/*"),
    VIDEO("video/*"),
    AUDIO("audio/*");

    private final String value;

    FileType(String value) {
        this.value = value;
    }

    public static FileType fromFile(File file) {
        if (file.isDirectory()) {
            return null;
        }

        MimetypesFileTypeMap mimetypes = new MimetypesFileTypeMap();
        return FileType.valueOf(mimetypes.getContentType(file));
    }
}
```

