import os
import json
import requests
from threading import Thread
from concurrent.futures import ThreadPoolExecutor, as_completed
from logzero import logger, logzero
from aiohttp import web, WPSession
from queue import Queue
import time
from datetime import datetime
import yaml

class WebpageMetadataFetcher:
    def __init__(self, config_path, timeout=5, max_retries=3, fallback_service='', **kwargs):
        with open(config_path) as f:
            self.config = yaml.safe_load(f)
        self.timeout = timeout
        self.max_retries = max_retries
        self.fallback_service = fallback_service

    async def fetch_metadata(self, url):
        try:
            response = await requests.get(url, timeout=self.timeout)
            response.raise_for_status()
            return {
                'url': url,
                'status_code': response.status_code,
                'title': response.headers['Title'],
                'content_type': response.headers['Content-Type']
            }
        except requests.exceptions.RequestException as e:
            logger.error(f"Error fetching metadata for {url}: {e}")
            if self.fallback_service:
                async with WPSession() as session:
                    retries = min(self.max_retries, 1)
                    start_time = time.monotonic()
                    retry_interval = (2**retries - 1) * (start_time - time.monotonic()) / (retries + 1)
                    try:
                        response = await session.get(url, timeout=self.timeout)
                        if response.status_code == 200:
                            return {
                                'url': url,
                                'status_code': response.status_code,
                                'title': response.headers['Title'],
                                'content_type': response.headers['Content-Type']
                            }
                    except requests.exceptions.RequestException as e:
                        if (time.monotonic() - start_time) > retry_interval:
                            raise Exception(f"Failed to fetch metadata for {url} after {retries} retries.") from e

    def process_urls(self, urls):
        completed = Queue()
        with ThreadPoolExecutor(max_workers=self.config['concurrency']) as executor:
            for url in urls:
                executor.submit(self._process_url, url, completed)
            for _ in range(len(urls)):
                result = completed.get()
                self.log_and_monitor(result['url'], result['status_code'])

    def _process_url(self, url, completion_queue):
        metadata = None
        for i in range(self.max_retries + 1):
            try:
                asyncio_loop = web.run_loop(lambda: self.fetch_metadata(url))
                metadata = next(asyncio_loop)['result']
                break
            except Exception as e:
                logger.error(f"Failed to fetch metadata for {url}: {e}")
                if i < self.max_retries:
                    continue
                else:
                    logger.warning(f"Giving up on {url} after max retries.")
        completion_queue.put((url, metadata))

    def log_and_monitor(self, url, status_code):
        current_time = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        logger.info(f"{current_time} - Processed {url} ({status_code})")

    def run(self, urls):
        self.process_urls(urls)

