void print_help() {
    std::cout << "Usage: [executable] [-c | --help | -o output_file]\n"
              << "\t-c : Count lines in a specified input file\n"
              << "\t--help : Display this help message\n"
              << "\t-o output_file : Write the result to the specified output file\n";
}

int main(int argc, char **argv) {
    bool count = false;
    bool help = false;
    std::string output_file;

    for (int i = 1; i < argc; ++i) {
        if (!strcasecmp(*(argv + i), "--help")) {
            help = true;
        } else if (!strcasecmp(*(argv + i), "-c")) {
            count = true;
        } else if (!strcasecmp(*(argv + i), "-o")) {
            if (++i >= argc) {
                std::cerr << "Error: Missing output file for -o\n";
                print_help();
                return 1;
            }
            output_file = *(argv + i);
        } else {
            std::cerr << "Error: Unrecognized argument: " << *(argv + i) << "\n";
            print_help();
            return 1;
        }
    }

    if (help) {
        print_help();
        return 0;
    }

    if (count && argc < 3) {
        std::cerr << "Error: No input file provided with -c\n";
        print_help();
        return 1;
    }

    size_t line_count = 0;
    std::ifstream input_file;

    if (count) {
        if (argc < 3) {
            std::cerr << "Error: No input file provided with -c\n";
            print_help();
            return 1;
        }
        input_file.open(*(argv + 2));

        if (!input_file.is_open()) {
            std::cerr << "Error: Cannot open the specified input file\n";
            print_help();
            return 1;
        }

        char c;
        while (input_file.get(c)) {
            if (c == '\n')
                ++line_count;
        }
        input_file.close();
    }

    std::ofstream output_stream;

    if (!count && !output_file.empty()) {
        output_stream.open(output_file, std::ios_base::app);

        if (!output_stream.is_open()) {
            std::cerr << "Error: Cannot open the specified output file\n";
            print_help();
            return 1;
        }
    } else if (count && line_count > 0) {
        std::cout << line_count << "\n";
    }

    if (output_stream.is_open()) {
        if (count)
            output_stream << line_count << "\n";
        output_stream.close();
    }

    return 0;
}
