        RX_UE_INFORMATION_TAG rx_ue_information_tag = read_from_external_source();
        RNTI rnti = generate_rnti();
        update_session(sessions[hash(rx_ue_information_tag, 1024)], rx_ue_information_tag, rnti);
    }

    // Cleanup the sessions when needed
    for (size_t i = 0; i < ARRAY_SIZE(threads); ++i) {
        pthread_join(threads[i], NULL);
    }
    for (size_t i = 0; i < ARRAY_SIZE(sessions); ++i) {
        destroy_session(&sessions[i]);
    }

    return 0;
}
