namespace CommandLineProcessor
{
    class Program
    {
        static void Main(string[] args)
        {
            Action action = null;
            string inputFile = null, outputFile = "result.txt";

            if (args.Contains("--help"))
                PrintUsageAndExit();

            var actionArgs = args.Where(arg => !new []{ "--help", "-c", "-o"}.Contains(arg)).ToArray();
            if (actionArgs.Length > 1)
            {
                PrintUsageAndExit();
            }

            switch (args[0])
            {
                case "-c":
                    action = CountLines;
                    inputFile = args[1];
                    break;
                case "-o":
                    outputFile = args[1];
                    break;
            }

            if (action != null)
            {
                try
                {
                    action();
                    File.WriteAllText(outputFile, inputFile == null ? "" : $"Number of lines: {LineCount}");
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"An error occurred: {ex.Message}");
                }
            }
            else if (string.IsNullOrEmpty(inputFile))
            {
                PrintUsageAndExit();
            }
        }

        private static void CountLines()
        {
            if (!File.Exists(inputFile) || string.IsNullOrWhiteSpace(File.ReadAllText(inputFile)))
            {
                throw new Exception("The specified input file is empty or does not exist.");
            }

            LineCount = File.ReadLines(inputFile).Count();
        }

        private static int LineCount;
        private static void PrintUsageAndExit()
        {
            Console.WriteLine(@"CommandLineProcessor:
    --help             Display this help message and exit.
    -c [FILE]          Count the number of lines in an input file. If no file is provided, use stdin.
    -o [OUTPUT_FILE]   Specify the output file for the result. Defaults to 'result.txt'.");
            Environment.Exit(0);
        }

        public static XElement? GetWebConfigFile(string directoryPath, string siteName)
        {
