void error(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

int parse_arguments(int argc, char **argv, Context *context) {
    static const char *usage = "Usage: program [options] input_file";
    static const struct option long_options[] = {
        {"manpage", no_argument, NULL, 'h'},
        {"count-empty", no_argument, NULL, 'c'},
        {"output", required_argument, NULL, 'o'},
        {"verbose", no_argument, NULL, 'v'},
        {0}
    };
