                exit(EXIT_SUCCESS);
            case 'c':
                context->line_count = 0;
                break;
            case 'o':
                context->output_file = fopen(optarg, "w");
                if (!context->output_file) {
                    error("Could not open output file: ");
                }
                break;
            case 'v':
                context->verbose = 1;
                break;
            case ':':
                error("Missing argument for option -");
                exit(EXIT_FAILURE);
        }
    }

    if (optind >= argc) {
        error("No input file provided.");
    }

    context->input_file = fopen(argv[optind], "r");
    if (!context->input_file) {
        error("Could not open input file: ");
    }

    return 1;
}

void log_line_position(Context *context, size_t position) {
    if (context->output_file && !ferror(context->input_file)) {
        fprintf(context->output_file, "%zu\n", position);
        context->position = position;
    }
}

void read_line(Context *context) {
    static char buffer[4096];
    size_t nread = fread(buffer, sizeof(char), sizeof(buffer), context->input_file);
    if (nread == 0) {
        return;
    }
    buffer[nread] = '\0';
    log_line_position(context, context->position + context->line_count);
    context->line_count++;

    // Process line here
}

int main(int argc, char **argv) {
    Context context;
    memset(&context, 0, sizeof(context));

    if (!parse_arguments(argc, argv, &context)) {
        return EXIT_FAILURE;
    }

    while (read_line(&context)) {}

    if (context.output_file) {
        fclose(context.output_file);
    }

    if (!context.verboses && !context.count_empty) {
        printf("%d lines\n", context.line_count);
    } else if (context.verbose) {
        printf("Lines processed: %d\n", context.line_count);
        printf("Total positions logged: %zu\n", ftell(context.input_file));
    }
    return EXIT_SUCCESS;
}
