    strncpy(new_iface->iface, interface, IF_NAMESIZE);
    pthread_mutex_init(&new_iface->lock, NULL);
    new_iface->head = NULL;
    new_iface->data_points = 0;
    *interfaces = new_iface;
}

void add_metric(InterfaceData* iface, LinkMetric* metric) {
    pthread_mutex_lock(&iface->lock);
    metric->timestamp = time(NULL);
    if (iface->head == NULL) {
        iface->head = metric;
    } else {
        LinkMetric* current = iface->head;
        while (current->next != NULL)
            current = current->next;
        current->next = metric;
    }
    ++iface->data_points;
    pthread_mutex_unlock(&iface->lock);
}

