import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.*;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

public class FileProcessor {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileProcessor.class);

    public Map<String, String> processFileHashes(List<String> filePaths) throws ExecutionException, InterruptedException {
        ExecutorService executor = Executors.newFixedThreadPool(Math.min(Runtime.getRuntime().availableProcessors(), 10));
        Map<String, Future<String>> tasks = new ConcurrentHashMap<>();

        for (String filePath : filePaths) {
            Callable<String> callable = () -> {
                String hash;
                try {
                    Path path = FileSystems.getDefault().getPath(filePath);
                    if (!Files.exists(path)) {
                        LOGGER.error("File not found: {}", filePath);
                        return null;
                    }

                    if (!Files.isRegularFile(path) || !Files.isReadable(path)) {
                        LOGGER.warn("Unable to read file: {}", filePath);
                        return null;
                    }

                    if (!Files.isExecutable(path)) {
                        LOGGER.warn("File not executable: {}", filePath);
                        return null;
                    }

                    byte[] bytes = Files.readAllBytes(path);
                    MessageDigest md5 = MessageDigest.getInstance("MD5");
                    hash = byteArrayToHex(md5.digest(bytes));
                    LOGGER.debug("Calculated MD5 for file: {}", filePath);
                } catch (Exception e) {
                    LOGGER.error("Error processing file: {}", filePath, e);
                    return null;
                }
                return hash;
            };

            Future<String> task = executor.submit(callable);
            tasks.put(filePath, task);
        }

        Map<String, String> results = new HashMap<>();
        for (Map.Entry<String, Future<String>> entry : tasks.entrySet()) {
            try {
                String hash = entry.getValue().get();
                if (hash != null) {
                    LOGGER.info("Successfully processed file: {}", entry.getKey());
                    results.put(entry.getKey(), hash);
                }
            } catch (Exception e) {
                LOGGER.error("Error getting result for file: {}", entry.getKey(), e);
            }
        }

        executor.shutdown();
        return results;
    }

    private String byteArrayToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }
        return sb.toString();
    }
}
