#include <sys/mman.h>
#include <json-c/json.h>

typedef struct {
    const char* format;
    int (*validator)(const char* line);
} Format;

Format formats[] = {
    {"txt", isalpha},
    {"csv", strchr},
    {"json", json_object_fromstring}
};

void log(const char* fmt, ...) {
    va_list args;
    FILE* log_file = fopen("error.log", "a");
    va_start(args, fmt);
    vfprintf(log_file, fmt, args);
    va_end(args);
    fclose(log_file);
}

bool is_valid_format(const char* filename) {
    for (int i = 0; i < sizeof(formats)/sizeof(Format); ++i) {
        const Format& format = formats[i];
        if (strchr(filename, '.') && strcmp(strrchr(filename, '.'), format.format) == 0)
            return true;
    }
    return false;
}

int validate_line(const char* line, int (*validator)(const char*)) {
    if (!validator(line))
        log("Invalid line: '%s'\n", line);
    return !!*validator(line);
}

long long read_file(FILE* file, void (*callback)(const char* line)) {
    long long count = 0;
    while (1) {
        char buf[4096];
        size_t len = fread(buf, sizeof(char), sizeof(buf), file);
        if (len == 0) break;
        for (size_t i = 0; i < len; ++i) {
            if (validate_line(&buf[i], callback)) ++count;
        }
    }
    return count;
}

int main(int argc, char* argv[]) {
    bool manpage = false, cs = true, output_set = false;
    const char* input_file = NULL, *output_file = "output.txt";
    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "--manpage")) manpage = true;
        else if (!strcmp(argv[i], "-cs") && ++i < argc) cs = !strcmp(argv[i], "insensitive");
        else if (!output_set && !strchr(argv[i], '.')) {
            input_file = argv[i];
            output_set = true;
        }
        else if (!output_set) output_file = argv[i];
    }

    if (!input_file || !is_valid_format(input_file)) {
        fprintf(stderr, "Usage: %s [--manpage] [-cs sensitive|insensitive] input_file [-o output_file]\n", argv[0]);
        return 1;
    }

    FILE* file = fopen(input_file, "r");
    if (!file) {
        log("Error opening input file: %s\n", strerror(errno));
        return 2;
    }

    void* mapped = mmap(NULL, getpagesize(), PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (mapped == MAP_FAILED) {
        log("Error mapping input file: %s\n", strerror(errno));
        fclose(file);
        return 3;
    }

    char* data = static_cast<char*>(mapped);
    size_t len = lseek(fileno(file), 0, SEEK_END);
    munmap(mapped, getpagesize());
    rewind(file);

    long long valid_lines = read_file(file, [](const char* line) {
        for (int i = 0; i < sizeof(formats)/sizeof(Format); ++i) {
            if (formats[i].validator && formats[i].validator(line))
                return true;
        }
        return false;
    });

    printf("Total valid lines: %lld\n", valid_lines);

    if (!manpage) {
        FILE* out = fopen(output_file, "w");
        if (!out) {
            log("Error opening output file: %s\n", strerror(errno));
            return 4;
        }
        fwrite(data, sizeof(char), len, out);
        fclose(out);
    }

    fclose(file);
    return 0;
}
