import org.apache.commons.io.FileUtils;
import org.apache.commons.codec.digest.DigestUtils;
import java.io.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;

public class FileHasher {
    private final ExecutorService executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
    private final int retryAttempts = 3;
    private final int chunkSize = 1024 * 8; // 8KB file chunks
    private final Map<String, String> processedFiles = new ConcurrentHashMap<>();
    private final Logger logger = LoggerFactory.getLogger(FileHasher.class);

    public Map<String, String> calculateHashes(List<String> filePaths) {
        Callable<Map.Entry<String, String>> fileHasherCallable = new FileHasherCallable();
        List<Future<Map.Entry<String, String>>> futures = executor.invokeAll(filePaths.stream()
                .map(f -> CompletableFuture.supplyAsync(() -> fileHasherCallable.call(f)))
                .collect(Collectors.toList()));

        Map<String, String> result = new HashMap<>();
        for (Future<Map.Entry<String, String>> future : futures) {
            try {
                Map.Entry<String, String> entry = future.get();
                if (entry != null) {
                    result.put(entry.getKey(), entry.getValue());
                }
            } catch (ExecutionException | InterruptedException e) {
                logger.error("Error processing file: {}", e.getMessage(), e);
            }
        }
        executor.shutdown();
        return result;
    }

    class FileHasherCallable implements Callable<Map.Entry<String, String>> {
        private final String filePath;

        public FileHasherCallable(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public Map.Entry<String, String> call() throws Exception {
            try (ProgressBar progressBar = new ProgressBar(filePaths.size())) {
                if (!Files.exists(Paths.get(filePath))) {
                    return null; // File does not exist
                }

                Path path = Paths.get(filePath);
                if (!path.toFile().canRead()) {
                    logger.warn("File {} is not readable", filePath);
                    return null; // File is not readable
                }

                if (!path.toFile().canExecute()) {
                    logger.warn("File {} does not have executable permissions", filePath);
                    return null; // File does not have executable permissions
                }

                byte[] hashBytes = new byte[DigestUtils.MD5_HASH_LENGTH];
                try (InputStream inputStream = Files.newInputStream(path)) {
                    int read = 0;
                    ByteBuffer buffer = ByteBuffer.allocateDirect(chunkSize);
                    while ((read = inputStream.read(buffer.array())) > -1) {
                        buffer.position(0);
                        digestUpdate(DigestUtils.getMd5Digester(), buffer);
                        buffer.clear();
                    }
                } catch (IOException e) {
                    logger.error("Error reading file {}", filePath, e);
                    return null; // Error reading the file
                }

                progressBar.incrementAndGet();
                return new SimpleEntry<>(filePath, DigestUtils.md5Hex(hashBytes));
            } catch (Exception e) {
                logger.error("Error processing file {}", filePath, e);
                return null; // Generic error during processing
            }
        }

        private void digestUpdate(MessageDigest messageDigest, byte[] buffer) throws Exception {
            if (messageDigest == null || buffer == null || buffer.length <= 0) {
                throw new IllegalArgumentException("Invalid arguments");
            }
            messageDigest.update(buffer);
        }
    }
}
