import java.io.*;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ConcurrentModificationException;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.*;
import java.nio.file.attribute.FileAttribute;
import java.net.URI;
import java.nio.links.SymbolicLinkOption;

public class FileProcessor {
    private static final int DEFAULT_BATCH_SIZE = 100;
    private ExecutorService executor;
    private int batchSize;
    private Map<String, String> fileHashes = new HashMap<>();
    private Logger logger;

    public FileProcessor(Logger logger) {
        this.logger = logger;
        this.executor = Executors.newFixedThreadPool(Runtime.getRuntime().availableProcessors());
        this.batchSize = DEFAULT_BATCH_SIZE;
    }

    public void setBatchSize(int batchSize) {
        this.batchSize = batchSize;
    }

    public Map<String, String> processFilePaths(List<String> filePaths) throws InterruptedException, ExecutionException {
        List<Future<Map<String, String>>> futures = new ArrayList<>();
        for (int i = 0; i < filePaths.size(); i += batchSize) {
            int endIndex = Math.min(filePaths.size(), i + batchSize);
            List<String> batch = filePaths.subList(i, endIndex);
            Callable<Map<String, String>> callableTask = FileProcessor::processBatch;
            futures.add(executor.submit(callableTask, batch));
        }

        for (Future<Map<String, String>> future : futures) {
            fileHashes.putAll(future.get());
        }
        executor.shutdown();
        return fileHashes;
    }

    private static Map<String, String> processBatch(List<String> batch) throws NoSuchAlgorithmException, IOException {
        Map<String, String> results = new HashMap<>();
        for (String path : batch) {
            try {
                if (!Files.exists(new FileSystems.DefaultFileSystem.getPath(URI.create(path)))) {
                    logger.log("FAILURE", "Path not found: " + path);
                } else if (!Files.isReadable(new FileSystems.DefaultFileSystem.getPath(URI.create(path)))) {
                    logger.log("WARNING", "File is not readable: " + path);
                } else if (!Files.isExecutable(new FileSystems.DefaultFileSystem.getPath(URI.create(path)))) {
                    logger.log("WARNING", "File is not executable: " + path);
                } else {
                    MessageDigest md5 = MessageDigest.getInstance("MD5");
                    byte[] digestBytes = Files.readAllBytes(new FileSystems.DefaultFileSystem.getPath(URI.create(path)));
                    md5.update(digestBytes);
                    String hash = Hex.encodeHexString(md5.digest());
                    results.put(path, hash);
                    logger.log("SUCCESS", "Processed file: " + path + ", hash: " + hash);
                }
            } catch (FileAttributeNotSupportingLinkOptionException | SymbolicLinkOptionNotFoundException e) {
                if (Files.isSymbolicLink(new FileSystems.DefaultFileSystem.getPath(URI.create(path)))) {
                    logger.log("WARNING", "Skipping symbolic link: " + path);
                } else {
                    logger.log("FAILURE", "Error occurred while processing file: " + path, e);
                }
            } catch (Exception e) {
                logger.log("FAILURE", "Error occurred while processing file: " + path, e);
            }
        }
        return results;
    }
}
