<?php

use GuzzleHttp\Client as GuzzleClient;
use Predis\Client as RedisClient;

class EnvironmentVariableManager {
    private $apiClients = [];
    private $redisClient;
    private $cacheTtl = 300; // Cache Time to Live in seconds

    public function __construct(RedisClient $redisClient) {
        $this->redisClient = $redisClient;
    }

    public function addApiClient($apiClient, $key) {
        $this->apiClients[$key] = $apiClient;
    }

    public function getVariable($key) {
        $cachedValue = $this->redisClient->get($key);
        if ($cachedValue !== false) {
            return unserialize($cachedValue);
        }

        $apiResponse = null;
        foreach ($this->apiClients as $client) {
            try {
                $response = $client->request('GET', '/variables/' . $key);
                if ($response->getStatusCode() == 200) {
                    $apiResponse = $response->getBody()->getContents();
                    break;
                }
            } catch (Exception $e) {
                // Implement failover strategy here
            }
        }

        if ($apiResponse !== null) {
            $this->redisClient->set($key, serialize($apiResponse), 'EX', $this->cacheTtl);
            return unserialize($apiResponse);
        } else {
            throw new Exception("Environment variable not found: " . $key);
        }
    }
}
