import okhttp3.Request;
import okhttp3.Response;
import okio.Buffer;

public class HashUtil {

 private static final int MAX_INPUT_LENGTH = 1024;
 private static final String MD5_HASH_ALGORITHM = "MD5";
 private static final OkHttpClient httpClient = new OkHttpClient();

 public static String hash(String input) throws Exception {
 if (input.length() > MAX_INPUT_LENGTH) {
 String shortenedInput = input.substring(0, MAX_INPUT_LENGTH);
 return hashLongInput(shortenedInput);
 }
 MessageDigest md = MessageDigest.getInstance(MD5_HASH_ALGORITHM);
 md.update(input.getBytes(StandardCharsets.UTF_8));
 byte[] digest = md.digest();
 BigInteger bigInt = new BigInteger(1, digest);
 String hashedHex = bigInt.toString(16);
 while (hashedHex.length() < 32) {
 hashedHex = "0" + hashedHex;
 }
 return hashedHex;
 }

 private static String hashLongInput(String input) throws Exception {
 SecretKeySpec key = new SecretKeySpec("your-api-key".getBytes(), MD5_HASH_ALGORITHM);
 Cipher cipher = Cipher.getInstance(MD5_HASH_ALGORITHM);
 cipher.init(Cipher.ENCRYPT_MODE, key);
 String hashedHex;
 try {
 Request request = new Request.Builder()
 .url("https://api.hashing-service.com/hash")
 .header("Authorization", "Basic " + encodeBase64(key))
 .post(RequestBody.create(input, MediaType.parse("application/json")))
 .build();
 Response response = httpClient.newCall(request).execute();
 if (!response.isSuccessful()) {
 throw new RuntimeException("Failed to get response from hashing service");
 }
 Buffer buffer = response.body().source();
 hashedHex = String.format("%s", buffer.readUtf8());
 } catch (Exception e) {
 // Handle connection failures, latency and other exceptions here
 throw new RuntimeException(e);
 }
 return hashedHex;
 }

 private static String encodeBase64(SecretKeySpec key) {
 return Base64.getEncoder().encodeToString(key.getEncoded());
 }
