[' Here's a C program that adheres to your specifications, using standard library functions and proper error handling:

```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <dirent.h>
#include <sys/stat.h>
#include <unistd.h>

// Global variables
FILE *output_file = stdout;
int focus_on_duplicates = 0;
char verbose = 0;

typedef struct WordCount {
    char *word;
    int count;
} WordCount;

void usage() {
    printf("Usage: wordfreq [options] directory\n");
    printf("\nOptions:\n");
    printf("-h, --help : Display this help message and exit.\n");
    printf("-d, --directory : Specify the directory from which to read files (required).\n");
    printf("-f       : Focus only on words appearing more than once in the report.\n");
    printf("-o output_file: Specify an output file to log the word frequency report.\n");
    printf("-v       : Enable verbose mode, which logs additional debugging information.\n");
}

void error(const char *message) {
    if (verbose) fprintf(stderr, "[ERROR] %s\n", message);
    else        fprintf(stderr, "Error: %s\n", message);
    exit(EXIT_FAILURE);
}

WordCount* createWordCount() {
    WordCount *wc = malloc(sizeof(WordCount));
    wc->word = NULL;
    wc->count = 0;
    return wc;
}

void freeWordCount(WordCount *wc) {
    free(wc->word);
    free(wc);
}

void addWordCount(WordCount **word_counts, char *word) {
    int i = 0;
    for (; word_counts[i] != NULL; i++);

    if (i == 0) {
        word_counts[i] = createWordCount();
        word_counts[i]->word = strdup(word);
        word_counts[i]->count = 1;
    } else {
        for (int j = 0; word_counts[j] != NULL; j++) {
            if (!strcmp(word_counts[j]->word, word)) {
                word_counts[j]->count++;
                if (!focus_on_duplicates && verbose) fprintf(stderr, "Added duplicate: %s\n", word);
                return;
            }
        }
        WordCount *wc = createWordCount();
        wc->word = strdup(word);
        wc->count = 1;
        word_counts[i] = wc;
    }
}

void processFile(const char* filename) {
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        error("Error opening file.");
    }

    char buffer[4096];
    size_t chars_read;
    while ((chars_read = fread(buffer, sizeof(char), sizeof(buffer)-1, file)) > 0) {
        buffer[chars_read] = '\0'; // Null-terminate the buffer

        char *token = strtok(buffer, " \t\n\r.,;:!?(){}[]");
        while (token != NULL) {
            addWordCount(&word_counts, token);
            token = strtok(NULL, " \t\n\r.,;:!?(){}[]");
        }
    }

    if (fclose(file)) error("Error closing file.");
}

void saveWordCounts(const char *filename) {
    output_file = fopen(filename, "w");
    if (!output_file) error("Error opening output file.");

    for (int i = 0; word_counts[i] != NULL; i++) {
        fprintf(output_file, "%s: %d\n", word_counts[i]->word, word_counts[i]->count);
    }

    if (fclose(output_file)) error("Error closing output file.");
}

int main(int argc, char *argv[]) {
    int opt;
    const char *directory = NULL;
    const char *output_filename = NULL;

    while ((opt = getopt(argc, argv, "h?d:fvo:")) != -1) {
        switch (opt) {
            case 'h':
            case '?':
                usage();
                return EXIT_SUCCESS;
            case 'd':
                directory = optarg;
                break;
            case 'f':
                focus_on_duplicates = 1;
                break;
            case 'v':
                verbose = 1;
                break;
            case 'o':
                output_filename = optarg;
                break;
        }
    }

    if (directory == NULL) {
        usage();
        return EXIT_FAILURE;
    }

    DIR *dir = opendir(directory);
    if (!dir) error("Error opening directory.");

    struct dirent *entry;
    while ((entry = readdir(dir)) != NULL) {
        char filepath[1024];
        snprintf(filepath, sizeof(filepath), "%s/%s", directory, entry->d_name);

        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }

        struct stat file_stat;
        if (lstat(filepath, &file_stat) < 0) error("Error getting file status.");
        if (!S_ISREG(file_stat.st_mode)) continue; // Skip non-regular files (e.g., directories and symbolic links)

        processFile(filepath);
    }

    saveWordCounts(output_filename ? output_filename : "word_frequencies.txt");
    return EXIT_SUCCESS;
}
```

