int main(int argc, char** argv) {
    Config cfg;
    static struct option long_options[] = {
        {"help", no_argument, 0, 'h'},
        {"manpage", no_argument, 0, 'm'},
        {"input-file", required_argument, 0, 'i'},
        {"output-file", optional_argument, 0, 'o'},
        {"case-sensitive", no_argument, 0, 'c'},
        {"log-level", required_argument, 0, 'l'},
        {0, 0, 0, 0}
    };

    int opt = 0;
    while ((opt = getopt_long(argc, argv, "hi:o:c::l:", long_options, NULL)) != -1) {
        switch (opt) {
            case 'h':
                printf("Usage:\n");
                return 0;
            case 'm':
                // Print manpage
                break;
            case 'i':
                cfg.input_file = optarg;
                break;
            case 'o':
                cfg.output_file = optarg;
                break;
            case 'c':
                cfg.case_sensitive = true;
                break;
            case 'l':
                YAML::Node node = YAML::Load(std::string("log_level: ") + optarg);
                if (node.IsDefined()) {
                    cfg.log_level = static_cast<LogLevel>(node["log_level"].as<int>());
                } else {
                    log(WARNING, "Invalid --log-level option.");
                }
                break;
            default:
                printf("Error: Unknown argument.\n");
                return -1;
        }
    }

    if (cfg.input_file.empty()) {
        printf("Error: No input file specified.\n");
        return -1;
    }

    std::ifstream file(cfg.input_file);
    if (!file.is_open()) {
        log(ERROR, "Failed to open input file.");
        return -1;
    }

    Config* configs = new Config[std::thread::hardware_concurrency()];
    pthread_t threads[std::thread::hardware_concurrency()];
    int chunk_size = file.seekg(0, std::ios::end).tellg() / static_cast<int>(std::thread::hardware_concurrency());

    for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
        configs[i].case_sensitive = cfg.case_sensitive;
        configs[i].log_level = cfg.log_level;

        file.seekg(i * chunk_size, std::ios::beg);
        std::string line;
        int valid_lines = 0;

        while (getline(file, line)) {
            if (validate_line(line, configs[i]))
                ++valid_lines;
        }

        pthread_create(&threads[i], NULL, process_lines, &configs[i]);
    }

    for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
        pthread_join(threads[i], NULL);
    }

    int total_valid_lines = 0;
    for (int i = 0; i < std::thread::hardware_concurrency(); ++i) {
        total_valid_lines += configs[i].total_valid_lines;
    }

    delete[] configs;

    if (cfg.output_file.empty()) {
        printf("Total number of valid lines: %d\n", total_valid_lines);
    } else {
        std::ofstream output(cfg.output_file);
        if (output.is_open()) {
            output << "Total number of valid lines: " << total_valid_lines;
        } else {
            log(ERROR, "Failed to open output file.");
        }
    }

    return 0;
}

void* process_lines(void* args) {
    Config* config = static_cast<Config*>(args);
    int valid_lines = 0;

    while (config->input_file.size() > 0) {
        std::string line;
        if (!getline((std::ifstream*)config, line)) break;

        if (validate_line(line, *config))
            ++config->total_valid_lines;
    }

    return nullptr;
}

int validate_line(const std::string& line, const Config& config) {
