}

// Function to calculate the MD5 hash of one or more large files
void file_hash(const char *file, const char *temp_dir) {
    struct stat file_stat;
    int fd = open(file, O_RDONLY);
    if (fd == -1) {
        perror("open failed");
        return;
    }

    if (fstat(fd, &file_stat) == -1) {
        perror("fstat failed");
        close(fd);
        return;
    }

    off_t file_size = file_stat.st_size;
    char *data = mmap(NULL, file_size, PROT_READ, MAP_PRIVATE, fd, 0);
    if (data == MAP_FAILED) {
        perror("mmap failed");
        close(fd);
        return;
    }

    pthread_t threads[max_threads];
    off_t current_offset = 0;
    for (int i = 0; i <= file_size && i < max_threads; ++i) {
        if ((current_offset + (1 * (MAXOFF_T_VALUE / max_threads))) > file_size)
            current_offset = file_size - (file_size % (1 * (MAXOFF_T_VALUE / max_threads)));

        pthread_create(&threads[i], NULL, md5_calculate, data + current_offset);
        current_offset += 1 * (file_size / max_threads);
    }

    for (int i = 0; i < max_threads; ++i)
        pthread_join(threads[i], NULL);

    munmap(data, file_size);
    close(fd);
}
