public class UrlMetadataExtractor {

 private static final int MAX_URL_LENGTH = 2048;
 private static final String EXTERNAL_METADATA_SERVICE_URL = "https://api.metadata-extractor.com/v1/url-metadata";
 private static OkHttpClient httpClient = new OkHttpClient();

 public static List<UrlMetadata> processUrls(List<String> urls) {
 List<UrlMetadata> results = new ArrayList<>();
 for (String url : urls) {
 if (url.length() > MAX_URL_LENGTH) {
 // Use external service
 Future<Response> call = httpClient.newCall(new Request.Builder()
 .url(EXTERNAL_METADATA_SERVICE_URL + "?url=" + url)
 .build()).asyncCall();
 try {
 Response response = call.get();
 if (!response.isSuccessful()) {
 continue; // Skip if connection failed or bad request
 }
 String metadataJson = response.body().string();
 JsonObject metadata = JsonParser.parseString(metadataJson).getAsJsonObject();
 results.add(createUrlMetadata(url, metadata));
 } catch (InterruptedException | ExecutionException e) {
 // Handle exceptions gracefully, log errors if needed
 }
 } else {
 try {
 URL parsedUrl = new URL(url);
 results.add(processLocalUrl(parsedUrl));
 } catch (MalformedURLException e) {
 // Handle exceptions gracefully, log errors if needed
 }
 }
 }
 return results;
 }

 private static UrlMetadata processLocalUrl(URL url) {
 // Perform local processing and extraction of metadata
 HttpsURLConnection connection = (HttpsURLConnection) url.openConnection();
 connection.setRequestProperty("User-Agent", "My-App/1.0");
 Document document = Jsoup.parse(new InputStreamReader(connection.getInputStream(), StandardCharsets.UTF_8));
 String domainName = getDomainName(document);
 String protocol = url.getProtocol();
 String path = document.select("html > body > a[href]").first().attr("href");
 // Add more extraction tasks here if needed
 return new UrlMetadata(url, domainName, protocol, path);
 }

 private static String getDomainName(Document document) {
 Element link = document.select("link[rel='canonical']").first();
 if (link != null) {
 return link.attr("href").split("/")[2];
 }
 // Handle edge cases, add more methods to extract domain name if needed
 return "";
 }

 public static class UrlMetadata {
 private final URL url;
 private final String domainName;
 private final String protocol;
 private final String path;

 public UrlMetadata(URL url, String domainName, String protocol, String path) {
 this.url = url;
 this.domainName = domainName;
 this.protocol = protocol;
 this.path = path;
 }
 // Add getters and setters here if needed
 }
}
