struct Config {
    std::string config_file;
    std::string log_file;
    bool debug;
    nlohmann::json config;

    static void from_json(const nlohmann::json &j, Config &c) {
        c.config_file = j["config_file"].get<std::string>();
        c.log_file = j["log_file"].get<std::string>();
        c.debug = j["debug"].get<bool>();
        c.config = j["config"];
    }

    nlohmann::json to_json() const {
        nlohmann::json j;
        j["config_file"] = config_file;
        j["log_file"] = log_file;
        j["debug"] = debug;
        j["config"] = config;
        return j;
    }
};

class ConfigRegistry {
public:
    template<typename T>
    void registerFactory(const std::string &id, const std::function<std::unique_ptr<T>(nlohmann::json)> &factory) {
        factories_[id] = factory;
    }

    std::unique_ptr<Config> createConfig(const nlohmann::json &j) {
        auto it = factories_.find(j["type"].get<std::string>());
        if (it == factories_.end())
            throw std::runtime_error("Unknown config type");
        return it->second(j);
    }

private:
    std::map<std::string, std::function<std::unique_ptr<Config>(nlohmann::json)>> factories_;
};

class ConfigLoader {
public:
    void load() {
        std::ifstream ifs(config_->config_file);
        if (!ifs.is_open()) {
            std::cerr << "Error opening configuration file" << std::endl;
            return;
        }

        boost::property_tree::ptree pt;
        try {
            if (fs::extension(config_->config_file) == ".xml") {
                read_xml(ifs, pt);
                boost::property_tree::json_parser::write_json(pt, config_->config);
            } else {
                read_json(ifs, config_->config);
            }
        } catch (boost::property_tree::json_parser::parse_error &e) {
            std::cerr << "Error parsing configuration: " << e.what() << std::endl;
        }
    }

    void save() const {
        boost::property_tree::ptree pt = boost::property_tree::json_parser::parse(config_->config.dump());
        std::ofstream ofs(config_->config_file);
        write_xml(ofs, pt);
    }

private:
    static size_t write_callback(void *contents, size_t size, size_t nmemb, void *userp) {
        ((std::string *)userp)->append((char *)contents, size * nmemb);
        return size * nmemb;
    }

    void updateConfigFromAPI() {
        CURL *curl;
        CURLcode res;
        std::string response;

        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, config_->api_url.c_str());
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
            curl_easy_setopt(curl, CURLOPT_WRITEDATA, &response);
            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                std::cerr << "Error fetching configuration from API: " << curl_easy_strerror(res) << std::endl;
            } else {
                try {
                    config_->config = nlohmann::json::parse(response);
                } catch (nlohmann::json::parse_error &e) {
                    std::cerr << "Error parsing API response: " << e.what() << std::endl;
                }
            }
        }
        curl_easy_cleanup(curl);
        curl_global_cleanup();
    }

    Config *config_;
};

int main(int argc, char **argv) {
    Config config;
    ConfigRegistry registry;
    ConfigLoader loader;

    for (int i = 1; i < argc; ++i) {
        if (argv[i][0] == '-') {
