                        return 1;
                    }
                    break;
                case 'l':
                    ++i;
                    if (i < argc) {
                        config.log_file = argv[i];
                    } else {
                        std::cout << "Error: --log requires a file path" << std::endl;
                        return 1;
                    }
                    break;
            }
        }
    }

    config.config["type"] = "MyConfig";
    registry.registerFactory<MyConfig>("MyConfig", [](nlohmann::json j) { return std::make_unique<MyConfig>(j); });
    config_.reset(registry.createConfig(config.to_json()));
