}

bool add_pdu_to_list(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    sem_wait(&list_sem);

    if (current_list_size >= max_list_size) {
        sem_post(&list_sem);
        return false;
    }

    size_t i = 0;
    for (; i < current_list_size; ++i) {
        if (pdu->tag.value == list[i].tag.value) {
            sem_post(&list_sem);
            free(pdu);
            return false;
        }
    }

    pthread_mutex_lock(&list_mutex);
    current_list_size++;
    list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * current_list_size);
    if (!list) {
        pthread_mutex_unlock(&list_mutex);
        sem_post(&list_sem);
        free(pdu);
        return false;
    }

    list[i] = *pdu;
    pthread_mutex_unlock(&list_mutex);
    sem_post(&list_sem);

    return true;
}

