import java.io.*;
import java.security.MessageDigest;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;
import java.util.concurrent.*;
import java.util.logging.Level;
import java.util.logging.Logger;
import okhttp3.*;

public class FileHashCalculator {
    private static final Logger LOGGER = Logger.getLogger(FileHashCalculator.class.getName());
    private static final int MAX_CONCURRENT_THREADS = 10;
    private static final ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_THREADS);
    private static final OkHttpClient httpClient = new OkHttpClient();
    private static final MessageDigest md5 = MessageDigest.getInstance("MD5");

    public Map<String, String> calculateHashes(List<String> filePaths) {
        Map<String, String> hashes = new ConcurrentHashMap<>();
        CompletionService<Path> completionService = new ExecutorCompletionService<>(executor);

        for (String filePath : filePaths) {
            Callable<Path> task = () -> getPath(filePath);
            completionService.submit(task);
        }

        while (!completionService.isTerminated()) {
            Future<Path> future = completionService.take();
            try {
                Path path = future.get();
                if (path != null) {
                    handleFileOperationResult(path, hashes);
                }
            } catch (ExecutionException | InterruptedException e) {
                LOGGER.log(Level.WARNING, "Error processing file: ", e);
            }
        }

        executor.shutdown();
        return hashes;
    }

    private Path getPath(String filePath) {
        try {
            Path path = Files.getAbsoluteFile(Paths.get(filePath));
            BasicFileAttributes attributes = Files.readAttributes(path, BasicFileAttributes.class);
            if (attributes.isSymbolicLink()) {
                return Files.readSymbolicLink(path);
            } else {
                validateAndGetReadableFileChannel(path).orElseThrow(() -> new FileNotFoundException("File not found"));
            }
        } catch (IOException e) {
            LOGGER.log(Level.WARNING, "Failed to resolve path: ", e);
            return null;
        }
    }

    private Optional<ReadableByteChannel> validateAndGetReadableFileChannel(Path path) throws IOException {
        if (!Files.exists(path)) {
            LOGGER.log(Level.WARNING, "File not found: ", path);
            return Optional.empty();
        }

        try (RandomAccessFile file = new RandomAccessFile(path.toFile(), "r")) {
            file.setLength(0);
            if (!file.canRead()) {
                LOGGER.log(Level.WARNING, "File is not readable: ", path);
                return Optional.empty();
            }
        } catch (SecurityException e) {
            LOGGER.log(Level.WARNING, "Permission denied for file: ", path);
            return Optional.empty();
        }

        try {
            File systemFile = new File(path.toUri());
            if (!systemFile.canExecute()) {
                LOGGER.log(Level.WARNING, "File is not executable: ", path);
                return Optional.empty();
            }
        } catch (SecurityException e) {
            LOGGER.log(Level.WARNING, "Permission denied for file: ", path);
            return Optional.empty();
        }

        return Optional.ofNullable(Files.newInputStream(path));
    }

    private void handleFileOperationResult(Path path, Map<String, String> hashes) {
        try (ReadableByteChannel readableByteChannel = validateAndGetReadableFileChannel(path).orElseThrow()) {
            byte[] fileContent = new byte[1024];
            while (readableByteChannel.read(fileContent) != -1) {
                md5.update(fileContent);
            }
            hashes.put(path.getFileName().toString(), HexFormat.hexaDecode(md5.digest()).toUpperCase());
        } catch (IOException | NoSuchAlgorithmException e) {
            LOGGER.log(Level.WARNING, "Error calculating hash for file: ", e);
        } catch (ExecutionException | InterruptedException e) {
            LOGGER.log(Level.SEVERE, "Unexpected exception during hash calculation", e);
        }
    }

    // Cloud API calls and retry logic using OkHttpClient can be added here
}
```

