void hash_file(const char* path, const HashContext* context, const Config* config) {
    FILE* file = fopen(path, "rb");
    if (!file) {
        // Handle error and log accordingly
        return;
    }

    pthread_mutex_lock(&context->lock);

    char buffer[1024];
    size_t chunk_size = 1024;
    size_t bytes_read = fread(buffer, 1, chunk_size, file);
    while (bytes_read > 0) {
        // Hash the chunk and update context.digest
        MD5_Transform(MD5_blk, &buffer, chunk_size);
        MD5_Final(context->digest, MD5_blk);

        // Log progress if necessary
        pthread_mutex_unlock(&context->lock);
        log("Processing: %s, Hash: %s", path, bin2hex(context->digest, MD5_DIGEST_LENGTH));
        pthread_mutex_lock(&context->lock);

        // Read next chunk and update processed size
        bytes_read = fread(buffer, 1, chunk_size, file);
    }

    fclose(file);

    // Clean up temporary files if necessary
    // Your implementation here

    pthread_mutex_unlock(&context->lock);
}
