public class FileChecksumGenerator {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileChecksumGenerator.class);
    private static final int MAX_THREADS = 10;
    private static final int RETRY_ATTEMPTS = 5;
    private static final OkHttpClient httpClient = new OkHttpClient();

    public Map<String, BigInteger> generateChecksums(List<String> filePaths) {
        ExecutorService executor = Executors.newFixedThreadPool(MAX_THREADS);
        Map<String, Future<BigInteger>> tasks = new ConcurrentHashMap<>();
        for (String path : filePaths) {
            Callable<BigInteger> callable = () -> calculateChecksumAndLog(path);
            Future<BigInteger> future = executor.submit(callable);
            tasks.put(path, future);
        }
        executor.shutdown();
        try {
            executor.awaitTermination(Long.MAX_VALUE, TimeUnit.MILLISECONDS);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        Map<String, BigInteger> results = new HashMap<>();
        for (Map.Entry<String, Future<BigInteger>> entry : tasks.entrySet()) {
            try {
                BigInteger hash = entry.getValue().get();
                if (hash != null) {
                    results.put(entry.getKey(), hash);
                }
            } catch (ExecutionException | InterruptedException e) {
                // Handle exceptions as needed
            }
        }
        return results;
    }

    private BigInteger calculateChecksumAndLog(String path) {
        Path file = Paths.get(path);
        try {
            if (!Files.exists(file)) {
                LOGGER.warn("File not found: {}", path);
                return null;
            }
            if (!Files.isReadable(file)) {
                LOGGER.error("Unable to read file: {}", path);
                return null;
            }
            if (!Files.isExecutable(file)) {
                LOGGER.warn("File not executable: {}", path);
                return null;
            }
            try (FileChannel channel = FileChannel.open(file)) {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] buffer = new byte[1024];
                int bytesRead;
                while ((bytesRead = channel.read(buffer)) != -1) {
                    md.update(buffer, 0, bytesRead);
                }
                return BigInteger.valueOf(md.digest());
            } catch (IOException e) {
                LOGGER.error("Error reading file: {}", path, e);
                return null;
            }
        } catch (NoSuchAlgorithmException e) {
            LOGGER.error("Unable to initialize MD5 digest: {}", e.getMessage());
            return null;
        }
    }

    // For handling remote resources via network APIs
    private BigInteger calculateChecksumAndLog(String path, HttpUrl url) {
        Request request = new Request.Builder()
                .url(url)
                .build();
        try (Response response = httpClient.newCall(request).execute()) {
            if (!response.isSuccessful()) {
                int statusCode = response.code();
                switch (statusCode) {
                    case 401:
                        LOGGER.warn("Unauthorized access to remote resource: {}", path);
                        break;
                    case 403:
                        LOGGER.warn("Forbidden access to remote resource: {}", path);
                        break;
                    case 404:
                        LOGGER.warn("Remote resource not found: {}", path);
                        break;
                    default:
                        LOGGER.error("Error accessing remote resource: {}", path, response.message());
                }
                return null;
            }
            try (InputStream inputStream = response.body().byteStream()) {
                MessageDigest md = MessageDigest.getInstance("MD5");
                byte[] buffer = new byte[4096];
                int bytesRead;
                while ((bytesRead = inputStream.read(buffer)) != -1) {
                    md.update(buffer, 0, bytesRead);
                }
                return BigInteger.valueOf(md.digest());
            } catch (IOException e) {
                LOGGER.error("Error reading remote resource: {}", path, e);
                return null;
            }
        } catch (IOException e) {
            int timeoutReached = e instanceof SocketTimeoutException;
            if (!timeoutReached && !retryAttempt(path)) {
                LOGGER.error("Error accessing remote resource: {}", path, e);
                return null;
            }
        }
    }

    private boolean retryAttempt(String path) {
        int attempts = 0;
        while (attempts < RETRY_ATTEMPTS) {
            try {
                Thread.sleep(500 * Math.pow(2, attempts));
                return true; // Retry successful, break the loop and resume processing.
            } catch (InterruptedException e) {
                LOGGER.debug("Retry attempt interrupted: {}", path);
                break; // Interrupted, break the loop and resume processing with the next task.
            }
            attempts++;
        }
        return false; // Maximum retries reached without success, do not retry.
    }
}
