['1. **MD5 Hash Calculation and File Validation Method**

```java
import java.io.*;
import java.security.MessageDigest;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.logging.Level;
import java.util.logging.Logger;

public class FileProcessor {
    private static final Logger LOGGER = Logger.getLogger(FileProcessor.class.getName());
    private Map<String, String> fileHashes;
    private int batchSize;
    private ExecutorService executor;

    public FileProcessor(int batchSize) {
        this.fileHashes = new HashMap<>();
        this.batchSize = batchSize;
        this.executor = Executors.newFixedThreadPool(Math.min(Runtime.getRuntime().availableProcessors(), 10));
    }

    public void processFileList(List<String> filePaths) {
        List<Runnable> tasks = new ArrayList<>();

        for (String filePath : filePaths) {
            tasks.add(() -> processFile(filePath));
        }

        int currentSize = 0;
        while (!tasks.isEmpty()) {
            List<Runnable> subList = tasks.subList(currentSize, Math.min(currentSize + batchSize, tasks.size()));
            executor.invokeAll(subList);
            currentSize += batchSize;
        }
    }

    private void processFile(String filePath) {
        try {
            Path path = Path.of(filePath);
            if (!Files.exists(path)) {
                LOGGER.log(Level.WARNING, "File not found: " + filePath);
                return;
            }

            if (!Files.isReadable(path)) {
                LOGGER.log(Level.WARNING, "File is not readable: " + filePath);
                return;
            }

            if (!Files.isExecutable(path)) {
                LOGGER.log(Level.WARNING, "File does not have executable permissions: " + filePath);
                return;
            }

            byte[] md5Hash = MessageDigest.getInstance("MD5").digest(Files.readAllBytes(path));
            String hash = bytesToHex(md5Hash);
            fileHashes.put(path.getFileName().toString(), hash);
            LOGGER.log(Level.INFO, "File processed successfully: " + filePath + ", Hash: " + hash);
        } catch (Exception e) {
            LOGGER.log(Level.SEVERE, "Error processing file: " + filePath, e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();
        for (byte aByte : bytes) {
            sb.append(String.format("%02x", aByte));
        }
        return sb.toString();
    }
}
