#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <unistd.h>
#include <sys/resource.hrtime.h>
#include <pthread.h>

#define BUFFER_MAX 1024
#define CONNECTIONS_MAX 500

typedef struct {
    int id;
    double bandwidth;
    double latency;
    double packetDelayVariation;
} NETWORK_CONNECTION_METADATA;

typedef struct {
    char buffer[BUFFER_MAX];
    double packetLossRate;
} NETWORK_PACKET_STRUCTURE;

typedef struct {
    NETWORK_CONNECTION_METADATA metadata;
    NETWORK_PACKET_STRUCTURE packet;
} NETWORK_CONNECTION_REQUEST;

void populateConnections(NETWORK_CONNECTION_REQUEST connections[]) {
    for (int i = 0; i < CONNECTIONS_MAX; ++i) {
        connections[i].metadata.id = i;
        connections[i].metadata.bandwidth = (rand() / (double)RAND_MAX * 10 + 50); // Simulated bandwidth between 50-105 Mbps
        connections[i].metadata.latency = (rand() / (double)RAND_MAX * 0.03 + 0.02); // Simulated latency between 2-8ms
        connections[i].metadata.packetDelayVariation = (rand() / (double)RAND_MAX * 0.05 + 0.02); // Simulated Packet Delay Variation between 2-7 ms
        connections[i].packet.packetLossRate = connections[i].metadata.bandwidth * connections[i].metadata.latency * connections[i].metadata.packetDelayVariation / (1000 * 1000); // Calculate packet loss rate based on network conditions
    }
}

void* networkSimulator(void* arg) {
    NETWORK_CONNECTION_REQUEST* connection = (NETWORK_CONNECTION_REQUEST*)arg;
    int id = connection->metadata.id;
    clock_gettime(CLOCK_MONOTONIC, &connection->packet.timestamp); // Set packet timestamp using monotonic clock

    // Simulate network delays and packet losses based on connection's metadata
    usleep(connection->metadata.latency * 1000000 * (1 + connection->metadata.packetDelayVariation));
    if (rand() / (double)RAND_MAX < connection->packet.packetLossRate) return NULL; // Drop packet with probability determined by packet loss rate

    clock_gettime(CLOCK_MONOTONIC, &connection->packet.transmissionTime); // Set transmission time using monotonic clock
    return &connection->packet;
}

void sendPackets(NETWORK_CONNECTION_REQUEST connections[], int count) {
    pthread_t threads[count];
    for (int i = 0; i < count; ++i)
        pthread_create(&threads[i], NULL, networkSimulator, &connections[i]);

    for (int i = 0; i < count; ++i)
        pthread_join(threads[i], NULL);
}

void initializeNetworkConnections(NETWORK_CONNECTION_REQUEST connections[]) {
    populateConnections(connections);
    sendPackets(connections, CONNECTIONS_MAX);
}
