FILE_SYSTEM_QUEUE* file_system_queue_init(size_t capacity) {
    FILE_SYSTEM_QUEUE* queue = malloc(sizeof(FILE_SYSTEM_QUEUE));
    if (!queue) return NULL;

    queue->capacity = capacity;
    queue->count = 0;
    queue->tasks = calloc(capacity, sizeof(FILE_SYSTEM_TASK));
    if (!queue->tasks) {
        free(queue);
        return NULL;
    }

    pthread_mutex_init(&queue->lock, NULL);
    // Initialize buffer pool manager and start a thread for it

    return queue;
}

void file_system_queue_destroy(FILE_SYSTEM_QUEUE* queue) {
    if (!queue) return;

    pthread_mutex_destroy(&queue->lock);
    free(queue->tasks);
    free(queue);
}

int file_system_queue_push(FILE_SYSTEM_QUEUE* queue, const FILE_SYSTEM_TASK* task) {
    if (queue->count == queue->capacity) return 0; // Queue full

    pthread_mutex_lock(&queue->lock);
    memcpy(&queue->tasks[queue->count], task, sizeof(FILE_SYSTEM_TASK));
    queue->count++;
    pthread_mutex_unlock(&queue->lock);

    return 1;
}

FILE_SYSTEM_TASK* file_system_queue_pop(FILE_SYSTEM_QUEUE* queue) {
    FILE_SYSTEM_TASK* task = NULL;

    if (queue->count == 0) return NULL; // Queue empty

    pthread_mutex_lock(&queue->lock);
    task = &queue->tasks[0];
    memmove(queue->tasks, queue->tasks + 1, sizeof(FILE_SYSTEM_TASK) * (queue->count - 1));
    queue->count--;
    pthread_mutex_unlock(&queue->lock);

    return task;
}

void manage_file_system_operations() {
    FILE_SYSTEM_QUEUE* queue = file_system_queue_init(NUM_OF_FILE_SYSTEM_TASKS);
    if (!queue) return; // Memory allocation error

