```java
import java.io.*;
import java.nio.file.*;
import java.security.MessageDigest;
import java.util.concurrent.*;
import java.util.logging.Logger;

public class MD5FileProcessor {
    private static final Logger LOGGER = Logger.getLogger(MD5FileProcessor.class.getName());
    private static final int CHUNK_SIZE = 1024 * 1024; // 1MB
    private Semaphore semaphore;

    public MD5FileProcessor() {
        this.semaphore = new Semaphore(Runtime.getRuntime().availableProcessors());
    }

    public void processFiles(List<String> filePaths) throws IOException, InterruptedException {
        ExecutorService executor = Executors.newCachedThreadPool();
        try {
            for (String filePath : filePaths) {
                if (filePath == null || !Files.exists(Paths.get(filePath)) || !Files.isReadable(Paths.get(filePath))) {
                    continue;
                }
                if (!lockFile(filePath)) {
                    continue;
                }
                semaphore.acquire();
                try {
                    FileInputStream fis = new FileInputStream(filePath);
                    long fileSize = fis.available();
                    if (fileSize > CHUNK_SIZE) {
                        FileChannel channel = fis.getChannel();
                        ByteBuffer buffer = channel.map(FileChannel.MapMode.READ_ONLY, 0, CHUNK_SIZE);
                        while (channel.position() < fileSize) {
                            channel.read(buffer);
                            computeHash(buffer);
                            buffer.clear();
                        }
                    } else {
                        byte[] bytes = new byte[(int)fileSize];
                        fis.read(bytes);
                        computeHash(new ByteBuffer.allocate(bytes));
                    }
                } finally {
                    semaphore.release();
                    fis.close();
                    unlockFile(filePath);
                }
            }
            executor.shutdown();
            while (!executor.isTerminated()) {
                Thread.sleep(100);
            }
        } catch (ExecutionException | InterruptedException e) {
            LOGGER.log(Level.SEVERE, "Error during file processing", e);
        } finally {
            executor.shutdownNow();
        }
    }

    private ByteBuffer computeHash(ByteBuffer buffer) throws NoSuchAlgorithmException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        md.update(buffer);
        return ByteBuffer.wrap(md.digest());
    }

    private boolean lockFile(String filePath) {
        try {
            File lockFile = new File(filePath + ".lock");
            if (!lockFile.createNewFile()) {
                return false;
            }
            return true;
        } catch (IOException e) {
            LOGGER.log(Level.WARNING, "Failed to create lock file", e);
            return false;
        }
    }

    private void unlockFile(String filePath) {
        File lockFile = new File(filePath + ".lock");
        if (lockFile.exists() && lockFile.delete()) {
            LOGGER.info("Unlocking file: " + filePath);
        } else {
            LOGGER.warning("Failed to delete lock file for: " + filePath);
        }
    }
}
