typedef struct {
    double timestamp;
    double throughput;
    double latency;
    double packet_loss;
    double diagnostic_score;
} LinkMetric;

typedef struct Node {
    int value;
    char* buffer;
    struct Node* next;
} Node;

void sortNodes(Node** nodes, int length) {
    if (length <= 1) return;

    int pivotIndex = length / 2;
    Node* pivot = nodes[pivotIndex];
    int i = -1, j = length - 1;

    while (i < j) {
        do i++; while (strcmp(nodes[i]->buffer, pivot->buffer) < 0);
        do j--; while (strcmp(nodes[j]->buffer, pivot->buffer) > 0);

        if (i <= j) {
            Node* temp = nodes[i];
            nodes[i] = nodes[j];
            nodes[j] = temp;
            i++; j--;
        }
    }

    sortNodes(nodes, i - 1);
    sortNodes(nodes + i + 1, length - i - 1);
}

