```c
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <openssl/sha.h>

typedef struct {
    char* path;
    SHA256_CTX ctx;
} FileHash;

void fileHasher(FileHash* fh, const char* path) {
    int fd = open(path, O_RDONLY);
    if (fd == -1 || !fh->path) return;

    struct stat st;
    if (fstat(fd, &st) < 0) {
        close(fd);
        return;
    }

    char* buffer = malloc(st.st_size);
    if (!buffer) return;

    size_t bytesRead = read(fd, buffer, st.st_size);
    SHA256_Init(&fh->ctx);
    SHA256_Update(&fh->ctx, buffer, bytesRead);

    close(fd);
    free(buffer);
}

void processFilesConcurrently(FileHash* hashes, const char** paths, size_t numPaths) {
    pthread_t threads[numPaths];
    for (size_t i = 0; i < numPaths; ++i) {
        FileHash* fh = &hashes[i];
        fh->path = paths[i];
        pthread_create(&threads[i], NULL, fileHasher, fh);
    }

    for (size_t i = 0; i < numPaths; ++i) {
        pthread_join(threads[i], NULL);
    }
}
```

