#include <sys/mman.h>
#include <string.h>
#include <fcntl.h>
#include <errno.h>

#define MAX_LINE 8192

void usage(const char *progname) {
    printf("Usage: %s [options] input_file\n", progname);
    printf("-cs              count lines in input file\n");
    printf("-o output_file   output to specified file\n");
    printf("--manpage         display this help and exit\n");
}

int main(int argc, char **argv) {
    const char *input_file = NULL;
    FILE *input = stdin;
    int count_lines = 0;
    char *output_file = NULL;
    int skip_comments = 0;

    for (int i = 1; i < argc; ++i) {
        if (!strcmp(argv[i], "--manpage")) {
            usage(argv[0]);
            return EXIT_SUCCESS;
        } else if (!strcmp(argv[i], "-cs")) {
            skip_comments = 1;
        } else if (strncmp(argv[i], "-o", 2) == 0 && argv[i][2]) {
            output_file = argv[i] + 2;
        } else if (input_file == NULL) {
            input_file = argv[i];
        }
    }

    if (!input_file) {
        usage(argv[0]);
        return EXIT_FAILURE;
    }

    if (output_file && access(output_file, F_OK)) {
        input = fopen(output_file, "w");
    } else {
        input = fopen(input_file, "r");
        if (!input) {
            perror("Failed to open file");
            return EXIT_FAILURE;
        }
    }

    char *map_base = NULL;
    size_t map_length = 0;
    int fd = open(input_file, O_RDONLY);
    if (fd >= 0) {
        struct stat st;
        fstat(fd, &st);
        map_length = st.st_size + getpagesize() - 1;
        map_base = mmap(NULL, map_length, PROT_READ, MAP_PRIVATE | MAP_FILE, fd, 0);
        if (map_base == MAP_FAILED) {
            perror("Failed to memory-map file");
            return EXIT_FAILURE;
        }
        close(fd);
    } else {
        map_base = calloc(1, map_length);
        if (!map_base) {
            perror("Out of memory");
            return EXIT_FAILURE;
        }
    }

    char line[MAX_LINE];
    size_t line_len = 0;
    char *ptr = map_base;
    while (line_len < map_length) {
        if (*ptr == '\n') {
            ++count_lines;
            line[line_len] = '\0';
            line_len = 0;
            ptr += getpagesize();
            continue;
        }

        if (skip_comments && (*ptr == '/' && *(ptr + 1) == '/')) {
            ptr += strlen("//\n");
            continue;
        }

        line[line_len++] = *ptr++;
    }

    munmap(map_base, map_length);

    if (output_file && input != stdout) {
        fseek(input, 0, SEEK_SET);
        char c;
        while ((c = fgetc(input)) != EOF) {
            fputc(c, output);
        }
    }

    printf("%d\n", count_lines);

    if (output_file && access(output_file, F_OK)) {
        unlink(output_file);
    }

    if (input != stdin) {
        fclose(input);
    }

    return EXIT_SUCCESS;
}
