    return stats;
}

void periodically_reset(int interval_ms, LTE_PHY_TransportChannelStats** stats, int num_structures) {
    struct timespec reset_time;
    clock_gettime(CLOCK_REALTIME, &reset_time);
    reset_time.tv_sec += interval_ms / 1000;
    reset_time.tv_nsec = (interval_ms % 1000) * 1000000;

    while (true) {
        clock_gettime(CLOCK_REALTIME, &reset_time);
        if ((reset_time.tv_sec - reset_time.tv_sec >= interval_ms / 1000) &&
            (reset_time.tv_nsec >= (interval_ms % 1000) * 1000000)) {
            for (int i = 0; i < num_structures; ++i) {
                LTE_PHY_TransportChannelStats* current_stats = stats[i];
                memset(current_stats, 0, sizeof(LTE_PHY_TransportChannelStats));
            }
            reset_time.tv_sec += interval_ms / 1000;
            reset_time.tv_nsec = (interval_ms % 1000) * 1000000;
        }
        usleep(100000); // Sleep for 100ms to reduce CPU usage during idle time
    }
}
