void InitializeTransportChannelStats(int cells_per_struct, int total_structs, int num_channels, int* log_ptr) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    TransportChannelStatsArray *channel_stats = NULL;
    if ((channel_stats = (TransportChannelStatsArray*)malloc(total_structs * cells_per_struct * sizeof(TransportChannelStatsArray))) == NULL) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    for (int i = 0; i < total_structs * cells_per_struct; ++i) {
        TransportChannelStatsArray *current_array = channel_stats + i / cells_per_struct;
        int cell_id = current_array->cell_id = i % cells_per_struct;

        for (int j = 0; j < num_channels; ++j) {
            LTE_PHY_TransportChannelStats *stats = &current_array->stats[j];
            stats->PDSCH.RSRQ = rand() % 100 + 5; // Random value within 5-100
            stats->PUCCH.BLER = (double)rand() / RAND_MAX * 0.1 + 0.05; // Random value between 5% and 15%
            stats->PUSCH.MCS = rand() % 28; // Random value within MCS range
            stats->PRACH.PREAMBLE_ERR = (double)rand() / RAND_MAX * 0.3 + 0.3; // Random value between 30% and 70%
        }
    }

    pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
    int log_interval = 1000; // Log every 1000 iterations
    int log_count = 0;

    for (int i = 0; i < total_structs * cells_per_struct; ++i) {
        pthread_mutex_lock(&mutex);
        if (log_ptr && !(log_count++ % log_interval)) {
            printf("Logging initialization progress...\n");
            GetMD5Hash((char*)channel_stats, sizeof(TransportChannelStatsArray) * total_structs * cells_per_struct, log_ptr);
        }
        pthread_mutex_unlock(&mutex);
    }

    // Periodically flush and reset the statistics to zero for all cells with a configurable interval.
    int flush_interval = 10000; // Flush every 10,000 iterations
    for (int i = 0; i < total_structs * cells_per_struct; ++i) {
        pthread_mutex_lock(&mutex);
        if (!(i % flush_interval)) {
            memset(channel_stats, 0, sizeof(TransportChannelStatsArray) * total_structs * cells_per_struct);
        }
        pthread_mutex_unlock(&mutex);
    }

    free(channel_stats);
}

