void lte_rrc_array_resize(LTE_RRC_ARRAY_C* array, size_t new_capacity) {
    if (new_capacity <= array->capacity) return;
    LTE_RRC_MESSAGE_TYPE_C *new_arr = realloc(array->array, new_capacity * sizeof(LTE_RRC_MESSAGE_TYPE_C));
    if (!new_arr) {
        fprintf(stderr, "Failed to resize array\n");
        return;
    }
    array->array = new_arr;
    array->capacity = new_capacity;
