    if (index >= array->size) {
        fprintf(stderr, "Invalid index\n");
        return NULL;
    }
    pthread_mutex_lock(&array->mutex);
    LTE_RRC_MESSAGE_TYPE_C* element = &array->array[index];
    pthread_mutex_unlock(&array->mutex);
    return element;
}

void lte_rrc_array_push_back(LTE_RRC_ARRAY_C* array, const LTE_RRC_MESSAGE_TYPE_C data) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) lte_rrc_array_resize(array, array->capacity * 2);
    memcpy(&array->array[array->size], &data, sizeof(LTE_RRC_MESSAGE_TYPE_C));
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

void lte_rrc_array_remove_at(LTE_RRC_ARRAY_C* array, size_t index) {
    if (index >= array->size) {
        fprintf(stderr, "Invalid index\n");
        return;
    }
    pthread_mutex_lock(&array->mutex);
    if (index < array->size - 1) {
        memmove(&array->array[index], &array->array[index + 1], (array->size - index - 1) * sizeof(LTE_RRC_MESSAGE_TYPE_C));
    }
    array->size--;
    pthread_mutex_unlock(&array->mutex);
}
