    int attempts = 0;
    Session* session = find_session(username);

    if (!session && attempts < max_login_attempts) {
        if (verify_auth(username, password, auth_method)) {
            Session* new_session = malloc(sizeof(Session));
            generate_token(new_session->token, sizeof(new_session->token));
            new_session->expiry_timestamp = time(NULL) + 60 * 60; // Session lasts for 1 hour
            sessions[hash_username(username)] = new_session;
            return new_session;
        } else {
            attempts++;
        }
    }

    pthread_mutex_unlock(&sessions_mutex);
    return NULL;
}

// Find a session by username
Session* find_session(const char* username) {
    size_t index = hash_username(username) % sizeof(sessions) / 2;
    for (size_t i = index; i < sizeof(sessions); ++i) {
        if (sessions[i] && strcmp(sessions[i]->token, username)) {
            return sessions[i];
        }
    }

    for (size_t i = 0; i <= index; ++i) {
        if (sessions[i] && strcmp(sessions[i]->token, username)) {
            return sessions[i];
        }
    }

    return NULL;
}

// Logout and remove a session
void logout(const char* username) {
    pthread_mutex_lock(&sessions_mutex);
    Session* session = find_session(username);
    if (session) {
        free(session);
        sessions[hash_username(username)] = NULL;
    }
    pthread_mutex_unlock(&sessions_mutex);
}

// Hash function for username to distribute load
uint64_t hash_username(const char* username) {
    uint64_t hash = 5381;
    int c;

    while ((c = *username++)) {
        hash = (hash << 5) + hash + c;
        /* hash * 33 + c */
    }

    return hash % sizeof(sessions);
}
