        }
        pthread_mutex_unlock(&nd->mutex);
    }
    return NULL;
}

void flush_metrics(struct network_data *nd) {
    if (nd->log_level > 1) {
        printf("Flushing all metrics\n");
    }
    for (size_t i = 0; i < nd->max_sessions; ++i) {
        nd->metrics[i].latency = 50.0;
        nd->metrics[i].throughput = 500 / 100.0;
        nd->metrics[i].packet_loss = 0.0;
        nd->metrics[i].jitter = 50.0;
    }
    nd->last_flush = time(NULL);
}

void InitializeNetworkConnectionMetrics(size_t max_sessions, double log_level, size_t *num_initialized) {
    struct network_data* nd = malloc(sizeof(struct network_data));
    if (!nd) {
        fprintf(stderr, "Failed to allocate memory for NetworkData\n");
        return;
    }
    nd->max_sessions = max_sessions;
    nd->metrics = calloc(max_sessions, sizeof(NetworkConnectionMetrics));
    if (!nd->metrics) {
        free(nd);
        fprintf(stderr, "Failed to allocate memory for NetworkConnectionMetrics\n");
        return;
    }
    nd->log_level = log_level;
    pthread_mutex_init(&nd->mutex, NULL);

    struct timespec interval = { 1, 0 }; // 1 second interval for flushing metrics
    if (max_sessions > 0) {
        pthread_t flush_thread;
        if (pthread_create(&flush_thread, NULL, &flush_metrics, nd)) {
            fprintf(stderr, "Failed to create flush thread\n");
            free(nd->metrics);
            free(nd);
            return;
        }
        struct timespec now;
        clock_gettime(CLOCK_REALTIME, &now);
        nd->last_flush = now.tv_sec;
        while (true) {
            clock_gettime(CLOCK_REALTIME, &now);
            if (difftime(now.tv_sec, nd->last_flush) > 1) {
                flush_metrics(nd);
            }
            sleep(interval.tv_sec);
        }
    }

    pthread_t init_threads[max_sessions];
    for (size_t i = 0; i < max_sessions; ++i) {
        if (pthread_create(&init_threads[i], NULL, &initialize_metrics, nd)) {
            fprintf(stderr, "Failed to create initialization thread\n");
            free(nd->metrics);
            free(nd);
            return;
        }
    }
    for (size_t i = 0; i < max_sessions; ++i) {
        pthread_join(init_threads[i], NULL);
    }
    *num_initialized = max_sessions;
}
