static pthread_mutex_t metrics_mutex = PTHREAD_MUTEX_INITIALIZER;
static NetworkConnectionMetrics* metrics;
static int max_sessions;
static int log_level;
static int flush_interval; // in seconds
static double mean, stddev;

void calculate_z_score(double value) {
    double z_score = (value - mean) / stddev;
    printf("Z-Score: %.3f\n", z_score);
}

void initialize_session(int index) {
    metrics[index].latency = rand() % 10 + 50; // latency in milliseconds
    metrics[index].throughput = (rand() % 100 + 500) / 1000.0; // throughput in Mbps
    metrics[index].packet_loss = rand() % 5 + 1; // packet loss percentage
    metrics[index].jitter = rand() % 10 + 20; // jitter in milliseconds
    time_t current_time = time(NULL);
    metrics[index].expiration_time = current_time + rand() % (flush_interval * 60) + flush_interval * 60;
}

void periodically_flush() {
    pthread_mutex_lock(&metrics_mutex);
    time_t current_time = time(NULL);

    int i;
    for (i = 0; i < max_sessions; ++i) {
        if (current_time > metrics[i].expiration_time) {
            metrics[i].latency = 0.0;
            metrics[i].throughput = 0.0;
            metrics[i].packet_loss = 0.0;
            metrics[i].jitter = 0.0;
            metrics[i].expiration_time = current_time + (flush_interval * 60);
        }
    }

    pthread_mutex_unlock(&metrics_mutex);
}

void InitializeNetworkConnectionMetrics(int max, int log_level_, int flush_interval_) {
    max_sessions = max;
    log_level = log_level_;
    flush_interval = flush_interval_;

