#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct UserSessionMetrics {
    time_t loginTime;
    time_t activityDuration;
    time_t idleTimeout;
    time_t lastInteractionTimestamp;
} UserSessionMetrics;

static pthread_mutex_t metricsMutex = PTHREAD_MUTEX_INITIALIZER;
static UserSessionMetrics* sessionMetrics;
static size_t numSessions = 0;
static const size_t maxSessions = 10000;
static time_t idleTimeoutPolicy = 60 * 60 * 24; // 1 day as idle timeout policy in seconds
static const int logLevel = 1; // 1 = INFO, 2 = DEBUG
static time_t flushInterval = 60 * 60; // 1 hour flush interval in seconds

void InitializeUserSessionMetrics(size_t maxNumSessions, time_t idleTimeoutPolicySeconds, time_t flushIntervalSeconds) {
    if (maxNumSessions > maxSessions) {
        maxNumSessions = maxSessions;
    }

    numSessions = 0;
    sessionMetrics = malloc(sizeof(UserSessionMetrics) * maxNumSessions);

    if (!sessionMetrics) {
        perror("Failed to allocate memory for session metrics");
        return;
    }

    pthread_mutex_init(&metricsMutex, NULL);

    for (size_t i = 0; i < maxNumSessions; ++i) {
        sessionMetrics[i].loginTime = time(NULL);
        sessionMetrics[i].activityDuration = rand() % 86400 + 3600; // random activity duration up to 24 hours, with at least 1 hour
        sessionMetrics[i].idleTimeout = idleTimeoutPolicySeconds;
        sessionMetrics[i].lastInteractionTimestamp = sessionMetrics[i].loginTime;
    }

    numSessions = maxNumSessions;
    periodicallyFlushMetrics(flushIntervalSeconds);
}

void periodicallyFlushMetrics(time_t interval) {
    struct timespec ts;

    if (interval <= 0) return;

    ts.tv_sec = interval;
    ts.tv_nsec = 0;

    while (1) {
        nanosleep(&ts, &ts);
        flushMetrics();
    }
}

void flushMetrics() {
    pthread_mutex_lock(&metricsMutex);

    for (size_t i = 0; i < numSessions; ++i) {
        sessionMetrics[i].activityDuration = rand() % 86400 + 3600; // reset activity duration up to 24 hours, with at least 1 hour
        sessionMetrics[i].lastInteractionTimestamp = time(NULL);
    }

    pthread_mutex_unlock(&metricsMutex);
}
