import datetime

def validate_session_activity(session, idleTimeoutPolicySeconds):
    current = datetime.datetime.now()
    last_interaction = datetime.datetime.fromtimestamp(session.lastInteractionTimestamp)
    delta = (current - last_interaction).total_seconds()
    return delta > idleTimeoutPolicySeconds
