    List *list = mmap(NULL, sizeof(List), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list == MAP_FAILED) {
        perror("mmap");
        return NULL;
    }

    list->count = 0;
    list->max_items = MAX_STRUCTURES;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_item(List *list) {
    if (list->count >= list->max_items) {
        return NULL;
    }

    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *item = &list->items[list->count];
    list->count++;
    pthread_mutex_unlock(&list->mutex);

    item->rx_ue_information_tag.value = 0xDEADBEEF; // Set your desired value here
    item->rnti.id = rand() % 0xFFFF;              // Random RNTI value
    item->crc_indication_rel8_tag.crcflag = rand() % 2; // Random CRCFLAG value

    return item;
}

void free_list(List *list) {
    if (list == NULL) {
        return;
    }

    pthread_mutex_destroy(&list->mutex);
    munmap(list, sizeof(List));
}

void reset_list(List *list) {
    if (list == NULL) {
        return;
    }

    list->count = 0;
    pthread_mutex_lock(&list->mutex);
    memset(&list->items[0], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->max_items);
    pthread_mutex_unlock(&list->mutex);
}
