class Logging {
private:
    std::atomic<int> createdCount{0};
    std::atomic<int> destroyedCount{0};
    static constexpr int logLevel = 2; // Set the log level here

public:
    void log(const std::string& message) {
        if (logLevel <= 1) {
            auto now = std::chrono::system_clock::now().time_since_epoch().count();
            auto timePoint = std::chrono::steady_clock::to_time_t(now);
            char timeBuffer[26];
            strftime(timeBuffer, sizeof(timeBuffer), "%Y-%m-%d %H:%M:%S", std::localtime(&timePoint));
            std::cout << timeBuffer << ": " << message << std::endl;
        }
    }

    void logCreation(const NFAPI_CRC_INDICATION_PDU_T* structure) {
        if (logLevel > 1) {
            log("Created NFAPI_CRC_INDICATION_PDU_T");
            createdCount++;
        }
    }

    void logDestruction(const NFAPI_CRC_INDICATION_PDU_T* structure) {
        if (logLevel > 0) {
            log("Destroyed NFAPI_CRC_INDICATION_PDU_T");
            destroyedCount++;
        }
    }
};

class ThreadSafeList {
private:
    std::mutex listMutex;
    std::vector<NFAPI_CRC_INDICATION_PDU_T*> data;
    Logging logger;

public:
    void reset() {
        std::lock_guard<std::mutex> lock(listMutex);
        data.clear();
    }

    NFAPI_CRC_INDICATION_PDU_T* pop() {
        std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T, decltype(&destroyStructure)> element;
        std::lock_guard<std::mutex> lock(listMutex);
        if (!data.empty()) {
            element = std::move(std::unique_ptr<NFAPI_CRC_INDICATION_PDU_T, decltype(&destroyStructure)>(data.back(), &destroyStructure));
            data.pop_back();
            logger.logCreation(element.get());
        }
        return element ? element.release() : nullptr;
    }

    void push(NFAPI_CRC_INDICATION_PDU_T* structure) {
        std::lock_guard<std::mutex> lock(listMutex);
        data.push_back(structure);
        logger.logDestruction(structure);
    }
};

class ThreadSafeListManager {
private:
    InterfaceConfig* config;
    Logging logger;
    std::map<int, ThreadSafeList> lists;
    static constexpr int maxStructures = 1000;

public:
    ThreadSafeListManager(InterfaceConfig* _config) : config(_config), logger() { }

    NFAPI_CRC_INDICATION_PDU_T* allocateStructure(int interfaceID) {
        auto it = lists.find(interfaceID);
        if (it == lists.end()) {
            it = lists.emplace(std::make_pair(interfaceID, ThreadSafeList())).first;
        }
        NFAPI_CRC_INDICATION_PDU_T* structure = it->second.pop();
        if (!structure) {
            if (it->second.data.size() >= maxStructures) {
                logger.log("Error: Maximum number of structures exceeded");
                return nullptr;
            }
            structure = config->createStructure();
            if (!structure) {
                logger.log("Error: Failed to allocate memory for structure");
                return nullptr;
            }
        }
        return structure;
    }

    void deallocateStructure(NFAPI_CRC_INDICATION_PDU_T* structure, int interfaceID) {
        auto it = lists.find(interfaceID);
        if (it != lists.end()) {
            it->second.push(structure);
        } else {
            logger.log("Error: Unknown interface ID");
        }
    }
};
