using StackExchange.Redis;

public class DatabaseManager
{
    private readonly IDbConnection _connection;
    private readonly ConnectionMultiplexer _redis;
    private readonly IDatabase _db;

    public DatabaseManager(string connectionString, string redisConnectionString)
    {
        _connection = new SqlConnection(connectionString);
        _redis = ConnectionMultiplexer.Connect(redisConnectionString);
        _db = _redis.GetDatabase();
    }

    public async Task<IDataReader> ExecuteComplexQueryAsync(byte[] data)
    {
        var queryResult = await _connection.QueryAsync<dynamic>("EXEC dbo.ComplexStoredProcedure @Data", new { Data = data });

        // Cache frequently accessed query results in Redis
        if (queryResult.Any())
            _db.HashTagsAdd(JsonConvert.SerializeObject(queryResult), "Result");

        return queryResult;
    }
}
