['```c
#include <arpa/argopt.h>
#include <fstream>
#include <iostream>
#include <map>
#include <sstream>
#include <string>
#include <vector>

std::map<std::string, int> word_count;
int total_lines = 0;
bool case_sensitive = false;

struct file_data {
    std::ifstream file;
    bool processed = false;
};

std::vector<file_data> input_files;

void process_input(const file_data& fd) {
    if (fd.processed) return;
    fd.processed = true;

    std::string line;
    while (std::getline(fd.file, line)) {
        total_lines++;
        for (const auto& word : split(line, ' ')) {
            ++word_count[case_sensitive ? word : tolower(word)];
        }
    }
}

std::vector<std::string> split(const std::string& s, char delimiter) {
    std::vector<std::string> tokens;
    std::stringstream tokenStream(s);
    std::string token;

    while (getline(tokenStream, token, delimiter)) {
        tokens.push_back(token);
    }

    return tokens;
}

void list_options() {
    std::cout << "Available options:\n"
              << "-i <filename> : Specify an input file for processing.\n"
              << "-o <filename> : Specify an output file to store the report.\n"
              << "-l          : List all supported options upon execution.\n"
              << "-h          : Display a brief help message.\n"
              << "--manpage   : Display detailed usage information.\n"
              << "-cs         : Perform case-sensitive comparisons when processing the input files.\n";
}

int main(int argc, char *argv[]) {
    argopt::argument_parser<int> parser("report");
    parser.add_flag(-1, "help", "h").help("Display this help message and exit.");
    parser.add_flag(0, "manpage", "manpage").help("Display detailed usage information and exit.");
    parser.add_file("-i", "i", ARGOPT_KEY_REQUIRED, "input file", &input_files);
    parser.add_file("-o", "o", ARGOPT_KEY_REQUIRED, "output file", nullptr);
    parser.add_flag(-1, "cs", "cs").help("Perform case-sensitive comparisons.");

    try {
        auto arguments = parser.parse(argc, argv);

        if (arguments["manpage"].count() > 0) {
            std::cout << R"(Report Generator Usage Information:

Usage: report [options]... [input files]...

Options:
    -i <filename>      Specify an input file for processing.
    -o <filename>      Specify an output file to store the report.
    -l                List all supported options upon execution.
    -h                Display a brief help message.
    --manpage         Display detailed usage information.
    -cs              Perform case-sensitive comparisons when processing the input files.
)";
            return EXIT_SUCCESS;
        }

        if (arguments["help"].count() > 0) {
            list_options();
            return EXIT_SUCCESS;
        }

        case_sensitive = arguments["cs"].count() > 0;

        for (auto it = arguments["input_files"].begin(); it != arguments["input_files"].end(); ++it) {
            file_data fd;
            fd.file.open(it->second, std::ios::in);
            if (!fd.file) {
                std::cerr << "Error: Could not open file '" << it->second << "'." << std::endl;
                return EXIT_FAILURE;
            }
            input_files.push_back(std::move(fd));
        }

        if (input_files.empty()) {
            std::cerr << "Error: No input files provided." << std::endl;
            list_options();
            return EXIT_FAILURE;
        }

        for (auto& fd : input_files) process_input(fd);

        std::ofstream outfile(arguments["output_file"][0]);
        if (!outfile) {
            std::cerr << "Error: Could not open output file '" << arguments["output_file"][0] << "'." << std::endl;
            return EXIT_FAILURE;
        }

        outfile << "Total lines processed: " << total_lines << std::endl;
        outfile << "Unique words across all files: " << word_count.size() << std::endl;
        for (const auto& item : word_count) {
            outfile << item.first << ": " << item.second << std::endl;
        }
    } catch (std::exception &e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return EXIT_FAILURE;
    }

    return EXIT_SUCCESS;
}
```']

