#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct {
    int id;
    time_t timestamp;
    char status[256];
    struct participant **participants; // dynamically allocated array of pointers to participants
    pthread_mutex_t mutex;
} Event;

typedef struct {
    char name[256];
    int age;
} Participant;

Event *events = NULL;
Participant **participants = NULL;
int event_count = 0, participant_count = 0, capacity = 0;
pthread_mutex_t events_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_event(Event *event) {
    event->id = rand();
    event->timestamp = time(NULL);
    strcpy(event->status, "..."); // replace with your status list
    event->participants = NULL;
    pthread_mutex_init(&event->mutex, NULL);
}

void init_participant(Participant *participant) {
    participant->age = rand() % 100 + 18;
    strcpy(participant->name, "..."); // replace with your participant names generation
}

void add_event() {
    Event *new_event;
    if (capacity == event_count) {
        capacity *= 2;
        events = realloc(events, capacity * sizeof(Event));
    }

    new_event = &events[event_count];
    init_event(new_event);

    // Assuming a maximum of 10 participants per event. Adjust if necessary.
    new_event->participants = mmap(NULL, capacity * sizeof(Participant*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_event->participants == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    event_count++;
}

void add_participant(Event *event, Participant participant) {
    if (participant_count == capacity) {
        capacity *= 2;
        participants = realloc(participants, capacity * sizeof(Participant*));
    }

    participants[participant_count] = &participants[event->participants - participants][participant_count];
    init_participant(participants[participant_count]);
    event->participants[participant_count++] = participants + participant_count;
}

void garbage_collection() {
    Event *walker, *temp;
    Participant *p_walker, *p_temp;

    for (int i = 0; i < event_count; ++i) {
        walker = &events[i];
        p_walker = walker->participants;

        // Walk through the participants of this event and free them if unused.
        for (int j = 0; j < participant_count; ++j) {
            if (!p_walker[j]) continue;
            p_temp = p_walker[j];
            p_walker[j] = NULL; // mark for garbage collection

            // Walk through other events to see if this participant is used.
            for (int k = 0; k < event_count; ++k) {
                if (i == k) continue;
                temp = &events[k];
                p_walker = temp->participants;

                // If found, don't free it.
                if (p_walker[j]) break;
            }

            if (!p_temp) {
                free(p_temp);
                --participant_count;
            }
        }
    }
}

// Thread function for setting event statuses.
void *set_event_status(void *arg) {
    int idx = (long) arg;

    // Acquire a lock to protect the data structure from concurrent access.
    pthread_mutex_lock(&events_mutex);

    if (idx >= event_count) {
        pthread_mutex_unlock(&events_mutex);
        return NULL;
    }

    events[idx].status[0] = 'S'; // replace with your status list

    pthread_mutex_unlock(&events_mutex);
    return NULL;
}

int main() {
    srand(time(NULL));

    int num_threads = 10; // Number of threads for setting event statuses. Adjust as necessary.
    pthread_t threads[num_threads];

    for (int i = 0; i < num_threads; ++i) {
        if (pthread_create(&threads[i], NULL, set_event_status, (void *) i)) {
            perror("pthread_create failed");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < num_threads; ++i) {
        pthread_join(threads[i], NULL);
    }

    // Perform garbage collection periodically.
    while (1) {
        garlicage_collection();
        sleep(5);
    }
}
```

