    int index;
    MAC_CONTEXT* context;
};

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_info(const struct log_data* data) {
    pthread_mutex_lock(&log_mutex);
    printf("MAC Context [%d]:\n", data->index);
    printf("DL Config: %p\n", &data->context->dl_params);
    printf("UL Config: %p\n", &data->context->ul_params);
    printf("PHY Stats: %p\n", &data->context->phy_stats);
    pthread_mutex_unlock(&log_mutex);
}

int allocate_mac_contexts(MAC_CONTEXT** contexts, int N) {
    if (N > MAX_STRUCTS) return -1; // exceeded maximum limit

    MAC_CONTEXT* temp = malloc(N * sizeof(MAC_CONTEXT));
    if (!temp) return -2; // memory allocation failure

    for (int i = 0; i < N; ++i) {
        if (!(temp + i)) {
            free(temp);
            return -3; // memory allocation within array failed
        }

        temp[i].dl_params = /* initialize DL params */ ;
        temp[i].ul_params = /* initialize UL params */ ;
        temp[i].phy_stats = /* initialize PHY stats */ ;
    }

    *contexts = temp;

    // Log detailed information about each allocated structure
    for (int i = 0; i < N && i < MAX_STRUCTS; ++i) {
        struct log_data data = { .index = i, .context = contexts + i };
        pthread_mutex_lock(&log_mutex);
        log_info(&data);
        pthread_mutex_unlock(&log_mutex);
    }

    return 0; // success
}
