import java.util.logging.Logger;

public class MD5HashUtils {
    private static final Logger LOGGER = Logger.getLogger(MD5HashUtils.class.getName());

    public static String computeMD5(String input) {
        if (input == null || input.length() > 1024 || !input.chars().allMatch(Character::isISOControl)) {
            return "";
        }

        MessageDigest md;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            LOGGER.log(Level.SEVERE, "Failed to initialize MD5 digest", e);
            return "";
        }

        md.update(input.getBytes());
        byte[] digest = md.digest();

        BigInteger number = new BigInteger(1, digest);
        String hashtext = number.toString(16);
        while (hashtext.length() < 32) {
            hashtext = "0" + hashtext;
        }
        return hashtex;
    }
}
