import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.logging.Level;
import java.util.logging.Logger;
import java.util.concurrent.locks.Lock;
import java.util.concurrent.locks.ReentrantLock;

public class HashUtility {
    private static final Logger LOGGER = Logger.getLogger(HashUtility.class.getName());
    private static final int MAX_INPUT_LENGTH = 4096;
    private static final Lock LOCK = new ReentrantLock();
    private static final String[] ALLOWED_ALGORITHMS = {"SHA-256", "SHA-512"};
    private static final String LOGGING_PROPERTY_NAME = "logging.level";

    public static String computeHash(String input, String algorithm) {
        if (input == null || input.length() > MAX_INPUT_LENGTH || !isPrintableAscii(input)) {
            return "";
        }

        LOCK.lock();
        try {
            MessageDigest messageDigest = getMessageDigestInstance(algorithm);
            messageDigest.update(input.getBytes(StandardCharsets.UTF_8));
            byte[] hashBytes = messageDigest.digest();
            BigInteger bigInteger = new BigInteger(1, hashBytes);
            String hashedInput = bigInteger.toString(16);

            while (hashedInput.length() < 64) {
                hashedInput = "0" + hashedInput;
            }

            recordSuccessfulLogEntry(input, hashedInput);
            return hashedInput;
        } finally {
            LOCK.unlock();
        }
    }

    private static MessageDigest getMessageDigestInstance(String algorithm) {
        try {
            return MessageDigest.getInstance(algorithm);
        } catch (NoSuchAlgorithmException e) {
            throw new IllegalArgumentException("Unsupported hash algorithm: " + algorithm);
        }
    }

    private static boolean isPrintableAscii(String input) {
        for (int i = 0; i < input.length(); i++) {
            if (!Character.isISOControl(input.charAt(i))) {
                continue;
            }
            return false;
        }
        return true;
    }

    private static void recordSuccessfulLogEntry(String input, String hashValue) {
        String loggingLevel = System.getProperty(LOGGING_PROPERTY_NAME, Level.INFO.getName());
        LOGGER.log(Level.parse(loggingLevel), "Hash computation successful: Input - %s, Hash - %s, Timestamp - %s", new Object[]{input, hashValue, Instant.now()});
    }
}
```

