    HTTP_REQUEST *requests = mmap(NULL, network_requests_count * sizeof(HTTP_REQUEST), PROT_READ | PROT_WRITE, MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (!requests) {
        log_error("Failed to allocate memory for requests");
        curl_easy_cleanup(curl);
        fclose(fp);
        return NULL;
    }

    size_t request_index = 0;
    while (request_index < network_requests_count) {
        HTTP_REQUEST *request = &requests[request_index];

        request->packet.data_size = random() % MAX_PACKET_SIZE + MIN_PACKET_SIZE;
        request->packet.data = malloc(request->packet.data_size);
        if (!request->packet.data) {
            log_error("Failed to allocate memory for request data");
            free_requests(&requests[0], request_index);
            curl_easy_cleanup(curl);
            fclose(fp);
            return NULL;
        }

        getrandom(&request->packet.sequence_number, sizeof(request->packet.sequence_number));

        request->header.type = RANDOM_REQUEST_TYPE;
        request->header.latency = random() % MAX_LATENCY + MIN_LATENCY;
        request->header.bandwidth = get_network_bandwidth();

        if (use_compression) {
            EVP_CIPHER_CTX *ctx;
            EVP_EncryptInit(&ctx, compression_algo, NULL);
            EVP_EncryptUpdate(ctx, request->packet.data, &request->packet.data_size, request->packet.data, request->packet.data_size);
            EVP_EncryptFinalEx(ctx, request->packet.data + request->packet.data_size, &len);
        }

        if (use_external_service) {
            CURLcode res = curl_easy_setopt(curl, CURLOPT_URL, generate_url());
            if (res != CURLE_OK) {
                log_error("Failed to set URL: %s", curl_easy_strerror(res));
                free_requests(&requests[0], request_index);
                break;
            }

            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                log_error("cURL transfer failed: %s", curl_easy_strerror(res));
                free_requests(&requests[0], request_index);
                break;
            }

            res = curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            if (res != CURLE_OK || response_code != HTTP_OK) {
                log_error("Non-200 response from server: %d", response_code);
                free_requests(&requests[0], request_index);
                break;
            }
        }

        if (use_compression) {
            EVP_CIPHER_CTX *ctx;
            EVP_DecryptInit(&ctx, compression_algo, NULL);
            EVP_DecryptUpdate(ctx, request->packet.data, &request->packet.data_size, request->packet.data, request->packet.data_size);
            EVP_DecryptFinalEx(ctx, request->packet.data + request->packet.data_size, NULL);
        }

        checksum = calculate_checksum(request->packet.data, request->packet.data_size);
        // Validate data integrity here

        request_index++;
    }

    curl_easy_cleanup(curl);
    fclose(fp);
    mprotect(requests, network_requests_count * sizeof(HTTP_REQUEST), PROT_READ);
    return requests;
}
