#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/ioctl.h>
#include <net/if.h>
#include <openssl/md5.h>

typedef struct LinkMetric {
    time_t timestamp;
    double throughput;
    double latency;
    int packet_loss_percentage;
    unsigned char md5[MD5_DIGEST_LENGTH];
} LinkMetric;

LinkMetric* initializeNetworkMetrics(char *iface, int logLevel) {
    struct ifreq ifr;
    int sock = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0) {
        perror("socket creation failed");
        return NULL;
    }

    strncpy(ifr.ifr_name, iface, IFNAMSIZ - 1);
    if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) {
        perror("unable to get interface index");
        close(sock);
        return NULL;
    }
    close(sock);

    int *indices = calloc(1, sizeof(int));
    if (!indices) {
        perror("memory allocation failed");
        return NULL;
    }
    *indices = ifr.ifr_ifindex;

    int size = sysconf(_SC_PAGE_SIZE);
    LinkMetric* linkMetrics = malloc(size * sizeof(LinkMetric));
    if (!linkMetrics) {
        free(indices);
        perror("memory allocation failed");
        return NULL;
    }

    MD5_CTX ctx;
    MD5_Init(&ctx);
    unsigned char ifaceHash[MD5_DIGEST_LENGTH];
    for (int i = 0; i < IFNAMSIZ; ++i) {
        MD5_Update(&ctx, &iface[i], 1);
    }
    MD5_Final(ifaceHash, &ctx);

    int index = *indices - 1; // Array index starts from 0
    for (int i = 0; i < size / sizeof(LinkMetric); ++i) {
        linkMetrics[i].timestamp = time(NULL);
        linkMetrics[i].throughput = 0.0;
        linkMetrics[i].latency = -1.0; // Unavailable initially
        linkMetrics[i].packet_loss_percentage = -1; // Unavailable initially
        memcpy(linkMetrics[i].md5, ifaceHash, MD5_DIGEST_LENGTH);
        index = (index + 1) % IFNAMSIZ; // Wrap around when reaching the end of the interface names
        snprintf(ifr.ifr_name, IFNAMSIZ, "eth%d", index);
        if (ioctl(sock, SIOCGIFINDEX, &ifr) < 0) {
            perror("unable to get interface index");
            break;
        }
        if (*(int*)&ifr.ifr_index != index + 1) {
            fprintf(stderr, "invalid interface index\n");
            break;
        }
    }
    close(sock);
    free(indices);

    if (logLevel > 2 || logLevel < 0) {
        fprintf(stderr, "Invalid logging level. Valid levels: 0-2.\n");
        free(linkMetrics);
        return NULL;
    }

    return linkMetrics;
}
```
This function takes a network interface identifier and an optional logging level. It dynamically allocates a `LinkMetric` array and initializes each structure with the given fields based on the current state of the specified network interface, while allowing for configuration of the logging level. The function also computes the MD5 hash of the network interface identifier as part of the initialization process.

Error checking is implemented to handle invalid inputs such as non-existent interfaces or improperly formatted configuration parameters. Any exceptions related to memory allocation and hash computation are handled gracefully.']

