// Custom memory pool manager functions
void* MemoryPool_alloc(MemoryPool* pool, size_t size) {
    if(!pool->start || pool->size - pool->allocated < size) {
        void* new_block = mmap(NULL, pool->size ? pool->size * 2 : GETPAGE_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if(new_block == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
        pool->start = new_block;
        pool->size *= 2;
    }
    void* result = pool->start + pool->allocated;
    pool->allocated += size;
    return result;
}

void MemoryPool_free(MemoryPool* pool, void* ptr) {
    if(ptr >= pool->start && ptr < (pool->start + pool->allocated)) {
        pool->allocated -= sizeof(NFAPI_CRC_INDICATION_PDU_T);
    }
}

