        exit(EXIT_FAILURE);
    }
    new_node->next = NULL;
    return new_node;
}

void append(Node** head_ref, Node* new_node) {
    if(*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }
    Node* last = *head_ref;
    while(last->next != NULL)
        last = last->next;
    last->next = new_node;
}
