int add_element(const NFAPI_CRC_INDICATION_PDU_T* data) {
    int ret = 0;
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    if (ts.tv_sec - gc_interval_timer > MIN_GC_INTERVAL || head->next == NULL) {
        // Perform garbage collection here
        gc_interval_timer = ts.tv_sec;
    }

    pthread_mutex_lock(&list_mutex);

    while (head->next && (ts.tv_sec - gc_interval_timer < MIN_GC_INTERVAL)) {
        pthread_cond_wait(&add_cond, &list_mutex);
    }

    node_t* new_node = malloc(sizeof(node_t));
    if (!new_node) {
