        ret = -1;
        goto out;
    }

    memcpy(&new_node->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    new_node->next = head->next;
    head->next = new_node;

out:
    pthread_mutex_unlock(&list_mutex);
    return ret;
}

int update_element(uint32_t rnti, const NFAPI_CRC_INDICATION_PDU_T* data) {
    int ret = 0;
    node_t *current = head;

    while (current != NULL && current->data.rnti != rnti) {
        current = current->next;
    }

    if (!current) {
        fprintf(stderr, "Element not found\n");
        ret = -1;
    } else {
        memcpy(&current->data, data, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    return ret;
}

int remove_element(uint32_t rnti) {
    int ret = 0;
    node_t *previous = head;
    node_t *current = head->next;

    while (current != NULL && current->data.rnti == rnti) {
        previous->next = current->next;
        free_element(current);
        current = previous->next;
        if (!current) break;
        previous = previous->next;
    }

    if (!current) {
        fprintf(stderr, "Element not found\n");
        ret = -1;
    }

