#include <sys/stat.h>
#include <boost/program_options.hpp>
#include <boost/filesystem.hpp>

namespace po = boost::program_options;
namespace fs = boost::filesystem;

std::mutex mtx;
unsigned long totalLines = 0, linesPerWord[1000] = {0}, wordsCount = 0;

void processLine(const std::string& line) {
    std::istringstream iss(line);
    std::string word;
    while (iss >> word) {
        ++wordsCount;
        auto it = std::find(std::begin(linesPerWord), std::end(linesPerWord), 1);
        if (it != std::end(linesPerWord))
            *it += 1;
        else
            linesPerWord[wordsCount] = 1;
    }
    ++totalLines;
}

void processFile(const std::string& filename) {
    std::ifstream file(filename);
    if (!file.is_open()) {
        throw std::runtime_error("Failed to open the specified file.");
    }

    std::string line;
    while (std::getline(file, line)) {
        processLine(line);
    }
}

void printSummary(const std::unordered_map<std::string, unsigned long>& summary) {
    for (const auto& item : summary) {
        std::lock_guard<std::mutex> lock(mtx);
        std::cout << item.first << ": " << item.second << "\n";
    }
}

void printCountOnly() {
    std::lock_guard<std::mutex> lock(mtx);
    std::cout << totalLines << "\n";
}

int main(int argc, char* argv[]) {
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "Print usage information")
        ("input-file,i", po::value<std::string>(), "Specifies the input file to be processed")
        ("output-file,o", po::value<std::string>(), "Specifies an output file where results should be written instead of being printed to console")
        ("count-only,c", "")
        ("summary,s", "")
        ("manpage,M", "Print detailed usage information");

    po::variables_map vm;
    po::store(po::parse_command_line(argc, argv, desc), vm);
    po::notify(vm);

    if (vm.count("help")) {
        std::cout << desc << "\n";
        return 0;
    } else if (vm.count("manpage")) {
        std::cout << desc << "\n";
        return 0;
    }

    std::string inputFile, outputFile;
    bool countOnly = false, summary = false;

    try {
        fs::path p(argv[0]);
        if (!fs::exists(p) || !fs::is_regular_file(p)) {
            throw std::runtime_error("The specified file does not exist or is not a regular file.");
        }
        inputFile = argv[0];
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << "\n";
        return 1;
    }

    if (vm.count("input-file"))
        inputFile = vm["input-file"].as<std::string>();
    if (vm.count("output-file"))
        outputFile = vm["output-file"].as<std::string>();

    if (vm.count("count-only")) {
        countOnly = true;
    } else if (vm.count("summary")) {
        summary = true;
    }

    std::thread threads[4];
    unsigned long chunkSize = inputFile.length() / 4;
    for (unsigned long i = 0; i < 4; ++i) {
        threads[i] = std::thread(processFile, inputFile.substr(i * chunkSize, chunkSize));
    }

    for (auto& t : threads)
        t.join();

    if (summary) {
        printSummary(linesPerWord);
    } else if (countOnly) {
        printCountOnly();
    }

    if (!outputFile.empty()) {
        std::ofstream outfile(outputFile);
        if (!outfile.is_open()) {
            throw std::runtime_error("Failed to open the specified output file.");
        }

        if (summary) {
            for (const auto& item : linesPerWord) {
                outfile << item.first << ": " << item.second << "\n";
            }
        } else if (countOnly) {
            outfile << totalLines << "\n";
        }
    }

    return 0;
}
