    pthread_mutex_init(&pool->lock, NULL);
}

NFAPI_CRC_INDICATION_PDU_T *acquire(MEMORY_POOL *pool) {
    pthread_mutex_lock(&pool->lock);
    for (size_t i = 0; i < pool->capacity; ++i) {
        if (pool->elements[i] == NULL) {
            pool->elements[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            NFAPI_CRC_INDICATION_PDU_T *node = pool->elements[i];
            node->next = NULL;
            node->tag.tag_value = RX_UE_INFORMATION_TAG_CRC_INDICATION;
            node->rnti = rand(); // Update with your random generation function
            node->crc_indication.crcflag = (rand() % 2) == 0 ? 1 : 0;
            pool->count++;
            pthread_mutex_unlock(&pool->lock);
            return node;
        }
    }
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

void release(MEMORY_POOL *pool, NFAPI_CRC_INDICATION_PDU_T *node) {
    pthread_mutex_lock(&pool->lock);
    node->next = pool->elements[0];
    pool->elements[0] = node;
    pthread_mutex_unlock(&pool->lock);
}

void validate_rnti(const NFAPI_CRC_INDICATION_PDU_T *node, const MEMORY_POOL *pool) {
    NFAPI_CRC_INDICATION_PDU_T *current = pool->elements[0];
    for (; current != NULL; current = current->next) {
        if (node->rnti == current->rnti && node != current) {
            fprintf(stderr, "RNTI is not unique in the list.\n");
            exit(EXIT_FAILURE);
        }
    }
}

void create_linked_list(MEMORY_POOL *pool, size_t size) {
    NFAPI_CRC_INDICATION_PDU_T *first = NULL;
    NFAPI_CRC_INDICATION_PDU_T *current = NULL;

    for (size_t i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU_T *node = acquire(pool);
        if (!node) {
            fprintf(stderr, "Failed to allocate memory for the linked list.\n");
            exit(EXIT_FAILURE);
        }
        validate_rnti(node, pool);
        if (first == NULL) {
            first = node;
            current = first;
        } else {
            current->next = node;
            current = current->next;
        }
    }
}
```

