// Define log levels and corresponding macro for logging
#define LOG_DEBUG 1
#define LOG_INFO  2
#define LOG_WARNING 3
#define LOG_ERROR 4

enum { MAX_LOG_LEVEL = 4, NUM_THREADS };

// Struct to store thread-local state and log settings
typedef struct LogState {
    sem_t *semaphore;
    int log_level;
    const char *tags[MAX_TAGS];
    size_t tag_count;
} LogState;

// Function to initialize thread-local state and set up dynamic logging options
void log_init(LogState **log_state, int level, const char *const *tags, size_t count) {
    // Allocate memory for thread-local state and setup semaphore
    LogState *ls = mmap(NULL, sizeof(LogState), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    memset(ls, 0, sizeof(LogState));
    ls->log_level = level;
    for (size_t i = 0; i < count; ++i) {
        ls->tags[i] = tags[i];
    }
    ls->tag_count = count;

    // Initialize semaphore for throttling
    if (sem_init(&(ls->semaphore), 1, MAX_SEMAPHORE_VALUE) != 0) {
        perror("Failed to initialize semaphore");
        free(ls);
        exit(-1);
    }
    *log_state = ls;
}

// Function to log messages asynchronously with throttling and compression
void log(const char *format, ...) {
    // Get thread-local state from TLS
    LogState *ls = __thread_local LogState;

    // Lock semaphore for logging rate control
    sem_wait(ls->semaphore);

    // Calculate current time for logging timestamp
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    // Generate log message and write to file (using snprintf and va_start/va_end)
    static char buf[4096];
    size_t len = snprintf(buf, sizeof(buf), "[%lu.%06lu] [%s] %s\n", ts.tv_sec, ts.tv_nsec, ls->tags, format);

    // Compress log data if needed (using gzip)
    char *compressed = malloc(len + (len >> 2)); // estimate compressed size as ~25% of original
    if (ls->log_level >= LOG_WARNING && (len >> 10) > MAX_LOG_COMPRESSION_THRESHOLD) {
        gzwrite(compressed, buf, len);
    } else {
        memcpy(compressed, buf, len);
    }

    // Write compressed log data to centralized logging service (using a stream or socket)
    // Implement this part based on your chosen logging framework and cloud-based service API.

    // Unlock semaphore for other threads to log
    sem_post(ls->semaphore);

    free(compressed);
}
```

