struct mem_pool {
    void *buffer;
    size_t capacity;
    size_t used;
};

void *mem_pool_alloc(struct mem_pool *pool, size_t size) {
    if (size > pool->capacity - pool->used)
        return NULL;

    void *result = (char *)pool->buffer + pool->used;
    pool->used += size;
    return result;
}

void mem_pool_free(struct mem_pool *pool, void *ptr) {
    if (!ptr)
        return;

    pool->used -= (char *)ptr - (char *)pool->buffer;
}

struct mem_pool g_mem_pool = {NULL, 0, 0};
sem_t g_mem_lock;

void init_mem_pool(size_t capacity) {
    if (g_mem_pool.buffer)
        free(g_mem_pool.buffer);

    g_mem_pool.capacity = capacity;
    g_mem_pool.used = 0;
    g_mem_pool.buffer = mmap(NULL, capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

void *create_PDUs(int N) {
    pthread_t threads[N];
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;
    sem_t data_queue;
    size_t pdu_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);

    if (N <= 128) {
        pdus = malloc(N * pdu_size);
        for (int i = 0; i < N; ++i) {
            int session_id = rand() % INT32_MAX;
            srandom(session_id);
            memcpy(pdus + i, calloc(1, pdu_size), pdu_size);
            ((NFAPI_CRC_INDICATION_PDU_T *)pdus)[i].RX_UE_INFORMATION_TAG = rand();
            ((NFAPI_CRC_INDICATION_PDU_T *)pdus)[i].RNTI = rand() % 0xffff + 1;
            ((NFAPI_CRC_INDICATION_PDU_T *)pdus)[i].CRC_INDICATION_REL8_TAG = rand() % 2;
        }
    } else {
        sem_init(&data_queue, 0, 0);
        pdus = mem_pool_alloc(&g_mem_pool, N * pdu_size);
        if (!pdus)
            return NULL;

        for (int i = 0; i < N; ++i) {
            pthread_create(&threads[i], NULL, create_PDU_in_thread, (void *)((char *)pdus + i * pdu_size));
        }

        for (int i = 0; i < N; ++i)
            pthread_join(threads[i], NULL);
    }

    sem_destroy(&data_queue);
    return pdus;
}

void *create_PDU_in_thread(void *arg) {
    char *pdu = (char *)arg;
    int session_id = rand() % INT32_MAX;
    srandom(session_id);

    sem_t lock;
    sem_init(&lock, 0, 1);

    while (1) {
        NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)mem_pool_alloc(&g_mem_pool, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdus) {
            sem_wait(&lock);
            sem_post(&lock);
            continue;
        }

        memset(pdus, 0, sizeof(*pdus));
        pdus->RX_UE_INFORMATION_TAG = rand();
        pdus->RNTI = rand() % 0xffff + 1;
        pdus->CRC_INDICATION_REL8_TAG = rand() % 2;

        sem_wait(&lock);
        memcpy(pdu, pdus, sizeof(*pdus));
        pdu += sizeof(*pdus);
        mem_pool_free(&g_mem_pool, pdus);
        sem_post(&lock);
    }
}
