    }

    private class RollingAverage {
        private int windowSize;
        private int currentIndex;
        private double[] buffer;

        public RollingAverage(int windowSize) {
            this.windowSize = windowSize;
            this.currentIndex = 0;
            this.buffer = new double[windowSize];
        }

        public void addDataPoint(double value) {
            if (currentIndex >= buffer.length) {
                currentIndex = 0;
            }

            buffer[currentIndex] = value;
            currentIndex++;
            updateAverage();
        }

        private void updateAverage() {
            if (currentIndex < windowSize) {
                return;
            }

            double sum = Arrays.stream(buffer).sum();
            buffer = Arrays.copyOfRange(buffer, 1, buffer.length);
            buffer[buffer.length - 1] = sum / windowSize;
        }

        public double getAverage() {
            return buffer[buffer.length - 1];
        }
    }

    private void storeData(int deviceId, byte[] data) throws SQLException {
        Connection connection = DriverManager.getConnection(DATABASE_URL);
        PreparedStatement statement = connection.prepareStatement("INSERT INTO sensor_data (device_id, data) VALUES (?, ?)");
        statement.setInt(1, deviceId);
        statement.setBytes(2, data);
        statement.executeUpdate();
        connection.close();
    }

    public void start() {
        executor.submit(() -> {
            while (true) {
                for (RollingAverage rollingAverage : rollingAverages.values()) {
                    double average = rollingAverage.getAverage();
                    if (average > THRESHOLD) {
                        try {
                            storeData(rollingAverage.deviceId, getBytesFromDouble(average)); // Assume you have a helper method for this
                        } catch (SQLException e) {
                            LOGGER.error("Error storing data: {}", e.getMessage());
                        }
                    }
                }

                try {
                    TimeUnit.SECONDS.sleep(1);
                } catch (InterruptedException e) {
                    LOGGER.error("Interrupted while waiting: {}", e.getMessage());
                }
            }
        });
    }
}
