#include <pthread.h>
#include <stdlib.h>
#include <stdio.h>
#include <time.h>

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rxUEInformationTag;
    uint32_t RNTI;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _CRC_INDICATION_REL8_TAG {
    uint32_t CRCFLAG;
} CRC_INDICATION_REL8_TAG;

struct memory_block {
    NFAPI_CRC_INDICATION_PDU_T* data;
    size_t capacity;
    size_t length;
};

void seed_random(uint64_t session_id) {
    srand((unsigned int)(session_id + time(NULL)));
}

int generate_crcflag() {
    return (rand() >> 1) & 1;
}

struct memory_block* create_memory_block(size_t size) {
    struct memory_block* block = malloc(sizeof(struct memory_block));
    if (!block) {
        perror("malloc failed");
        return NULL;
    }

    block->data = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!block->data) {
        perror("calloc failed");
        free(block);
        return NULL;
    }

    block->capacity = size;
    block->length = 0;
    return block;
}

void destroy_memory_block(struct memory_block* block) {
    if (block && block->data) {
        free(block->data);
        free(block);
    }
}

NFAPI_CRC_INDICATION_PDU_T* pop_from_memory_block(struct memory_block* block) {
    if (!block || !block->data || block->length == 0) {
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* item = &block->data[--block->length];
    return item;
}

void push_to_memory_block(struct memory_block* block, const NFAPI_CRC_INDICATION_PDU_T* item) {
    if (!block || !item) {
        return;
    }

    if (block->length >= block->capacity) {
        struct memory_block* new_block = create_memory_block(block->capacity * 2);
        if (!new_block) {
            perror("Memory allocation failed");
            return;
        }

        memcpy(new_block->data, block->data, block->length * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        destroy_memory_block(block);
        block = new_block;
    }

    block->data[block->length++] = *item;
}

void* populate_array(size_t N, uint64_t session_id) {
    void* result = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!result) {
        perror("malloc failed");
        return NULL;
    }

    struct memory_block* memory_block = create_memory_block(N);
    if (!memory_block) {
        free(result);
        return NULL;
    }

    seed_random(session_id);
    for (size_t i = 0; i < N; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* item = pop_from_memory_block(memory_block);
        if (!item) {
            perror("Failed to allocate data in memory block");
            goto cleanup;
        }

        item->rxUEInformationTag.tag = i % 256;
        item->RNTI = i + session_id;
        item->crcIndicationRel8Tag.CRCFLAG = generate_crcflag();
    }

    memcpy(result, memory_block->data, N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

cleanup:
    destroy_memory_block(memory_block);

    return result;
}
```

