private static readonly ThreadSafeQueue<NFAPI_CRC_INDICATION_PDU_T> _deserializedPdus = new ThreadSafeQueue<NFAPI_CRC_INDICATION_PDU_T>();
private static object _lockObject = new object();
private static Random _randomGenerator;
private const int SessionIdentifier = 42; // Unique session identifier for seeding pseudo-random number generator

public async Task DeserializeAndPopulateNFAPDUs(string filePath)
{
    if (string.IsNullOrEmpty(filePath)) throw new ArgumentException("Invalid input parameter", nameof(filePath));

    using var fileStream = File.OpenRead(filePath);
    BinaryFormatter formatter = new BinaryFormatter();

    CancellationTokenSource cts = new CancellationTokenSource();
    CancellationToken token = cts.Token;

    ParallelOptions options = new ParallelOptions { MaxDegreeOfParallelism = Environment.ProcessorCount };
    await Parallel.ForEachAsync(Enumerable.Range(0, (int)fileStream.Length / sizeof(NFAPI_CRC_INDICATION_PDU_T)), options, async (chunk, loopState) =>
    {
        var chunkData = new byte[chunk];
        await fileStream.ReadAsync(chunkData, 0, chunkData.Length, token);

        using var memoryStream = new MemoryStream(chunkData);
        try
        {
            NFAPI_CRC_INDICATION_PDU_T deserializedPdu;
            lock (_lockObject)
            {
                // Deserialize and populate the structure with unique tags and CRCFLAG
                deserializedPdu = (NFAPI_CRC_INDICATION_PDU_T)formatter.Deserialize(memoryStream);
                deserializedPdu.RX_UE_INFORMATION_TAG = unchecked((ushort)(deserializedPdu.RX_UE_INFORMATION_TAG | new Random(_randomGenerator.Next()).Next() << 15));
                deserializedPdu.RNTI = (byte)_randomGenerator.Next(0x01, 0xfe); // Valid RNTIs are in the range [1..254]
                deserializedPdu.CRC_INDICATION_REL8_TAG = _randomGenerator.Next() & 0xFFFFFF;
            }

            _deserializedPdus.Enqueue(deserializedPdu);
        }
        catch (Exception ex)
        {
            // Handle errors and memory leaks appropriately (e.g., log, clean up resources, etc.)
            Console.WriteLine($"Error while deserializing data: {ex}");
        }
    });

    cts.Cancel(); // Ensure no further chunks are processed after the loop has ended
}
