class RandomUtils {
public:
    explicit RandomUtils(const std::string& chars) : chars_(chars), rand_(std::random_device{}()), gen_() {
        generate(begin(rand_vec_), end(rand_vec_), [this](){return rand_() % (chars_.length());});
    }

    std::string generateRandomString(size_t length) {
        std::string res;
        for (size_t i = 0; i < length; ++i) {
            res += chars_[rand_vec_[i]];
        }
        return res;
    }

    std::string sha256(const std::string& data) const {
        unsigned char digest[SHA256_DIGEST_LENGTH];
        EVP_sha256((const unsigned char*)data.c_str(), data.size(), digest);
        std::string result;
        for (int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            result += std::hex(static_cast<int>(digest[i]) << 8 | static_cast<int>(digest[i + 1]));
