                        }
                        std::cout << "Total lines: " << line_count << ", Words per unique word: ";
                        for (const auto& e : word_count) {
                            if (e.first[0] != '\0') {
                                sum -= e.second;
                                std::cout << e.first << ':' << e.second << ',' << delimiters;
