                    .await?;

                user_profiles.extend(response);
                next_page = response.iter().last().map(|p| p.next_page());
            }
        };

        let process_batch = move || {
            if !user_profiles.is_empty() {
                tx.send(user_profiles.drain(..batch_size).collect()).unwrap();
                user_profiles.clear();
            }
        };

        let retry_delay = std::time::Duration::from_secs(1);
        let backoff = tokio::retry::backoff::exponential_backoff(retry_delay).max_retries(5);

        runtime.block_on(async move {
            loop {
                fetch_user_profiles();
                process_batch();

                if let Err(e) = backoff.get().call(|| async {
                    client.get(DEFAULT_API_URL).send().await.is_err()
                }).await {
