            }
        }
    });

    if let Ok(mut writer) = OpenOptions::new()
        .write(true)
        .create(true)
        .append(true)
        .open("processed_user_data.csv") {
        let mut writer = WriterBuilder::new().from_writer(writer);

        writer.serialize(processed_profiles)?;
    } else {
        error!("Failed to open processed_user_data.csv for writing");
    }

    Ok(())
