class FrameList {
private:
    std::vector<PHY_FRAME_STATS> data;
    std::map<FRAME_TYPE, std::vector<PHY_FRAME_STATS>> indexed;
    size_t capacity = 50000;
    size_t count = 0;
    int ttl = 60; // Default TTL is 60 seconds
    pthread_mutex_t mutex;
    Args* args;

    void clearOldData() {
        std::chrono::system_clock::time_point now = std::chrono::system_clock::now();
        for (auto& vec : indexed) {
            for (auto& elem : vec.second) {
                if ((now - std::chrono::duration_cast<std::chrono::seconds>(elem.ttl).get() > std::chrono::system_clock::now()) || elem.ttl <= 0) {
                    continue;
                }
                data.erase(data.begin() + (elem - &data[0]));
                count--;
            }
        }
    }

public:
    FrameList(Args* args) : args(args), mutex(PTHREAD_MUTEX_INITIALIZER) {}

    int init() {
        if (args->password == NULL || args->conn == NULL || args->callback == NULL) {
            return -1;
        }

        if (args->conn->title == NULL) {
            return -2;
        }

        clearOldData();
        return 0;
    }

    int add(PHY_FRAME_STATS stats) {
        std::unique_lock<std::mutex> lock(mutex);
        if (count >= capacity) {
            clearOldData();
        }
        data.push_back(stats);
        count++;
        index(stats.frame_type).push_back(stats);
        lock.unlock();

        stats.checksum = calculateChecksum(stats); // Assuming a checksum function is provided
        if (args->callback != NULL) {
            args->callback(&stats, args->callback_data);
        }

        return 0;
    }

    int update(FRAME_TYPE frame_type, PHY_FRAME_STATS stats) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = index(frame_type).begin();
        if (it == index(frame_type).end()) {
            return -1;
        }

        PHY_FRAME_STATS& elem = *it;
        elem.tx_power_level = stats.tx_power_level;
        elem.snr = stats.snr;
        elem.ber = stats.ber;
        elem.ttl = stats.ttl; // Update TTL if provided
        elem.checksum = calculateChecksum(elem);

        lock.unlock();

        if (args->callback != NULL) {
            args->callback(&elem, args->callback_data);
        }

        return 0;
    }

    int remove(FRAME_TYPE frame_type) {
        std::unique_lock<std::mutex> lock(mutex);
        auto it = index(frame_type).begin();
        if (it == index(frame_type).end()) {
            return -1;
        }

        PHY_FRAME_STATS& elem = *it;
        data.erase(elem - &data[0]);
        count--;
        lock.unlock();

        if (args->callback != NULL) {
            args->callback(&elem, args->callback_data);
        }

        return 0;
    }

private:
    std::vector<PHY_FRAME_STATS>& index(FRAME_TYPE frame_type) {
        if (indexed.find(frame_type) == indexed.end()) {
            indexed[frame_type] = {};
        }
        return indexed[frame_type];
    }

