// Function to generate NFAPI PDU list
NFAPI_CRC_INDICATION_PDU_T* generateNfalibPduList(int N) {
    NFAPI_CRC_INDICATION_PDU_T *pduList = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*N);
    if (!pduList) {
        printf("Failed to allocate memory. Exiting.\n");
        exit(EXIT_FAILURE);
    }

    struct timespec timeout;
    clock_gettime(CLOCK_MONOTONIC, &timeout);
    timeout.tv_sec += TIMEOUT/1000;

    for (int i = 0; i < N; ++i) {
        if (clock_gettime(CLOCK_MONOTONIC, &timeout) && timeout.tv_sec >= timeout.tv_sec + TIMEOUT/1000) {
            printf("Timed out after %d milliseconds.\n", TIMEOUT);
            break;
        }
        pduList[i].RX_UE_INFORMATION_TAG = i;
        pduList[i].RNTI = rand();
        pduList[i].CRC_INDICATION_REL8_TAG = rand() & 0xFFFF;
        pduList[i].CRCFLAG = rand() % 2;
    }

    return pduList;
}

// Function to free allocated memory
void freeNfalibPduList(NFAPI_CRC_INDICATION_PDU_T *pduList, int N) {
    if (!pduList) return;
    free(pduList);
}
