#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <limits.h>

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_ELEMENTS 10000
static NFAPI_CRC_INDICATION_PDU_T* list = NULL;
static size_t num_elements = 0;
static const size_t element_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
static pthread_mutex_t mutex;

// Validate RNTI is within the specified range
bool validate_rnti(uint32_t rnti) {
    return rnti > 0 && rnti < UINT32_MAX / 4 - 1;
}

void log(const char* message) {
    // Implement logging here, optimized to avoid excessive logging impacting performance.
}

// Generate a random CRCFLAG value within the valid range
uint8_t generate_crcflag() {
    return rand() % ((1 << (sizeof(CRC_INDICATION_REL8_TAG[0]) * CHAR_BIT) - 1);
}

void init_list(size_t num_elements) {
    if (num_elements > MAX_ELEMENTS) {
        log("Error: Requested number of elements exceeds maximum limit.");
        return;
    }

    pthread_mutex_init(&mutex, NULL);

    void* memory = calloc(num_elements * element_size, sizeof(char));
    if (!memory) {
        log("Error: Memory allocation failed. Exiting...");
        exit(1);
    }

    list = (NFAPI_CRC_INDICATION_PDU_T*) memory;
    num_elements = num_elements;
}

void add_element() {
    pthread_mutex_lock(&mutex);

    // Validate RNTI and generate CRCFLAG values
    NFAPI_CRC_INDICATION_PDU_T* element = &list[num_elements];
    uint32_t rnti;
    do {
        rnti = rand() % UINT32_MAX / 4 + 1;
    } while (!validate_rnti(rnti) || find_element_by_rnti(rnti));

    element->RX_UE_INFORMATION_TAG = rand(); // Use a unique identifier for RX_UE_INFORMATION_TAG
    element->RNTI = rnti;
    memcpy(element->CRC_INDICATION_REL8_TAG, generate_crcflag(), sizeof(element->CRC_INDICATION_REL8_TAG));

    num_elements++;
    pthread_mutex_unlock(&mutex);
}

bool find_element_by_rnti(uint32_t rnti) {
    bool found = false;
    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_elements; ++i) {
        if (list[i].RNTI == rnti) {
            found = true;
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
    return found;
}

void remove_element(uint32_t rnti) {
    if (!find_element_by_rnti(rnti)) {
        log("Error: Element not found to remove.");
        return;
    }

    pthread_mutex_lock(&mutex);

    size_t index = 0;
    for (size_t i = 0; i < num_elements; ++i) {
        if (list[i].RNTI == rnti) {
            memmove(&list[index], &list[i + 1], (num_elements - index - 1) * element_size);
            num_elements--;
            break;
        }
        index++;
    }

    pthread_mutex_unlock(&mutex);
}

void update_element(uint32_t rnti, NFAPI_CRC_INDICATION_PDU_T* new_data) {
    if (!find_element_by_rnti(rnti)) {
        log("Error: Element not found to update.");
        return;
    }

    pthread_mutex_lock(&mutex);

    for (size_t i = 0; i < num_elements; ++i) {
        if (list[i].RNTI == rnti) {
            memcpy(&list[i], new_data, element_size);
            break;
        }
    }

    pthread_mutex_unlock(&mutex);
}

void dump_list(const char* filename) {
    pthread_mutex_lock(&mutex);

    FILE* file = fopen(filename, "w");
    if (!file) {
        log("Error: Could not open file for writing.");
        pthread_mutex_unlock(&mutex);
        return;
    }

    fprintf(file, "List of NFAPI_CRC_INDICATION_PDU_T structures:\n");
    for (size_t i = 0; i < num_elements; ++i) {
        fprintf(file, "\nRX_UE_INFORMATION_TAG: %u\n", list[i].RX_UE_INFORMATION_TAG);
        fprintf(file, "RNTI: %u\n", list[i].RNTI);
        fprintf(file, "CRC_INDICATION_REL8_TAG: ");
        for (size_t j = 0; j < sizeof(list[i].CRC_INDICATION_REL8_TAG); ++j) {
            fprintf(file, "%02hhx ", list[i].CRC_INDICATION_REL8_TAG[j]);
        }
    }

    fclose(file);
    pthread_mutex_unlock(&mutex);
}
```

