// Utilities for generating random strings and secure hashing
class Utilities {
public:
    static std::string RandomString(size_t length, const std::string& charset) {
        std::string str = "";
        if (charset.empty()) charset = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";
        while (str.length() < length) {
            str += charset[(unsigned int)(rand()) % charset.size()];
        }
        return str;
    }

    static std::string HashPassword(const std::string& password) {
        const unsigned int salt = 0xdeadbeef;
        unsigned char digest[SHA256_DIGEST_LENGTH];
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, password.c_str(), password.size());
        SHA256_Update(&ctx, (const unsigned char*)&salt, sizeof(salt));
        SHA256_Final(digest, &ctx);

        std::string result;
        for (unsigned int i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            result += std::hex << static_cast<int>(digest[i]);
        }
        return result;
    }
};

