#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct NetworkInterface {
    time_t timestamp;
    double throughput;
    double latency;
    double packet_loss;
} NetworkInterface;

void init_ni(NetworkInterface* ni) {
    ni->timestamp = time(NULL);
    ni->throughput = 0.0;
    ni->latency = NAN; // Indicates not measured yet
    ni->packet_loss = 0.0;
}

void* collect_metrics(void* arg) {
    NetworkInterface* ni = arg;
    // Simulate collecting network interface metrics here
    ni->throughput = (double)(rand() % 10 + 5); // Random throughput between 5 and 14 Mbps
    ni->latency = (double)(rand() % 1000 + 500) / 1e3; // Random latency between 0.5 ms and 1.5 ms
    ni->packet_loss = (double)(rand() % 20 + 30) / 100.0; // Random packet loss between 30% and 59.99%

    return NULL;
}

void reduce(NetworkInterface* accumulator, NetworkInterface* current) {
    accumulator->throughput += current->throughput;
    accumulator->latency = fmin(accumulator->latency, current->latency);
    accumulator->packet_loss += current->packet_loss;
}

int initializeNetworkInterface(int log_level, NetworkInterface* interfaces, size_t count, size_t* processed) {
    if (!interfaces || !count || !processed) {
        fprintf(stderr, "Invalid input: interfaces, count or processed are NULL\n");
        return -1;
    }

    *processed = 0;

    pthread_t threads[count];
    NetworkInterface ni;

    for (size_t i = 0; i < count; ++i) {
        if (!interfaces) {
            fprintf(stderr, "Error: interfaces array is NULL or has insufficient capacity\n");
            return -1;
        }
        init_ni(&interfaces[i]);
    }

    NetworkInterface accumulator = { .timestamp = time(NULL), .throughput = 0.0, .latency = NAN, .packet_loss = 0.0 };

    for (size_t i = 0; i < count; ++i) {
        pthread_create(&threads[i], NULL, collect_metrics, &interfaces[i]);
    }

    size_t thread_index = 0;
    for (size_t i = 0; i < count; ) {
        int rc = pthread_join(threads[i], NULL);
        if (rc == 0) {
            reduce(&accumulator, &interfaces[i]);
            ++(*processed);
            i = thread_index + 1 >= count ? 0 : thread_index + 1;
            thread_index++;
        } else if (rc != EINTR) {
            fprintf(stderr, "Error: pthread_join failed with error %d\n", rc);
            return -1;
        }
    }

    if (log_level >= 2) {
        printf("Averaged network interface metrics:\n");
        printf("Throughput: %.2f Mbps\n", accumulator.throughput / count);
        printf("Latency: %.3fs\n", accumulator.latency * 1e3);
        printf("Packet Loss: %.2f%%\n", accumulator.packet_loss / (double)count * 100.0);
    }

    return 0;
}

int main() {
    const size_t interface_count = 10;
    NetworkInterface* interfaces = malloc(interface_count * sizeof(NetworkInterface));
    if (!interfaces) {
        fprintf(stderr, "Error: Failed to allocate memory for network interfaces\n");
        return -1;
    }

    size_t processed = 0;
    int rc = initializeNetworkInterface(2, interfaces, interface_count, &processed);
    if (rc != 0) {
        free(interfaces);
        return rc;
    }

    // Add more test cases here

    free(interfaces);
    return 0;
}
