typedef struct {
    time_t timestamp;
    double throughput;
    double latency;
    double packet_loss_percentage;
} LinkMetric;

typedef enum { LOG_LEVEL_ERROR, LOG_LEVEL_WARNING, LOG_LEVEL_INFO, LOG_LEVEL_DEBUG } LogLevel;

struct NetworkInterface {
    char iface_name[IF_NAMESIZE];
    pthread_mutex_t metrics_lock;
    LinkMetric* metrics;
    size_t metrics_count;
    size_t capacity;
    LogLevel log_level;
};

void init_network_interface(struct NetworkInterface* interface, const char* iface_name, LogLevel log_level) {
    strncpy(interface->iface_name, iface_name, IF_NAMESIZE);
    interface->metrics = NULL;
    interface->metrics_count = 0;
    interface->capacity = 0;
    interface->log_level = log_level;
    pthread_mutex_init(&interface->metrics_lock, NULL);
}

void configure_network_interface(struct NetworkInterface* interface, void (*on_system_check)(void*), void (*on_hardware_update)(void*)) {
    if (on_system_check) {
        interface->on_system_check = on_system_check;
    }

    if (on_hardware_update) {
        interface->on_hardware_update = on_hardware_update;
    }
}

void update_link_metric(struct NetworkInterface* interface, const LinkMetric* metric) {
    pthread_mutex_lock(&interface->metrics_lock);

    if (interface->capacity == interface->metrics_count) {
        interface->capacity *= 2;
        LinkMetric* new_metrics = realloc(interface->metrics, sizeof(LinkMetric) * interface->capacity);
        if (!new_metrics) {
            fprintf(stderr, "Failed to allocate memory for link metrics\n");
            pthread_mutex_unlock(&interface->metrics_lock);
            return;
        }
        interface->metrics = new_metrics;
    }

    interface->metrics[interface->metrics_count] = *metric;
    interface->metrics_count++;

    pthread_mutex_unlock(&interface->metrics_lock);
}

void log(struct NetworkInterface* interface, const char* message, LogLevel level) {
    if (level <= interface->log_level) {
        printf("%s\n", message);
    }
}
