using namespace std;

void count_lines(ifstream &in, mutex *line_count_mutex) {
    long long line_count = 0;
    string line;
    while (getline(in, line)) {
        unique_lock<mutex> lock(*line_count_mutex);
        ++line_count;
    }
}

void summary(ifstream &in, const string &delimiter, ostream &out) {
    map<string, long long> word_count;
    string line;
    while (getline(in, line)) {
        istringstream iss(line);
        string word;
        while (iss >> word) {
            ++word_count[word];
        }
    }
    for (const auto &p : word_count) {
        out << p.first << ": " << p.second << '\n';
    }
}

void process_file(ifstream input, const string &output_path, bool count_only,
                  const string &delimiter, const string &help) {
    if (!count_only) {
        thread line_counter(&count_lines, ref(input), new mutex());
        thread summary_thread(&summary, ref(input), delimiter, ws);
        line_counter.join();
        summary_thread.join();
    }

    if (!output_path.empty()) {
        ofstream output(output_path);
        if (!output) {
            cerr << "Error: Could not create output file.\n";
            return;
        }

        if (count_only) {
            output << input.name() << ": " << input.tellg() << " lines\n";
        }
    } else {
        if (count_only) {
            cout << input.name() << ": " << input.tellg() << " lines\n";
        } else {
            summary(input, delimiter, ws);
        }
    }
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        cerr << "Usage: " << argv[0] << " [options] -i/--input-file input_file [-c/--count-only] [-s/--summary] [-o/--output-file output_file] --manpage\n"
            "\nOptions:\n"
            "-i, --input-file <path>\tPath to the input file.\n"
            "-c, --count-only\tPrint only the total number of lines without reading the entire content.\n"
            "-s, --summary\tGenerate a summary of lines per unique word. Use --delimiter to specify custom delimiters.\n"
            "--output-file <path>\tSpecifies an output file where results should be written instead of being printed to the console.\n"
            "--manpage\tDisplay detailed usage information.\n";
        return 0;
    }

    string input_file, output_file, delimiter = " ";
    bool count_only = false, summary_enabled = false;

    for (int i = 1; i < argc; ++i) {
        if (argv[i][0] == '-' && argv[i][1] != '-') { // handle single-character options
            switch (argv[i][0]) {
                case 'i':
                    ++i;
                    if (i >= argc) {
                        cerr << "Error: Missing input file for -i option.\n";
                        return 1;
                    }
                    input_file = argv[i];
                    break;
                case 'c':
                    count_only = true;
                    break;
                case 's':
                    summary_enabled = true;
                    if (++i >= argc) {
                        cerr << "Error: Missing delimiter for --summary option.\n";
                        return 1;
                    }
                    delimiter = argv[i];
                    break;
                case 'o':
                    ++i;
                    if (i >= argc) {
                        cerr << "Error: Missing output file for --output-file option.\n";
                        return 1;
                    }
                    output_file = argv[i];
                    break;
                case 'h':
                case '?':
                    // --manpage or unknown option, display help and exit
                    return show_help();
            }
        } else { // handle multi-character options
            if (argv[i] == string("-")) {
                ++i;
                if (i >= argc) {
                    cerr << "Error: Missing value for - option.\n";
                    return 1;
                }
                switch (*argv[++i]) {
                    case 'i':
                        input_file = argv[i];
                        break;
                    case 's':
                        delimiter = argv[i];
                        summary_enabled = true;
                        break;
                    // ... add other options here ...
                }
            } else {
                cerr << "Error: Unrecognized option: " << argv[i] << '\n';
                return show_help();
            }
        }
    }

    ifstream input(input_file);
    if (!input) {
        cerr << "Error: Could not open input file: " << input_file << '\n';
        return 1;
    }

    process_file(input, output_file, count_only, delimiter, help_string);

    return 0;
}
