typedef struct {
    int buffer_size;
    double timeout;
    int compression_level;
    double error_threshold;
} DataProcessingUnit;

struct ProcessingPipeline {
    DataProcessingUnit* units;
    int num_units;
    int max_tasks;
    bool logging;
    pthread_mutex_t lock;
    time_t last_flush;
    int flush_interval;
};

void InitializeDataProcessingPipeline(struct ProcessingPipeline* pipeline, int max_tasks, int log_level, int flush_interval) {
    if (max_tasks > 1000)
        max_tasks = 1000;
    pipeline->max_tasks = max_tasks;
    pipeline->num_units = 0;
    pipeline->logging = log_level != 0;
    pipeline->flush_interval = flush_interval;
    pipeline->last_flush = time(NULL);
    pipeline->lock = PTHREAD_MUTEX_INITIALIZER;

    pipeline->units = (DataProcessingUnit*)malloc((max_tasks+1) * sizeof(DataProcessingUnit));
    if (!pipeline->units) {
        perror("Memory allocation failed");
        return;
    }

    for (int i = 0; i < max_tasks; ++i) {
        pipeline->units[i].buffer_size = 1 << 20; // 1MB buffer size
        pipeline->units[i].timeout = 5.0;          // 5 seconds timeout
        pipeline->units[i].compression_level = 9; // High compression level
        pipeline->units[i].error_threshold = 0.01; // 1% error threshold
    }

    if (pipeline->logging) {
        printf("Initializing %d data processing units...\n", max_tasks);
    }
}

void periodicallyFlush(struct ProcessingPipeline* pipeline) {
    struct timespec ts;

    clock_gettime(CLOCK_REALTIME, &ts);
    ts.tv_sec += pipeline->flush_interval;

    while (true) {
        clock_gettime(CLOCK_REALTIME, &ts);
        if (ts.tv_sec >= pipeline->last_flush + pipeline->flush_interval) {
            pthread_mutex_lock(&pipeline->lock);
            for (int i = 0; i < pipeline->num_units; ++i) {
                // Reset processing parameters to default values
                memset(&(pipeline->units[i]), 0, sizeof(DataProcessingUnit));
            }
            pipeline->last_flush = ts.tv_sec;
            pthread_mutex_unlock(&pipeline->lock);
        }
        usleep(100000); // Sleep for 0.1 seconds before checking again
    }
}

