#include <openssl/evp.h>

EVP_CIPHER *create_cipher(const char* mode) {
    EVP_CIPHER_CTX *ctx;
    const EVP_CIPHER *algorithm = NULL;

    if (strcmp(mode, "ecb") == 0) {
        algorithm = EVP_des_ecb();
    } else if (strcmp(mode, "ede") == 0 || strcmp(mode, "ede3") == 0) {
        algorithm = EVP_des_ede();
    } else if (strcmp(mode, "cfb") == 0) {
        algorithm = EVP_des_cbc();
    } else if (strcmp(mode, "null") == 0) { // Null encryption for testing purposes
        return NULL;
    }

    if (!algorithm) {
        fprintf(stderr, "Invalid cipher mode\n");
        return NULL;
    }

    EVP_CIPHER_CTX_init(ctx);
    EVP_CIPHER_CTX_set_key_length(ctx, EVP_CIPHER_key_length(algorithm));
    EVP_CIPHER_CTX_set_cipher(ctx, algorithm);

    return ctx;
}
```

